function buildBank() {
  const out = [];
  let id = 0;
  CORE.forEach(([d,q,o,a,e,qEn,oEn,eEn]) => out.push({ id:`c${id++}`, d, q, o:[...o], a, e, qEn, oEn:oEn?[...oEn]:null, eEn }));
  const allNames = FACTS.map(f => f[1]);
  // 日本語サービス名 → 英語名（x[9]があればそれ、なければ同名=言語非依存）
  const EN_NAME = {};
  FACTS.forEach(x => { EN_NAME[x[1]] = x[9] || x[1]; });
  const enName = (jp) => EN_NAME[jp] || jp;
  const enOpts = (opts) => opts.map(enName);
  const pickDistractors = (correct, pool, n) => shuffle(pool.filter(x => x !== correct)).slice(0, n);
  FACTS.forEach((f) => {
    const [d, name, role, use, rival, diff, roleEn, useEn, diffEn] = f;
    const hasEn = !!roleEn;
    const nameE = enName(name);
    const rivalE = rival ? enName(rival) : rival;
    const sameD = FACTS.filter(x => x[0] === d && x[1] !== name).map(x => x[1]);
    // 角度1：役割→サービス
    {
      const distract = pickDistractors(name, sameD.length >= 3 ? sameD : allNames, 3);
      const opts = shuffle([name, ...distract]);
      out.push({ id:`g${id++}`, d, q:`${role}はどれか。`, o:opts, a:opts.indexOf(name), e:`${name}：${use}`,
        qEn: hasEn?`Which is ${roleEn}?`:null, oEn: enOpts(opts), eEn: hasEn?`${nameE}: ${useEn}`:null });
    }
    // 角度2：用途→サービス
    {
      const distract = pickDistractors(name, sameD.length >= 3 ? sameD : allNames, 3);
      const opts = shuffle([name, ...distract]);
      out.push({ id:`g${id++}`, d, q:`次の用途に最も適すのはどれか：「${use}」`, o:opts, a:opts.indexOf(name), e:`${name}は${role}。`,
        qEn: hasEn?`Which best fits this use case: "${useEn}"?`:null, oEn: enOpts(opts), eEn: hasEn?`${nameE} is ${roleEn}.`:null });
    }
    // 角度3：対比（前者）
    if (rival) {
      const opts = shuffle([name, rival, ...pickDistractors(name, sameD.filter(x=>x!==rival), 2)]);
      out.push({ id:`g${id++}`, d, q:`${diff}という違いがある。前者に当たるのはどれか。`, o:opts, a:opts.indexOf(name), e:`${name} vs ${rival}：${diff}`,
        qEn: hasEn?`There is a difference: ${diffEn}. Which is the former?`:null, oEn: enOpts(opts), eEn: hasEn?`${nameE} vs ${rivalE}: ${diffEn}`:null });
    }
    // 角度4：特徴説明の正誤
    {
      const wrongPool = FACTS.filter(x => x[1] !== name && x[6]);
      const wrongFacts = shuffle(wrongPool).slice(0,3);
      const wrongs = wrongFacts.map(x => `${name}は${x[2]}`);
      const correctStmt = `${name}は${role}`;
      const opts = shuffle([correctStmt, ...wrongs]);
      let oEn = null;
      if (hasEn && wrongFacts.length === 3) {
        const correctEn = `${nameE} is ${roleEn}`;
        const map = new Map();
        map.set(correctStmt, correctEn);
        wrongFacts.forEach((x, i) => map.set(wrongs[i], `${nameE} is ${x[6]}`));
        oEn = opts.map(o => map.get(o));
      }
      out.push({ id:`g${id++}`, d, q:`${name}の説明として正しいのはどれか。`, o:opts, a:opts.indexOf(correctStmt), e:`${name}：${use}`,
        qEn: hasEn?`Which statement about ${nameE} is correct?`:null, oEn, eEn: hasEn?`${nameE}: ${useEn}`:null });
    }
    // 角度5：シナリオ
    {
      const distract = pickDistractors(name, sameD.length >= 3 ? sameD : allNames, 3);
      const opts = shuffle([name, ...distract]);
      out.push({ id:`g${id++}`, d, q:`ある要件で「${use}」が求められている。最も適すサービスはどれか。`, o:opts, a:opts.indexOf(name), e:`${name}は${role}。要件に合致する。`,
        qEn: hasEn?`A requirement calls for "${useEn}". Which service fits best?`:null, oEn: enOpts(opts), eEn: hasEn?`${nameE} is ${roleEn}; it matches the requirement.`:null });
    }
    // 角度6：グループ該当
    if (sameD.length >= 3) {
      const others = shuffle(sameD).slice(0, 3);
      const opts = shuffle([name, ...others]);
      out.push({ id:`g${id++}`, d, q:`「${role}」に該当するサービスはどれか。`, o:opts, a:opts.indexOf(name), e:`${name}が該当。${use}`,
        qEn: hasEn?`Which service is "${roleEn}"?`:null, oEn: enOpts(opts), eEn: hasEn?`${nameE} applies. ${useEn}`:null });
    }
    // 角度7：対比（後者）
    if (rival) {
      const sameOfRival = FACTS.filter(x => x[0] === d && x[1] !== rival && x[1] !== name).map(x => x[1]);
      const opts = shuffle([rival, name, ...shuffle(sameOfRival).slice(0,2)]);
      out.push({ id:`g${id++}`, d, q:`${name}と対比される「${diff}」。後者(対比相手)はどれか。`, o:opts, a:opts.indexOf(rival), e:`${name} ⇔ ${rival}：${diff}`,
        qEn: hasEn?`"${diffEn}" — which is the latter (the counterpart to ${nameE})?`:null, oEn: enOpts(opts), eEn: hasEn?`${nameE} ⇔ ${rivalE}: ${diffEn}`:null });
    }
  });
  return out;
}

function buildExamSets(bank) {
  const byDom = {};
  DOMAINS.forEach(d => { byDom[d.id] = bank.filter(q => q.d === d.id); });
  const plan = { D1:19, D2:18, D3:12, D4:16 }; // 合計65問。各分野のプールが配分×5問以上あるので5セットが重ならない
  const sets = {};
  for (let s = 0; s < 5; s++) {
    const arr = [];
    Object.entries(plan).forEach(([dom, n]) => {
      const pool = byDom[dom];
      for (let i = 0; i < n; i++) arr.push(pool[(i + s * n) % pool.length]);
    });
    sets[s + 1] = arr;
  }
  return sets;
}

function shuffle(arr) { const a = [...arr]; for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; }

// 各問題の選択肢順をシャッフルし、正解index(a)とoEnを連動させる
function shuffleChoices(q) {
  const idxs = shuffle(q.o.map((_, i) => i));
  const o = idxs.map(i => q.o[i]);
  const oEn = q.oEn ? idxs.map(i => q.oEn[i]) : q.oEn;
  const a = idxs.indexOf(q.a);
  return { ...q, o, oEn, a };
}

const BANK = buildBank().map(shuffleChoices);
const ADP_HARD = ([{"id":"h0","d":"D1","q":"あるEC企業は、オンプレミスのMySQLデータベース（約2TB）をGoogle Cloudへ移行したいと考えています。移行中もソースDBは稼働を続け、ダウンタイムは最小限に抑える必要があります。移行後の宛先はCloud SQL for MySQLです。継続的レプリケーションで差分を同期しながら計画的に切り替えたい場合、最も適切なマネージドサービスはどれですか。","o":["Database Migration Service を使い、継続的レプリケーションで初期ダンプ後の変更を同期する","Storage Transfer Service で mysqldump をエクスポートして定期転送する","Transfer Appliance にダンプを書き出して物理輸送する","Dataflow のバッチジョブで毎晩全テーブルを洗い替えする"],"a":0,"e":"Database Migration Service (DMS) はソースの初期スナップショット後にCDCで継続的レプリケーションを行い、最小ダウンタイムでCloud SQL等へ移行できるマネージドサービスです。Storage TransferやTransfer Applianceはファイル/オブジェクト転送用で継続的DB同期には不適。全洗い替えはダウンタイムと負荷が大きく不適です。","qEn":"An e-commerce company wants to migrate an on-premises MySQL database (~2TB) to Google Cloud. The source must keep serving traffic during migration with minimal downtime, and the target is Cloud SQL for MySQL. To continuously replicate changes and cut over on a planned schedule, which managed service is most appropriate?","oEn":["Use Database Migration Service with continuous replication to sync changes after the initial dump","Use Storage Transfer Service to periodically move a mysqldump export","Write a dump to a Transfer Appliance and ship it physically","Run a nightly Dataflow batch job that fully reloads every table"],"eEn":"Database Migration Service (DMS) performs an initial snapshot then continuous CDC replication, enabling minimal-downtime migration to Cloud SQL. Storage Transfer and Transfer Appliance move files/objects, not live DB replication. A full reload creates heavy downtime and load."},{"id":"h1","d":"D1","q":"転送は自動化して人手を介さず、失敗時の再試行と進捗の可視化も求められています。データエンジニアは、AWS S3バケットに毎日蓄積される数百万件のJSONログを、追加コードを書かずにスケジュールでCloud Storageへ同期したいと考えています。差分検出と再試行を備え、フルマネージドで運用したいという要件があります。最も適したサービスはどれですか。","o":["Transfer Appliance を米国リージョンに発送して差分を取り込む","gcloud storage cp を cron で毎日手動実行する","Dataproc の Spark ジョブでS3から読み込みGCSへ書き出す","Storage Transfer Service でS3をソースにスケジュール転送ジョブを構成する"],"a":3,"e":"Storage Transfer Service はS3など他クラウドやオンプレをソースに、スケジュール・差分検出・再試行を備えたフルマネージド転送を提供します。Transfer Applianceは物理輸送用でクラウド間の定期同期には不適。cronスクリプトやSparkは運用負荷が高く要件に反します。","qEn":"Transfers must be automated without manual steps, with retries on failure and progress visibility. A data engineer wants to sync millions of daily JSON logs from an AWS S3 bucket to Cloud Storage on a schedule, without writing custom code, with change detection, retries, and fully managed operation. Which service fits best?","oEn":["Ship a Transfer Appliance to a US region to ingest the deltas","Run gcloud storage cp daily via cron manually","Use a Dataproc Spark job to read from S3 and write to GCS","Configure a scheduled Storage Transfer Service job with S3 as the source"],"eEn":"Storage Transfer Service offers fully managed, scheduled transfers from sources like S3 with change detection and retries. Transfer Appliance is for physical shipping, not recurring cross-cloud sync. Cron scripts or Spark add operational burden and miss the requirement."},{"id":"h2","d":"D1","q":"現地の回線増強は予算・期間の制約から現実的でなく、一度きりの初期移行として計画されています。ある製造業は、ネットワーク帯域が限られた工場から500TBの過去センサーデータを一度だけGoogle Cloudへ移行する必要があります。現行の10Mbps回線ではオンライン転送に数か月かかると見積もられています。最もコストと時間の効率が良い移行手段はどれですか。","o":["gcloud storage の並列アップロードで直接送る","Datastream でセンサーDBから継続レプリケーションする","Transfer Appliance を利用してデータを物理デバイスに書き込み輸送する","Storage Transfer Service のオンライン転送ジョブを並列実行する"],"a":2,"e":"帯域が細く一度限りの大容量（500TB）移行では、Transfer Appliance に物理デバイスへ書き込んで輸送するのが時間・コスト効率的です。10Mbpsのオンライン転送は非現実的に長時間かかります。Datastreamは継続CDC用で一括過去データ移行には不向きです。","qEn":"Upgrading the local link is impractical due to budget and timeline, and this is planned as a one-time initial migration. A manufacturer must do a one-time migration of 500TB of historical sensor data from a factory with limited network bandwidth. Their 10Mbps link would take months for online transfer. Which migration approach is most time- and cost-efficient?","oEn":["Send it directly with gcloud storage parallel uploads","Use Datastream to continuously replicate from the sensor DB","Use Transfer Appliance to write data to a physical device and ship it","Run parallel online Storage Transfer Service jobs"],"eEn":"For a one-time, very large (500TB) move over a thin link, Transfer Appliance (write to a physical device and ship) is most efficient. Online transfer over 10Mbps would take impractically long. Datastream is for continuous CDC, not bulk historical migration."},{"id":"h3","d":"D1","q":"同社ではダウンタイムやデータ整合性のリスクを厳しく管理しており、切り替えは業務時間外に短時間で完了させたいと考えています。分析チームはOracleデータベースの変更をほぼリアルタイムでBigQueryに反映し、常に最新の状態で分析したいと考えています。サーバーレスのCDCで、ソースへの負荷を抑えつつ挿入・更新・削除をストリーミングで取り込みたい場合、最適なサービスはどれですか。","o":["Cloud Data Fusion のバッチパイプラインを日次で走らせる","Datastream を使ってOracleからBigQueryへCDCストリームを構成する","BigQuery Data Transfer Service で毎時フルロードする","Dataproc の Sqoop ジョブを1時間ごとに実行する"],"a":1,"e":"Datastream はサーバーレスのCDCサービスで、OracleやMySQLの変更（INSERT/UPDATE/DELETE）をほぼリアルタイムにBigQueryへストリーミングでき、ソース負荷を抑えます。フルロードやバッチ（Sqoop、日次Data Fusion）はリアルタイム性に欠け、削除の反映も困難です。","qEn":"The company strictly manages downtime and data-consistency risk and wants cutover completed quickly outside business hours. An analytics team wants to reflect Oracle database changes in BigQuery in near real time for always-fresh analysis. Using serverless CDC that streams inserts, updates, and deletes with low source impact, which service is best?","oEn":["Run a daily Cloud Data Fusion batch pipeline","Use Datastream to configure an Oracle-to-BigQuery CDC stream","Full-load hourly with BigQuery Data Transfer Service","Run a Dataproc Sqoop job every hour"],"eEn":"Datastream is a serverless CDC service that streams Oracle/MySQL changes (INSERT/UPDATE/DELETE) to BigQuery in near real time with low source load. Full loads and batch (Sqoop, daily Data Fusion) lack real-time freshness and struggle to propagate deletes."},{"id":"h4","d":"D1","q":"あるゲーム会社は、Pub/Subに秒間10万件流入するイベントを、ウィンドウ集計や重複排除などの変換を施しながらBigQueryへストリーミングで書き込みたいと考えています。Apache Beamで記述したパイプラインをオートスケールで運用したい場合、最適なサービスはどれですか。","o":["BigQuery の load ジョブでファイルを定期取り込みする","Dataflow のストリーミングジョブでBeamパイプラインを実行する","Dataproc の常時起動Sparkクラスタで処理する","Cloud Data Fusion のバッチ実行で1時間ごとに集計する"],"a":1,"e":"Dataflow は Apache Beam のマネージド実行基盤で、ストリーミングのウィンドウ集計や重複排除をオートスケールで処理しBigQueryへ書き込めます。Dataprocは手動クラスタ運用でストリーム自動スケールに劣り、Data Fusionバッチやloadジョブはリアルタイム要件を満たしません。","qEn":"A gaming company wants to stream events arriving at 100k/sec on Pub/Sub into BigQuery while applying transforms like windowed aggregation and deduplication, running an Apache Beam pipeline with autoscaling. Which service is best?","oEn":["Periodically ingest files with BigQuery load jobs","Run the Beam pipeline as a Dataflow streaming job","Process on an always-on Dataproc Spark cluster","Aggregate hourly with Cloud Data Fusion batch runs"],"eEn":"Dataflow is the managed runner for Apache Beam, handling streaming windowed aggregation and dedup with autoscaling and writing to BigQuery. Dataproc needs manual cluster management, and Data Fusion batch or load jobs don't meet the real-time requirement."},{"id":"h5","d":"D1","q":"イベントは急峻なバーストを伴い、遅延なく確実に取り込めるスケーラビリティが強く求められています。あるチームは既存のオンプレHadoop/Sparkジョブ群（PySpark、Hive）を最小限の書き換えでGoogle Cloudへ移行し、ジョブ実行時のみクラスタを起動してコストを抑えたいと考えています。既存エコシステムとの互換性を重視する場合、最適なサービスはどれですか。","o":["Dataproc でエフェメラルクラスタを起動しジョブごとに実行する","Dataflow へ全ジョブをApache Beamで書き直す","Cloud Data Fusion でGUIパイプラインに再構築する","BigQuery のストアドプロシージャに全ロジックを移す"],"a":0,"e":"Dataproc はマネージドHadoop/Sparkで、既存のPySparkやHiveジョブをほぼそのまま実行でき、ジョブ単位のエフェメラルクラスタでコストを抑えられます。DataflowはBeamへの書き直しが必要、Data FusionやBigQueryへの再構築は移行コストが大きく互換性重視の要件に反します。","qEn":"Events come in sharp bursts, so scalable, low-latency, reliable ingestion is strongly required. A team wants to migrate existing on-prem Hadoop/Spark jobs (PySpark, Hive) to Google Cloud with minimal rewrites, spinning up clusters only during job runs to save cost, prioritizing ecosystem compatibility. Which service is best?","oEn":["Use Dataproc ephemeral clusters, one per job run","Rewrite all jobs in Apache Beam on Dataflow","Rebuild them as GUI pipelines in Cloud Data Fusion","Move all logic into BigQuery stored procedures"],"eEn":"Dataproc is managed Hadoop/Spark that runs existing PySpark and Hive jobs largely unchanged, using per-job ephemeral clusters to cut cost. Dataflow requires a Beam rewrite; Data Fusion or BigQuery rebuilds are costly and conflict with the compatibility goal."},{"id":"h6","d":"D1","q":"このチームはSparkやHiveの既存資産を多く抱え、再教育コストを避けたいと考えており、運用の手離れの良さも重視しています。データ統合チームには、SQLやコードに不慣れなアナリストが多く、GUIでドラッグ＆ドロップにより複数ソースを結合・クレンジングするETLパイプラインを構築したいという要望があります。事前構築コネクタとメタデータ管理を備えたマネージドサービスはどれですか。","o":["Dataflow でJavaのBeamコードを書く","Dataproc で Scala の Spark を実装する","Compute Engine上に独自ETLサーバを構築する","Cloud Data Fusion でビジュアルパイプラインを構築する"],"a":3,"e":"Cloud Data Fusion はCDAPベースのGUIデータ統合サービスで、コードなしのドラッグ＆ドロップ、豊富な事前構築コネクタ、メタデータ/リネージ管理を提供します。DataflowやDataprocはコード記述が必要で、独自サーバは運用負荷が高くGUI要件を満たしません。","qEn":"The team has substantial existing Spark and Hive assets, wants to avoid retraining costs, and values low operational overhead. A data integration team has many analysts unfamiliar with SQL or code and wants to build ETL pipelines that join and cleanse multiple sources via drag-and-drop GUI, with prebuilt connectors and metadata management. Which managed service fits?","oEn":["Write Java Beam code in Dataflow","Implement Scala Spark on Dataproc","Build a custom ETL server on Compute Engine","Build visual pipelines in Cloud Data Fusion"],"eEn":"Cloud Data Fusion is a CDAP-based GUI integration service offering no-code drag-and-drop, many prebuilt connectors, and metadata/lineage. Dataflow and Dataproc require coding, and a custom server adds operational burden, missing the GUI requirement."},{"id":"h7","d":"D1","q":"導入部門はセルフサービスでの内製化を志向し、専門エンジニアへの依存を減らしたいと考えています。複数のマイクロサービスが不定期にバースト的なイベントを生成し、下流の分析パイプラインがそれを取りこぼさず非同期に受け取れる仕組みが必要です。プロデューサとコンシューマを疎結合にし、少なくとも1回配信とスケーラブルなバッファリングを提供するサービスはどれですか。","o":["Cloud SQL のテーブルにINSERTしてポーリングする","BigQuery に直接ストリーミング挿入して仲介させる","Pub/Sub をメッセージングバッファとして導入する","Cloud Storage にファイルとして直接書き込む"],"a":2,"e":"Pub/Sub はスケーラブルな非同期メッセージングで、プロデューサとコンシューマを疎結合にし、少なくとも1回配信とバッファリングを提供します。GCSファイルやCloud SQLポーリングはバースト吸収や疎結合に劣り、BigQuery直挿入はメッセージバッファの役割を果たしません。","qEn":"The adopting team favors self-service in-house work and wants to reduce reliance on specialist engineers. Several microservices emit bursty events irregularly, and a downstream analytics pipeline must receive them asynchronously without loss. Which service decouples producers and consumers with at-least-once delivery and scalable buffering?","oEn":["INSERT into a Cloud SQL table and poll it","Stream-insert directly into BigQuery as the broker","Introduce Pub/Sub as a messaging buffer","Write files directly to Cloud Storage"],"eEn":"Pub/Sub is scalable async messaging that decouples producers and consumers with at-least-once delivery and buffering. GCS files or Cloud SQL polling handle bursts and decoupling poorly, and direct BigQuery inserts don't serve as a message buffer."},{"id":"h8","d":"D1","q":"下流の処理速度は一定でないため、流入の急増を吸収するバッファリングが不可欠だと考えられています。あるデータチームはBigQueryにデータを取り込むにあたり、変換ロジックが複雑でも強力な演算能力を活用したいと考えています。まず生データをそのままBigQueryにロードし、SQLで変換して分析用テーブルを作る方針です。この設計思想を最もよく表す用語はどれですか。","o":["CDC（変更データキャプチャ）","MDM（マスターデータ管理）","ELT（抽出・ロード後にBigQuery内で変換）","ETL（ロード前に外部で全変換）"],"a":2,"e":"生データを先にロードし、BigQueryのSQL処理能力で変換する方式はELT（Extract-Load-Transform）です。ETLはロード前に外部エンジンで変換します。BigQueryのスケーラブルな演算を活かす近年の主流はELTで、CDCやMDMは別概念です。","qEn":"Downstream throughput varies, so buffering to absorb spikes is considered essential. A data team wants to load raw data into BigQuery first and transform it with SQL to build analytics tables, leveraging BigQuery's compute for complex logic. Which term best describes this design?","oEn":["CDC (change data capture)","MDM (master data management)","ELT (extract and load, then transform inside BigQuery)","ETL (transform fully externally before loading)"],"eEn":"Loading raw data first and transforming with BigQuery SQL is ELT (Extract-Load-Transform). ETL transforms externally before loading. Leveraging BigQuery's scalable compute favors ELT; CDC and MDM are unrelated concepts."},{"id":"h9","d":"D1","q":"この組織はデータウェアハウスを刷新中で、変換処理をどこで実行するかによってコストと保守性が変わることを理解しています。データエンジニアは、BigQueryに毎日ロードする大量の分析データについて、ストレージと読み取りバイト数を最小化したいと考えています。列指向で高い圧縮率を持ち、スキーマを内包しBigQueryロードにも効率的なファイル形式はどれですか。","o":["固定長テキスト","Parquet","CSV","改行区切りJSON（NDJSON）"],"a":1,"e":"Parquet は列指向でスキーマを内包し、高圧縮かつBigQueryロードで効率的に読み取れます。CSVやNDJSONは行指向でスキーマ情報が乏しく圧縮率も低め、固定長テキストも同様に非効率です。列指向はスキャン列の絞り込みにも有利です。","qEn":"The organization is modernizing its data warehouse and understands that where transformation runs affects cost and maintainability. A data engineer wants to minimize storage and bytes read for large analytics data loaded into BigQuery daily. Which file format is columnar, highly compressible, self-describing, and efficient for BigQuery loads?","oEn":["Fixed-width text","Parquet","CSV","Newline-delimited JSON (NDJSON)"],"eEn":"Parquet is columnar, self-describing, highly compressed, and efficient for BigQuery loads. CSV and NDJSON are row-oriented with weak schema info and lower compression; fixed-width text is similarly inefficient. Columnar formats also help prune scanned columns."},{"id":"h10","d":"D1","q":"このデータは日次でテラバイト規模に達し、下流の分析クエリでも読み取り効率が重要になると想定されています。あるストリーミングパイプラインでは、上流のスキーマが頻繁に進化（フィールド追加）します。生産側と消費側でスキーマ互換性を保ち、行指向で書き込みに強く、スキーマ進化をネイティブにサポートするデータシリアライズ形式はどれですか。","o":["Avro","Parquet","CSV","XML"],"a":0,"e":"Avro は行指向でスキーマをファイルに内包し、後方・前方互換のスキーマ進化をネイティブにサポートするため、書き込みが多くスキーマが変化するストリーミングに適します。Parquetは列指向で読み取り分析向き、CSV/XMLはスキーマ進化管理が弱いです。","qEn":"The data reaches terabytes daily, and downstream analytics queries also depend on efficient reads. In a streaming pipeline, the upstream schema evolves frequently (fields added). Which serialization format keeps producer/consumer schema compatibility, is row-oriented for write-heavy workloads, and natively supports schema evolution?","oEn":["Avro","Parquet","CSV","XML"],"eEn":"Avro is row-oriented, embeds its schema, and natively supports backward/forward-compatible schema evolution, ideal for write-heavy streaming with changing schemas. Parquet is columnar for read analytics; CSV/XML handle schema evolution poorly."},{"id":"h11","d":"D1","q":"このパイプラインは複数の外部システムからデータを集約しており、下位互換・上位互換の両立が運用上の要件になっています。BigQueryに数年分のイベントログを蓄積しており、分析クエリはほぼ常に直近30日など特定の日付範囲に限定されます。スキャンするバイト数とコストを大幅に削減するために、テーブル設計で最初に検討すべき手法はどれですか。","o":["全行を1つのパーティションに格納し圧縮を上げる","テーブルを日付ごとに手動で分割し UNION する","結果を毎回マテリアライズドビューに複製する","取り込み日または日付列によるパーティション分割"],"a":3,"e":"日付でパーティション分割すると、クエリの日付フィルタでプルーニングが効き、スキャンバイト数とコストを大幅に削減できます。手動分割＋UNIONは管理が煩雑、単一パーティションはプルーニング不可、マテビューは補助策で第一選択ではありません。","qEn":"The pipeline aggregates data from several external systems, so both backward and forward compatibility are operational requirements. You store years of event logs in BigQuery, and queries almost always filter to a date range like the last 30 days. Which table design technique should you consider first to greatly reduce bytes scanned and cost?","oEn":["Put all rows in one partition and increase compression","Manually split tables by date and UNION them","Copy results into a materialized view every time","Partition by ingestion date or a date column"],"eEn":"Date partitioning lets date filters prune partitions, greatly cutting bytes scanned and cost. Manual splitting with UNION is unwieldy, a single partition can't be pruned, and materialized views are a complementary tactic, not the first choice."},{"id":"h12","d":"D1","q":"このテーブルはコスト最適化の主要対象で、オンデマンド課金のためスキャン量が直接料金に響くことがわかっています。日付でパーティション分割済みの大規模BigQueryテーブルで、さらにcustomer_idやregionといった高カーディナリティ列での絞り込みクエリが多発しています。パーティション内でこれらの列の絞り込みとソートを最適化する追加手法はどれですか。","o":["パーティションをさらに時間単位に細分化する","全列にわたって二次パーティションを作る","各クエリで SELECT * を用いて統計を集める","よく絞り込む列でクラスタリングを設定する"],"a":3,"e":"クラスタリングはパーティション内でデータを指定列（例: customer_id, region）でソート・ブロック化し、絞り込みクエリのスキャン量を減らします。BigQueryはパーティション＋クラスタリングの併用が推奨。時間細分化や二次パーティションはこの目的には不適で、SELECT *は逆効果です。","qEn":"This table is a primary cost-optimization target, and under on-demand billing scanned volume directly drives charges. On a large date-partitioned BigQuery table, many queries also filter on high-cardinality columns like customer_id and region. Which additional technique optimizes filtering and sorting on these columns within partitions?","oEn":["Subdivide partitions further into hourly granularity","Create a secondary partition across all columns","Use SELECT * in each query to gather statistics","Enable clustering on the frequently filtered columns"],"eEn":"Clustering sorts and blocks data within partitions by columns like customer_id/region, reducing scanned data for filters. BigQuery recommends combining partitioning and clustering. Finer time partitions or secondary partitions don't help here, and SELECT * is counterproductive."},{"id":"h13","d":"D1","q":"このテーブルは既にコスト削減のため日付でパーティション分割されていますが、それでも一部クエリが高額になっています。あるチームは、コンプライアンス目的で7年間保持が必要なログをCloud Storageに保管します。アクセスは年に1回未満と極めて稀ですが、取得時の待ち時間よりも長期保管コストの最小化を最優先したいと考えています。最適なストレージクラスはどれですか。","o":["Nearline ストレージクラス","Coldline ストレージクラス","Archive ストレージクラス","Standard ストレージクラス"],"a":2,"e":"年1回未満の極めて稀なアクセスで長期保管コスト最小化を最優先するなら Archive が最適です。Standardは頻繁アクセス向け、Nearlineは月1回程度、Coldlineは四半期に1回程度が目安。保持年数と最小アクセス頻度から Archive が要件に合致します。","qEn":"This table is already date-partitioned for cost savings, yet some queries remain expensive. A team stores logs that must be retained 7 years for compliance in Cloud Storage. Access is extremely rare (less than once a year), and minimizing long-term storage cost matters more than retrieval latency. Which storage class is best?","oEn":["Nearline storage class","Coldline storage class","Archive storage class","Standard storage class"],"eEn":"For access less than once a year prioritizing minimal long-term cost, Archive is best. Standard suits frequent access, Nearline ~monthly, Coldline ~quarterly. Given the retention and minimal access frequency, Archive matches the requirement."},{"id":"h14","d":"D1","q":"保管対象は法令上の長期保持が義務付けられ、総保有コストの最小化が最重要の評価軸になっています。データレイクとしてCloud Storageに格納したParquetファイル群を、BigQueryへ物理ロードせずにクエリしたいと考えています。さらに、行・列レベルのアクセス制御を効かせつつBigQueryのSQLで直接分析したい場合、最適なアプローチはどれですか。","o":["Dataproc でParquetを都度スキャンし結果を手元に保存する","BigLake テーブルを作成しGCS上のParquetをガバナンス付きで参照する","毎回 gcloud でファイルをダウンロードしローカル分析する","Cloud SQL に全Parquetをインポートしてから参照する"],"a":1,"e":"BigLake テーブルはGCS上のParquet等をBigQueryから直接クエリでき、行・列レベルのセキュリティなどガバナンスを適用できます。ローカルダウンロードやCloud SQLインポートは非効率でガバナンスも弱く、Dataproc都度スキャンはSQL直接分析要件に合いません。","qEn":"The data is legally mandated for long-term retention, and minimizing total cost of ownership is the top criterion. You want to query Parquet files in a Cloud Storage data lake without physically loading them into BigQuery, while enforcing row/column-level access control and analyzing directly with BigQuery SQL. Which approach is best?","oEn":["Scan Parquet ad hoc with Dataproc and save results locally","Create a BigLake table referencing the GCS Parquet with governance","Download files with gcloud each time and analyze locally","Import all Parquet into Cloud SQL first, then query"],"eEn":"BigLake tables let BigQuery query GCS Parquet directly while applying governance like row/column-level security. Local downloads or Cloud SQL imports are inefficient and weakly governed, and ad-hoc Dataproc scans don't meet the direct-SQL requirement."},{"id":"h15","d":"D1","q":"データ量は継続的に増加しており、物理ロードを繰り返す運用は避けたいという方針があります。マーケティングチームは、Google広告とYouTubeのレポートデータを毎日自動でBigQueryに取り込み、社内ダッシュボードを更新したいと考えています。コードを書かずにSaaSソースからスケジュール取り込みできるBigQuery純正の仕組みはどれですか。","o":["BigQuery Data Transfer Service で定期転送を構成する","Dataflow のカスタムコネクタを自作する","Storage Transfer Service でSaaS APIを叩く","Transfer Appliance でレポートを物理輸送する"],"a":0,"e":"BigQuery Data Transfer Service はGoogle広告・YouTube・Google Analyticsなど各種SaaSからコード不要でスケジュール取り込みできるマネージド機能です。Dataflow自作は開発負荷が高く、Storage TransferはオブジェクトストレージやファイルソースでSaaS APIレポート用ではありません。","qEn":"Data volume keeps growing, and the policy is to avoid repeatedly physically loading it. A marketing team wants to automatically ingest Google Ads and YouTube report data into BigQuery daily to refresh internal dashboards, without writing code, on a schedule from SaaS sources. Which native BigQuery capability fits?","oEn":["Configure recurring transfers with BigQuery Data Transfer Service","Build a custom Dataflow connector","Call the SaaS APIs via Storage Transfer Service","Physically ship reports with Transfer Appliance"],"eEn":"BigQuery Data Transfer Service ingests from SaaS sources like Google Ads, YouTube, and Google Analytics on a schedule without code. A custom Dataflow build is heavy, and Storage Transfer targets object/file sources, not SaaS API reports."},{"id":"h16","d":"D1","q":"このデータはAPI経由でのみ取得でき、認証やスキーマ変更の追従を自前で実装すると保守負荷が高くなります。あるパイプラインでは、Cloud Storageに1日1回まとめて到着する大容量CSVをBigQueryへ取り込みます。リアルタイム性は不要で、取り込みコストを最小化したい要件があります。BigQueryへのデータ投入方法として最も適切なのはどれですか。","o":["無料のバッチ load ジョブでファイルをロードする","ストリーミング挿入APIで1行ずつ挿入する","Storage Write API を常時接続で使う","外部テーブル経由で毎回フルスキャンする"],"a":0,"e":"日次バッチでリアルタイム不要なら、無料のバッチloadジョブが最もコスト効率的です。ストリーミング挿入やStorage Write APIのストリーミングは課金され低レイテンシ用途向け。外部テーブルの都度フルスキャンはクエリコストが増え取り込み手段としても非効率です。","qEn":"The data is available only via APIs, and implementing auth and schema tracking yourself would be high-maintenance. A pipeline ingests large CSVs that arrive once daily in Cloud Storage into BigQuery. Real-time is not needed and ingestion cost should be minimized. What is the most appropriate way to load into BigQuery?","oEn":["Load the files with free batch load jobs","Insert row by row via the streaming insert API","Use the Storage Write API in always-connected mode","Full-scan via an external table every time"],"eEn":"For daily batches without real-time needs, free batch load jobs are most cost-efficient. Streaming inserts and streaming Storage Write API are billed and meant for low latency. Repeated external-table full scans raise query cost and are inefficient for ingestion."},{"id":"h17","d":"D1","q":"複数のBigQueryのSQL変換、Dataflowジョブ、外部API呼び出しを、依存関係を持つ複雑なワークフローとして毎晩オーケストレーションしたいと考えています。Apache AirflowベースでDAGを記述でき、リッチなスケジューリングと監視を備えたマネージドサービスはどれですか。","o":["Cloud Workflows","Cloud Scheduler 単体","Pub/Sub のトリガのみ","Cloud Composer"],"a":3,"e":"Cloud Composer はマネージドApache Airflowで、依存関係のある複雑なDAG、リッチなスケジューリング、リトライ、監視を備え、多数のBigQueryやDataflowタスクのオーケストレーションに適します。Workflowsは軽量なサーバーレスオーケストレーション、Schedulerは単純なトリガで複雑DAGには不足です。","qEn":"You need to orchestrate multiple BigQuery SQL transforms, Dataflow jobs, and external API calls as a complex dependency-driven workflow every night, authoring DAGs with rich scheduling and monitoring. Which managed service fits?","oEn":["Cloud Workflows","Cloud Scheduler alone","Only Pub/Sub triggers","Cloud Composer"],"eEn":"Cloud Composer is managed Apache Airflow with complex dependency DAGs, rich scheduling, retries, and monitoring, ideal for orchestrating many BigQuery/Dataflow tasks. Workflows is lightweight serverless orchestration, and Scheduler is a simple trigger insufficient for complex DAGs."},{"id":"h18","d":"D1","q":"これらのタスクは相互に依存し、失敗時のリトライや通知、実行履歴の追跡も必要とされています。チームは、数個のサーバーレスAPI呼び出しとFunctionを、軽量で低コストなステートマシンとして順次・条件分岐で連携させたいと考えています。Airflowほどの重厚なDAG基盤は不要で、YAML/JSONで定義しサーバー管理不要にしたい場合、最適なサービスはどれですか。","o":["Dataproc Workflow Template","Compute Engine上の自作スケジューラ","Cloud Workflows","Cloud Composer"],"a":2,"e":"Cloud Workflows はサーバーレスで軽量なオーケストレーションを提供し、YAML/JSONでAPI・Functionの順次実行や条件分岐を低コストに定義できます。Composerは重厚なAirflowで小規模用途には過剰、Dataproc Workflow TemplateはHadoop向け、自作スケジューラは運用負荷が高いです。","qEn":"The tasks are interdependent and need retries, notifications on failure, and run-history tracking. A team wants to chain a few serverless API calls and Functions as a lightweight, low-cost state machine with sequencing and branching, without heavy Airflow DAG infrastructure, defined in YAML/JSON and serverless. Which service fits best?","oEn":["Dataproc Workflow Template","A custom scheduler on Compute Engine","Cloud Workflows","Cloud Composer"],"eEn":"Cloud Workflows provides serverless, lightweight orchestration to define sequential and branching API/Function execution in YAML/JSON at low cost. Composer's heavy Airflow is overkill for small cases, Dataproc Workflow Templates target Hadoop, and a custom scheduler adds operational burden."},{"id":"h19","d":"D1","q":"このチームは軽量さと低コストを重視し、フルマネージドでインフラ管理を避けたいと考えています。Pub/Subでイベントを受けるパイプラインで、一部メッセージがコンシューマの処理に繰り返し失敗し、再配信がループしています。問題のあるメッセージを隔離して他の処理を止めないようにするための、Pub/Subのネイティブ機能はどれですか。","o":["メッセージ保持期間を0にする","デッドレタートピック（dead-letter topic）を構成する","サブスクリプションの ack 期限を無限に延ばす","トピックを削除して作り直す"],"a":1,"e":"Pub/Sub のデッドレタートピックは、指定回数を超えて配信失敗したメッセージを別トピックへ退避させ、処理ループを断ち切って他メッセージの流れを維持します。ack期限延長や保持0、トピック再作成は問題解決にならず、むしろデータ喪失や滞留を招きます。","qEn":"The team values lightness and low cost and wants fully managed operation without infrastructure management. In a Pub/Sub pipeline, some messages repeatedly fail consumer processing and redelivery loops. Which native Pub/Sub feature isolates the problematic messages so other processing isn't blocked?","oEn":["Set message retention to zero","Configure a dead-letter topic","Extend the subscription ack deadline indefinitely","Delete and recreate the topic"],"eEn":"Pub/Sub dead-letter topics move messages that exceed a delivery-attempt threshold to a separate topic, breaking the loop while keeping other messages flowing. Extending ack deadlines, zero retention, or recreating the topic don't fix it and risk loss or backlog."},{"id":"h20","d":"D1","q":"この問題はコンシューマ側のバグに起因することがあり、原因調査の間も他メッセージの処理は継続させたいと考えています。あるチームは、数百万個の小さなファイルをローカルからCloud Storageへできるだけ高速にアップロードしたいと考えています。単一スレッドの逐次アップロードでは遅すぎます。CLIで並列・複合アップロードを活用して転送を高速化する最適な方法はどれですか。","o":["Cloud SQL に一度入れてからGCSへ書き出す","gcloud storage cp を並列処理で実行しスループットを上げる","1ファイルずつ Web コンソールで手動アップロードする","全ファイルを1つのファイルにzipせず個別にcurlする"],"a":1,"e":"gcloud storage コマンドは並列・複合アップロードに対応し、多数の小ファイルを高スループットで転送できます。Webコンソール手動や個別curlは遅く、Cloud SQL経由は不要な迂回で非効率。大量ファイルはCLIの並列転送が最適です。","qEn":"The issue can stem from consumer-side bugs, and other messages should keep processing during investigation. A team wants to upload millions of small files from local to Cloud Storage as fast as possible; single-threaded sequential upload is too slow. What is the best way to speed transfer using the CLI's parallel/composite upload?","oEn":["Load into Cloud SQL first, then write out to GCS","Run gcloud storage cp with parallelism to increase throughput","Upload files one by one manually in the web console","curl each file individually without zipping"],"eEn":"The gcloud storage command supports parallel/composite uploads to move many small files at high throughput. Manual console uploads or per-file curl are slow, and routing through Cloud SQL is an unnecessary detour. CLI parallel transfer is best for many files."},{"id":"h21","d":"D1","q":"これらのファイルはサイズが小さくオブジェクト数が膨大で、逐次処理では所要時間が現実的でないことがわかっています。BigQueryに既にあるトランザクションデータと、Cloud SQL上でリアルタイム更新される小さなマスターテーブルを結合して分析したいと考えています。マスターをBigQueryに複製せず、常に最新の値で結合する最適な方法はどれですか。","o":["EXTERNAL_QUERyでCloud SQLへのフェデレーテッドクエリを使う","毎晩マスターをエクスポートしBigQueryへロードする","Cloud SQL に全トランザクションを移してから結合する","Transfer Appliance でマスターを物理コピーする"],"a":0,"e":"BigQueryのフェデレーテッドクエリ（EXTERNAL_QUERY）はCloud SQLへ直接問い合わせ、複製せずに常に最新のマスターと結合できます。日次エクスポートは鮮度が落ち、全トランザクション移動はBigQueryの利点を失い、Transfer Applianceはリアルタイム結合用途に不適です。","qEn":"The files are small but enormous in count, making sequential processing impractically slow. You want to join transactional data already in BigQuery with a small master table updated in real time on Cloud SQL, joining against always-fresh values without replicating the master into BigQuery. What is best?","oEn":["Use a federated query to Cloud SQL via EXTERNAL_QUERY","Export the master nightly and load it into BigQuery","Move all transactions into Cloud SQL, then join","Physically copy the master with Transfer Appliance"],"eEn":"BigQuery federated queries (EXTERNAL_QUERY) reach into Cloud SQL directly, joining always-fresh master data without replication. Nightly exports lose freshness, moving all transactions forfeits BigQuery's strengths, and Transfer Appliance doesn't fit real-time joins."},{"id":"h22","d":"D1","q":"このパイプラインはコスト最適化が重視されており、取り込み手段の選択が月次のBigQuery料金に直結します。あるアナリストは、複数のCSVに混在する欠損値・型不整合・重複を、コードを書かずにインタラクティブに探索・クレンジングし、変換レシピを組んでスケーラブルに実行したいと考えています。データラングリングに特化した最適なサービスはどれですか。","o":["BigQuery で手書きの巨大なCASE式を書く","Compute Engine 上のpandasスクリプトを手動運用する","Cloud SQL のトリガで逐次補正する","Cloud Dataprep でビジュアルにデータをクレンジングする"],"a":3,"e":"Cloud Dataprep はコード不要でデータの探索・クレンジング・変換レシピ作成を行い、内部でスケーラブルに実行するデータラングリング特化サービスです。BigQueryの手書きCASEや手動pandas、Cloud SQLトリガは対話的ラングリング体験や規模の点で要件に劣ります。","qEn":"Cost optimization matters here, and the ingestion method chosen directly affects the monthly BigQuery bill. An analyst wants to interactively explore and cleanse missing values, type mismatches, and duplicates across several CSVs without code, build transformation recipes, and run them at scale. Which service specializes in data wrangling?","oEn":["Write huge hand-coded CASE expressions in BigQuery","Manually run a pandas script on Compute Engine","Correct rows via Cloud SQL triggers","Cleanse data visually with Cloud Dataprep"],"eEn":"Cloud Dataprep is a data-wrangling service for no-code exploration, cleansing, and recipe building that executes at scale. Hand-coded BigQuery CASE, manual pandas, or Cloud SQL triggers fall short on interactive wrangling and scale."},{"id":"h23","d":"D1","q":"このマスターテーブルは頻繁に更新されるため、鮮度の低下は分析結果の正確性を損なうリスクがあります。ストリーミングパイプラインでは、ネットワーク再送などにより同一イベントが重複してPub/Subに配信されることがあります。BigQueryへ書き込む際に重複行を防ぎたい場合、Dataflowなどで実装すべき最も効果的な考え方はどれですか。","o":["ランダムなUUIDを毎回付け直して区別する","重複は後で手動で削除する前提で無視する","イベントの一意なIDを用いて冪等・重複排除を行う","全行に現在時刻を付与し常にユニークにする"],"a":2,"e":"重複配信に対しては、イベント固有の一意ID（例: event_id）をキーに冪等な書き込みや重複排除ウィンドウを行うのが最も効果的です。現在時刻や毎回のUUID付与は同一イベントを別物にしてしまい重複を助長。手動削除は運用負荷が高くスケールしません。","qEn":"The master table updates frequently, so staleness risks the accuracy of analytics results. In a streaming pipeline, network retries can deliver the same event to Pub/Sub more than once. To prevent duplicate rows when writing to BigQuery, which is the most effective approach to implement (e.g., in Dataflow)?","oEn":["Re-assign a random UUID each time to differentiate them","Ignore duplicates and delete them manually later","Use each event's unique ID for idempotent deduplication","Attach the current time to every row to make them unique"],"eEn":"For duplicate delivery, deduplicating idempotently on a unique event ID (e.g., event_id) is most effective. Adding current time or fresh UUIDs makes identical events look distinct, worsening duplication. Manual deletion is high-effort and doesn't scale."},{"id":"h24","d":"D1","q":"このアナリストはSQLに不慣れで、変換の試行錯誤を対話的に行いつつ最終的には大規模データにも適用したいと考えています。あるチームは、BigQueryのステージングテーブルから本番テーブルへ、変更された行のみを効率的に反映（挿入・更新）したいと考えています。1つの文でマッチ条件に応じて挿入・更新・削除を行える最適なSQL構文はどれですか。","o":["全行 DELETE してから INSERT で入れ直す","SELECT でループしながら1行ずつ更新する","MERGE 文を使って条件付きで UPSERT する","毎回 DROP TABLE して CREATE TABLE で作り直す"],"a":2,"e":"BigQueryの MERGE 文はマッチ条件に応じてINSERT/UPDATE/DELETEを1文で行えるUPSERTに最適です。DROP&CREATEや全DELETE&INSERTは無駄なスキャンとコスト、履歴喪失リスクを生み、行単位ループはスケールしません。差分反映にはMERGEが標準です。","qEn":"The analyst is unfamiliar with SQL, wants to iterate transformations interactively, and ultimately apply them to large data. A team wants to efficiently apply only changed rows (inserts/updates) from a BigQuery staging table into a production table. Which SQL construct can insert, update, or delete based on match conditions in a single statement?","oEn":["DELETE all rows then re-INSERT everything","Loop with SELECT and update one row at a time","Use a MERGE statement to conditionally UPSERT","DROP TABLE and CREATE TABLE anew each time"],"eEn":"BigQuery's MERGE statement performs INSERT/UPDATE/DELETE based on match conditions in one statement, ideal for UPSERT. DROP&CREATE or full DELETE&INSERT waste scans and cost and risk history loss; row-by-row loops don't scale. MERGE is standard for change application."},{"id":"h25","d":"D1","q":"このパイプラインは高スループットで、重複がダッシュボードの指標を歪めることが運用上の懸念になっています。IoTデバイスからのテレメトリを、少ないコード運用でPub/SubからBigQueryへ直接ストリーミングしたいと考えています。単純なパススルー（変換なし）で、Dataflowジョブを自分で書かずに済ませたい場合、最も簡素で運用負荷の低い方法はどれですか。","o":["一旦GCSに保存し日次でloadする","Pub/Sub の BigQuery サブスクリプションを使って直接書き込む","自作Dataflowストリーミングジョブを常時運用する","Cloud Functions で1メッセージずつ挿入する"],"a":1,"e":"変換不要の単純なストリーミングなら、Pub/SubのBigQueryサブスクリプションがトピックから直接BigQueryへ書き込め、Dataflowコード不要で運用負荷が最小です。自作Dataflowやfunctionは開発・運用負荷が増え、GCS経由日次はリアルタイム要件を満たしません。","qEn":"The pipeline is high-throughput, and duplicates skewing dashboard metrics is an operational concern. You want to stream IoT telemetry directly from Pub/Sub to BigQuery with minimal code and operations, as a simple passthrough (no transforms), without writing a Dataflow job. Which is the simplest, lowest-ops approach?","oEn":["Stage to GCS and load daily","Use a Pub/Sub BigQuery subscription to write directly","Operate a custom Dataflow streaming job continuously","Insert one message at a time with Cloud Functions"],"eEn":"For simple transform-free streaming, a Pub/Sub BigQuery subscription writes directly from the topic to BigQuery with no Dataflow code and minimal ops. Custom Dataflow or Functions add dev/ops burden, and GCS-then-daily-load misses the real-time requirement."},{"id":"h26","d":"D2","q":"この構成は運用の簡素化を最重視し、変換ロジックを持たない純粋な取り込みだけを担わせたいと考えています。あるダッシュボードでは、巨大なファクトテーブルに対する同一の集計クエリ（日次のGROUP BY集計）が、多数のユーザーによって繰り返し実行されコストと待ち時間が問題になっています。ベーステーブル更新時に増分的に自動更新される、集計結果を事前計算する最適な機能はどれですか。","o":["マテリアライズドビューで集計を事前計算し自動増分更新する","通常のビューを作成してクエリを短くする","毎回 CREATE TABLE AS SELECT で手動更新する","結果をスプレッドシートにコピーして共有する"],"a":0,"e":"マテリアライズドビューは集計結果を事前計算・保存し、ベーステーブル更新時に増分的に自動更新されるため、繰り返す集計のコストと待ち時間を削減します。通常ビューは実行時に毎回計算し、手動CTASは鮮度管理が煩雑、スプレッドシートコピーは論外です。","qEn":"This design prioritizes operational simplicity and should handle pure ingestion with no transformation logic. On a dashboard, the same aggregation query (daily GROUP BY) over a huge fact table is run repeatedly by many users, causing cost and latency issues. Which feature precomputes aggregates and refreshes incrementally when base data changes?","oEn":["Use a materialized view that precomputes aggregates and auto-refreshes incrementally","Create a regular view to shorten the query","Manually refresh with CREATE TABLE AS SELECT each time","Copy results into a spreadsheet to share"],"eEn":"Materialized views precompute and store aggregates and refresh incrementally as base data changes, cutting cost and latency for repeated aggregations. Regular views recompute at query time, manual CTAS complicates freshness, and spreadsheet copies are unsuitable."},{"id":"h27","d":"D2","q":"この集計は多数の同時ユーザーに参照され、リアルタイム性より応答の速さとコスト効率が重視されます。データサイエンティストは、住宅の広さや部屋数から販売価格（連続値）を予測するモデルをBigQuery ML上のSQLで構築します。この回帰モデルの予測精度を評価する際、予測誤差の大きさを元の単位で表す代表的な指標はどれですか。","o":["Precision（適合率）","Recall（再現率）","AUC（ROC曲線下面積）","RMSE（二乗平均平方根誤差）"],"a":3,"e":"連続値を予測する回帰では RMSE（Root Mean Squared Error）が代表的な評価指標で、誤差を元の単位で表し大きな誤差に敏感です。Precision/Recall/AUCは分類モデルの指標で、連続値予測の回帰評価には用いません。","qEn":"The aggregate is viewed by many concurrent users, prioritizing response speed and cost efficiency over real-time freshness. A data scientist builds a BigQuery ML model in SQL to predict house sale price (a continuous value) from size and room count. Which is a standard metric to evaluate this regression's error magnitude in the original units?","oEn":["Precision","Recall","AUC (area under the ROC curve)","RMSE (root mean squared error)"],"eEn":"For regression predicting continuous values, RMSE is a standard metric expressing error in original units and sensitive to large errors. Precision/Recall/AUC are classification metrics, not used for continuous-value regression evaluation."},{"id":"h28","d":"D2","q":"このモデルは不動産評価のワークフローに組み込まれ、誤差の大きさを担当者が直感的に理解できることが重要です。不正取引検知の分類モデルを評価しています。不正の見逃し（実際に不正なのに正常と判定）を最小化することが最優先で、正常を誤って不正とする程度のコストは許容できます。この目的に最も直結する評価指標はどれですか。","o":["Precision（適合率）だけを最大化する","RMSE を最小化する","決定係数 R^2 を最大化する","Recall（再現率）を最大化する"],"a":3,"e":"見逃し（偽陰性）の最小化を最優先するなら、実際の陽性を捕捉する割合であるRecall（再現率）が最も直結します。Precisionのみでは見逃しを見落とし、RMSEやR^2は回帰指標で分類の見逃し評価には不適です。","qEn":"The model feeds a property-valuation workflow, and stakeholders must intuitively grasp the error magnitude. You evaluate a fraud-detection classifier. Minimizing missed fraud (actually fraud but predicted normal) is the top priority, and the cost of flagging normal as fraud is acceptable. Which metric most directly serves this goal?","oEn":["Maximize Precision only","Minimize RMSE","Maximize the coefficient of determination R^2","Maximize Recall"],"eEn":"To minimize missed fraud (false negatives), Recall, the fraction of actual positives caught, is most directly relevant. Precision alone ignores misses, and RMSE or R^2 are regression metrics unsuited to classification miss evaluation."},{"id":"h29","d":"D2","q":"このモデルは金融取引の監視に用いられ、見逃しが直接的な金銭的損失につながる点が経営から強く懸念されています。組織は、複数チームが一貫した指標定義（例: 売上、解約率）で分析できるよう、集中管理されたセマンティックモデルとガバナンス、埋め込み分析やモデリング層を求めています。単なるレポート作成を超えたエンタープライズBIプラットフォームとして最適なのはどれですか。","o":["スプレッドシートのピボットテーブル","BigQuery コンソールのクエリ履歴","Looker（LookMLでセマンティック層を集中管理）","Looker Studio（無料の簡易ダッシュボード）"],"a":2,"e":"Looker はLookMLによる集中管理されたセマンティックモデルで指標定義を統一し、ガバナンス・埋め込み分析・モデリング層を備えるエンタープライズBIプラットフォームです。Looker Studioは軽量な可視化向けでセマンティック層の集中管理には不足、他選択肢はBIプラットフォームではありません。","qEn":"The model monitors financial transactions, and management is strongly concerned that misses cause direct monetary loss. An organization wants centrally governed, consistent metric definitions (e.g., revenue, churn) across teams, with a semantic model, embedded analytics, and a modeling layer, beyond simple reporting. Which is the enterprise BI platform of choice?","oEn":["Spreadsheet pivot tables","BigQuery console query history","Looker (centrally governed semantic layer via LookML)","Looker Studio (free lightweight dashboards)"],"eEn":"Looker provides a centrally governed semantic model via LookML for consistent metric definitions, with governance, embedded analytics, and a modeling layer, an enterprise BI platform. Looker Studio is lightweight visualization lacking a governed semantic layer; the others aren't BI platforms."},{"id":"h30","d":"D2","q":"この組織では部門ごとに指標の定義がばらつき、レポート間で数値が食い違う問題が長年の課題になっています。小規模チームが、BigQueryとGoogleスプレッドシートのデータを手早く接続し、無料で共有可能なインタラクティブダッシュボードを作りたいと考えています。LookMLのようなモデリング層は不要で、素早く可視化することが目的です。最適なツールはどれですか。","o":["BigQuery のクエリ結果をCSVで毎回配布する","Looker Studio で手軽にダッシュボードを作成する","Looker のフルLookMLプロジェクトを構築する","Dataproc でカスタムWebアプリを開発する"],"a":1,"e":"Looker Studio（旧Data Studio）は無料で、BigQueryやスプレッドシートに素早く接続しインタラクティブなダッシュボードを共有できる軽量ツールです。フルLookMLのLookerは重厚で目的に過剰、Dataproc自作やCSV配布は手間がかかり共有・対話性に劣ります。","qEn":"Metric definitions vary by department, and mismatched numbers across reports have been a long-standing problem. A small team wants to quickly connect BigQuery and Google Sheets data and build free, shareable interactive dashboards, without needing a modeling layer like LookML, prioritizing speed to visualization. Which tool is best?","oEn":["Distribute BigQuery query results as CSV each time","Build dashboards quickly with Looker Studio","Stand up a full LookML project in Looker","Develop a custom web app with Dataproc"],"eEn":"Looker Studio (formerly Data Studio) is a free lightweight tool that quickly connects to BigQuery and Sheets to build and share interactive dashboards. Full-LookML Looker is overkill, and custom Dataproc apps or CSV distribution are laborious with poor sharing/interactivity."},{"id":"h31","d":"D2","q":"このチームは予算が限られ、専任のBI管理者を置かずに素早く価値を出すことを最優先しています。アナリストは、各顧客の注文について、同一顧客内での購入金額の累計や、直前の注文からの差分を1つのクエリで計算したいと考えています。行をグループに折り畳まずに、パーティション・並び順を指定して行ごとに計算するSQL機能はどれですか。","o":["ウィンドウ関数（OVER句によるPARTITION BY / ORDER BY）","単純な GROUP BY 集計","INNER JOIN の多用","サブクエリのCOUNT(*)だけ"],"a":0,"e":"OVER句を使うウィンドウ（分析）関数は、行を折り畳まずにPARTITION BY・ORDER BYで顧客ごとの累計（SUM OVER）や直前値との差分（LAG）を計算できます。GROUP BYは行を集約してしまい、JOIN多用やサブクエリCOUNTでは同等の行単位計算を簡潔に表現できません。","qEn":"The team has a limited budget and prioritizes quick value without a dedicated BI administrator. An analyst wants to compute, per customer order, a running total of spend within the same customer and the difference from the previous order, in one query, without collapsing rows into groups. Which SQL feature applies per-row with partitioning and ordering?","oEn":["Window functions (OVER with PARTITION BY / ORDER BY)","A simple GROUP BY aggregation","Heavy use of INNER JOINs","Only a subquery COUNT(*)"],"eEn":"Window (analytic) functions with OVER compute per-row running totals (SUM OVER) and previous-value differences (LAG) using PARTITION BY/ORDER BY without collapsing rows. GROUP BY aggregates rows away, and heavy JOINs or subquery COUNTs can't express this per-row logic concisely."},{"id":"h32","d":"D2","q":"このレポートはリテンション分析に用いられ、顧客単位の時系列的な振る舞いを1つのクエリで表現する必要があります。数十億行のイベントテーブルで、ユニークユーザー数の概算をダッシュボードで頻繁に表示します。厳密な精度は不要で、スキャンコストとレイテンシを抑えたいという要件があります。BigQueryで最も効率的な方法はどれですか。","o":["APPROX_COUNT_DISTINCT を使って近似ユニーク数を高速計算する","COUNT(DISTINCT ...) を毎回正確に計算する","全行を配列に集めてアプリ側で数える","データを一旦Cloud SQLに移して数える"],"a":0,"e":"厳密な精度が不要で規模が大きい場合、BigQueryのAPPROX_COUNT_DISTINCT（HyperLogLog++ベース）はメモリとレイテンシを抑えつつ近似ユニーク数を高速に返します。正確なCOUNT(DISTINCT)は重く、アプリ集計やCloud SQL移送は非効率です。","qEn":"The report supports retention analysis and must express per-customer time-ordered behavior in one query. On a table of billions of events, a dashboard frequently shows approximate unique user counts. Exact precision isn't needed and you want to reduce scan cost and latency. What is the most efficient approach in BigQuery?","oEn":["Use APPROX_COUNT_DISTINCT for fast approximate uniques","Compute exact COUNT(DISTINCT ...) every time","Collect all rows into an array and count in the app","Move the data to Cloud SQL first and count there"],"eEn":"When exact precision isn't needed at large scale, BigQuery's APPROX_COUNT_DISTINCT (HyperLogLog++) returns approximate uniques fast with low memory and latency. Exact COUNT(DISTINCT) is heavy, and app-side counting or moving to Cloud SQL is inefficient."},{"id":"h33","d":"D2","q":"この指標はリアルタイムダッシュボードで頻繁に更新表示され、応答時間の短縮がユーザー体験に直結します。経営ダッシュボードでは、BigQuery上の同じ集計を多数の同時ユーザーが操作し、サブ秒のインタラクティブな応答が求められます。SQLを書き換えずにBigQueryのクエリ応答を高速化する、インメモリ分析アクセラレーションはどれですか。","o":["スロットを0にして待機させる","結果を毎回CSVエクスポートする","テーブルを暗号化して再ロードする","BI Engine を有効化してインメモリでクエリを高速化する"],"a":3,"e":"BigQuery BI Engine はインメモリ分析アクセラレーションで、SQLを変えずにダッシュボードのクエリをサブ秒に高速化し多数の同時アクセスに応えます。スロット0は逆効果、CSVエクスポートや再暗号化は応答高速化と無関係です。","qEn":"This metric refreshes frequently on a real-time dashboard, and shorter response times directly improve UX. An executive dashboard has many concurrent users interacting with the same BigQuery aggregates, requiring sub-second interactive responses. Which in-memory analytics acceleration speeds up BigQuery responses without rewriting SQL?","oEn":["Set slots to zero to make it wait","Export results to CSV every time","Encrypt the table and reload it","Enable BI Engine to accelerate queries in memory"],"eEn":"BigQuery BI Engine is in-memory analytics acceleration that speeds dashboard queries to sub-second without changing SQL, serving high concurrency. Zero slots is counterproductive, and CSV export or re-encryption are unrelated to response speed."},{"id":"h34","d":"D2","q":"このダッシュボードは経営会議で使われ、遅延なくドリルダウンできる操作性が強く求められています。データガバナンス担当は、複数のBigQueryテーブルに対して、鮮度（最終更新）、NULL率、値の範囲などのルールを定義し自動でデータ品質を監視・スコアリングしたいと考えています。データカタログと統合されたGoogle Cloudのサービスはどれですか。","o":["BigQuery のクエリ履歴タブ","Cloud Monitoring の CPU アラート","Dataplex のデータ品質（自動データ品質/データプロファイリング）","Looker Studio のグラフ機能"],"a":2,"e":"Dataplex はデータ品質ルールの定義・自動チェック・プロファイリングやカタログ/リネージを統合的に提供し、鮮度やNULL率、範囲などを監視・スコアリングできます。Looker Studioは可視化、クエリ履歴やCPUアラートはデータ品質監視の専用機能ではありません。","qEn":"The dashboard is used in executive meetings and must support drill-down without lag. A data governance lead wants to define rules like freshness, null rate, and value ranges across multiple BigQuery tables and automatically monitor and score data quality, integrated with a data catalog. Which Google Cloud service fits?","oEn":["The BigQuery query history tab","Cloud Monitoring CPU alerts","Dataplex data quality (auto data quality / data profiling)","Looker Studio charting"],"eEn":"Dataplex provides data-quality rule definition, automated checks, profiling, and catalog/lineage integration, monitoring and scoring freshness, null rate, ranges, etc. Looker Studio is visualization, and query history or CPU alerts aren't dedicated data-quality features."},{"id":"h35","d":"D2","q":"この組織は監査対応のためデータ品質の証跡を残す必要があり、手作業のチェックでは追随できなくなっています。あるレポートは、毎朝決まった時刻にBigQueryで集計クエリを実行し、結果を宛先テーブルに保存してダッシュボードを更新する必要があります。外部オーケストレータを持ち込まず、BigQuery内で完結してスケジュール実行する最も簡単な方法はどれですか。","o":["Dataflow ジョブを常時起動しておく","BigQuery のスケジュールされたクエリ（scheduled query）を設定する","手動で毎朝コンソールからクエリを実行する","Compute Engine の cron でCLIを叩く"],"a":1,"e":"BigQueryのスケジュールされたクエリは、指定時刻に定期実行し結果を宛先テーブルへ書き込む機能で、外部オーケストレータ不要で簡単に構成できます。手動実行は非現実的、Compute Engine cronや常時Dataflowは過剰で運用負荷が高いです。","qEn":"The organization must retain data-quality evidence for audits, and manual checks can no longer keep up. A report must run an aggregation query in BigQuery every morning at a fixed time, save results to a destination table, and refresh a dashboard, all within BigQuery without an external orchestrator. What is the simplest scheduled approach?","oEn":["Keep a Dataflow job always running","Set up a BigQuery scheduled query","Run the query manually from the console each morning","Hit the CLI via cron on Compute Engine"],"eEn":"BigQuery scheduled queries run periodically at a set time and write results to a destination table, configured simply without an external orchestrator. Manual runs are impractical, and Compute Engine cron or always-on Dataflow are overkill with high ops burden."},{"id":"h36","d":"D2","q":"あるアナリストのクエリは SELECT * FROM huge_table WHERE ... と書かれ、必要なのは3列だけなのに全列をスキャンして高額になっています。BigQueryはオンデマンド課金で、スキャンしたバイト数で料金が決まります。コストを下げる最も直接的な改善はどれですか。","o":["テーブルを一時テーブルにコピーしてから同じ SELECT * をする","必要な列だけを明示的にSELECTしてスキャン列を絞る","LIMIT を付けてスキャンバイト数を減らす","結果を降順に ORDER BY する"],"a":1,"e":"BigQueryは列指向で、スキャンしたバイト数（列×行）で課金されます。必要な列だけをSELECTすれば読み取り列が減りコストが直接下がります。LIMITは表示行を絞るだけでスキャンは減らず、ORDER BYやコピー後の SELECT * はコスト削減になりません。","qEn":"An analyst's query is SELECT * FROM huge_table WHERE ... but only 3 columns are needed, yet all columns are scanned, driving up cost. BigQuery on-demand billing charges by bytes scanned. What is the most direct cost improvement?","oEn":["Copy the table to a temp table, then run the same SELECT *","Explicitly SELECT only the needed columns to prune scanned columns","Add LIMIT to reduce bytes scanned","ORDER BY the results descending"],"eEn":"BigQuery is columnar and bills by bytes scanned (columns x rows). Selecting only needed columns reduces columns read and directly lowers cost. LIMIT only trims displayed rows without cutting scan, and ORDER BY or copy-then-SELECT-* don't reduce cost."},{"id":"h37","d":"D2","q":"このクエリはオンデマンド課金のプロジェクトで実行されており、無駄なスキャンが月次コストを押し上げています。データチームは、過去24か月の月次売上から今後6か月を予測したいと考えています。SQLだけで、季節性やトレンドを自動で扱う時系列予測モデルをBigQuery ML上で構築したい場合、最適なモデルタイプはどれですか。","o":["ARIMA_PLUS（時系列予測モデル）","LINEAR_REG（単純な線形回帰）","KMEANS（クラスタリング）","LOGISTIC_REG（ロジスティック回帰）"],"a":0,"e":"BigQuery MLのARIMA_PLUSは季節性・トレンド・休日効果などを自動で扱う時系列予測モデルで、月次売上の将来予測に最適です。単純な線形回帰は季節性を捉えにくく、KMEANSはクラスタリング、ロジスティック回帰は分類で時系列予測には不適です。","qEn":"The query runs in an on-demand billing project, and wasted scans inflate monthly cost. A data team wants to forecast the next 6 months from 24 months of monthly sales, building a time-series model in BigQuery ML with SQL that automatically handles seasonality and trend. Which model type is best?","oEn":["ARIMA_PLUS (time-series forecasting model)","LINEAR_REG (simple linear regression)","KMEANS (clustering)","LOGISTIC_REG (logistic regression)"],"eEn":"BigQuery ML ARIMA_PLUS automatically handles seasonality, trend, and holiday effects, ideal for forecasting monthly sales. Simple linear regression struggles with seasonality, KMEANS is clustering, and logistic regression is classification, unsuited to forecasting."},{"id":"h38","d":"D2","q":"この予測は在庫計画に用いられ、季節的な繁閑を織り込めないと発注精度が大きく損なわれます。あるBigQueryデータセットには、機微な個人情報を含む顧客テーブルがあります。アナリストには集計結果は見せたいが、生の行や特定の列（例: マイナンバー相当）は見せたくありません。基盤テーブルへの直接アクセスを与えずに制御する最適な方法はどれですか。","o":["全アナリストにベーステーブルの閲覧権限を直接付与する","テーブルをCSVで全員に配布する","データセットを公開設定にして誰でも読めるようにする","認可済みビュー（authorized view）と列レベルセキュリティで公開範囲を限定する"],"a":3,"e":"認可済みビューはベーステーブルへの直接権限を与えずに、ビュー経由で必要な集計・列だけを公開でき、列レベルセキュリティで機微列を保護できます。ベース直接権限付与やCSV全配布、公開設定は機微情報を露出させ要件に反します。","qEn":"The forecast informs inventory planning, and failing to capture seasonality badly degrades ordering accuracy. A BigQuery dataset has a customer table with sensitive PII. Analysts should see aggregates but not raw rows or certain columns (e.g., national ID). What is the best way to control access without granting direct access to the base table?","oEn":["Grant all analysts direct read on the base table","Distribute the table as CSV to everyone","Make the dataset public so anyone can read it","Use authorized views plus column-level security to limit exposure"],"eEn":"Authorized views expose only needed aggregates/columns via the view without granting direct base-table access, and column-level security protects sensitive columns. Direct grants, CSV distribution, or making it public expose PII and violate the requirement."},{"id":"h39","d":"D2","q":"この要件は個人情報保護規程に基づくもので、違反は重大なコンプライアンスリスクにつながります。あるアナリストは、広告費と売上という2つの連続変数の間に、どの程度の直線的な関連があるかを1つの数値で把握したいと考えています。因果ではなく関連の強さと向きを-1〜1で示す統計量はどれですか。","o":["標準偏差（standard deviation）","最頻値（mode）","相関係数（correlation, CORR）","中央値（median）"],"a":2,"e":"2つの連続変数の直線的関連の強さと向きを-1〜1で示すのは相関係数（BigQueryのCORR）です。相関は因果を意味しません。中央値・標準偏差・最頻値はそれぞれ代表値やばらつき・頻度の指標で、2変数間の関連度は表しません。","qEn":"This requirement stems from privacy policy, and violations pose serious compliance risk. An analyst wants a single number for how strongly two continuous variables, ad spend and revenue, are linearly related. Which statistic shows the strength and direction of association from -1 to 1 (not causation)?","oEn":["Standard deviation","Mode","Correlation coefficient (CORR)","Median"],"eEn":"The correlation coefficient (BigQuery CORR) shows the strength and direction of a linear association between two continuous variables from -1 to 1; correlation isn't causation. Median, standard deviation, and mode describe central tendency, spread, or frequency, not two-variable association."},{"id":"h40","d":"D2","q":"この分析はマーケティング投資の意思決定に用いられ、関連の強さを1つの解釈しやすい数値で伝える必要があります。回帰モデルの評価で、外れ値の影響を過度に強調せず、平均的な予測誤差を元の単位で頑健に把握したいと考えています。誤差を二乗せずに絶対値の平均を取るため大きな外れ値の影響を相対的に抑える指標はどれですか。","o":["Precision（適合率）","AUC（ROC曲線下面積）","MAE（平均絶対誤差）","RMSE（二乗平均平方根誤差）"],"a":2,"e":"MAE（平均絶対誤差）は誤差の絶対値の平均で、二乗しないため大きな外れ値の影響がRMSEより相対的に小さく、頑健に平均誤差を表します。RMSEは外れ値に敏感、Precisionは分類、AUCも分類指標で回帰の頑健な誤差評価には不適です。","qEn":"The analysis informs marketing-investment decisions and must convey association strength as one interpretable number. When evaluating a regression model, you want a robust view of average prediction error in original units without overemphasizing outliers. Which metric averages absolute errors (not squared), relatively dampening large outliers?","oEn":["Precision","AUC (area under the ROC curve)","MAE (mean absolute error)","RMSE (root mean squared error)"],"eEn":"MAE averages the absolute errors and, by not squaring, dampens large outliers relative to RMSE, giving a robust average error. RMSE is outlier-sensitive, and Precision/AUC are classification metrics unsuited to robust regression error evaluation."},{"id":"h41","d":"D2","q":"このモデルは需要予測に用いられ、一部の異常値に評価が過度に引きずられることを避けたいと考えています。マーケティングチームは、購買履歴に基づいて顧客を自然なグループに分けたいと考えていますが、事前のラベル（正解セグメント）はありません。BigQuery MLで教師なし学習により顧客セグメンテーションを行う最適なモデルはどれですか。","o":["ARIMA_PLUS で時系列予測する","KMEANS クラスタリングで教師なしにグループ化する","LOGISTIC_REG で二値分類する","LINEAR_REG で連続値を予測する"],"a":1,"e":"ラベルなしで自然なグループに分ける教師なし学習にはKMEANSクラスタリングが最適で、顧客セグメンテーションに広く使われます。ロジスティック回帰や線形回帰はラベルが必要な教師あり、ARIMA_PLUSは時系列予測でセグメンテーションには不適です。","qEn":"The model supports demand forecasting, and evaluation should not be overly dragged by a few anomalies. A marketing team wants to split customers into natural groups from purchase history, with no predefined labels (ground-truth segments). Which BigQuery ML model does unsupervised customer segmentation best?","oEn":["ARIMA_PLUS for time-series forecasting","KMEANS clustering for unsupervised grouping","LOGISTIC_REG for binary classification","LINEAR_REG to predict a continuous value"],"eEn":"For unsupervised grouping into natural clusters without labels, KMEANS clustering is best and widely used for customer segmentation. Logistic and linear regression are supervised (need labels), and ARIMA_PLUS is forecasting, unsuited to segmentation."},{"id":"h42","d":"D2","q":"この分析はデータ探索の初期段階で行われ、施策判断の前提として関係の傾向を素早く把握したいと考えています。あるデータプロバイダは、パートナー企業に対して、BigQuery上のキュレーション済みデータセットを、コピーや定期エクスポートなしにライブで安全に共有したいと考えています。データを移動させずに横断的に共有・購読できるGoogle Cloudの仕組みはどれですか。","o":["Analytics Hub でデータ共有（データエクスチェンジ/リスティング）を行う","データを毎晩CSVにしてメール添付で送る","相手にプロジェクトのオーナー権限を渡す","Transfer Appliance でデータを郵送する"],"a":0,"e":"Analytics Hub はBigQueryのデータをコピーせずにライブで安全に共有・購読できるデータエクスチェンジ機能で、パートナー間共有に最適です。CSVメールやオーナー権限譲渡はガバナンス・鮮度・セキュリティに劣り、Transfer Applianceは共有用途ではありません。","qEn":"The analysis is exploratory and aims to quickly grasp the trend of the relationship before deciding on actions. A data provider wants to share curated BigQuery datasets with partner companies live and securely, without copies or periodic exports, sharing across organizations without moving data. Which Google Cloud mechanism fits?","oEn":["Share via Analytics Hub (data exchanges/listings)","Email nightly CSVs as attachments","Grant partners project owner permissions","Mail the data with Transfer Appliance"],"eEn":"Analytics Hub is a data-exchange feature to share and subscribe to live BigQuery data securely without copies, ideal for partner sharing. CSV emails or granting owner rights are worse on governance, freshness, and security, and Transfer Appliance isn't for sharing."},{"id":"h43","d":"D2","q":"このデータは第三者に対する有償提供の基盤となるため、鮮度とセキュリティの両立が事業上の要件です。分類モデルでは、確率スコアに対する判定しきい値を上げると、陽性と判定する件数が減ります。この操作をした場合、一般にPrecisionとRecallはどのように変化しますか。トレードオフを正しく説明しているのはどれですか。","o":["PrecisionもRecallも必ず同時に上がる","PrecisionもRecallも必ず同時に下がる","しきい値はPrecisionにもRecallにも影響しない","Precisionは上がりやすく、Recallは下がりやすい"],"a":3,"e":"しきい値を上げると陽性判定が厳しくなり、誤検知が減ってPrecisionは上がりやすい一方、拾える陽性が減ってRecallは下がりやすくなります。両者は一般にトレードオフ関係にあり、同時に必ず上下する、または無関係という説明は誤りです。","qEn":"The data underpins a paid third-party offering, so freshness and security together are business requirements. In a classifier, raising the decision threshold on the probability score reduces the number predicted positive. Generally, how do Precision and Recall change? Which correctly describes the trade-off?","oEn":["Both Precision and Recall always rise together","Both Precision and Recall always fall together","The threshold affects neither Precision nor Recall","Precision tends to rise while Recall tends to fall"],"eEn":"Raising the threshold makes positive calls stricter, reducing false positives so Precision tends to rise, while catching fewer positives so Recall tends to fall. They generally trade off; claims that both always move together or are unaffected are wrong."},{"id":"h44","d":"D2","q":"この評価はモデルの運用しきい値を決める議論の一部で、指標間のトレードオフを正しく理解する必要があります。アナリストは、月次・地域別の売上テーブルを、行に月・列に地域を配置したクロス集計（ピボット）形式でレポートに表示したいと考えています。BigQuery SQLで集計しつつ行を列方向に展開する最適な構文はどれですか。","o":["ORDER BY を複数付けて並べ替えるだけ","DISTINCT で重複を除くだけ","LIMIT で表示件数を絞るだけ","PIVOT 演算子を使って地域を列方向に展開する"],"a":3,"e":"BigQueryのPIVOT演算子は、集計しながら特定列の値（地域）を列方向に展開してクロス集計を作れます。ORDER BYやDISTINCT、LIMITは並び替え・重複除去・件数制限であり、行を列に変換するピボット表示はできません。","qEn":"This evaluation is part of deciding the operating threshold, requiring correct understanding of metric trade-offs. An analyst wants to display a monthly-by-region sales table as a cross-tab (pivot) with months in rows and regions in columns. Which BigQuery SQL construct aggregates while turning rows into columns?","oEn":["Just add multiple ORDER BY clauses to sort","Just use DISTINCT to remove duplicates","Just use LIMIT to cap the row count","Use the PIVOT operator to expand regions into columns"],"eEn":"BigQuery's PIVOT operator aggregates while spreading a column's values (regions) across columns to build a cross-tab. ORDER BY, DISTINCT, and LIMIT sort, dedupe, or cap rows and can't turn rows into columns."},{"id":"h45","d":"D2","q":"このレポートは月次の経営レビューで配布され、地域と期間を一目で比較できる表形式が求められています。データサイエンティストは、BigQuery MLで学習と推論の両方に同じ特徴量前処理（標準化やバケット化など）を適用し、予測時に前処理漏れを防ぎたいと考えています。前処理をモデルに焼き込み、推論時に自動適用する最適な仕組みはどれですか。","o":["予測のたびに前処理を忘れないよう手順書で運用する","前処理はせず生の特徴量をそのまま使う","TRANSFORM 句でモデル内に前処理を定義し推論時も自動適用する","学習前に手動でSQL変換し、推論時は別途書き直す"],"a":2,"e":"BigQuery MLのTRANSFORM句は、標準化やバケット化などの前処理をモデル定義に含め、学習・推論で自動適用するため前処理漏れ（トレーニング/サービングスキュー）を防ぎます。手動再記述や手順書運用はミスを招き、前処理省略は精度を損ないます。","qEn":"The report is distributed at monthly executive reviews and needs a tabular form comparing region and period at a glance. A data scientist wants to apply the same feature preprocessing (standardization, bucketization, etc.) to both training and inference in BigQuery ML, avoiding missed preprocessing at prediction time. Which mechanism bakes preprocessing into the model and applies it automatically at inference?","oEn":["Rely on a runbook to remember preprocessing on each prediction","Skip preprocessing and use raw features","Define preprocessing in the TRANSFORM clause so it auto-applies at inference","Transform manually in SQL before training and rewrite it for inference"],"eEn":"BigQuery ML's TRANSFORM clause embeds preprocessing (standardization, bucketization) in the model and applies it automatically for training and inference, preventing missed preprocessing (training/serving skew). Manual rewrites or runbooks invite errors, and skipping preprocessing hurts accuracy."},{"id":"h46","d":"D2","q":"学習と推論で処理が一致しないと精度が劣化するため、再現性のある一貫した前処理が不可欠だと考えられています。このモデルは頻繁に再学習・再デプロイされ、前処理の不整合がトレーニング/サービングスキューを生む懸念があります。二値分類モデルを、しきい値に依存せずに全体的な判別性能で比較したいと考えています。陽性・陰性の順位付け能力を、しきい値を動かしながら評価する代表的な指標はどれですか。","o":["平均絶対誤差（MAE）","ROC-AUC（ROC曲線下面積）","単一しきい値でのAccuracyのみ","RMSE"],"a":1,"e":"ROC-AUCは全しきい値にわたる真陽性率と偽陽性率の関係を要約し、しきい値に依存しない順位付け（判別）性能を評価できます。単一しきい値のAccuracyは不均衡データで誤解を招き、RMSEやMAEは回帰指標で分類の総合判別評価には不適です。","qEn":"Mismatched training and inference processing degrades accuracy, so reproducible, consistent preprocessing is essential. The model is retrained and redeployed often, raising concern that preprocessing mismatch causes training/serving skew. You want to compare binary classifiers by overall discrimination independent of threshold, evaluating their ability to rank positives above negatives across thresholds. Which is a standard metric?","oEn":["Mean absolute error (MAE)","ROC-AUC (area under the ROC curve)","Only Accuracy at a single threshold","RMSE"],"eEn":"ROC-AUC summarizes true-positive vs false-positive rates across all thresholds, evaluating threshold-independent ranking (discrimination). Single-threshold Accuracy misleads on imbalanced data, and RMSE/MAE are regression metrics unsuited to overall classification discrimination."},{"id":"h47","d":"D2","q":"この比較は複数モデルの選定に用いられ、運用しきい値を固定せずに総合的な判別力を評価する必要があります。あるダッシュボードは日次で十分な鮮度で構いませんが、閲覧のたびにBigQueryへ重いクエリが飛び、コストがかさんでいます。Looker Studioで同一クエリの再実行を抑え、コストとレイテンシを下げる最も直接的な設定はどれですか。","o":["データ抽出やキャッシュ（データの更新頻度設定）を活用して再クエリを減らす","毎回リフレッシュを強制してキャッシュを無効化する","レポートの色数を減らして軽量化する","グラフの種類を棒から円に変えて負荷を下げる"],"a":0,"e":"Looker Studioのキャッシュやデータ抽出（Extract）、更新頻度の設定を使えば、同一クエリの再実行を抑え、BigQueryへのクエリ回数・コスト・レイテンシを下げられます。強制リフレッシュはキャッシュを無効化し逆効果、色数やグラフ種類の変更はクエリコストと無関係です。","qEn":"The comparison guides model selection and must assess overall discrimination without fixing an operating threshold. A dashboard only needs daily freshness, but every view fires a heavy BigQuery query, driving up cost. In Looker Studio, which setting most directly reduces re-running the same query to cut cost and latency?","oEn":["Use data extract/caching (data freshness settings) to reduce re-queries","Force a refresh every time to disable caching","Reduce the number of colors to lighten the report","Change charts from bar to pie to lower load"],"eEn":"Looker Studio caching, data extract, and freshness settings reduce re-running the same query, cutting BigQuery query count, cost, and latency. Forcing refresh disables caching (counterproductive), and changing colors or chart types is unrelated to query cost."},{"id":"h48","d":"D2","q":"この不均衡は業務データでは一般的で、単純な正解率が意思決定を誤らせる危険性が指摘されています。アナリストは、複数の指標を単一のスコアカードで示すのではなく、地域ごとの売上を地図上の色の濃淡で直感的に比較し、地理的な偏りを把握したいと考えています。この目的に最も適した可視化の種類はどれですか。","o":["塗り分け地図（コロプレスマップ）","単純なテキストの表","1つの数値を示すスコアカード","時系列の折れ線グラフ"],"a":0,"e":"地域ごとの値を地図上の色の濃淡で比較し地理的偏りを見るにはコロプレス（塗り分け）マップが最適です。テキストの表は地理的直感に乏しく、スコアカードは単一値、折れ線は時間推移向けで地域比較の地理表現には適しません。","qEn":"Such imbalance is common in business data, and simple accuracy risks misleading decisions. An analyst wants to intuitively compare regional sales by color shading on a map and grasp geographic skew, rather than showing several metrics on a single scorecard. Which visualization type fits best?","oEn":["A choropleth (shaded region) map","A plain text table","A scorecard showing one number","A time-series line chart"],"eEn":"To compare regional values by color shading on a map and see geographic skew, a choropleth map is best. A text table lacks geographic intuition, a scorecard shows one value, and a line chart is for time trends, not geographic regional comparison."},{"id":"h49","d":"D2","q":"この課題はモデルの本番採用可否を左右し、適切な指標選択が評価の信頼性を決めると認識されています。あるチームは、BigQuery MLのロジスティック回帰で解約予測モデルを作りましたが、データの90%が非解約で偏っています。Accuracyが高く見えても実運用で解約者をほとんど捕捉できていません。この不均衡データで解約者の捕捉力を正しく評価する指標の組み合わせはどれですか。","o":["Accuracy だけを見て判断する","学習データのサイズだけを見る","特徴量の数だけを見る","Precision・Recall（およびF1やPR-AUC）で少数クラスを評価する"],"a":3,"e":"90%が多数クラスの不均衡データでは、全て非解約と予測してもAccuracyは高く見えます。少数クラス（解約者）の捕捉はPrecision・Recall（およびF1やPR-AUC）で評価すべきです。Accuracyのみやデータ量・特徴量数だけでは不均衡下の性能を正しく測れません。","qEn":"This issue determines production adoption, and choosing the right metric is recognized as decisive for evaluation reliability. A team built a churn model with BigQuery ML logistic regression, but 90% of data is non-churn. Accuracy looks high yet it captures almost no churners in production. Which metrics correctly evaluate churner capture on this imbalanced data?","oEn":["Look only at Accuracy","Look only at the training data size","Look only at the number of features","Precision and Recall (and F1 or PR-AUC) to assess the minority class"],"eEn":"With 90% majority class, predicting all non-churn still yields high Accuracy. Minority-class (churner) capture should be judged by Precision/Recall (and F1 or PR-AUC). Accuracy alone, data size, or feature count can't correctly measure performance under imbalance."},{"id":"h50","d":"D3","q":"小売企業のデータ基盤チームは、販売・在庫・広告の各ソースを統合する日次ETLを運用しており、処理は20以上のタスクが多段に依存し合う。運用要件として、タスク失敗時の自動リトライ、障害復旧後に過去日付をまとめて再処理するバックフィル、タスクごとのSLA監視が必須である。チームには既にApache Airflowの実装・運用知見がある。これらを運用負荷を最小化しつつ満たす手段として、最も適切なものはどれか。","o":["Workflowsで全タスクを1本のYAMLに直列記述し、失敗時は手動で再実行する","Cloud Schedulerで各タスクを個別に時刻起動し、順序はスクリプトで制御する","Cloud Composer上でDAGとして実装し、依存関係・リトライ・バックフィル・SLAを定義する","Pub/Subメッセージを各タスクが購読し、疎結合に連鎖させる"],"a":2,"e":"複雑な多段依存・リトライ・バックフィル・SLA監視という要件はAirflow(DAG)の中核機能であり、フルマネージドのCloud Composerが最適。既存のAirflow知見も活かせる。Cloud Schedulerは単純な時刻起動のみで依存管理ができない。Workflowsは軽量サーバーレス向きで、この規模の依存・バックフィルには不向き。Pub/Subの連鎖は監視・バックフィルが困難。","qEn":"A nationwide retailer's data platform team runs a daily ETL that integrates sales, inventory, and advertising sources, with 20+ tasks arranged in multi-level dependencies. Operational requirements include automatic retries on task failure, backfill to reprocess past dates in bulk after recovery, and per-task SLA (deadline) monitoring. The team already has Apache Airflow implementation and operations expertise and wants to limit extra learning cost. Which orchestration option best meets these requirements while minimizing operational overhead?","oEn":["Write all tasks serially in one Workflows YAML and re-run manually on failure","Trigger each task individually by time with Cloud Scheduler and control ordering via scripts","Implement as a DAG on Cloud Composer, defining dependencies, retries, backfill, and SLAs","Have each task subscribe to Pub/Sub messages and chain them loosely"],"eEn":"Complex multi-level dependencies, retries, backfill, and SLA monitoring are core Airflow (DAG) features, so fully managed Cloud Composer is the best fit and reuses existing Airflow skills. Cloud Scheduler only triggers by time with no dependency management. Workflows suits lightweight serverless flows, not this scale of dependencies/backfill. Pub/Sub chaining makes monitoring and backfill hard."},{"id":"h51","d":"D3","q":"あるSaaSスタートアップは、Cloud Run上の3つのマイクロサービスAPIを定められた順序で呼び出し、各レスポンスに応じて後続処理を分岐させる軽量な処理を、1時間ごとに定期実行したい。各呼び出しは数秒で完了し状態を持たない。少人数のチームで、Cloud ComposerやAirflowのように常時稼働する重厚な基盤を運用する余力はなく、アイドル時のコストも極力ゼロに近づけたい。この要件に最も適したサーバーレスな構成はどれか。","o":["Cloud Composer環境を常時起動してDAGで3つのAPIを呼び出す","BigQueryのスケジュールクエリで外部APIを呼び出す","Dataflowストリーミングジョブで3つのAPIを順に呼び出す","Workflowsで3つのAPIをステップ定義し、Cloud Schedulerで1時間ごとに起動する"],"a":3,"e":"軽量なサーバーレスのステップ実行・分岐にはWorkflowsが最適で、実行時のみ課金され常時起動コストがない。定期起動はCloud Schedulerと組み合わせる。Cloud Composerは環境が常時稼働しコストが高く、この軽量用途には過剰。Dataflowはデータ並列処理用でAPIオーケストレーション向きでない。BigQueryスケジュールクエリはSQL実行用で外部API呼び出しには不向き。","qEn":"A SaaS startup wants to run a lightweight process hourly that calls three microservice APIs on Cloud Run in a fixed order and branches on the content of each response. Each call finishes in seconds and is stateless. The small team lacks the capacity to operate always-on heavy infrastructure like Cloud Composer or Airflow and wants idle-time cost as close to zero as possible. Which serverless setup best fits this requirement?","oEn":["Keep a Cloud Composer environment always on and call the three APIs via a DAG","Call the external APIs from a BigQuery scheduled query","Call the three APIs sequentially from a Dataflow streaming job","Define the three API calls as steps in Workflows and trigger hourly with Cloud Scheduler"],"eEn":"Workflows is ideal for lightweight serverless step execution and branching, billed per execution with no always-on cost, combined with Cloud Scheduler for periodic triggering. Cloud Composer keeps an environment always running and is overkill/costly here. Dataflow is for parallel data processing, not API orchestration. BigQuery scheduled queries run SQL, not external API calls."},{"id":"h52","d":"D3","q":"データアナリストのチームは、BigQuery内のデータマート向けに、数十のSQLモデルを依存関係を保ちながら順番に変換・更新したい。各テーブルには品質を担保するテスト(アサーション)とドキュメントを紐付け、変換ロジックはGitでバージョン管理してレビュー可能にしたい。チームはSQLファーストで作業したく、Pythonでのコーディングは最小限にとどめたい。この宣言的なSQL変換管理に最も適したBigQueryネイティブのツールはどれか。","o":["Cloud Composerで各SQLをPythonOperatorとして書く","Dataflowで変換パイプラインを実装する","DataformでSQLXの定義と依存関係・アサーションを管理する","Cloud Data Fusionでビジュアルにパイプラインを組む"],"a":2,"e":"BigQuery内のSQL変換を依存グラフ・テスト(assertions)・ドキュメント付きで宣言的に管理し、Gitと連携できるのはDataformが最適。SQLファースト志向にも合致する。Cloud ComposerはSQLを手続き的に書く必要があり冗長。Dataflowはコード中心のデータ処理でSQL変換管理には過剰。Data FusionはビジュアルETL向きで、SQLファースト・Git連携の宣言的変換管理には最適でない。","qEn":"A team of data analysts wants to transform and update dozens of SQL models for a BigQuery data mart in sequence while preserving their mutual dependencies. Each table should have quality-assuring tests (assertions) and documentation attached, with transformation logic version-controlled and reviewable in Git. The team prefers to work SQL-first and keep Python coding to a minimum. Which BigQuery-native tool best fits this declarative SQL transformation management?","oEn":["Write each SQL as a PythonOperator in Cloud Composer","Implement the transformation pipeline in Dataflow","Manage SQLX definitions, dependencies, and assertions in Dataform","Build the pipeline visually in Cloud Data Fusion"],"eEn":"Dataform is best for declaratively managing in-BigQuery SQL transformations with a dependency graph, assertions (tests), and documentation, integrating with Git, matching the SQL-first preference. Cloud Composer requires procedural SQL wrapping and is verbose. Dataflow is code-centric and overkill for SQL transformation management. Data Fusion is visual ETL, not ideal for SQL-first declarative Git-based management."},{"id":"h53","d":"D3","q":"あるデータチームは、パートナー企業がCloud Storageバケットへ不定期にアップロードするCSVファイルを取り込むパイプラインを運用している。ファイルの到着タイミングは予測できず、アップロードのたびに可能な限り遅延なく取り込み処理を開始したい。定期ポーリングによる待ち時間や無駄な実行コストは避けたく、オブジェクト作成をきっかけにイベント駆動で処理を起動したい。この要件に最も適したGoogle Cloudの構成はどれか。","o":["Cloud Schedulerで5分ごとにバケットをポーリングして新規ファイルを探す","BigQueryの外部テーブルを定期的に再スキャンする","Cloud Composerのタイムトリガーで毎時DAGを起動する","EventarcでCloud Storageのオブジェクト作成イベントを受けてCloud RunやWorkflowsを起動する"],"a":3,"e":"オブジェクト作成という単一イベントで即時に処理を起動するにはEventarc(内部でPub/SubやCloud Audit Logs/GCS通知を利用)が最適で、Cloud RunやWorkflowsをターゲットにできる。ポーリング不要で遅延が小さい。Cloud Schedulerのポーリングは遅延とコストが生じる。Composerのタイムトリガーは不規則な到着に即応できない。BigQuery外部テーブルの再スキャンはイベント駆動ではない。","qEn":"A data team runs a pipeline that ingests CSV files uploaded irregularly by a partner company to a Cloud Storage bucket. Arrival timing is unpredictable, and they want ingestion to start with as little delay as possible on each upload. They want to avoid the latency and wasted run cost of periodic polling, triggering processing in an event-driven way on object creation. Which Google Cloud setup best fits this requirement?","oEn":["Poll the bucket every 5 minutes with Cloud Scheduler to find new files","Periodically re-scan a BigQuery external table","Trigger a DAG hourly on a time schedule in Cloud Composer","Use Eventarc to trigger Cloud Run or Workflows on Cloud Storage object-create events"],"eEn":"To start processing immediately on a single object-create event, Eventarc (using Pub/Sub / Cloud Audit Logs / GCS notifications underneath) is best and can target Cloud Run or Workflows, with no polling and low latency. Cloud Scheduler polling adds latency and cost. Composer time triggers can't react promptly to irregular arrivals. Re-scanning a BigQuery external table is not event-driven."},{"id":"h54","d":"D3","q":"データエンジニアが新しく作成したAirflowのDAGは、start_dateが90日前に設定され、日次でスケジュールされている。本番環境へデプロイした直後、Airflowが過去90日分の実行を一斉にスケジュールしてしまい、ワーカーが飽和して環境全体が過負荷に陥った。今後はこのような一括の過去実行を防ぎつつ、必要になったときだけ特定の期間を明示的に選んで再実行できるようにしたい。この状況への対応として最も適切なものはどれか。","o":["schedule_interval を None にしてスケジュール実行を完全にやめる","start_date を毎回当日に手動で書き換える","DAGの catchup を False に設定し、必要時に対象期間を指定してバックフィルを実行する","max_active_runs を無制限にして一気に処理を終わらせる"],"a":2,"e":"catchup=False にすると過去分の自動一括実行(キャッチアップ)を防げる。必要な過去期間だけは backfill コマンドで明示的に実行できるため要件に合致。start_dateの手動書き換えは運用が煩雑でバックフィル不能。schedule_intervalをNoneにすると定期実行自体が失われる。max_active_runsを無制限にすると過負荷が悪化する。","qEn":"A data engineer's newly created Airflow DAG has start_date set to 90 days ago and is scheduled daily. Immediately after deploying to production, Airflow scheduled all 90 days of past runs at once, saturating the workers and overloading the whole environment. Going forward they want to prevent such bulk historical runs while still being able to explicitly select and re-run specific periods only when needed. What is the most appropriate response to this situation?","oEn":["Set schedule_interval to None to stop scheduled runs entirely","Manually rewrite start_date to today each time","Set the DAG's catchup to False and run backfill for the target period when needed","Set max_active_runs to unlimited to finish everything at once"],"eEn":"Setting catchup=False prevents automatic bulk catch-up of past runs, while backfill can explicitly run only the needed historical period, meeting the requirement. Manually rewriting start_date is cumbersome and prevents backfill. Setting schedule_interval to None loses periodic scheduling entirely. Unlimited max_active_runs worsens the overload."},{"id":"h55","d":"D3","q":"あるDAGのタスクは外部SaaSのREST APIを呼び出してデータを取得するが、相手側の一時的なネットワーク不調やレート制限により時々失敗する。恒久的な障害でなければ、数分後に再試行すればたいてい成功する。運用チームは、こうした一過性の失敗を人手の介入なしに自動で吸収しつつ、恒久的な障害についてはリトライ上限を超えた時点で確実にアラートを受け取りたい。Airflowでの設定として最も適切なものはどれか。","o":["DAG全体を1分ごとに再スケジュールして毎回最初からやり直す","失敗したタスクを try/except で握りつぶし常に成功として扱う","タスクに retries と retry_delay(指数バックオフ)を設定し、上限超過でアラートする","タスクのタイムアウトを無限にして成功するまで待つ"],"a":2,"e":"一時障害はタスクレベルの retries と retry_delay(指数バックオフ推奨)で自動的に吸収でき、リトライ上限を超えたら失敗として通知・アラートできる。これが要件に最適。例外を握りつぶすと恒久障害が検知できず、プロジェクト規約にも反する。DAG全体の再実行は非効率で成功済みタスクも巻き戻す。タイムアウト無限は障害時にリソースを占有し続ける。","qEn":"A DAG task calls an external SaaS REST API to fetch data but occasionally fails due to the other side's transient network issues or rate limiting. If it is not a permanent failure, retrying a few minutes later usually succeeds. The ops team wants to automatically absorb such transient failures without human intervention, while reliably receiving an alert for permanent failures once the retry limit is exceeded. Which Airflow setting is most appropriate?","oEn":["Reschedule the whole DAG every minute and restart from the beginning each time","Swallow failed tasks with try/except and always treat them as success","Set retries and retry_delay (exponential backoff) on the task, and alert when the limit is exceeded","Set the task timeout to infinite and wait until it succeeds"],"eEn":"Transient failures are absorbed automatically via task-level retries and retry_delay (exponential backoff recommended), and once retries are exhausted the task fails and can alert, meeting the requirement. Swallowing exceptions hides permanent failures and violates project conventions. Re-running the whole DAG is inefficient and rolls back completed tasks. Infinite timeout holds resources during failures."},{"id":"h56","d":"D3","q":"あるデータエンジニアは、パラメータ化されたDataflowのバッチジョブをFlexテンプレートとして用意しており、これを毎晩決まった時刻に自動実行したい。実行のたびに入力データのGCSパスと出力先を動的に変えて渡す必要がある。この定期実行のためだけにCloud Composerのような常時稼働の基盤を新設して維持するのはコスト面で避けたい。最小の追加コストで定期起動を実現する組み合わせとして最も適切なものはどれか。","o":["BigQueryスケジュールクエリからDataflowを呼び出す","Compute EngineのcronでローカルのDataflow SDKを毎晩起動する","Cloud SchedulerからDataflow Flexテンプレートを起動し、実行ごとにパラメータを渡す","Cloud Composerを常時起動してテンプレートを起動するためだけに使う"],"a":2,"e":"Dataflow Flexテンプレートは、Cloud Scheduler(HTTP/APIターゲット)から起動時パラメータを渡して定期実行でき、常時稼働の基盤が不要でコスト効率が良い。Compute EngineのcronはVM管理が発生し可用性・運用負荷が高い。BigQueryスケジュールクエリはSQL用でDataflow起動に不適。Composerを起動目的だけで常時稼働させるのは過剰コスト。","qEn":"A data engineer has a parameterized Dataflow batch job packaged as a Flex Template and wants to run it automatically at a fixed time every night, passing a dynamically varying input GCS path and output destination per run. For cost reasons they want to avoid standing up and maintaining always-on orchestration infrastructure like Cloud Composer just for this scheduling. Which combination best achieves scheduled launching with the least added cost?","oEn":["Call Dataflow from a BigQuery scheduled query","Run the local Dataflow SDK nightly via cron on a Compute Engine VM","Launch the Dataflow Flex Template from Cloud Scheduler, passing parameters per run","Keep Cloud Composer always on solely to launch the template"],"eEn":"A Dataflow Flex Template can be launched on a schedule from Cloud Scheduler (HTTP/API target) with per-run parameters, needing no always-on infrastructure and being cost-efficient. Compute Engine cron adds VM management and operational burden. BigQuery scheduled queries are for SQL, not launching Dataflow. Keeping Composer always on just to launch is unnecessary cost."},{"id":"h57","d":"D3","q":"あるDAGは、社内の別チームが管理する外部のDAGが特定パーティションのデータ生成を完了してから、はじめて後続の集計処理を実行できる。外部処理の完了時刻は日によって大きく変動し、固定の時刻を前提にはできない。データエンジニアは、外部処理の完了状態をポーリングで待機し、完了を検知した時点で自動的に後続タスクへ処理を進める仕組みを実装したい。Airflowで最も適切な仕組みはどれか。","o":["固定の sleep で外部処理が終わるであろう時間だけ待つ","schedule_interval を極端に遅い時刻にして衝突を避ける","毎回タスクを失敗させてリトライで偶然成功するのを待つ","Sensor(例: 外部タスク/オブジェクトの存在を待つセンサー)で完了を検知してから後続を実行する"],"a":3,"e":"外部の完了を待って後続を進めるには、条件成立まで待機するSensor(ExternalTaskSensorやGCSObjectExistenceSensorなど)が最適で、完了時刻の変動にも柔軟に対応できる。固定sleepは変動に対応できず脆い。失敗リトライ頼みは不確実で無駄が多い。scheduleを遅らせるのは根本的な依存解決にならない。","qEn":"A DAG can run its downstream aggregation only after an external DAG owned by another team finishes producing data for a specific partition. The external completion time varies greatly day to day, so a fixed time cannot be assumed. The engineer wants to implement a mechanism that polls and waits for the external completion state and automatically advances to downstream tasks once completion is detected. Which Airflow mechanism is most appropriate?","oEn":["Wait a fixed sleep for however long the external process usually takes","Set schedule_interval to a very late time to avoid collisions","Fail the task each time and hope a retry happens to succeed","Use a Sensor (e.g., waiting for an external task/object to exist) to detect completion, then run downstream"],"eEn":"To wait for external completion before proceeding, a Sensor (e.g., ExternalTaskSensor or GCSObjectExistenceSensor) that waits until a condition holds is ideal and adapts to varying completion times. A fixed sleep is brittle. Relying on failure retries is unreliable and wasteful. Delaying the schedule does not truly resolve the dependency."},{"id":"h58","d":"D3","q":"あるセキュリティ運用チームは、Cloud Audit Logsに『特定の機密性の高いBigQueryデータセットに対するテーブル削除操作』が記録された瞬間に、直ちに調査・通知パイプラインを起動したい。定期的にログをスキャンする方式では検知が遅れるため避けたく、監査ログの特定イベントを条件にサーバーレスなターゲット(Cloud RunやWorkflows)を即時に起動できるマネージドな仕組みを求めている。最も適切な手段はどれか。","o":["Cloud Loggingのログをエクスポートしたバケットを毎時スキャンする","BigQueryのINFORMATION_SCHEMAをComposerで毎晩集計する","Cloud Schedulerで定期的に監査ログをクエリして差分を探す","EventarcでCloud Audit LogsのイベントをフィルタしCloud Run/Workflowsを起動する"],"a":3,"e":"Cloud Audit Logsの特定イベントを条件にサーバーレスターゲットを即時起動するにはEventarcが最適で、メソッド名やリソースでフィルタしCloud RunやWorkflowsを起動できる。ログをエクスポートして毎時スキャンやスケジュールクエリでは遅延が大きくイベント駆動でない。ComposerでのINFORMATION_SCHEMA集計はリアルタイム性がない。","qEn":"A security operations team wants to immediately trigger an investigation and notification pipeline the moment Cloud Audit Logs record a 'table deletion on a specific highly sensitive BigQuery dataset.' They want to avoid periodic log scanning because it delays detection, and instead seek a managed mechanism that can immediately trigger a serverless target (Cloud Run or Workflows) conditioned on a specific audit log event. Which is the most appropriate means?","oEn":["Scan a bucket exporting Cloud Logging logs every hour","Aggregate BigQuery INFORMATION_SCHEMA nightly via Composer","Periodically query audit logs with Cloud Scheduler to find diffs","Use Eventarc to filter Cloud Audit Logs events and trigger Cloud Run/Workflows"],"eEn":"To trigger a serverless target immediately on a specific Cloud Audit Logs event, Eventarc is best, filtering by method name/resource to invoke Cloud Run or Workflows. Exporting logs and hourly scanning or scheduled queries add latency and aren't event-driven. Aggregating INFORMATION_SCHEMA via Composer is not real-time."},{"id":"h59","d":"D3","q":"あるCloud Composer環境には、上流の取り込みDAGと下流の日次集計DAGがある。下流のDAGは、上流のDAGが当日分のデータ取り込みを正常に完了したときにだけ実行されるべきだが、上流の完了時刻は日によって変動する。データエンジニアは、単なる時刻オフセットではなく、データの準備が完了したという事実を基準にして、DAG間の依存を疎結合に表現したい。現代的なAirflowで推奨されるアプローチとして最も適切なものはどれか。","o":["下流DAGのschedule_intervalを上流より少し遅らせて時間で暗黙依存させる","下流DAGを手動トリガーのみにして自動実行をやめる","2つのDAGを1つに統合して全部を毎回実行する","AirflowのDataset(データ更新)による依存、または上流完了を待つセンサーで明示的に連携する"],"a":3,"e":"データ準備完了を基準にDAG間を連携する現代的な方法は、Airflowのデータセット(Dataset)駆動スケジューリングや、上流完了を待つExternalTaskSensorで明示的に依存を表現することである。時間差での暗黙依存は完了時刻の変動に弱く不整合を招く。1つに統合すると再利用性・独立運用が損なわれる。手動トリガー化は自動化要件を満たさない。","qEn":"A Cloud Composer environment has an upstream ingestion DAG and a downstream daily-aggregation DAG. The downstream DAG should run only when the upstream DAG has successfully completed today's ingestion, but the upstream completion time varies from day to day. The engineer wants to express the inter-DAG dependency loosely based on the fact that the data is ready, rather than on a mere time offset. Which modern Airflow approach is most appropriate?","oEn":["Set the downstream schedule_interval slightly later than upstream to imply a time-based dependency","Make the downstream DAG manual-trigger only and stop auto-running","Merge the two DAGs into one and run everything each time","Use Airflow Datasets (data updates) or a sensor waiting on upstream completion to link them explicitly"],"eEn":"The modern way to link DAGs on data readiness is Airflow Dataset-driven scheduling or an ExternalTaskSensor waiting for upstream completion, expressing the dependency explicitly. Time-offset implicit dependency is fragile to varying completion times and risks inconsistency. Merging into one DAG loses reusability/independent operation. Manual-only triggering fails the automation requirement."},{"id":"h60","d":"D3","q":"あるビジネスアナリストは、BigQuery上のあるレポート用テーブルを、毎朝6時に集計クエリで洗い替え更新するだけの単純な定期処理を実現したい。処理は単一のSQLで完結し、他タスクへの依存関係もなく、外部システムのAPI呼び出しも一切必要ない。専任のエンジニアはおらず、Cloud Composerのような追加基盤を新たに構築・運用することは避けたい。最小コスト・最小構成でこの定期実行を実現する方法として、最も適切なものはどれか。","o":["Cloud Composerを新設してDAGにクエリを1つ書く","Dataflowテンプレートで集計を実装して定時起動する","Workflowsで1ステップのフローを作りCloud Schedulerで起動する","BigQueryのスケジュールクエリで毎朝6時に実行するよう設定する"],"a":3,"e":"依存も外部呼び出しもない単一クエリの定期実行は、BigQueryネイティブのスケジュールクエリで完結し、追加基盤ゼロ・最小コストで実現できる。Composerは環境コストが高く単一クエリには過剰。Workflows+Schedulerは可能だがBigQuery内で完結する方が簡潔。Dataflowは分散処理用でSQL集計には過剰。","qEn":"A business analyst wants a simple recurring job that just refreshes a BigQuery reporting table with an aggregation query every morning at 6 AM. The job is completed by a single SQL statement, has no dependencies on other tasks, and requires no external system API calls at all. There is no dedicated engineer, and they want to avoid building and operating additional infrastructure like Cloud Composer. Which approach best achieves this scheduled run with minimal cost and setup?","oEn":["Stand up Cloud Composer and write a single query in a DAG","Implement the aggregation as a Dataflow template on a schedule","Create a one-step Workflows flow triggered by Cloud Scheduler","Configure a BigQuery scheduled query to run daily at 6 AM"],"eEn":"A single query on a schedule with no dependencies or external calls is fully handled by a BigQuery-native scheduled query, with zero extra infrastructure and minimal cost. Composer has environment cost and is overkill for one query. Workflows+Scheduler works but staying inside BigQuery is simpler. Dataflow is for distributed processing, overkill for a SQL aggregation."},{"id":"h61","d":"D3","q":"あるチームは、複数の外部APIを順番に呼び出す処理をWorkflowsで実装している。途中のあるAPI呼び出しが、相手側の一時的な過負荷により時々HTTP 503を返す。恒久的な障害ではないため、少し待ってから再試行すればたいてい成功する。チームは、ワークフロー全体を最初からやり直すことなく、失敗したそのステップだけを安全に自動再試行して処理を継続させたい。Workflowsでの実装として最も適切なものはどれか。","o":["失敗時にワークフローを最初から全部やり直す","エラーを無視して次のステップへ常に進む","ステップに retry ポリシー(バックオフと再試行対象条件)を定義する","Cloud Schedulerでワークフロー全体を数分おきに多重起動する"],"a":2,"e":"Workflowsはステップ単位で retry ポリシー(バックオフ、再試行対象のエラーコード指定)を定義でき、一時的な503のみを安全に再試行してワークフロー全体を止めない。エラー無視はデータ不整合を招く。全体やり直しは非効率で副作用の恐れ。多重起動は重複実行や競合を起こす。","qEn":"A team implements a process that calls several external APIs in sequence using Workflows. One mid-flow API call sometimes returns HTTP 503 due to the other side's transient overload. Since it is not a permanent failure, retrying after a short wait usually succeeds. The team wants to safely auto-retry only that failed step and continue processing, without restarting the entire workflow from the beginning. Which Workflows implementation is most appropriate?","oEn":["Restart the entire workflow from the beginning on failure","Ignore the error and always proceed to the next step","Define a retry policy (backoff and which errors to retry) on the step","Multi-trigger the whole workflow every few minutes via Cloud Scheduler"],"eEn":"Workflows lets you define a per-step retry policy (backoff, which error codes to retry), safely retrying only transient 503s without stopping the whole workflow. Ignoring errors risks data inconsistency. Restarting the whole flow is inefficient and risks side effects. Multi-triggering causes duplicate runs and contention."},{"id":"h62","d":"D3","q":"あるECサイトは、Pub/Subに届く注文確定イベントをリアルタイムに処理し、集計テーブルを継続的に更新したい。イベントは平常時でも秒間数千件に達し、セール時にはさらに大きなスパイクが発生する。処理は負荷に応じて自動的にスケールし、重複や欠損を極力抑えてBigQueryへ書き込まれる必要がある。この常時稼働のストリーミング取り込みパイプラインとして、最も適したGoogle Cloudの構成はどれか。","o":["Cloud Schedulerで5分ごとにPub/Subをまとめて読み出すバッチ処理","Workflowsで無限ループを回してメッセージを1件ずつ処理する","Composerで毎分DAGを起動してPub/Subをドレインする","DataflowのストリーミングパイプラインでPub/Subを購読しBigQueryへ書き込む"],"a":3,"e":"秒間数千件・スパイクありのストリーミングをスケーラブルに処理しBigQueryへ書き込むにはDataflow(Apache Beam)のストリーミングが最適で、オートスケールと厳密な処理保証を備える。Schedulerの5分バッチはリアルタイム性がない。Composerの毎分DAGはオーバーヘッドが大きくスパイクに弱い。Workflowsの逐次処理は高スループット処理に不向き。","qEn":"An e-commerce site wants to process order-confirmation events arriving in Pub/Sub in real time and continuously update aggregation tables. Events reach thousands per second even under normal load and spike much higher during sales. Processing must scale automatically with load and write to BigQuery while minimizing duplicates and loss. Which Google Cloud setup best fits this always-on streaming ingestion pipeline?","oEn":["A batch that reads Pub/Sub in bulk every 5 minutes via Cloud Scheduler","Run an infinite loop in Workflows processing messages one by one","Trigger a DAG every minute in Composer to drain Pub/Sub","A Dataflow streaming pipeline that subscribes to Pub/Sub and writes to BigQuery"],"eEn":"For scalable streaming of thousands/sec with spikes writing to BigQuery, Dataflow (Apache Beam) streaming is best, with autoscaling and strong processing guarantees. A 5-minute Scheduler batch isn't real-time. A per-minute Composer DAG has high overhead and handles spikes poorly. Sequential Workflows processing isn't suited to high throughput."},{"id":"h63","d":"D3","q":"あるデータチームのCloud Composer環境では、運用するDAGとタスクの数が増え続けた結果、スケジューラとワーカーの処理が逼迫し、タスクがキューに滞留して実行遅延が慢性化している。チームはマネージドサービスの利点を維持したまま、負荷の増減に応じてワーカーの処理能力を柔軟に調整し、安定した実行を取り戻したい。素のAirflowを自前のVMで運用する選択は避けたい。最も適切な対応はどれか。","o":["タスクを減らすためにDAGの半分を削除する","全DAGを1つのVM上の素のAirflowに移して手動管理する","Composer 2(GKE Autopilotベース)を使い、ワーカーのオートスケールやスケジューラ設定を調整する","スケジュール間隔を全て1日1回に統一してタスクを絞る"],"a":2,"e":"Cloud Composer 2はGKE Autopilotベースで、ワーカーのオートスケールや環境サイズ・スケジューラのパラメータ調整により負荷に応じて処理能力を柔軟に拡張でき、マネージドのまま安定運用できる。素のAirflowへの移行は運用負荷を増やす。DAG削除や間引きは要件(処理そのもの)を犠牲にする本末転倒。","qEn":"In a data team's Cloud Composer environment, the ever-growing number of DAGs and tasks has strained the scheduler and workers, causing tasks to back up in the queue and chronic execution delays. The team wants to keep the benefits of a managed service while flexibly adjusting worker capacity with load to restore stable execution, and wants to avoid running plain Airflow on its own VMs. What is the most appropriate action?","oEn":["Delete half the DAGs to reduce task count","Move all DAGs to plain Airflow on a single VM and manage manually","Use Composer 2 (GKE Autopilot-based) and tune worker autoscaling and scheduler settings","Force all schedules to once per day to cut tasks"],"eEn":"Cloud Composer 2 is GKE Autopilot-based and can flexibly scale capacity via worker autoscaling and environment/scheduler tuning, staying managed and stable. Migrating to plain Airflow increases operational burden. Deleting DAGs or throttling sacrifices the actual work and defeats the purpose."},{"id":"h64","d":"D3","q":"あるバッチ取り込みDAGは、リトライやバックフィルによって同じ日付の処理が複数回実行されることがある。現状の実装では同じソースファイルを二重に取り込んでしまい、BigQueryのテーブルに重複行が生じている。データエンジニアは、同一日付が何度実行されても最終結果が壊れず一貫性を保てるように、パイプラインを設計し直したい。この冪等性(idempotency)を確保する設計として、最も適切なものはどれか。","o":["重複が出たら手動でDELETEするのを前提に運用する","毎回テーブル全体を削除して作り直し、履歴は保持しない","取り込み処理を冪等に設計し、パーティション上書き(WRITE_TRUNCATE)やMERGEで重複を防ぐ","リトライを完全に無効化して失敗したら諦める"],"a":2,"e":"リトライ・バックフィルで同一日付が複数回走っても壊れないためには、取り込みを冪等に設計し、対象パーティションのWRITE_TRUNCATE上書きやキーによるMERGEで重複を防ぐのが最適。テーブル全削除は履歴喪失や広範な影響を招く。手動DELETE前提は運用が脆弱でスケールしない。リトライ無効化は一時障害への耐性を失う。","qEn":"A batch ingestion DAG may run the same date multiple times due to retries or backfill. In its current implementation it ingests the same source file twice, producing duplicate rows in a BigQuery table. The engineer wants to redesign the pipeline so the final result stays correct and consistent no matter how many times the same date runs. Which design best ensures this idempotency?","oEn":["Operate on the assumption of manually DELETEing duplicates when they appear","Drop and recreate the whole table each run, keeping no history","Design ingestion to be idempotent, using partition overwrite (WRITE_TRUNCATE) or MERGE to prevent duplicates","Disable retries entirely and give up on failure"],"eEn":"To stay correct under repeated runs from retries/backfill, design ingestion to be idempotent, using WRITE_TRUNCATE overwrite of the target partition or key-based MERGE to prevent duplicates. Dropping the whole table loses history and has broad impact. Relying on manual DELETE is fragile and doesn't scale. Disabling retries loses resilience to transient failures."},{"id":"h65","d":"D3","q":"あるチームは、新しいデータ処理基盤のオーケストレータとして、軽量サーバーレスのWorkflowsと、AirflowベースのフルマネージドなCloud Composerのどちらを採用すべきか検討している。想定される要件は、数百のタスク、複雑な多段依存、豊富な既製Operatorエコシステムの活用、過去分のバックフィル、そして成熟した監視・可視化UIである。これらの要件を踏まえたとき、最も適切な選択とその理由はどれか。","o":["Workflows。ステップが多くても全てYAMLで書けば十分だから","Cloud Scheduler。時刻起動だけで全要件を満たせるから","どちらでも同じなのでコストの安い方を選ぶ","Cloud Composer。複雑な依存・バックフィル・豊富なOperator・監視UIというAirflowの強みに合致するから"],"a":3,"e":"数百タスク・複雑依存・豊富なOperatorエコシステム・バックフィル・成熟した監視UIという要件は、まさにAirflow(Cloud Composer)の強みであり最適。Workflowsは軽量サーバーレス向けで、この規模の依存管理・バックフィル・Operatorエコシステムには不足。Cloud Schedulerは時刻起動のみで依存管理ができない。要件を満たすのはComposer。","qEn":"A team is deciding whether to adopt lightweight serverless Workflows or Airflow-based fully managed Cloud Composer as the orchestrator for a new data processing platform. The expected requirements are hundreds of tasks, complex multi-level dependencies, use of a rich ready-made Operator ecosystem, backfill of past periods, and a mature monitoring and visualization UI. Given these requirements, which is the most appropriate choice and why?","oEn":["Workflows, because even many steps can just be written in YAML","Cloud Scheduler, because time-based triggering alone meets all requirements","Either is the same, so pick whichever is cheaper","Cloud Composer, because complex dependencies, backfill, rich Operators, and monitoring UI match Airflow's strengths"],"eEn":"Hundreds of tasks, complex dependencies, a rich Operator ecosystem, backfill, and a mature monitoring UI are exactly Airflow (Cloud Composer) strengths, making it the best fit. Workflows is for lightweight serverless and falls short on this scale of dependencies/backfill/Operators. Cloud Scheduler only triggers by time with no dependency management. Composer meets the requirements."},{"id":"h66","d":"D4","q":"ある本番プロジェクトで、データ分析者のグループがBigQuery上でクエリを実行して分析業務を行う必要がある。一方でセキュリティ方針上、彼らにテーブルの削除やIAMポリシーの変更といった破壊的・管理的な操作を行う権限は一切与えたくない。最小権限の原則に従い、必要なクエリ実行に足るだけの権限を過不足なく付与したい。このグループへのロール付与として、最も適切なものはどれか。","o":["プロジェクトのOwner基本ロールを付与する","BigQuery Data Viewer と BigQuery Job User の事前定義ロールを付与する","Editor基本ロールを付与する","カスタムロールを作らずroles/ownerを全員に付与する"],"a":1,"e":"クエリ実行にはデータ参照(BigQuery Data Viewer)とジョブ実行権限(BigQuery Job User)の事前定義ロールの組み合わせが最小権限として最適で、削除やIAM変更は含まれない。Owner/Editorの基本ロールは広範すぎて最小権限に反する。ownerを全員に付与するのは重大な過剰付与でセキュリティリスク。","qEn":"In a production project, a group of data analysts needs to run queries in BigQuery for their analysis work. At the same time, per security policy, they must not be granted any destructive or administrative permissions such as deleting tables or changing IAM policies. Following the principle of least privilege, you want to grant exactly the permissions sufficient for running queries and no more. Which role grant to this group is most appropriate?","oEn":["Grant the project Owner basic role","Grant the BigQuery Data Viewer and BigQuery Job User predefined roles","Grant the Editor basic role","Grant roles/owner to everyone instead of creating a custom role"],"eEn":"For running queries, combining the predefined roles BigQuery Data Viewer (read data) and BigQuery Job User (run jobs) is the least-privilege fit and excludes deletion and IAM changes. Owner/Editor basic roles are too broad and violate least privilege. Granting owner to everyone is severe over-provisioning and a security risk."},{"id":"h67","d":"D4","q":"あるセキュリティ監査により、本番プロジェクトにおいて多数のユーザーにEditorやOwnerといった基本ロールが広範に付与されていることが、重大な問題として指摘された。これらの基本ロールは粒度が粗く、各ユーザーの実際の職務に対して過剰な権限を与えてしまっている。セキュリティチームは、最小権限の原則に沿ってこの状態を根本から是正したい。最も適切な是正方針はどれか。","o":["基本ロールを維持しつつパスワードを複雑にする","職務に応じた事前定義ロールやカスタムロールに置き換え、基本ロールの利用を最小化する","全員をViewerに下げて誰も書き込めないようにする","IAMをやめてサービスアカウントキーを共有する"],"a":1,"e":"基本ロール(Owner/Editor/Viewer)は粒度が粗く本番では最小権限に反するため、職務に応じた事前定義ロールや必要なら最小のカスタムロールへ置き換えるのが正しい是正方針。パスワード強化は権限過剰の問題を解決しない。全員Viewerは業務遂行を妨げ極端。キー共有はさらに危険な悪手。","qEn":"A security audit flagged, as a serious issue, that many users in a production project hold broad basic roles such as Editor or Owner. These basic roles are coarse-grained and grant permissions far in excess of each user's actual job. The security team wants to fundamentally remediate this state in line with the principle of least privilege. Which remediation policy is most appropriate?","oEn":["Keep basic roles but require complex passwords","Replace them with job-appropriate predefined or custom roles, minimizing basic role use","Downgrade everyone to Viewer so no one can write","Abandon IAM and share a service account key"],"eEn":"Basic roles (Owner/Editor/Viewer) are coarse-grained and violate least privilege in production, so replacing them with job-appropriate predefined roles or minimal custom roles is the correct remediation. Stronger passwords don't fix over-provisioning. Making everyone Viewer blocks work and is extreme. Sharing keys is an even worse, more dangerous practice."},{"id":"h68","d":"D4","q":"ある金融機関では、コンプライアンス要件により、Cloud StorageとBigQueryに保存するすべての機密データを、自組織が管理・ローテーション・必要時に失効できる暗号鍵で暗号化することが義務付けられている。Googleが管理するデフォルトの暗号鍵では、鍵のライフサイクルを組織が制御できないため監査要件を満たせない。この要件を満たす暗号化方式として、最も適切なものはどれか。","o":["CSEK(顧客が鍵素材を毎リクエスト提供する方式)を全サービスで使う","Cloud KMSで管理するCMEK(顧客管理暗号鍵)を各サービスに設定する","暗号化を無効化してアクセス制御だけで保護する","GMEK(Google管理鍵)のままにして要件は無視する"],"a":1,"e":"組織が鍵をCloud KMSで管理・ローテーション・失効できる要件にはCMEK(顧客管理暗号鍵)が最適で、BigQueryやCloud Storageに設定できる。CSEKは鍵素材を毎回自前で渡す方式でGCSなど限定的、鍵管理の運用負荷が高くBigQueryでは一般的でない。暗号化無効化は不可。GMEK維持では管理要件を満たせない。","qEn":"At a financial institution, compliance requires that all sensitive data stored in Cloud Storage and BigQuery be encrypted with keys the organization itself can manage, rotate, and revoke when necessary. Google-managed default encryption keys do not meet the audit requirement because the organization cannot control the key lifecycle. Which encryption approach best meets this requirement?","oEn":["Use CSEK (customer supplies key material on every request) across all services","Set CMEK (customer-managed encryption keys) managed in Cloud KMS on each service","Disable encryption and protect with access control only","Keep GMEK (Google-managed keys) and ignore the requirement"],"eEn":"For an organization to manage, rotate, and revoke keys via Cloud KMS, CMEK (customer-managed encryption keys) is best and can be set on BigQuery and Cloud Storage. CSEK requires supplying key material each request, is limited (e.g., GCS), operationally heavy, and uncommon for BigQuery. Disabling encryption is not allowed. Keeping GMEK doesn't meet the management requirement."},{"id":"h69","d":"D4","q":"ある大企業のデータ統括チームは、社内のデータレイクに散在するBigQueryのデータセットやCloud Storage上のファイルなど、多数のデータ資産を横断的に発見・分類し、統一的にガバナンスしたい。加えて、メタデータの一元管理、データ品質の評価、そしてデータの系統(リネージ)の追跡も、同じ基盤上で実現したい。この用途に最も適したGoogle Cloudのサービスはどれか。","o":["Compute Engineに自作のカタログアプリを構築する","Cloud Schedulerでメタデータを毎晩CSVに書き出す","Dataplex(データガバナンス・カタログ/メタデータ・品質・系統)を用いる","Cloud Monitoringのダッシュボードでデータ資産を管理する"],"a":2,"e":"BigQueryやCloud Storageを横断したデータ資産の発見・分類・ガバナンス、メタデータ・品質・系統の一元管理にはDataplex(データカタログ機能を含む)が最適。Cloud SchedulerのCSV書き出しは検索・ガバナンス機能を持たない。自作アプリは運用負荷が高く車輪の再発明。Cloud Monitoringはシステム監視用でデータガバナンスの用途ではない。","qEn":"A large enterprise's data governance team wants to discover, classify, and uniformly govern a large number of data assets scattered across the data lake, including BigQuery datasets and Cloud Storage files. In addition, they want centralized metadata management, data quality assessment, and data lineage tracking on the same platform. Which Google Cloud service best fits this purpose?","oEn":["Build a custom catalog app on Compute Engine","Export metadata to CSV nightly via Cloud Scheduler","Use Dataplex (data governance/catalog, metadata, quality, lineage)","Manage data assets with a Cloud Monitoring dashboard"],"eEn":"For cross-service discovery, classification, and governance of data assets across BigQuery and Cloud Storage with centralized metadata, quality, and lineage, Dataplex (including catalog capabilities) is best. Scheduler CSV export lacks search/governance. A custom app is high-effort reinvention. Cloud Monitoring is for system monitoring, not data governance."},{"id":"h70","d":"D4","q":"あるチームは大量のログデータをCloud Storageに保存している。データは書き込みから直近30日間は分析のため頻繁にアクセスされるが、それを過ぎるとアクセスは激減し、さらに90日を超えると年に数回の監査目的で参照されるだけになる。データ自体は長期保管が必要である。ストレージコストを自動的に最適化する、ライフサイクル管理とストレージクラスの設計として、最も適切なものはどれか。","o":["全期間Standardのまま保持する","オブジェクトライフサイクル管理で30日後Nearline、90日後Coldlineへ自動移行する","初日からArchiveに置き頻繁アクセス時も毎回取り出す","30日後に全部削除して監査要件を無視する"],"a":1,"e":"アクセス頻度の変化に応じ、オブジェクトライフサイクル管理で30日後Nearline(月1回程度)、90日後Coldline(四半期〜年数回)へ自動移行するのがコスト最適。全期間Standardは割高。初日からArchiveは頻繁アクセス時の取り出しコストが高い。30日で全削除は監査要件に反する。","qEn":"A team stores large volumes of log data in Cloud Storage. The data is accessed frequently for analysis during the first 30 days after write, but access drops sharply afterward, and beyond 90 days it is only referenced a few times a year for audits. The data itself must be retained long term. Which lifecycle management and storage class design best automatically optimizes storage cost?","oEn":["Keep everything in Standard the whole time","Use Object Lifecycle Management to auto-transition to Nearline after 30 days and Coldline after 90 days","Put it in Archive from day one and retrieve on every frequent access","Delete everything after 30 days, ignoring the audit requirement"],"eEn":"Matching access frequency, Object Lifecycle Management auto-transitioning to Nearline after 30 days (~monthly) and Coldline after 90 days (quarterly to a few times a year) is most cost-optimal. All-Standard is expensive. Archive from day one has high retrieval cost during frequent access. Deleting at 30 days violates the audit requirement."},{"id":"h71","d":"D4","q":"ある企業は、法規制により特定のデータセットを7年間にわたって保持する義務がある。このデータは保持期間中、監査のために年に1回程度アクセスされる可能性がある以外はほとんど参照されず、7年経過後には削除する予定である。取り出し頻度は極めて低いため、単位ストレージあたりの保管コストが最も安いクラスを選びたい。この長期・超低頻度アクセスの要件に、最も適したストレージクラスはどれか。","o":["Standard","Nearline","Coldline","Archive"],"a":3,"e":"7年という超長期・年1回未満の超低頻度アクセスにはArchiveクラスが最適で、保存単価が最も安い(取り出しコストと最低保存期間は長い)。Standardは頻繁アクセス向けで割高。Nearlineは月1回程度、Coldlineは四半期〜年数回程度が目安で、Archiveほど長期保管の単価が安くない。要件にはArchiveが最良。","qEn":"A company is legally required to retain a specific dataset for 7 years. During the retention period the data is rarely referenced, apart from possibly being accessed about once a year for audits, and it will be deleted after 7 years. Because retrieval frequency is extremely low, they want the class with the lowest per-unit storage cost. Which storage class best fits this long-term, ultra-low-frequency access requirement?","oEn":["Standard","Nearline","Coldline","Archive"],"eEn":"For 7-year, less-than-annual ultra-low-frequency access, the Archive class is best with the lowest storage price (retrieval cost and minimum storage duration are higher/longer). Standard is for frequent access and pricey. Nearline (~monthly) and Coldline (quarterly to a few times a year) don't match this longevity as cheaply as Archive. Archive is the best fit."},{"id":"h72","d":"D4","q":"あるBigQuery環境で、機密性の高い営業実績を含むデータセットは営業チームのメンバーだけが参照でき、全社共通のマスタデータを含む別のデータセットは全従業員が参照できるようにしたい。テーブルごとに個別に設定するのは運用負荷が高いため避け、データセットという単位でアクセス権をまとめて制御し、対象となるグループに適切な参照権限を付与したい。最も適切な方法はどれか。","o":["各テーブルをCSVでエクスポートしメールで配布する","データセットのアクセス制御(データセットレベルのIAM/共有設定)で対象グループに適切なロールを付与する","プロジェクトのOwnerを全社員に付与する","BigQueryを使わずスプレッドシートに移す"],"a":1,"e":"BigQueryはデータセット単位でアクセス制御ができ、対象グループにデータセットレベルの適切なロール(例: Data Viewer)を付与するのが最適。CSV配布は制御不能で漏洩リスク。全社にOwner付与は最小権限に反し危険。スプレッドシート移行は分析基盤を捨てる不適切な対応。","qEn":"In a BigQuery environment, a dataset containing sensitive sales performance should be readable only by members of the sales team, while another dataset containing company-wide master data should be readable by all employees. Rather than configuring each table individually, you want to control access at the dataset unit and grant appropriate read permissions to the target groups. Which is the most appropriate method?","oEn":["Export each table to CSV and distribute by email","Use dataset access controls (dataset-level IAM/sharing) to grant appropriate roles to the target groups","Grant project Owner to all employees","Move off BigQuery to spreadsheets"],"eEn":"BigQuery supports dataset-level access control; granting appropriate dataset-level roles (e.g., Data Viewer) to the target groups is best. CSV distribution is uncontrolled and leaky. Granting Owner company-wide violates least privilege and is dangerous. Moving to spreadsheets abandons the analytics platform inappropriately."},{"id":"h73","d":"D4","q":"あるデータ基盤で、分析チームには元テーブルに含まれる全カラムを見せたくなく、集計済み・マスク済みに加工した結果だけを別のデータセット経由で参照させたい。同時に、彼らに元テーブルそのものへの直接的な参照権限を与えることは避けたい。加工ロジックは単一のクエリで表現でき、参照時には常に最新の元データを反映させたい。BigQueryでこれを実現する最適な実装はどれか。","o":["認可済みビュー(Authorized View)を別データセットに作り、元データへの直接権限は与えない","元テーブルにViewerを付与し、見ないよう口頭で依頼する","元データをコピーして手作業でカラムを削る","全員にプロジェクトEditorを付与する"],"a":0,"e":"元データへの直接権限を与えずに加工結果だけを参照させるには、別データセットの認可済みビュー(Authorized View)が最適で、ビュー経由でのみ元データにアクセスできる。元テーブルへのViewer付与は全カラムが見えてしまう。手作業コピーは保守困難で最新性を欠く。Editor付与は過剰権限で危険。","qEn":"In a data platform, you do not want the analytics team to see all columns in a source table—only results processed into aggregated and masked form, exposed through a separate dataset. At the same time, you want to avoid giving them direct read access to the source table itself. The processing logic can be expressed in a single query and must always reflect the latest source data. What is the best BigQuery implementation for this?","oEn":["Create an Authorized View in a separate dataset and grant no direct access to the source data","Grant Viewer on the source table and verbally ask them not to look","Copy the source and manually strip columns","Grant everyone project Editor"],"eEn":"To expose only processed results without direct source access, an Authorized View in a separate dataset is best—it can read the source only through the view. Granting Viewer on the source exposes all columns. A manual copy is hard to maintain and stale. Granting Editor is excessive and dangerous."},{"id":"h74","d":"D4","q":"あるBigQueryのテーブルには従業員の『給与』という機密カラムが含まれている。人事チームはこのカラムを参照できてよいが、一般アナリストには給与カラムだけを見せず、同じテーブルの他のカラムはこれまでどおり参照させたい。テーブルを分割したりデータを加工したりすることなく、特定のカラム単位できめ細かくアクセスを制御したい。この要件に最も適したBigQueryの仕組みはどれか。","o":["テーブルを2つに分割して手動で同期する","ポリシータグ(Data Catalog/Dataplexの分類)による列レベルのアクセス制御を設定する","給与カラムをNULLで上書きして元データを失う","給与カラムを含むデータセット全体を非公開にする"],"a":1,"e":"特定カラムだけをアクセス制御するにはポリシータグ(Data Catalog/Dataplexの分類法)を用いた列レベルセキュリティが最適で、タグを付与したカラムへの参照を権限で制御できる。テーブル分割は同期負荷と不整合を招く。NULL上書きは元データ喪失。データセット全体の非公開は他カラムまで見えなくなり要件過剰。","qEn":"A BigQuery table contains a sensitive 'salary' column for employees. The HR team may view this column, but general analysts should not see the salary column while still viewing the table's other columns as before. Without splitting the table or transforming the data, you want fine-grained access control at the specific column level. Which BigQuery mechanism best fits this requirement?","oEn":["Split the table into two and sync manually","Set column-level access control using policy tags (Data Catalog/Dataplex taxonomy)","Overwrite the salary column with NULL, losing the source data","Make the entire dataset containing salary private"],"eEn":"To control a specific column, column-level security using policy tags (Data Catalog/Dataplex taxonomy) is best, gating access to tagged columns by permission. Splitting tables adds sync burden and inconsistency. NULL overwrite loses source data. Making the whole dataset private hides other columns too and overshoots the requirement."},{"id":"h75","d":"D4","q":"ある企業の顧客データには、クレジットカード番号やメールアドレス、電話番号といった機密性の高い個人情報が、多数のフィールドに混在している。このデータを分析用データセットへコピーして活用する前に、こうした機密情報を自動的にスキャンして検出し、マスキングやトークン化によって匿名化(de-identify)しておきたい。この用途に最も適したGoogle Cloudのサービスはどれか。","o":["Cloud DLP(Sensitive Data Protection)で機密データを検査し、de-identify(マスキング/トークン化)する","BigQueryのSELECTで目視して手動置換する","Cloud Monitoringでカード番号を検知する","そのままコピーしてアクセス制御だけに頼る"],"a":0,"e":"クレジットカード番号やメールなどの機密検出とマスキング/トークン化にはCloud DLP(Sensitive Data Protection)が最適で、infoType検査とde-identify変換を提供する。目視・手動置換はスケールせず漏れる。Cloud Monitoringはシステム監視用で機密検出機能はない。無加工コピーは機密拡散のリスクが高い。","qEn":"A company's customer data mixes highly sensitive personal information—credit card numbers, email addresses, and phone numbers—across a large number of fields. Before copying this data to an analytics dataset for use, they want to automatically scan and detect such sensitive information and anonymize (de-identify) it through masking or tokenization. Which Google Cloud service best fits this purpose?","oEn":["Use Cloud DLP (Sensitive Data Protection) to inspect sensitive data and de-identify (mask/tokenize)","Eyeball it via a BigQuery SELECT and replace manually","Detect card numbers with Cloud Monitoring","Copy as-is and rely on access control only"],"eEn":"For detecting sensitive data like card numbers/emails and masking/tokenizing, Cloud DLP (Sensitive Data Protection) is best, offering infoType inspection and de-identify transforms. Manual review doesn't scale and misses data. Cloud Monitoring is for system monitoring, not sensitive-data detection. Copying as-is risks spreading sensitive data."},{"id":"h76","d":"D4","q":"あるデータ処理パイプラインは専用のサービスアカウントで実行されている。このサービスアカウントに必要な操作は、入力用の特定のCloud Storageバケットからの読み取りと、出力先である特定のBigQueryデータセットへの書き込みだけである。セキュリティチームは最小権限の原則を徹底し、万一この資格情報が漏洩しても影響範囲を限定したい。このサービスアカウントへの権限設計として、最も適切なものはどれか。","o":["SAにプロジェクトのEditorを付与して何でもできるようにする","必要なバケットとデータセットに限定した事前定義ロールを、リソーススコープで付与する","SAキーを複数チームで共有して使い回す","SAにOwnerを付与し将来の変更に備える"],"a":1,"e":"最小権限に従い、必要なバケット(例: Storage Object Viewer)と対象データセット(例: BigQuery Data Editor)に限定した事前定義ロールを、リソース単位のスコープで付与するのが最適。Editor/Ownerの広範付与は最小権限違反。SAキーの共有は資格情報漏洩・追跡不能のリスクで禁忌。将来に備えた過剰付与も不適切。","qEn":"A data processing pipeline runs as a dedicated service account. The only operations this service account needs are reading from a specific input Cloud Storage bucket and writing to a specific output BigQuery dataset. The security team wants to strictly enforce least privilege and limit the blast radius should these credentials ever leak. Which permission design for this service account is most appropriate?","oEn":["Grant the SA project Editor so it can do anything","Grant predefined roles scoped to just the needed bucket and dataset at the resource level","Share the SA key across multiple teams","Grant the SA Owner to prepare for future changes"],"eEn":"Following least privilege, grant predefined roles scoped to the needed bucket (e.g., Storage Object Viewer) and dataset (e.g., BigQuery Data Editor) at the resource level. Broad Editor/Owner grants violate least privilege. Sharing SA keys risks credential leakage and untraceability. Over-provisioning for the future is also inappropriate."},{"id":"h77","d":"D4","q":"ある企業は規制対応のため、Cloud Storageに保存する取引記録を、少なくとも5年間は削除も上書きもできない状態で保持しなければならない。運用担当者による誤操作での削除はもちろん、内部関係者による意図的な改ざんも技術的に防止する必要がある。管理者権限を持つ者であっても、保持期間中はデータを消せないようにしたい。この要件を満たす設定として、最も適切なものはどれか。","o":["バケットに保持ポリシー(Retention Policy)を設定し、必要ならロックして5年間の保持を強制する","オブジェクトのメタデータにコメントで『消さないで』と書く","IAMでdeleteを外すが後でいつでも戻せるようにする","毎日手動でバックアップを取り原本は自由に削除可とする"],"a":0,"e":"一定期間の削除・上書きを強制的に防ぐにはバケットの保持ポリシー(Retention Policy)が最適で、ロックすれば管理者でも短縮・解除できず改ざん・誤削除を防止できる(WORM相当)。メタデータのコメントは何も強制しない。IAMでdeleteを外すだけでは権限変更で戻せてしまう。手動バックアップ+原本削除可では改ざん耐性がない。","qEn":"For regulatory compliance, a company must keep transaction records in Cloud Storage in a state where they cannot be deleted or overwritten for at least 5 years. It must technically prevent not only accidental deletion by operators but also intentional tampering by insiders, so that even someone with administrator privileges cannot erase the data during the retention period. Which setting best meets this requirement?","oEn":["Set a bucket Retention Policy and lock it if needed to enforce 5-year retention","Add a comment 'do not delete' to object metadata","Remove delete via IAM but keep it reversible anytime","Take manual backups daily and allow deleting the originals freely"],"eEn":"To forcibly prevent deletion/overwrite for a period, a bucket Retention Policy is best; locking it prevents even admins from shortening/removing it, blocking tampering and accidental deletion (WORM-like). A metadata comment enforces nothing. Removing delete via IAM alone is reversible by a policy change. Manual backups with deletable originals aren't tamper-resistant."},{"id":"h78","d":"D4","q":"あるチームは、頻繁に更新される重要なBigQueryテーブルについて、誤った更新や削除に備えて特定時点の状態を低コストに保全し、問題が発生した際にはその時点の状態へ迅速に復元できるようにしたい。専用のバックアップ基盤を別途構築・運用するのは避けたく、BigQueryのネイティブ機能で運用負荷を抑えつつ実現したい。この要件に最も適した方法として、最も適切なものはどれか。","o":["テーブルスナップショット(またはタイムトラベルによる復元)を活用する","毎晩テーブルをCSVでエクスポートしてローカルに保管する","テーブルを複製したコピーを手動で大量に作る","バックアップは取らずアクセス制御だけで守る"],"a":0,"e":"BigQueryネイティブのテーブルスナップショットは特定時点の状態を低コストに保全でき、タイムトラベルは既定期間内の過去状態への復元を可能にする。運用負荷が低く要件に最適。CSVエクスポートはスキーマ/型情報の欠落や復元の手間が大きい。手動大量コピーはコスト・管理が煩雑。アクセス制御だけでは誤更新自体からは守れない。","qEn":"A team wants to preserve point-in-time states of a critical, frequently updated BigQuery table cheaply to guard against erroneous updates or deletion, and to be able to restore to that point if a problem occurs. They want to avoid building and operating a separate dedicated backup platform, achieving this with BigQuery native features while keeping operational overhead low. Which method best fits this requirement?","oEn":["Use table snapshots (or time travel restore)","Export the table to CSV nightly and keep locally","Manually create many duplicate copies of the table","Take no backups and rely on access control only"],"eEn":"BigQuery-native table snapshots preserve point-in-time state cheaply, and time travel restores past states within the retention window—low overhead and a great fit. CSV export loses schema/types and is cumbersome to restore. Many manual copies are costly and hard to manage. Access control alone doesn't protect against accidental updates themselves."},{"id":"h79","d":"D4","q":"あるチームは、社外のパートナー企業の担当者に対し、Cloud Storage上にある特定のオブジェクト1つを、24時間だけダウンロードできるように一時的に共有したい。相手はGoogleアカウントを持っておらず、そのためだけにIAMでプリンシパルを追加したり権限を付与したりはしたくない。また、バケット全体を一般公開することも避けたい。この一時的なアクセス提供に、最も適した方法はどれか。","o":["バケットを一般公開(allUsers)にする","期限付きの署名付きURL(Signed URL)を発行して渡す","パートナーにプロジェクトViewerを付与する","オブジェクトをメール添付で送る"],"a":1,"e":"Googleアカウントを持たない相手に一時的なオブジェクトアクセスを与えるには、有効期限付きの署名付きURL(Signed URL)が最適で、IAM付与不要で24時間などの期限も設定できる。バケット公開は無関係な全員に露出し危険。プロジェクトViewer付与は広範かつアカウント前提。メール添付はサイズ・監査・セキュリティ面で不適切。","qEn":"A team wants to temporarily share a single specific object in Cloud Storage with an external partner's staff member so they can download it for only 24 hours. The partner has no Google account, and the team does not want to add a principal or grant permissions via IAM just for this, nor make the entire bucket public. Which method best fits this temporary access provisioning?","oEn":["Make the bucket public (allUsers)","Issue a time-limited Signed URL and share it","Grant the partner project Viewer","Send the object as an email attachment"],"eEn":"To give temporary object access to someone without a Google account, a time-limited Signed URL is best—no IAM grant needed and you can set a 24-hour expiry. Making the bucket public exposes it to everyone and is dangerous. Project Viewer is broad and requires an account. Email attachment is poor for size, audit, and security."},{"id":"h80","d":"D4","q":"ある組織はCMEKを用いてBigQueryとCloud Storageのデータを暗号化しているが、セキュリティ方針により暗号鍵を一定間隔で定期的にローテーションすることが求められている。手作業で新しい鍵を作成して全データを再暗号化するような高コストな運用は避け、鍵の更新をできるだけ自動化して運用負荷を最小化したい。Cloud KMSを用いてこの鍵ローテーション要件を満たす設定として、最も適切なものはどれか。","o":["Cloud KMSで鍵の自動ローテーション期間を設定する","鍵を一切変えずに運用し続ける","毎回手動で新しい鍵を作り全データを再暗号化する","暗号化をGMEKに戻してローテーション要件を無視する"],"a":0,"e":"Cloud KMSは鍵の自動ローテーション期間を設定でき、新しい鍵バージョンを自動生成して以後の暗号化に使うため、運用負荷を抑えつつローテーション要件を満たせる。鍵を変えないのは方針違反。毎回手動作成・全再暗号化は過剰な運用負荷。GMEKに戻すと顧客管理・ローテーション制御の要件を満たせない。","qEn":"An organization encrypts BigQuery and Cloud Storage data using CMEK, but security policy requires rotating the encryption keys periodically at fixed intervals. They want to avoid costly operations such as manually creating new keys and re-encrypting all data, automating key updates as much as possible to minimize operational overhead. Which Cloud KMS setting best meets this key rotation requirement?","oEn":["Configure an automatic rotation period for the key in Cloud KMS","Keep operating without ever changing the key","Manually create a new key each time and re-encrypt all data","Revert to GMEK and ignore the rotation requirement"],"eEn":"Cloud KMS lets you set an automatic rotation period, generating new key versions automatically for subsequent encryption, meeting the requirement with low overhead. Never changing keys violates policy. Manual creation and full re-encryption each time is excessive overhead. Reverting to GMEK fails the customer-managed/rotation-control requirement."},{"id":"h81","d":"D4","q":"あるグローバル企業のBigQueryには、全リージョンの売上を格納した大きなイベントテーブルがある。各地域のアナリストには、自分が担当するリージョンに該当する行だけを参照させ、他リージョンの行は見せたくない。テーブルは1つのまま維持し、リージョンごとに物理的に分割することは避けたい。同一テーブル内で、ユーザー属性に応じて行単位のアクセス制御を適用する、最適なBigQueryの機能はどれか。","o":["リージョンごとにテーブルを分割して権限を分ける","行レベルセキュリティ(Row-Level Security)ポリシーを定義する","各アナリストにテーブル全体のViewerを付与し自己申告に任せる","BigQueryを使わずリージョン別のスプレッドシートを配る"],"a":1,"e":"単一テーブルで行単位のアクセス制御を行うにはBigQueryの行レベルセキュリティ(Row-Level Security)が最適で、ユーザー属性に応じて可視行をフィルタするポリシーを定義できる。テーブル分割は管理・結合の負荷が増える。全体Viewer+自己申告は制御になっていない。スプレッドシート配布は分析基盤を捨て整合性も欠く。","qEn":"A global company's BigQuery has a large event table storing sales for all regions. Each region's analysts should see only the rows corresponding to their assigned region and not rows for other regions. They want to keep it as a single table and avoid physically splitting it by region. Which BigQuery feature best applies row-level access control within the same table based on user attributes?","oEn":["Split the table by region and separate permissions","Define Row-Level Security policies","Grant each analyst Viewer on the whole table and rely on self-restraint","Distribute per-region spreadsheets instead of using BigQuery"],"eEn":"For row-level access control on a single table, BigQuery Row-Level Security is best, defining policies that filter visible rows by user attributes. Splitting tables adds management/join burden. Whole-table Viewer with self-restraint is no control. Spreadsheets abandon the platform and lack consistency."},{"id":"h82","d":"D4","q":"あるチームは、機密データがクライアントとGoogle Cloudのサービスの間でやり取りされる際、その通信経路上で第三者に傍受されないように保護されているかを確認したい。特に、保存時(at-rest)の暗号化とは別に、転送中(in-transit)のデータがどのように守られているのかを正しく理解したい。Google Cloudにおける転送中の暗号化に関する説明として、最も正確なものはどれか。","o":["転送中の暗号化はユーザーが必ず自前で実装しなければならない","Google Cloudのサービス通信はTLSで転送中に暗号化され、保存時の暗号化とは別レイヤで保護される","転送中データは暗号化できず保存時のみ保護される","転送中の暗号化はCSEKを使わないと有効化されない"],"a":1,"e":"Google Cloudではサービスとの通信はTLSにより転送中(in-transit)に暗号化され、保存時(at-rest)の暗号化とは独立したレイヤで保護される。ユーザーが必ず自前実装する必要はない(HTTPS/TLSで保護)。転送中も暗号化される。CSEKは保存時の鍵素材提供の話であり転送中暗号化の前提ではない。","qEn":"A team wants to confirm that when sensitive data is exchanged between a client and Google Cloud services, it is protected from third-party interception on the network path. In particular, apart from at-rest encryption, they want to correctly understand how in-transit data is protected. Which statement about in-transit encryption in Google Cloud is the most accurate?","oEn":["In-transit encryption must always be implemented by the user themselves","Google Cloud service traffic is encrypted in transit via TLS, protected as a separate layer from at-rest encryption","In-transit data cannot be encrypted; only at-rest is protected","In-transit encryption is only enabled if you use CSEK"],"eEn":"In Google Cloud, traffic to services is encrypted in transit via TLS, protected independently from at-rest encryption. Users need not always implement it themselves (HTTPS/TLS protects it). In-transit data is encrypted. CSEK concerns supplying key material for at-rest and is not a prerequisite for in-transit encryption."},{"id":"h83","d":"D4","q":"ある組織のデータガバナンス方針では、各データ資産に対して所有者・機密度・保持期間といったメタデータを付与し、それらをもとに資産を横断的に検索・分類できるようにすることが求められている。さらに、ビジネス部門が使う用語集(ビジネス用語)と技術的なメタデータを結び付け、組織全体で一貫した統制を効かせたい。この要件に最も適したGoogle Cloudの仕組みはどれか。","o":["Dataplex/Data Catalogのメタデータ・タグ・タクソノミーで資産を分類・統制する","各テーブル名に情報を詰め込んで命名規約で管理する","メタデータはスプレッドシートで手管理する","Cloud Loggingのログにメタデータを書き込む"],"a":0,"e":"データ資産へのメタデータ付与・分類・検索、ビジネス用語と技術メタデータの結合による統制にはDataplex(Data Catalog)のタグテンプレート・ポリシータグ/タクソノミーが最適。テーブル名詰め込みは拡張性・検索性に欠ける。スプレッドシート手管理は同期漏れと非統制。Cloud Loggingはメタデータ管理の用途ではない。","qEn":"An organization's data governance policy requires attaching metadata such as owner, sensitivity, and retention period to each data asset so that assets can be searched and classified based on them. It further wants to tie the business glossary used by business units to technical metadata, applying consistent governance across the whole organization. Which Google Cloud mechanism best fits this requirement?","oEn":["Classify and govern assets with Dataplex/Data Catalog metadata, tags, and taxonomies","Cram info into each table name and manage via naming conventions","Manage metadata by hand in a spreadsheet","Write metadata into Cloud Logging logs"],"eEn":"For attaching, classifying, and searching metadata on data assets and tying business glossary to technical metadata for governance, Dataplex (Data Catalog) tag templates and policy tags/taxonomies are best. Cramming into table names lacks extensibility/searchability. A hand-managed spreadsheet drifts and is ungoverned. Cloud Logging isn't for metadata management."},{"id":"h84","d":"D4","q":"あるチームは、BigQueryを操作するサービスアカウントに対し、『クエリの実行はできるが、データセットの作成や削除はできない』という、プロジェクトレベルの特定の権限セットだけを与えたい。既存の事前定義ロールを調べたが、どれも粒度が要件と合わず、余分な権限が含まれてしまう。最小権限を厳密に守るため、必要な権限だけを過不足なく付与したい。このケースで最も適切なアプローチはどれか。","o":["Owner基本ロールを付与し余分な権限は無視する","必要な権限だけを列挙したIAMカスタムロールを作成して付与する","権限管理をやめてSAキーを共有する","Editorを付与して足りない分は都度追加する"],"a":1,"e":"事前定義ロールの粒度が要件に合わず、必要な権限だけを厳密に与えたい特殊ケースでは、必要な権限を列挙したカスタムロールを作成するのが最小権限に最も適う。Owner/Editorは広範すぎて最小権限違反。SAキー共有は資格情報管理の観点で危険。要件に合致するのはカスタムロール。","qEn":"A team wants to give a service account operating BigQuery only a specific project-level permission set: 'can run queries but cannot create or delete datasets.' They examined the existing predefined roles, but none match the required granularity and all include extra permissions. To strictly enforce least privilege, they want to grant exactly the necessary permissions and no more. Which approach is most appropriate in this case?","oEn":["Grant the Owner basic role and ignore the extra permissions","Create and grant an IAM custom role listing only the needed permissions","Stop managing permissions and share the SA key","Grant Editor and add missing permissions as needed"],"eEn":"When predefined role granularity doesn't fit and you want exactly the needed permissions, creating a custom role listing only those permissions best satisfies least privilege. Owner/Editor are too broad and violate least privilege. Sharing SA keys is dangerous for credential management. A custom role is the requirement-fitting choice."},{"id":"h85","d":"D4","q":"ある企業は、極めて機密性の高いデータをBigQueryで扱っており、たとえ正規のユーザーの認証情報が漏洩した場合でも、そのデータが組織のネットワーク境界の外へ持ち出される(exfiltration)リスクを構造的に低減したい。IAMによるアクセス制御だけに頼るのではなく、サービスの境界を定義してAPIレベルでデータの持ち出しを制限する仕組みを追加で導入したい。最も適切なものはどれか。","o":["VPC Service Controlsでサービス境界を設定しデータの外部への持ち出しを制限する","全ユーザーにMFAを課すだけで境界対策は行わない","BigQueryを一般公開して監視だけ強化する","IAMのViewerを剥がして誰も読めなくする"],"a":0,"e":"認証情報漏洩時でもデータの外部持ち出し(exfiltration)を境界で防ぐにはVPC Service Controlsが最適で、サービス境界を定義しAPIレベルで持ち出しを制限できる。MFAは認証強化であって持ち出し境界対策ではない。一般公開は逆効果で危険。Viewer全剥奪は正規業務を止め要件を満たさない。","qEn":"A company handles extremely sensitive data in BigQuery and wants to structurally reduce the risk that the data is exfiltrated beyond the organization's network perimeter even if a legitimate user's credentials leak. Rather than relying solely on IAM access control, they want to additionally introduce a mechanism that defines a service perimeter and restricts data egress at the API level. Which is most appropriate?","oEn":["Use VPC Service Controls to define a service perimeter and restrict data exfiltration","Just require MFA for all users with no perimeter controls","Make BigQuery public and only strengthen monitoring","Strip Viewer via IAM so no one can read"],"eEn":"To block data exfiltration at the perimeter even with leaked credentials, VPC Service Controls is best, defining a service perimeter and restricting egress at the API level. MFA strengthens authentication but isn't an exfiltration perimeter. Making it public is counterproductive and dangerous. Stripping all Viewer halts legitimate work and fails the requirement."},{"id":"h86","d":"D4","q":"あるチームは、特定のIAM権限を常時有効にするのではなく、条件付きで有効範囲を絞りたい。例えば『リソースのタグがproductionである対象だけ』や『特定の業務時間帯だけ』アクセスを許可する、といった制御を実現したい。ロールの付与そのものに条件式を組み込み、宣言的かつ強制力のある形でアクセス範囲を限定したい。この要件に最も適したGoogle CloudのIAMの仕組みはどれか。","o":["IAM Conditions(条件付きロールバインディング)を使う","基本ロールを付与して条件は運用の口約束で守る","権限を毎回手動で付けたり外したりする","Cloud Schedulerでロールを時間帯ごとに付け替えるスクリプトを常時回す"],"a":0,"e":"リソース属性や時間などの条件でロール付与を絞るにはIAM Conditions(条件付きロールバインディング)が最適で、式で有効範囲を制御できる。口約束は強制力がなく統制にならない。手動付け外しはヒューマンエラーとスケール問題。Schedulerでの常時付け替えは脆弱で複雑、IAM Conditionsで宣言的に表現するのが正攻法。","qEn":"A team wants to scope certain IAM permissions conditionally rather than keeping them always active. For example, they want to allow access 'only for resources tagged production' or 'only during certain business hours.' They want to embed a condition expression into the role grant itself, limiting the access scope in a declarative and enforceable way. Which Google Cloud IAM mechanism best fits this requirement?","oEn":["Use IAM Conditions (conditional role bindings)","Grant basic roles and honor conditions by verbal agreement","Manually add/remove permissions every time","Run a script via Cloud Scheduler constantly swapping roles by time of day"],"eEn":"To scope grants by conditions like resource attributes or time, IAM Conditions (conditional role bindings) is best, controlling validity via expressions. Verbal agreements aren't enforceable governance. Manual add/remove is error-prone and unscalable. Constant Scheduler-based swapping is fragile and complex; IAM Conditions expresses it declaratively."},{"id":"h87","d":"D4","q":"あるチームは、比較的短期間で削除・上書きされるデータを、保管コストを抑えるつもりでNearlineストレージクラスに保存していた。ところが、保存から数日後に削除する運用を繰り返した結果、想定していたよりも請求額が大幅に高くなってしまった。Nearline・Coldline・Archiveといったクラスに設定されている『最低保存期間(minimum storage duration)』について、最も正確な理解はどれか。","o":["これらのクラスには最低保存期間があり、期間内に削除/変更しても最低期間分の保存料が課金される","最低保存期間は存在せず、いつ消しても課金は発生しない","最低保存期間はStandardにのみ存在する","最低保存期間を過ぎると取り出しが無料になる"],"a":0,"e":"Nearline(30日)・Coldline(90日)・Archive(365日)などには最低保存期間があり、期間内に削除・上書き・クラス変更しても最低期間分の保存料が課金される。頻繁に短期間で消す用途では割高になるため、アクセス/保持特性に合ったクラス選択が重要。最低保存期間がない、Standardのみに存在、過ぎると取り出し無料、はいずれも誤り。","qEn":"A team stored data that is deleted or overwritten within a relatively short period in the Nearline storage class, intending to reduce storage cost. However, repeatedly deleting data a few days after storage resulted in a bill significantly higher than expected. Which is the most accurate understanding of the 'minimum storage duration' set for classes such as Nearline, Coldline, and Archive?","oEn":["These classes have a minimum storage duration; deleting/changing within it still incurs storage charges for the minimum period","There is no minimum storage duration; deleting anytime incurs no charge","Minimum storage duration exists only for Standard","After the minimum duration, retrieval becomes free"],"eEn":"Nearline (30 days), Coldline (90 days), and Archive (365 days) have minimum storage durations; deleting, overwriting, or changing class within the period still charges storage for the minimum period. For frequent short-lived deletion this is costly, so pick a class matching access/retention. Claims of no minimum, Standard-only, or free retrieval after the period are all wrong."},{"id":"h88","d":"D1","q":"小売企業が日次の POS ログを Cloud Storage に蓄積している。作成後 30 日間は毎日参照されるが、その後は月に数回、1 年を過ぎると監査でごくまれに読まれる程度で、社内規程により 7 年経過後は削除する。スクリプトを書かずに、保存クラスの切り替えと削除を自動化したい場合、最も適切な方法はどれですか。","o":["バケットで Autoclass を有効にし、削除までの保持日数も Autoclass の設定項目として 7 年に指定する","バケットのライフサイクルルールで、オブジェクトの経過日数に応じて SetStorageClass による低頻度向けクラスへの変更と、7 年後の Delete を設定する","Cloud Scheduler から Cloud Run functions を毎晩起動し、経過日数を計算してオブジェクトを別クラスのバケットへコピーし、元のオブジェクトを削除する","バケットでオブジェクトのバージョニングを有効にし、古い世代が自動的に低頻度向けのクラスへ移るようにする"],"a":1,"e":"ライフサイクルルールは経過日数を条件に SetStorageClass と Delete を宣言的に自動実行できます。Autoclass はアクセス実績で自動遷移する機能で、日数指定の削除はできません。Scheduler と関数の組み合わせはスクリプトが必要で要件に反し、バージョニングは世代を残す機能でクラスを変えません。","qEn":"A retailer stores daily POS logs in Cloud Storage. For the first 30 days they are read every day, afterward only a few times a month, and after one year only rarely during audits; company policy requires deletion after 7 years. Which approach automates the storage class changes and the deletion without writing scripts?","oEn":["Enable Autoclass on the bucket and also specify a 7-year retention-until-delete setting inside the Autoclass configuration itself","Configure bucket lifecycle rules that use SetStorageClass to move objects to colder classes by age, plus a Delete action at 7 years","Run a Cloud Run functions job nightly from Cloud Scheduler that computes each object's age, copies it to a colder bucket, and deletes the original","Enable Object Versioning on the bucket so that older generations are automatically moved to a colder storage class over time"],"eEn":"Lifecycle rules declaratively run SetStorageClass and Delete actions based on object age. Autoclass transitions objects by observed access and has no age-based delete setting. A Scheduler-plus-function job requires scripts, which the requirement rules out, and versioning keeps generations but never changes the storage class."},{"id":"h89","d":"D1","q":"データサイエンスチームが共有する Cloud Storage バケットに、数百万枚の学習用画像が入っている。どの画像がいつ読まれるかは予測できず、数か月触られなかった画像が突然まとまって再利用されることもある。年齢ベースのルールを個別に設計せず、低頻度クラスに置いたまま頻繁に読んで割高になる事態も避けつつ、保管コストを下げたい。最も適切な設定はどれですか。","o":["作成から 90 日を過ぎたオブジェクトをすべて Coldline に変更するライフサイクルルールを設定し、再利用が集中しても、そのクラスのまま読み取る","すべての画像を Archive クラスで保存し、学習に必要になったときに Standard のバケットへコピーしてから使う運用ルールを定める","各オブジェクトに最終アクセス日のメタデータを手作業で記録し、担当者が月次でクラスを書き換えるスクリプトを実行する","バケットで Autoclass を有効にし、アクセスのないオブジェクトを自動で低頻度向けクラスへ移し、読まれたオブジェクトは Standard に戻す"],"a":3,"e":"Autoclass はオブジェクト単位でアクセスの有無を見て自動的にクラスを変え、読まれたオブジェクトは Standard に戻るため、予測できないアクセスに向きます。固定日数のルールは再利用時に低頻度クラスのまま読むことになり割高です。全件 Archive や手作業のクラス変更は、頻繁な再利用や規模に合いません。","qEn":"A data science team's shared Cloud Storage bucket holds millions of training images. It is impossible to predict which images will be read and when, and images untouched for months are sometimes reused in bulk. The team wants lower storage cost without designing per-object age rules and without leaving frequently read data in a colder class where it becomes expensive. Which setting is most appropriate?","oEn":["Create a lifecycle rule that changes every object older than 90 days to Coldline and keep reading reused images from that class","Store every image in the Archive class and copy it to a Standard bucket whenever it is needed for a training run","Record the last access date in each object's metadata by hand and run a script every month that rewrites the storage classes","Enable Autoclass so idle objects move to colder classes on their own and objects that get read return to Standard"],"eEn":"Autoclass watches access per object, moves idle objects to colder classes and returns read objects to Standard, which suits unpredictable access. A fixed-age rule leaves reused data in a cold class, making frequent reads costly. Archiving everything or rewriting classes by hand does not fit heavy reuse or this scale."},{"id":"h90","d":"D1","q":"ある部署が毎日、同じ名前の設定ファイル群を Cloud Storage に上書き保存している。誤上書きに備えて過去の世代へ戻せる状態にしたいが、古い世代が際限なく溜まって保管料が増え続けている。現行のオブジェクトは削除せず、現行を含む直近の数世代だけを残し、それより古い世代は自動で消したい。最も適切な構成はどれですか。","o":["バケットに保持ポリシーを設定し、すべてのオブジェクトを一定期間は削除も上書きもできないようにして、期間後に自動で消えるようにする","作成から一定日数が経過したオブジェクトを削除するライフサイクルルールを設定し、バージョニングは無効のままにして運用する","オブジェクトのバージョニングを有効にした上で、新しい世代が一定数以上ある非現行バージョンを削除するライフサイクルルールを設定する","上書きをやめて毎日日付入りの新しいオブジェクト名で保存する運用に変え、参照側のアプリケーションも毎日の名前を読むようにする"],"a":2,"e":"バージョニングで過去の世代を保持し、新しい世代の数を条件にした非現行バージョン削除のルールを組み合わせれば、現行を残したまま古い世代だけを自動で整理できます。保持ポリシーは削除を禁止するだけで溜まる一方、日数での削除は現行まで消し、別名保存は参照側の変更が必要で戻す仕組みになりません。","qEn":"A department overwrites the same set of configuration files in Cloud Storage every day. It wants to be able to roll back to earlier generations after accidental overwrites, but old generations keep piling up and storage cost keeps rising. Current objects must never be deleted; only the latest few generations, including the current one, should be kept and anything older removed automatically. Which setup is most appropriate?","oEn":["Set a retention policy on the bucket so no object can be deleted or overwritten for a fixed period, then let them disappear afterward","Add a lifecycle rule that deletes any object older than a set number of days and leave Object Versioning disabled","Enable Object Versioning and add a lifecycle rule that deletes noncurrent versions once enough newer versions exist","Stop overwriting and save a new, date-stamped object name every day, with consumer applications reading each day's name"],"eEn":"Versioning keeps prior generations, and a lifecycle rule keyed on the number of newer versions removes only noncurrent ones, leaving the live object intact. A retention policy only blocks deletion so versions keep accumulating, an age-based delete would remove live objects, and renaming forces every consumer to change without giving a rollback."},{"id":"h91","d":"D1","q":"東京リージョン (asia-northeast1) に作成した BigQuery データセットへ、米国マルチリージョン (US) のバケットにある CSV を bq load で取り込もうとして、場所の不一致を示すエラーになった。社内規程で BigQuery 上のデータは東京に置く必要があり、ファイルは今後も毎日このバケットに届く。最も適切な対処はどれですか。","o":["出力先を asia-northeast1 のバケットに変えるか、Storage Transfer Service で複製してからロードする","bq load のジョブの場所を US に指定して実行し、東京のデータセットへの書き込みも同じジョブの中で行わせる","同じ CSV を指す外部テーブルを東京のデータセットに作成し、ロードジョブを使わずに、米国のバケットを直接参照して毎日クエリを実行し続けるようにする","データセットを US マルチリージョンに作り直し、以降のロードと分析はすべてそちらのデータセットで行い、東京側は使用をやめる"],"a":0,"e":"BigQuery のロードジョブとデータセット、読み込み元バケットは互換性のあるロケーションに置く必要があります。ジョブの場所を US にしても東京のデータセットには書けず、外部テーブルもバケットの場所が合わなければ使えません。US へ作り直すと規程に反するため、東京のバケットへ出力または複製してロードします。","qEn":"A BigQuery dataset was created in Tokyo (asia-northeast1), and a bq load of CSV files from a bucket in the US multi-region fails with a location mismatch error. Company policy requires BigQuery data to stay in Tokyo, and new files will keep arriving in that bucket every day. What is the most appropriate fix?","oEn":["Export to a bucket in asia-northeast1, or replicate to one with Storage Transfer Service, and load from there","Run the bq load job with its location set to US and have that same job write into the dataset that lives in Tokyo","Create an external table in the Tokyo dataset that points at the same CSV files and read the US bucket without a load job","Recreate the dataset in the US multi-region and perform all later loading and analysis in that dataset instead"],"eEn":"A load job, the target dataset, and the source bucket must have compatible locations. Running the job in US cannot write to a Tokyo dataset, an external table also needs a matching bucket location, and moving the dataset to the US violates the policy. Write to or replicate into a Tokyo bucket and load from it."},{"id":"h92","d":"D1","q":"ある企業は、取引先 200 社に月次の CSV を Cloud Storage へアップロードさせたい。取引先は Google アカウントを持たず、長期間有効な認証情報を配布する運用は避けたい。アップロードの許可は、特定のオブジェクト名と限られた期間に絞る必要がある。最も適切な方法はどれですか。","o":["各取引先へサービスアカウントキーを配布し、そのサービスアカウントにバケットへの書き込み権限を付与して利用してもらう","取引先ごとに、対象オブジェクト名と短い有効期限を指定した署名付き URL (V4) を発行し、HTTP PUT でアップロードしてもらう","バケットに allUsers の Storage Object Creator を付与し、バケットの URL を取引先だけにメールで共有しておく","取引先担当者のメールアドレスを IAM に追加し、対象バケットに対する Storage Object Admin ロールを付与する"],"a":1,"e":"署名付き URL は Google アカウントを持たない相手にも、オブジェクト名と有効期限を限定して一時的な書き込みを許可できます。サービスアカウントキーは長期有効な認証情報の配布にあたります。allUsers への付与は誰でも書き込めてしまい、IAM 追加は Google アカウントが必要で権限も過大です。","qEn":"A company wants 200 partners to upload monthly CSV files to Cloud Storage. The partners do not have Google accounts, and the company does not want to distribute long-lived credentials. Upload permission must be limited to a specific object name and a short period. Which approach is most appropriate?","oEn":["Distribute a service account key to each partner and grant that service account write access to the bucket for them to use","Issue each partner a V4 signed URL limited to the target object name and a short expiry, to upload with HTTP PUT","Grant allUsers the Storage Object Creator role on the bucket and share the bucket URL only with the partners by email","Add each partner contact's email address to IAM and grant the Storage Object Admin role on the target bucket"],"eEn":"A signed URL gives people without Google accounts temporary write access limited to one object name and expiry. A service account key is a long-lived credential. Granting allUsers lets anyone write, and adding emails to IAM requires Google accounts and grants far broader rights than needed."},{"id":"h93","d":"D1","q":"研究所の Linux サーバー 1 台に約 200 GB の実験データのディレクトリがあり、毎晩一部のファイルが追加・更新される。ネットワークは十分だが、サーバーには転送エージェントやコンテナ基盤などの追加ソフトウェアを導入できない。変更分だけを Cloud Storage に反映したい場合、最も適切な方法はどれですか。","o":["gcloud storage cp -r を cron で毎晩実行し、ディレクトリ全体を変更の有無にかかわらず毎回バケットへ上書きアップロードし直す","Storage Transfer Service のエージェントプールを作成し、サーバーにエージェントをインストールして定期転送ジョブを実行する","gcloud storage rsync --recursive を cron で毎晩実行して、新規または変更されたファイルだけをバケットに同期する","Dataflow のバッチジョブを毎晩起動し、サーバーのローカルディレクトリを走査して変更ファイルをバケットに書き込む"],"a":2,"e":"gcloud storage rsync はソースと宛先を比較して差分のファイルだけを転送するため、追加導入なしに変更分のみ反映できます。cp -r は毎回全体を再アップロードし、Storage Transfer Service のオンプレミス転送はエージェントの導入が必要です。Dataflow のワーカーは手元のサーバーのローカルディスクを直接読めません。","qEn":"A research lab has a directory of about 200 GB of experiment data on a single Linux server, with some files added or updated each night. The network is sufficient, but no extra software such as transfer agents or a container platform can be installed on the server. Which method best reflects only the changed files in Cloud Storage?","oEn":["Run gcloud storage cp -r from cron each night so the whole directory is uploaded and overwritten in the bucket every time","Create an agent pool for Storage Transfer Service, install an agent on the server, and run a recurring transfer job from it","Run gcloud storage rsync --recursive from cron each night so only new or changed files are synchronized to the bucket","Launch a nightly Dataflow batch job that scans the server's local directory and writes the changed files to the bucket"],"eEn":"gcloud storage rsync compares source and destination and transfers only differences, so changes can be reflected without installing anything. cp -r re-uploads everything each night, Storage Transfer Service for on-premises needs an installed agent, and Dataflow workers cannot read a local disk on that server."},{"id":"h94","d":"D1","q":"製造業の企業が、データセンターの NFS 共有に保存された約 80 TB の設計図面ファイルを Cloud Storage へ移したい。10 Gbps の専用接続があり、転送は並列で高速に行い、チェックサムによる検証と失敗時の再試行も自動化したい。物理デバイスの輸送は必要ない。最も適切な方法はどれですか。","o":["1 台のサーバーで gcloud storage cp を手動で実行し、失敗したファイルは担当者が確認して再実行する","Cloud Run functions から NFS 共有を直接マウントし、ファイルを 1 つずつ順に Cloud Storage へコピーする","NFS に接続できるサーバーに Storage Transfer Service のエージェントを複数台導入し、そのプールで転送ジョブを実行する","各ファイルを Pub/Sub のメッセージとして発行し、Dataflow のストリーミングジョブで Cloud Storage へ書き出す"],"a":2,"e":"Storage Transfer Service のオンプレミス転送は、複数のエージェントが並列に読み取り、チェックサム検証や失敗時の再試行を自動で行います。手動の gcloud storage cp は並列性と自動再試行に欠け、Cloud Run functions はオンプレミスの NFS をマウントできません。Pub/Sub 経由は大容量ファイルの転送に不向きです。","qEn":"A manufacturer wants to move about 80 TB of design drawings from an NFS share in its data center to Cloud Storage. A 10 Gbps dedicated connection is available, and the company wants fast parallel transfer with checksum verification and automatic retries on failure. No physical shipping is needed. What is the most appropriate method?","oEn":["Run gcloud storage cp manually from a single server and have staff check and rerun any files that failed","Mount the NFS share directly from Cloud Run functions and copy the files to Cloud Storage one at a time","Install several Storage Transfer Service agents on servers that reach the NFS share, form an agent pool, and run a job","Publish each file's contents as Pub/Sub messages and write them out to Cloud Storage with an always-running streaming Dataflow job"],"eEn":"Storage Transfer Service for on-premises data uses multiple agents to read in parallel, verifies checksums, and retries failures automatically. A manual gcloud storage cp lacks parallelism and automatic retries, Cloud Run functions cannot mount an on-premises NFS share, and Pub/Sub is unsuited to moving large files."},{"id":"h95","d":"D1","q":"取引先が AWS の S3 バケットに不定期にファイルを置く。置かれてから数分以内に Cloud Storage へ複製して下流の処理を始めたい。定期スケジュールでバケット全体を走査する方式は、遅延と、オブジェクト数が多いことによる無駄が大きい。最も適切な方法はどれですか。","o":["Storage Transfer Service のスケジュール転送を 1 日 1 回に設定し、前日分の差分をまとめて同期する","BigQuery Data Transfer Service の Amazon S3 コネクタを毎時実行して、S3 のファイルを Cloud Storage に複製する","Compute Engine の VM に cron を設定し、1 分ごとに aws s3 sync と gcloud storage cp を連続して実行する","Storage Transfer Service のイベントドリブン転送で、S3 のイベント通知 (SQS) を契機に新規・更新オブジェクトだけを転送する"],"a":3,"e":"イベントドリブン転送は S3 のイベント通知を SQS 経由で受け、追加・更新されたオブジェクトだけを速やかに転送するため、走査コストが生じません。1 日 1 回の同期では数分以内になりません。BigQuery Data Transfer Service の宛先は BigQuery で、cron と VM は全走査を繰り返す運用負荷の高い方式です。","qEn":"A partner drops files into an AWS S3 bucket at irregular times. The team wants them replicated to Cloud Storage within minutes of arrival so downstream processing can start. Scanning the whole bucket on a fixed schedule causes delay and wasted work because the bucket holds so many objects. What is the most appropriate approach?","oEn":["Set up a scheduled Storage Transfer Service job that runs once a day and syncs the previous day's differences in bulk","Run the BigQuery Data Transfer Service Amazon S3 connector every hour to replicate the S3 files into Cloud Storage","Set up a cron job on a Compute Engine VM that runs aws s3 sync and gcloud storage cp back to back every minute","Use event-driven Storage Transfer Service with S3 event notifications (SQS) to transfer only new or changed objects"],"eEn":"Event-driven transfers receive S3 event notifications through SQS and move only added or updated objects promptly, avoiding repeated scans. A daily sync cannot meet the within-minutes goal, the BigQuery Data Transfer Service lands data in BigQuery rather than Cloud Storage, and a cron VM repeats full scans with heavy operational burden."},{"id":"h96","d":"D1","q":"気象データの提供元が、公開 HTTPS で配信している約 5 万個の観測ファイルについて、URL の一覧 (TSV) を毎月提供してくれる。提供元はクラウドストレージを持っておらず、Google Cloud 側から取りに行って Cloud Storage にコピーする必要がある。一覧にはファイルサイズと MD5 も載せられる。最も適切な方法はどれですか。","o":["Cloud Scheduler で Cloud Run functions を 1 回起動し、5 万個の URL を 1 回の実行の中で順にダウンロードして保存する","Storage Transfer Service の URL リスト転送で TSV を指定し、サイズと MD5 を検証しながらファイルを取り込む","BigQuery Data Transfer Service の Cloud Storage コネクタに TSV を指定し、HTTPS 先のファイルも取り込ませる","gcloud storage cp のソースに https:// で始まる URL を 5 万個並べて、1 回のコマンドで Cloud Storage へコピーする"],"a":1,"e":"Storage Transfer Service の URL リスト転送は、TSV に載せた公開 URL のファイルを取得して Cloud Storage に保存し、サイズや MD5 で検証できます。単一の関数実行で 5 万本を順に処理するとタイムアウトしやすく、BigQuery Data Transfer Service のコネクタは Cloud Storage 上のファイルを読む機能です。gcloud storage cp は https の URL をソースに取れません。","qEn":"A weather data provider publishes about 50,000 observation files over public HTTPS and gives the team a TSV list of their URLs every month. The provider has no cloud storage of its own, so Google Cloud must pull the files and copy them into Cloud Storage. The list can also include file sizes and MD5 hashes. What is the most appropriate method?","oEn":["Start one Cloud Run functions execution from Cloud Scheduler that downloads all 50,000 URLs in sequence within a single run","Use a Storage Transfer Service URL list transfer that points at the TSV and ingests the files while verifying size and MD5","Point the BigQuery Data Transfer Service Cloud Storage connector at the TSV so it also ingests the files behind the HTTPS URLs","Pass all 50,000 https:// URLs as sources to a single gcloud storage cp command to copy them into Cloud Storage"],"eEn":"A Storage Transfer Service URL list transfer fetches public URLs listed in a TSV into Cloud Storage and can verify size and MD5. Processing 50,000 files in one function run is likely to time out, the BigQuery Data Transfer Service connector reads files already in Cloud Storage, and gcloud storage cp cannot take https URLs as sources."},{"id":"h97","d":"D1","q":"工場内のステージング領域 (POSIX ファイルシステム) に、検査機が出力した結果ファイルが溜まっていく。Cloud Storage への転送が成功したファイルだけを元の領域から消して容量を空けたいが、転送前に別の処理がファイルを消してしまう事故は避けたい。Storage Transfer Service を使う場合、最も適切な設定はどれですか。","o":["転送ジョブとは別に、更新から 1 日経過したファイルを毎晩 find コマンドで削除する cron を、転送の成否を確認せずに動かす","転送ジョブで、転送完了後にソース側のオブジェクトを削除するオプションを有効にし、転送が成功したファイルだけを削除させる","転送先バケットにライフサイクルルールを設定し、一定日数が経過したオブジェクトを自動で削除させる","転送ジョブの上書きオプションを「常に上書き」にし、既存のファイルを置き換えながら転送する"],"a":1,"e":"転送後にソースを削除するオプションは、Storage Transfer Service が転送成功を確認したファイルだけを削除するため、未転送のファイルを失いません。別の cron による削除は転送の成否と無関係で、転送前に消す恐れがあります。宛先のライフサイクルは転送元に作用せず、上書きオプションは削除と無関係です。","qEn":"Result files written by inspection machines pile up in a factory staging area (a POSIX file system). The team wants to delete from the source only the files that were transferred successfully to Cloud Storage, and must avoid any other process deleting files before they are transferred. Using Storage Transfer Service, which setting is most appropriate?","oEn":["Run a separate cron job each night that uses find to delete files that were last modified more than a day ago","Enable the transfer job option that deletes source objects after transfer so only successfully transferred files are removed","Set a lifecycle rule on the destination bucket that automatically deletes objects after a number of days","Set the transfer job's overwrite option to always overwrite so existing files at the destination are replaced as they are transferred"],"eEn":"Deleting source objects after transfer lets Storage Transfer Service remove only files it has confirmed as transferred, so untransferred files are never lost. A separate cron deletion ignores transfer success and can delete files too early, a destination lifecycle rule does not act on the source, and the overwrite option has nothing to do with deletion."},{"id":"h98","d":"D1","q":"製造業の基幹システムの Oracle データベース (約 500 GB) を、ライセンス費用を下げるために Cloud SQL for PostgreSQL へ移行する。スキーマ、ストアドプロシージャ、データ型の変換が必要で、移行中の業務停止は短くしたい。最も適切な手段はどれですか。","o":["Datastream で Oracle から Cloud SQL for PostgreSQL へ変更データを流し、スキーマやプロシージャの変換も Datastream に任せる","Oracle から CSV をエクスポートして Cloud SQL にインポートし、ストアドプロシージャは同名のままそのまま実行する","BigQuery Data Transfer Service で Oracle のテーブルを BigQuery に取り込み、そこから Cloud SQL へエクスポートする","Database Migration Service の異種移行 (Oracle から PostgreSQL) で、変換ワークスペースによる変換と継続的なデータ移行を行う"],"a":3,"e":"Database Migration Service は Oracle から PostgreSQL への異種移行に対応し、変換ワークスペースでスキーマや PL/SQL を変換しつつ、継続的移行で停止時間を短くできます。Datastream は変換を行わず宛先も BigQuery などに限られ、CSV の移行は PL/SQL がそのまま動かず、BigQuery 経由では OLTP の移行になりません。","qEn":"A manufacturer is moving its core system's Oracle database (about 500 GB) to Cloud SQL for PostgreSQL to reduce licensing costs. Schemas, stored procedures, and data types must be converted, and downtime during the move must be short. What is the most appropriate approach?","oEn":["Stream changes from Oracle to Cloud SQL for PostgreSQL with Datastream and rely on Datastream to also convert the schema and procedures","Export Oracle tables to CSV, import them into Cloud SQL, and run the stored procedures unchanged under the same names","Load the Oracle tables into BigQuery with the BigQuery Data Transfer Service and then export them from BigQuery to Cloud SQL","Use Database Migration Service for a heterogeneous Oracle-to-PostgreSQL migration with a conversion workspace and continuous sync"],"eEn":"Database Migration Service supports Oracle-to-PostgreSQL heterogeneous migrations, converts schema and PL/SQL in a conversion workspace, and migrates continuously to keep downtime short. Datastream does no conversion and writes only to BigQuery or Cloud Storage, PL/SQL does not run unchanged on PostgreSQL, and a BigQuery detour is not an OLTP migration."},{"id":"h99","d":"D1","q":"金融グループの AWS 米国東部 (バージニア北部) リージョンの S3 に、契約上そのリージョンから持ち出せない Parquet の取引データがある。分析チームは BigQuery の SQL でこのデータを分析したいが、データの複製や移動は禁止されている。最も適切な方法はどれですか。","o":["BigQuery Omni を使い、AWS リージョンに BigLake テーブルを作成して、S3 上のデータをその場でクエリする","BigQuery Data Transfer Service の Amazon S3 コネクタで、米国マルチリージョンの BigQuery データセットへ日次で取り込む","Storage Transfer Service で S3 のデータを Cloud Storage に複製し、BigLake テーブルとして参照する","通常の BigQuery データセットに外部テーブルを作成し、データの場所として S3 の URI を直接指定する"],"a":0,"e":"BigQuery Omni は AWS リージョン内でクエリを実行し、S3 上のデータを複製せずに BigLake テーブルとして分析できるため、持ち出し禁止の要件を満たします。Data Transfer Service や Storage Transfer Service での取り込みは複製にあたり、通常のデータセットの外部テーブルは S3 を直接参照できません。","qEn":"A financial group has Parquet transaction data in S3 in the AWS US East (N. Virginia) region that contractually cannot leave that region. The analytics team wants to analyze it with BigQuery SQL, but copying or moving the data is prohibited. What is the most appropriate approach?","oEn":["Use BigQuery Omni and create a BigLake table in the AWS region so the data in S3 is queried in place","Ingest it daily into a BigQuery dataset in the US multi-region with the BigQuery Data Transfer Service Amazon S3 connector","Replicate the S3 data into Cloud Storage with Storage Transfer Service and then reference it as a BigLake table","Create an external table in a standard BigQuery dataset and specify the S3 URI directly as the data location"],"eEn":"BigQuery Omni runs queries inside the AWS region and analyzes S3 data in place as a BigLake table, satisfying the no-export rule. Loading through the Data Transfer Service or Storage Transfer Service copies the data, and an external table in a standard dataset cannot reference S3 directly."},{"id":"h100","d":"D1","q":"ある企業が、データセンターの共用回線を通じて NAS の 60 TB を Cloud Storage へ移行する。回線は業務システムも使っているため、平日の日中は転送が回線を圧迫して業務に影響しないようにしたい。夜間と週末は帯域を使い切ってよい。Storage Transfer Service のオンプレミス転送で、最も適切な設定はどれですか。","o":["転送を常時実行にしておき、日中に業務が遅くなったら担当者が手動でエージェントを停止し、夜間に再開する運用にする","エージェントを 1 台だけ起動し、同時に動く転送の数を常に最小限に固定したままにしておく","転送先バケットの場所を回線に近いリージョンに変更して、転送に必要な帯域を減らす","エージェントプールに帯域幅の上限を設定し、転送ジョブを夜間と週末の時間帯に実行するようスケジュールする"],"a":3,"e":"オンプレミス転送ではエージェントプールに帯域幅の上限を設定でき、日中の業務への影響を抑えられます。転送ジョブを夜間や週末に寄せれば、空いている時間に帯域を使えます。手動のエージェント停止は運用が属人化し、エージェント 1 台化は夜間の速度も下げ、バケットの場所変更は送るべき通信量を減らしません。","qEn":"A company is moving 60 TB from a NAS to Cloud Storage over a data center link that business systems also use. Weekday daytime transfers must not squeeze the link and disrupt business, while nights and weekends may use all available bandwidth. Using Storage Transfer Service for on-premises data, which setting is most appropriate?","oEn":["Run the transfer continuously and have staff stop the agents by hand whenever daytime business traffic slows down","Run only one agent and keep the number of concurrent transfers fixed at the minimum value at all times","Move the destination bucket to a location closer to the data center so the transfer needs less bandwidth","Set a bandwidth limit on the agent pool and schedule the transfer job to run during nights and weekends"],"eEn":"Agent pools allow a bandwidth limit to protect daytime business traffic, and scheduling the job at night or on weekends uses the idle capacity. Stopping agents by hand is error prone, a single agent slows the night transfer too, and changing the bucket location does not reduce the traffic that must be sent."},{"id":"h101","d":"D1","q":"物流会社の基幹システムが、gs://logistics-in/shipments/ 配下に連番名の CSV を不定期に追加する。既存のファイルは書き換えられない。前回の取り込み以降に追加されたファイルだけを毎時 BigQuery のテーブルへ追記し、同じファイルの二重取り込みは避けたい。コードは書きたくない。最も適切な方法はどれですか。","o":["外部テーブルを作成し、毎時のスケジュールクエリで全ファイルを SELECT して、その結果を宛先のテーブルへ INSERT する","BigQuery Data Transfer Service の Cloud Storage 転送を毎時で作り、追加分だけを取り込ませる","毎時 WRITE_TRUNCATE の load ジョブを実行して、バケット内の全ファイルを読み直し、宛先のテーブルを置き換える","Cloud Storage のオブジェクト作成通知を Pub/Sub に流し、BigQuery サブスクリプションでファイルの中身を取り込ませる"],"a":1,"e":"BigQuery Data Transfer Service の Cloud Storage 転送は、前回の実行以降に追加・更新されたファイルだけを取り込み、スケジュール実行まで設定できます。外部テーブルの INSERT は毎時、全ファイルを重複して追記し、WRITE_TRUNCATE は追記の要件に反します。作成通知にはファイルの中身が含まれません。","qEn":"A logistics company's core system adds CSV files with sequential names under gs://logistics-in/shipments/ at irregular times, and existing files are never rewritten. The team wants to append only files added since the previous run to a BigQuery table every hour, avoiding double ingestion of the same file, without writing code. What is the most appropriate method?","oEn":["Create an external table and run an hourly scheduled query that SELECTs all files and INSERTs the result into the destination table","Create an hourly Cloud Storage transfer in BigQuery Data Transfer Service that loads only files added since the last run","Run a load job with WRITE_TRUNCATE every hour that re-reads every file in the bucket and replaces the destination table","Send object-creation notifications to Pub/Sub and use a BigQuery subscription to ingest the contents of each file"],"eEn":"The Cloud Storage transfer in BigQuery Data Transfer Service loads only files added or modified since the previous run and can run on a schedule. An external-table INSERT would append every file again each hour, WRITE_TRUNCATE contradicts the append requirement, and creation notifications do not carry file contents."},{"id":"h102","d":"D1","q":"BigQuery の asia-northeast1 にある分析用データセット (約 40 テーブル) を、災害対策と欧州拠点からの参照のために、europe-west1 のデータセットへ毎日自動で複製したい。独自コードの開発や、Cloud Storage を経由する手作業の運用は避けたい。最も適切な方法はどれですか。","o":["テーブルごとに bq extract で Cloud Storage に書き出し、別リージョンのバケットを経由して毎日 bq load を実行し直す","欧州側から東京のテーブルを直接参照する JOIN クエリを書き、複製せずに毎日のレポートを作成する運用にする","既存データセットのロケーションを europe-west1 に変更して、東京側のテーブルがそのまま欧州に移るようにする","BigQuery のデータセットコピー (Data Transfer Service) を宛先のデータセットに作成し、毎日のスケジュールで実行させる"],"a":3,"e":"データセットコピーはテーブルを別リージョンのデータセットへスケジュールでコピーでき、コード開発も Cloud Storage 経由の作業も不要です。extract と load の組み合わせは手作業の運用が重く、リージョンをまたぐクエリは単一のジョブでは実行できません。作成済みデータセットのロケーションは変更できません。","qEn":"A BigQuery analytics dataset in asia-northeast1 (about 40 tables) must be copied to a dataset in europe-west1 every day, for disaster recovery and for reference by the European office. The team wants to avoid custom code and manual operations that route data through Cloud Storage. What is the most appropriate method?","oEn":["Export each table with bq extract to Cloud Storage and run bq load every day through a bucket in the other region","Write a JOIN query in Europe that reads the Tokyo tables directly, so daily reports are built without copying anything","Change the location of the existing dataset to europe-west1 so the Tokyo tables simply move to Europe as they are","Create a BigQuery dataset copy (Data Transfer Service) to the destination dataset and run it on a daily schedule"],"eEn":"A dataset copy replicates tables to a dataset in another region on a schedule, with no code and no Cloud Storage detour. The extract-and-load combination is heavy manual operation, a single query cannot span regions, and the location of an existing dataset cannot be changed."},{"id":"h103","d":"D1","q":"小売企業が Teradata から BigQuery への移行を進めている。分析チームが保守する Teradata SQL のスクリプトが約 800 本あり、BigQuery の SQL への書き換え工数が最大の懸念である。データ本体の移行とは別に、SQL の方言変換を効率化したい。最も適切な手段はどれですか。","o":["Cloud Data Fusion のパイプラインに 800 本の SQL を貼り付け、実行時に Teradata の方言を自動で吸収させる運用にする","スクリプトをそのまま BigQuery のクエリエディタで実行し、Teradata 方言の構文を BigQuery が自動認識して処理することに任せる","Database Migration Service のスキーマ変換機能に SQL スクリプトを読み込ませ、BigQuery 向けの構文に変換してもらう","BigQuery Migration Service のバッチ SQL トランスレーターで、Cloud Storage 上のスクリプトを一括して変換する"],"a":3,"e":"BigQuery Migration Service のバッチ SQL トランスレーターは、Teradata などの SQL スクリプトを Cloud Storage から読み込み、BigQuery SQL へ一括変換します。Data Fusion は SQL 方言を吸収せず、BigQuery は Teradata 方言をそのままは実行できません。Database Migration Service は運用データベースの移行用です。","qEn":"A retailer is migrating from Teradata to BigQuery. The analytics team maintains about 800 Teradata SQL scripts, and the effort of rewriting them for BigQuery is the biggest concern. Separately from moving the data itself, the team wants to make the SQL dialect conversion efficient. What is the most appropriate tool?","oEn":["Paste the 800 scripts into a Cloud Data Fusion pipeline and have it absorb the Teradata dialect at execution time","Run the scripts unchanged in the BigQuery query editor and rely on BigQuery to recognize and process Teradata dialect syntax","Load the SQL scripts into the schema conversion feature of Database Migration Service and convert them for BigQuery","Convert the scripts in Cloud Storage in bulk with the BigQuery Migration Service batch SQL translator"],"eEn":"The BigQuery Migration Service batch SQL translator reads Teradata and other scripts from Cloud Storage and converts them to BigQuery SQL in bulk. Data Fusion does not absorb SQL dialects, BigQuery cannot run Teradata dialect as is, and Database Migration Service targets operational databases."},{"id":"h104","d":"D1","q":"Cloud SQL for PostgreSQL の本番データベースから BigQuery へ、Datastream でレプリケーションしている。週末の障害対応でストリームを一時停止したまま放置したところ、ソースデータベースのディスク使用量が急増して警告が出た。当面ストリームを再開する予定はない。原因と対処として最も適切なものはどれですか。","o":["Datastream が BigQuery に書き込めなかった変更を、ソースデータベース内のテーブルに一時退避しているので、BigQuery 側の容量を増やす","停止中に全テーブルのバックフィルが始まったことが原因なので、バックフィルの対象からテーブルを除外すれば WAL が解放される","停止中のストリームが使う論理レプリケーションスロットが未消費の WAL を保持し続けていることが原因なので、不要ならストリームを削除してスロットも削除する","ソースの自動バックアップが原因なので、バックアップの保持日数を短くすれば、ディスク使用量は元の水準に戻る"],"a":2,"e":"PostgreSQL のレプリケーションスロットは、読み取り側が消費するまで WAL を保持します。ストリームが停止したままだと WAL が溜まってディスクを圧迫するため、再開しないならストリームとスロットを削除します。Datastream は変更をソースのテーブルに退避せず、バックフィルや自動バックアップは WAL の滞留と関係しません。","qEn":"Datastream replicates a production Cloud SQL for PostgreSQL database to BigQuery. After the stream was left paused following weekend incident work, disk usage on the source database surged and triggered warnings. There is no plan to resume the stream for the time being. Which cause and remedy is most appropriate?","oEn":["Datastream parks changes it could not write to BigQuery in a table inside the source database, so increase capacity on the BigQuery side","A backfill of all tables started while the stream was paused, so excluding tables from the backfill will release the WAL","The paused stream's replication slot retains unconsumed WAL, so delete the stream and drop the slot if it is no longer needed","Automatic backups of the source are the cause, so shortening the backup retention period will bring disk usage back down"],"eEn":"A PostgreSQL replication slot retains WAL until its consumer reads it. A stream left paused lets WAL accumulate and fill the disk, so if it will not resume, delete the stream and the slot. Datastream does not park changes in source tables, and backfills or automatic backups are unrelated to WAL buildup."},{"id":"h105","d":"D1","q":"保険会社が Datastream で MySQL の契約テーブルを BigQuery に複製している。監査部門は、現在の状態だけでなく、各契約が「いつ、どう変更されたか」という履歴と削除の記録も BigQuery 上で追跡したい。ソーステーブルには主キーがある。最も適切な設定はどれですか。","o":["既定のマージモードのまま運用し、BigQuery のタイムトラベルを使って過去の時点の状態や削除された契約を参照する","BigQuery 宛先の書き込みモードを追加専用 (append-only) にし、変更イベントを行として蓄積させる","マージモードのままソース側に論理削除用の列を追加し、物理削除をやめて履歴が BigQuery に残るようにする","ステイルネス上限を最長に設定し、変更をまとめて遅らせて適用させることで、中間の状態も保持させる"],"a":1,"e":"追加専用モードは挿入・更新・削除の各変更イベントを行として蓄積するので、履歴と削除の記録を追えます。既定のマージモードは最新の状態に集約し、削除された行は残りません。タイムトラベルは参照できる期間が限られ、ソース側の列追加は監査要件を満たさず、ステイルネス上限は履歴の保持と無関係です。","qEn":"An insurer replicates a MySQL contracts table to BigQuery with Datastream. The audit department wants to trace not only the current state but also when and how each contract changed, including deletions, in BigQuery. The source table has a primary key. Which setting is most appropriate?","oEn":["Keep the default merge mode and use BigQuery time travel to look at the state at earlier points in time","Set the BigQuery destination write mode to append-only so that change events are accumulated as rows","Keep merge mode but add a soft-delete column on the source and stop physical deletes so history remains in BigQuery","Set the staleness limit to its maximum so changes are applied late in batches and intermediate states are kept"],"eEn":"Append-only mode accumulates every insert, update, and delete event as rows, so history and deletions can be traced. The default merge mode collapses to the latest state and deleted rows vanish. Time travel covers only a limited window, a source column change does not meet the audit need, and the staleness limit is unrelated to keeping history."},{"id":"h106","d":"D1","q":"Datastream で Oracle の受注テーブルを BigQuery に複製している。ダッシュボードは数分以内の鮮度を求めているが、BigQuery 側への反映は最大で十数分遅れることがある。コストが多少増えても鮮度を優先したい。最も適切な調整はどれですか。","o":["ステイルネス上限を長く設定し、バックグラウンドで走るマージの回数を減らして、反映の遅れを小さくしようとする","ストリームの並列バックフィルの数を増やして、変更データのキャプチャにかかる遅延を縮めようとする","BigQuery 宛先のステイルネス上限を短く設定して鮮度を上げる (マージが増えコストも増える)","ソースの Oracle のアーカイブログの保持期間を延ばして、ログの読み取りで生じる遅延を解消する"],"a":2,"e":"BigQuery 宛先ではステイルネス上限が鮮度とコストのトレードオフを決め、短くするほど新しい状態が反映される一方、マージが増えてコストも上がります。上限を長くすると遅れは大きくなります。バックフィルは初期の全件コピー用で CDC の遅延と無関係、アーカイブログの保持期間も鮮度を変えません。","qEn":"Datastream replicates an Oracle orders table to BigQuery. The dashboard needs data that is at most a few minutes old, but changes sometimes show up in BigQuery more than ten minutes late. The team is willing to pay somewhat more for freshness. Which adjustment is most appropriate?","oEn":["Set a longer staleness limit so fewer background merges run and the delay in reflecting changes becomes smaller","Increase the number of concurrent backfill tasks on the stream to shorten the change data capture delay","Set a shorter staleness limit on the BigQuery destination to raise freshness (more merges and higher cost)","Lengthen the archived log retention period on the source Oracle database to remove the log reading delay"],"eEn":"The staleness limit on a BigQuery destination trades freshness against cost: a shorter limit reflects newer state but runs more merges and costs more, while a longer one widens the lag. Backfill is the initial full copy and unrelated to CDC delay, and archived log retention does not change freshness."},{"id":"h107","d":"D1","q":"外食チェーンの注文データベース (MySQL) の全テーブル (合計 10 億行超) を、毎日 BigQuery に反映している。現行は updated_at が前日以降の行だけを JDBC で抽出して MERGE しているが、物理削除された注文が BigQuery に残り続け、売上が過大になる。ソースのスキーマは変更できず、全件スキャンによる業務時間帯の負荷も避けたい。最も適切な見直しはどれですか。","o":["Datastream のバイナリログ CDC に切り替え、挿入・更新・削除をそのまま BigQuery に反映する","抽出条件を updated_at が直近 1 週間の行に広げて、削除済みの注文も拾えるようにする","毎日 BigQuery 側のテーブルを削除し、全テーブルの全行を JDBC で抽出し直して、同じ名前のテーブルへ置き換える","ソースの各テーブルに削除用のトリガーを作成し、削除された行を履歴テーブルへ記録させる"],"a":0,"e":"Datastream はバイナリログから挿入・更新・削除を取り込むので、物理削除も BigQuery に反映でき、全件スキャンも不要です。削除済みの行は updated_at で抽出できず、期間を広げても拾えません。毎日の全件置換は負荷が大きく、ソースへのトリガー追加はスキーマ変更の禁止に反します。","qEn":"A restaurant chain reflects all tables of its order database (MySQL, over 1 billion rows in total) into BigQuery every day. The current job extracts only rows with updated_at since the previous day over JDBC and MERGEs them, but physically deleted orders remain in BigQuery and inflate sales. The source schema cannot be changed, and heavy full scans during business hours must be avoided. Which revision is most appropriate?","oEn":["Switch to Datastream binary-log-based CDC so inserts, updates, and deletes are reflected in BigQuery as they occur","Widen the extraction condition to rows whose updated_at falls in the last week so that deleted orders are also picked up","Drop the BigQuery tables every day and re-extract every row of every table over JDBC to replace them","Create delete triggers on each source table that record the deleted rows in a history table"],"eEn":"Datastream reads inserts, updates, and deletes from the binary log, so physical deletes reach BigQuery without full scans. Deleted rows cannot be found by updated_at, even with a wider window. A daily full replacement is heavy on the source, and adding triggers violates the ban on schema changes."},{"id":"h108","d":"D1","q":"データ基盤チームは、PostgreSQL の変更データを Datastream で取り込み、生の変更ファイルを保管したうえで、Dataflow や Spark で自社の複雑な変換を行いたい。必要に応じて同じ変更ファイルを再処理できることも要件である。BigQuery のテーブルへ直接マージしたいわけではない。最も適切な宛先はどれですか。","o":["BigQuery を宛先にして、マージモードで最新状態のテーブルだけを保持させ、そのテーブルを変換の入力にする","Pub/Sub を宛先に指定し、変更イベントをトピックに発行して、サブスクライバが読み出した時点でメッセージを削除させる","別の Cloud SQL for PostgreSQL インスタンスを宛先にして、変更ファイルをテーブルへ複製したうえで処理する","Cloud Storage を宛先にして、変更イベントを Avro または JSON のファイルとして書き出して、下流で処理する"],"a":3,"e":"Datastream は Cloud Storage を宛先にすると、変更イベントを Avro や JSON のファイルとして書き出すため、生データを保管して下流の Dataflow や Spark で再処理できます。BigQuery のマージモードは最新状態へ集約され生の変更を残さず、Pub/Sub や Cloud SQL は Datastream の宛先ではありません。","qEn":"A data platform team wants to capture PostgreSQL changes with Datastream, keep the raw change files, and then apply its own complex transformations with Dataflow or Spark. It must also be able to reprocess the same change files when needed. It does not want to merge directly into BigQuery tables. Which destination is most appropriate?","oEn":["Use BigQuery as the destination in merge mode so that only the latest-state tables are kept and used as transformation input","Specify Pub/Sub as the destination so change events are published to a topic and removed once they are read","Use another Cloud SQL for PostgreSQL instance as the destination and replicate the change files into tables before processing","Use Cloud Storage as the destination so change events are written as Avro or JSON files and processed downstream"],"eEn":"With Cloud Storage as the destination, Datastream writes change events as Avro or JSON files, so raw data is retained and can be reprocessed by Dataflow or Spark. BigQuery merge mode collapses to the latest state and keeps no raw changes, and neither Pub/Sub nor Cloud SQL is a Datastream destination."},{"id":"h109","d":"D1","q":"AWS 上のアプリが Amazon Kinesis Data Streams にイベントを出力している。分析基盤は Google Cloud にあり、BigQuery で分析したい。Kinesis 側のアプリは変更できず、コンシューマのコードを自作して運用することも避けたい。最も適切な構成はどれですか。","o":["Pub/Sub の Kinesis インポートトピックでストリームを取り込み、BigQuery サブスクリプションでテーブルに書き込む","Storage Transfer Service で Kinesis のレコードを Cloud Storage へ定期的に転送し、そこから BigQuery にロードする","Datastream で Kinesis を変更データのソースに指定して、BigQuery へレプリケーションするストリームを作成する","AWS 側に Lambda 関数を作成し、Kinesis のレコードを Pub/Sub に発行するコードを自分たちで書いて運用する"],"a":0,"e":"Pub/Sub のインポートトピックは Kinesis Data Streams からの取り込みをマネージドで行い、BigQuery サブスクリプションでコードなしにテーブルへ書き込めます。Storage Transfer Service と Datastream は Kinesis をソースにできず、AWS 側の Lambda 開発はコードの自作と運用を避ける要件に反します。","qEn":"An app on AWS writes events to Amazon Kinesis Data Streams. The analytics platform is on Google Cloud, and the team wants to analyze the events in BigQuery. The Kinesis-side app cannot be changed, and the team does not want to write and operate its own consumer code. What is the most appropriate architecture?","oEn":["Ingest the stream with a Pub/Sub Kinesis import topic and write it to a table with a BigQuery subscription","Periodically transfer Kinesis records to Cloud Storage with Storage Transfer Service and then load them into BigQuery","Create a Datastream stream that specifies Kinesis as a change data source and replicates it to BigQuery","Write and operate a Lambda function on AWS that publishes Kinesis records to Pub/Sub with custom code"],"eEn":"A Pub/Sub import topic ingests from Kinesis Data Streams as a managed feature, and a BigQuery subscription writes to a table without code. Storage Transfer Service and Datastream cannot use Kinesis as a source, and building a Lambda function means writing and operating custom code, which the team wants to avoid."},{"id":"h110","d":"D1","q":"配車アプリが、ドライバーごとの位置・状態の更新イベントを Pub/Sub に発行している。同一ドライバーのイベントは発行順に処理しないと状態が逆転するが、全体では毎秒数万件あり、並列に処理して水平にスケールさせたい。最も適切な設計はどれですか。","o":["トピックのパブリッシャとサブスクライバを 1 つずつに固定し、1 スレッドで届いた順番に処理して、水平スケールはあきらめる","driver_id を順序指定キーにしてメッセージ順序指定を有効にし、同じキーは同じリージョンから発行する","サブスクリプションで exactly-once delivery を有効にして、メッセージの順序もサービス側で保証させる","各メッセージにタイムスタンプ属性を付け、サブスクライバ側で全メッセージをバッファして並べ替えてから処理する構成にする"],"a":1,"e":"順序指定キーを使うと、同じキーのメッセージが発行順に配信され、キーが異なれば並列に処理できるため、スケールと順序を両立できます。単一のパブリッシャとスレッドでは毎秒数万件をさばけず、exactly-once delivery は重複排除であり順序の保証ではありません。全件の並べ替えは遅延とメモリの面で現実的でありません。","qEn":"A ride-hailing app publishes location and status update events for each driver to Pub/Sub. Events for the same driver must be processed in publish order or the state will be reversed, yet the overall rate is tens of thousands per second and processing must scale out in parallel. Which design is most appropriate?","oEn":["Pin the topic to one publisher and one subscriber and process the messages in order of arrival on a single thread, giving up horizontal scale","Enable message ordering with driver_id as the ordering key and publish same-key messages to the same regional endpoint","Enable exactly-once delivery on the subscription and rely on it to guarantee message order as well","Attach a timestamp attribute to each message and have subscribers buffer all messages and sort them before processing"],"eEn":"With ordering keys, messages sharing a key are delivered in publish order while different keys are processed in parallel, so order and scale coexist. One publisher and thread cannot handle tens of thousands per second, exactly-once delivery removes duplicates but does not guarantee order, and sorting everything in memory is impractical."},{"id":"h111","d":"D1","q":"注文システムは 1 つのトピックに、order_created、order_cancelled、payment_failed など多様なイベントを発行しており、各メッセージには event_type 属性が付いている。請求チームは payment_failed だけ、物流チームは order_created だけを受け取りたい。パブリッシャのコード変更やトピックの増設は避けたい。最も適切な方法はどれですか。","o":["チームごとにサブスクリプションを作り、event_type 属性のフィルタを設定して、サービス側で配信を絞る","全チームが同じサブスクリプションを共有し、各自のコードで event_type を見て不要なメッセージを破棄するようにする","イベント種別ごとに新しいトピックを作り、パブリッシャが種別に応じて振り分けて発行するよう変更する","各チームのコードで不要なメッセージには ack を返さず、ack 期限が切れて再配信されるのを待つ運用にする"],"a":0,"e":"サブスクリプションのフィルタを使えば、属性が一致するメッセージだけがその購読に配信され、パブリッシャ側の変更は不要です。1 つのサブスクリプションを共有すると各メッセージは 1 つのコンシューマにしか届かず、他チームの分が失われます。トピックの増設は変更要件に反し、ack しない運用は再配信のループを生みます。","qEn":"An ordering system publishes many event types, such as order_created, order_cancelled, and payment_failed, to a single topic, and each message carries an event_type attribute. The billing team wants only payment_failed and the logistics team wants only order_created. Changing publisher code or adding topics should be avoided. What is the most appropriate method?","oEn":["Create one subscription per team with a filter on the event_type attribute so delivery is narrowed on the service side","Have all teams share one subscription and let each team's code inspect event_type and discard messages it does not need","Create a new topic for each event type and change the publisher to route each message to the right topic","Have each team's code skip the ack for unwanted messages and wait for the ack deadline to expire and trigger redelivery"],"eEn":"Subscription filters deliver only messages whose attributes match, with no publisher changes. Sharing one subscription means each message reaches just one consumer, so other teams lose messages. Adding topics requires publisher changes, and withholding acks causes endless redelivery."},{"id":"h112","d":"D1","q":"IoT 機器のイベントが Pub/Sub トピックに流れている。コンプライアンスのため、加工せずに生データを 5 分ごとにまとまった Avro ファイルとして Cloud Storage に保管したい。ストリーミングジョブの運用や自前のコードは避けたい。最も運用負荷の低い方法はどれですか。","o":["Dataflow のストリーミングジョブを自作して常時稼働させ、ウィンドウごとにファイルへ書き込む構成にする","トピックに Cloud Storage サブスクリプションを作成し、Avro 形式とバッチ期間を指定してバケットへ書き出す","BigQuery サブスクリプションでテーブルに書き込み、そのテーブルを日次で Avro としてエクスポートする","プルサブスクリプションを Cloud Run functions で 5 分ごとに読み、メッセージを 1 件ずつオブジェクトとして保存する"],"a":1,"e":"Cloud Storage サブスクリプションは、メッセージを指定した形式とバッチ期間でバケットにファイルとして直接書き出すマネージド機能で、ジョブもコードも不要です。自作の Dataflow ジョブは常時稼働の運用が必要で、BigQuery 経由は生データのままではない 2 段構成です。1 件ずつの保存は小さなファイルを大量に作ります。","qEn":"IoT device events flow into a Pub/Sub topic. For compliance, the raw data must be stored without transformation as consolidated Avro files in Cloud Storage every 5 minutes. The team wants to avoid operating a streaming job or writing its own code. Which method has the lowest operational burden?","oEn":["Build a Dataflow streaming job of your own, keep it running all the time, and write a file for each window","Create a Cloud Storage subscription on the topic and write Avro files to the bucket with a batch duration","Write to a table with a BigQuery subscription and then export that table as Avro every day","Read a pull subscription from Cloud Run functions every 5 minutes and save each message as its own object"],"eEn":"A Cloud Storage subscription is a managed feature that writes messages straight to the bucket in the chosen format and batch window, with no job or code. A custom Dataflow job needs always-on operation, the BigQuery route is a two-step design rather than raw data, and saving each message separately creates huge numbers of tiny files."},{"id":"h113","d":"D1","q":"複数のアプリチームが同じ Pub/Sub トピックにイベントを発行しており、フィールドの欠落や型違いのメッセージが混ざって、下流の BigQuery への取り込みが壊れる事故が続いた。不正な形式のメッセージは発行の時点で拒否したい。最も適切な対策はどれですか。","o":["BigQuery サブスクリプションの未知フィールドの破棄オプションを有効にして、型違いのメッセージを自動で補正させる","サブスクリプションにデッドレタートピックを設定し、取り込みに失敗したメッセージだけを別のトピックへ退避させる","トピックに Avro か Protocol Buffers のスキーマを関連付け、不適合なメッセージの発行を拒否させる","各チームに発行前の自己検証を依頼するガイドラインを定め、リリースのたびにレビューで確認する"],"a":2,"e":"トピックにスキーマを関連付けると、スキーマに合わないメッセージは発行時点でエラーになり、不正な形式の混入を入口で防げます。未知フィールドの破棄は型違いを補正せず、デッドレタートピックは配信後の退避で事故そのものは防げません。ガイドラインとレビューだけでは強制力がありません。","qEn":"Several app teams publish events to the same Pub/Sub topic, and messages with missing fields or wrong types keep slipping in and breaking ingestion into BigQuery downstream. The team wants malformed messages rejected at publish time. Which measure is most appropriate?","oEn":["Enable the option to drop unknown fields on the BigQuery subscription so that mistyped messages are corrected automatically","Configure a dead-letter topic on the subscription and divert only the messages that fail to be ingested to another topic","Associate an Avro or Protocol Buffers schema with the topic so non-conforming messages are rejected at publish","Ask each team to validate before publishing through a guideline and confirm it in every release review"],"eEn":"A topic schema makes publishing fail for non-conforming messages, blocking malformed data at the entrance. Dropping unknown fields does not repair wrong types, a dead-letter topic only diverts messages after delivery and does not prevent the incidents, and guidelines with reviews have no enforcement power."},{"id":"h114","d":"D1","q":"Cloud Run 上のサービスが、Pub/Sub のメッセージを受け取って処理する。メッセージ量に応じてインスタンスを自動で増減させたい。ポーリング用のコードや常駐のプルループは書きたくなく、エンドポイントは認証済みのリクエストだけを受け付けたい。最も適切な構成はどれですか。","o":["ストリーミングプルで常時接続するコンテナを Compute Engine に置き、最小インスタンス数を固定して運用する","エンドポイントを未認証で公開し、リクエスト本文に含まれる共有パスワードをアプリケーションのコードで検証する","プッシュサブスクリプションを Cloud Run の URL に向け、OIDC トークンで認証して起動元ロールを付与する","Cloud Scheduler から毎分 Cloud Run を呼び出し、その処理の中で Pub/Sub から同期的にメッセージをプルさせる"],"a":2,"e":"プッシュサブスクリプションは HTTPS でメッセージを送り、Cloud Run が受信量に応じてオートスケールします。OIDC トークンと起動元ロールで認証済みの呼び出しだけを受けられ、ポーリングのコードも不要です。常駐プルの VM は手動のスケール運用になり、未認証の公開は要件に反し、毎分のプルは遅延と無駄を生みます。","qEn":"A Cloud Run service receives and processes Pub/Sub messages. Instances should scale automatically with message volume, the team does not want to write polling code or a resident pull loop, and the endpoint must accept only authenticated requests. Which configuration is most appropriate?","oEn":["Run a container with a streaming pull connection on Compute Engine and keep the minimum instance count fixed","Expose the endpoint without authentication and verify a shared password included in the request body in application code","Point a push subscription at the Cloud Run URL, authenticate with an OIDC token, and grant the invoker role","Call Cloud Run from Cloud Scheduler every minute and have it pull messages synchronously from Pub/Sub"],"eEn":"A push subscription delivers over HTTPS and Cloud Run autoscales with the load. An OIDC token plus the invoker role admits only authenticated calls, and no polling code is needed. A resident pull VM means manual scaling, an unauthenticated endpoint violates the requirement, and per-minute pulls add latency and waste."},{"id":"h115","d":"D1","q":"製造ラインのカメラが、1 回あたり数十 MB の検査動画を撮影するたびに、解析パイプラインへ通知を送る。現在は動画データそのものを Pub/Sub のメッセージ本文に入れて発行しており、メッセージサイズの上限を超えて失敗している。最も適切な設計はどれですか。","o":["動画を Cloud Storage に置き、バケット名とオブジェクト名だけを Pub/Sub で通知する","動画を複数のメッセージに分割して順番に発行し、下流で受信した順に連結して元の動画を復元する","動画データをメッセージの属性 (attributes) に入れ、本文を空にして発行する構成に変更し、サイズの上限を回避する","動画を gzip で圧縮してからメッセージ本文に入れ、発行するメッセージの数を増やさずに送る"],"a":0,"e":"大きなデータは Cloud Storage に置き、Pub/Sub には参照 (バケットとオブジェクト名) だけを送る設計が標準です。分割して連結する方式は順序と欠落の管理が複雑になり、属性は本文よりさらに小さい制限があります。動画の圧縮では、サイズが上限内に収まる保証がありません。","qEn":"Each time a camera on a manufacturing line records an inspection video of tens of megabytes, it must notify an analysis pipeline. Currently the video data itself is put into the Pub/Sub message body, and publishing fails because it exceeds the message size limit. Which design is most appropriate?","oEn":["Upload the video to Cloud Storage and notify with a Pub/Sub message carrying only the bucket and object name","Split the video into several messages, publish them in order, and reassemble them downstream in order of arrival","Change the design to put the video data in the message attributes and publish with an empty message body","Compress the video with gzip, put it in the message body, and send it without adding more messages"],"eEn":"The standard design stores large data in Cloud Storage and sends only a reference (bucket and object name) through Pub/Sub. Splitting and reassembling complicates ordering and loss handling, attributes have an even smaller limit than the body, and compression does not guarantee the video fits within the limit."},{"id":"h116","d":"D1","q":"決済イベントを Pub/Sub のプルサブスクリプションから読んで処理する。ワーカーは処理後に ack を送るが、ネットワークの瞬断で ack が届かないことがあり、その場合に同じメッセージが再配信されて二重に課金処理される。ack が成功したかをアプリで確認でき、成功後は再配信されない仕組みにしたい。最も適切な対処はどれですか。","o":["プッシュサブスクリプションに切り替えて exactly-once delivery を有効にし、HTTP の応答コードで ack の成否を確認する","ack 期限を最短に設定して、処理中のメッセージがより早く再配信されるようにして、取りこぼしを防ぐ","ワーカーの並列度を上げて処理を速め、ack が届かないという状況そのものが起きにくくなるようにする","プルサブスクリプションで exactly-once delivery を有効にし、ack の結果を確認して成功分だけを処理済みにする"],"a":3,"e":"exactly-once delivery はプルサブスクリプションで使え、ack の成否が応答で分かり、ack に成功したメッセージは再配信されません。プッシュサブスクリプションでは exactly-once delivery を使えません。ack 期限を短くすると再配信がむしろ増え、並列度を上げても ack が届かない問題は解決しません。","qEn":"Payment events are read from a Pub/Sub pull subscription and processed. The worker sends an ack after processing, but brief network interruptions sometimes prevent the ack from arriving, in which case the same message is redelivered and charged twice. The team wants the app to be able to confirm whether an ack succeeded, with no redelivery after a successful ack. Which action is most appropriate?","oEn":["Switch to a push subscription with exactly-once delivery enabled and check whether each ack succeeded by the HTTP response code","Set the ack deadline to the minimum so in-flight messages are redelivered sooner and nothing is missed","Raise worker parallelism to process faster so the situation where an ack fails to arrive becomes less likely","Enable exactly-once delivery on the pull subscription, check each ack result, and count only successful acks as processed"],"eEn":"Exactly-once delivery works on pull subscriptions, reports ack success or failure in the response, and does not redeliver messages whose ack succeeded. Push subscriptions cannot use it. A shorter ack deadline causes more redelivery, and more parallelism does not fix acks that fail to arrive."},{"id":"h117","d":"D1","q":"モバイルアプリのイベントを Pub/Sub に発行している。1 つのトピックのメッセージ本文に電話番号フィールドが含まれるが、下流のどのサブスクライバにも電話番号を渡してはならない。パブリッシャは多数のチームが管理しており、Dataflow などの変換ジョブの新設は避けたい。軽量な変更をサービス側で行う最も適切な方法はどれですか。","o":["全サブスクライバに電話番号を無視するよう通知し、各自のコードで該当フィールドを読み飛ばしてもらう","電話番号を含むメッセージをすべて Cloud Storage に保存し、Pub/Sub へは何も発行しない構成に変える","サブスクリプションごとにフィルタを設定し、電話番号の項目を本文に持つメッセージを配信対象から外す","トピックに SMT の JavaScript UDF を設定し、保存前に電話番号フィールドを取り除く"],"a":3,"e":"Pub/Sub の単一メッセージ変換 (SMT) は、トピックにアタッチした JavaScript UDF で保存前にメッセージを加工でき、全サブスクライバに加工後の内容だけが届きます。サブスクライバ任せでは漏えいを防げず、サブスクリプションのフィルタは属性しか見ないため本文の電話番号を取り除けません。","qEn":"Mobile app events are published to Pub/Sub. The message body on one topic contains a phone number field, but no downstream subscriber may receive phone numbers. Many teams manage the publishers, and the team wants to avoid adding a transformation job such as Dataflow. Which is the most appropriate way to make this lightweight change on the service side?","oEn":["Notify all subscribers to ignore phone numbers and ask each of them to skip the field in their own code","Store every message that contains a phone number in Cloud Storage and change the design so nothing is published to Pub/Sub","Set a filter on each subscription that excludes messages carrying a phone number field in the body from delivery","Attach a single message transform (JavaScript UDF) to the topic that removes the phone number field before storage"],"eEn":"A single message transform with a JavaScript UDF attached to the topic can modify messages before storage, so every subscriber receives only the processed content. Leaving it to subscribers cannot prevent leakage, and subscription filters look only at attributes and cannot strip a field from the body."},{"id":"h118","d":"D1","q":"国内の基幹システムが出力する Shift_JIS (CP932) エンコードの CSV を、毎日 Cloud Storage 経由で BigQuery に取り込んでいる。日本語の列が文字化けしており、ロードジョブのエンコーディング指定を変えて試しても直らない。最も適切な対処はどれですか。","o":["ロードジョブのエンコーディングに ISO-8859-1 を指定すれば、日本語の文字もそのまま保持されて取り込まれるようになる","ロードジョブのエンコーディングに SHIFT_JIS を指定して、変換を行わずにそのまま取り込めるようにする","Shift_JIS から UTF-8 へ変換したファイルを Cloud Storage に出力し直し、それをロードする","全列を BYTES 型で取り込み、後から SQL の CAST で STRING 型に変換して、文字を元の状態に戻す"],"a":2,"e":"BigQuery の CSV ロードが扱えるエンコーディングは UTF-8 と ISO-8859-1 だけで、Shift_JIS は指定できません。ISO-8859-1 を選んでも日本語は保持されず、BYTES を STRING にキャストする場合も UTF-8 として解釈されるため直りません。事前に UTF-8 へ変換してからロードします。","qEn":"A domestic core system outputs CSV files encoded in Shift_JIS (CP932), which are loaded into BigQuery every day via Cloud Storage. The Japanese columns come out garbled, and changing the encoding setting of the load job does not fix it. What is the most appropriate action?","oEn":["Specify ISO-8859-1 as the load job encoding, which keeps Japanese characters intact when they are loaded","Specify SHIFT_JIS as the load job encoding so the files can be loaded as they are without any conversion","Convert the files from Shift_JIS to UTF-8, write them back to Cloud Storage, and load the converted files","Load every column as BYTES and later convert it to STRING with a SQL CAST to restore the original characters"],"eEn":"BigQuery CSV loads support only UTF-8 and ISO-8859-1, so Shift_JIS cannot be specified. Choosing ISO-8859-1 does not preserve Japanese text, and casting BYTES to STRING interprets the bytes as UTF-8, so it does not help either. Convert to UTF-8 before loading."},{"id":"h119","d":"D1","q":"外部システムが、数百万件のオブジェクトを 1 つの大きな JSON 配列 ([ {...}, {...} ]) として 1 ファイルにエクスポートする。この Cloud Storage 上のファイルを BigQuery にロードすると解析エラーになる。ソース側の出力形式は変更できない。最も適切な対処はどれですか。","o":["ロード前に配列を 1 行 1 オブジェクトの NDJSON に変換してから、JSON 形式でロードする","ロードジョブの JSON オプションで「配列形式を許可」を有効にして、1 つの配列を行に展開して取り込ませる","ソース形式に AVRO を指定してロードジョブを実行し、配列の各要素をレコードとして読み取らせる","ファイル全体を区切り文字を変えた CSV として読み込み、1 つの列に入った配列を後から SQL で行に分解する"],"a":0,"e":"BigQuery の JSON ロードは改行区切り JSON (1 行 1 オブジェクト) が前提で、全体が配列のファイルは読み込めません。ソースを変更できないので、取り込み前に NDJSON へ変換します。配列を許可するオプションは存在せず、AVRO 指定は形式が合わず、1 列に全体を入れる方法は行サイズの上限を超えます。","qEn":"An external system exports millions of objects as one large JSON array ([ {...}, {...} ]) in a single file. Loading this file from Cloud Storage into BigQuery fails with a parsing error, and the source cannot change its output format. What is the most appropriate action?","oEn":["Convert the array into newline-delimited JSON (NDJSON) with one object per line before loading it as a JSON source","Enable an 'allow array format' JSON option on the load job so the single array is expanded into rows during loading","Run the load job with AVRO as the source format so that each element of the array is read as a record","Read the whole file as a CSV with a different delimiter and later split the array in one column into rows with SQL"],"eEn":"BigQuery JSON loads expect newline-delimited JSON, one object per line, and cannot read a file that is a single array. Since the source cannot change, convert to NDJSON before loading. No option allows arrays, AVRO does not match the format, and putting everything into one column exceeds the row size limit."},{"id":"h120","d":"D1","q":"コールセンターの問い合わせ履歴 CSV には、コメント欄にダブルクォートで囲まれた改行が含まれ、一部の行は末尾の列が省略されている。BigQuery へのロードで行数や列数の不一致を示すエラーになる。データを欠落させずに取り込みたい。最も適切なロード設定はどれですか。","o":["許容する不正レコード数 (max_bad_records) を十分に大きくして、エラーになる行を読み飛ばしてロードを成功させる","allow_quoted_newlines で引用符内の改行を、allow_jagged_rows で欠けた末尾の列を許可する","スキーマの自動検出 (autodetect) を有効にして、列数の違いと引用符内の改行を自動で補正させる","区切り文字をタブに変更し、引用符で囲む設定を無効にして、改行をそのまま区切りとして扱わせる"],"a":1,"e":"引用符内の改行は allow_quoted_newlines、末尾の列が欠けた行は allow_jagged_rows で許可すれば、行を捨てずに取り込めます。max_bad_records は不正行を読み飛ばすため欠落が生じ、自動検出は構造の不一致を補正せず、タブへの変更や引用符の無効化では改行を含む値を正しく読めません。","qEn":"Call center inquiry history CSV files contain line breaks inside double-quoted comment fields, and some rows omit trailing columns. Loading them into BigQuery fails with errors about mismatched row and column counts. The data must be loaded without dropping any rows. Which load setting is most appropriate?","oEn":["Set the maximum number of bad records (max_bad_records) high enough to skip the failing rows and let the load succeed","Enable allow_quoted_newlines for quoted line breaks and allow_jagged_rows so missing trailing columns become NULL","Enable schema auto-detection (autodetect) so that differing column counts and quoted line breaks are corrected automatically","Change the delimiter to tab and disable quote handling so that line breaks are simply treated as record separators"],"eEn":"Allowing quoted newlines and jagged rows loads every row, filling missing trailing columns with NULL. max_bad_records skips bad rows and loses data, autodetect does not repair structural mismatches, and switching to tabs or disabling quotes cannot read values that contain line breaks correctly."},{"id":"h121","d":"D1","q":"ドキュメント DB から出力した注文データには、配列 (明細行) と入れ子のオブジェクト (配送先) が含まれる。BigQuery で REPEATED と STRUCT として保持し、型情報も欠落させずにロードしたい。CSV にフラット化するとスキーマ管理が煩雑になる。出力形式として最も適切なものはどれですか。","o":["CSV で出力し、明細行を行方向に展開してから、注文 ID で後から結合して元の構造を再現する","CSV の 1 列に配列を区切り文字付きの文字列として入れ、ロード時に REPEATED 型へ自動変換させる","Avro (または Parquet) で出力し、スキーマを内包したままロードして入れ子と配列を保つ","XML で出力し、BigQuery のロードジョブで XML のネスト構造をそのまま解釈させる"],"a":2,"e":"Avro や Parquet はスキーマと入れ子・繰り返し構造を内包しており、BigQuery は STRUCT と ARRAY として型を保ったままロードできます。CSV は入れ子を表せず、展開や文字列化はスキーマ管理を複雑にします。区切り文字付きの文字列は REPEATED に自動変換されず、BigQuery は XML のロードに対応しません。","qEn":"Order data exported from a document database contains arrays (line items) and nested objects (shipping address). The team wants to load it into BigQuery as REPEATED and STRUCT fields without losing type information, and flattening to CSV would make schema management messy. Which output format is most appropriate?","oEn":["Export as CSV, expand the line items into separate rows, and join them back by order ID later to rebuild the structure","Put arrays into one CSV column as delimiter-joined strings and have the load convert them to REPEATED fields automatically","Export as Avro (or Parquet) and load it with its embedded schema so nested objects become STRUCT and arrays become ARRAY","Export as XML and have the BigQuery load job interpret the nested XML structure as it is"],"eEn":"Avro and Parquet embed the schema and nested or repeated structure, so BigQuery loads them as STRUCT and ARRAY with types intact. CSV cannot represent nesting, and expanding or stringifying complicates schema management. Delimited strings are not auto-converted to REPEATED, and BigQuery does not load XML."},{"id":"h122","d":"D1","q":"取引先が、1 日分のログを 1 つの巨大な gzip 圧縮 CSV (展開後 約 1.2 TB) として毎日 Cloud Storage に置く。BigQuery へのロードに数時間かかり、並列に読み込まれていないようだ。取引先には出力形式の変更を依頼できる。ロード時間を短縮するための最も適切な依頼はどれですか。","o":["gzip の圧縮レベルを最大にしてもらい、BigQuery が読み込むデータ量を減らして処理を速くする","gzip の単一ファイルをやめ、非圧縮の分割ファイル、または Avro・Parquet で出力してもらう","単一ファイルのまま bzip2 など別の圧縮形式に変更してもらい、BigQuery が並列で展開できるようにする","ロード用のスロットを追加購入して、1 つの圧縮ファイルを複数のスロットで並列に読み込ませる"],"a":1,"e":"BigQuery は gzip 圧縮された単一の CSV を分割して並列に読めないため、ロードに時間がかかります。非圧縮の複数ファイルや、ブロック単位で圧縮される Avro・Parquet なら並列にロードできます。圧縮レベルの変更や別の圧縮形式の単一ファイルでは並列性が変わらず、スロットを増やしても 1 つの圧縮ファイルは分割されません。","qEn":"A partner places one day of logs as a single huge gzip-compressed CSV (about 1.2 TB uncompressed) in Cloud Storage every day. Loading it into BigQuery takes hours and does not appear to run in parallel. The partner can be asked to change the output format. Which request is most appropriate to shorten the load time?","oEn":["Ask them to raise the gzip compression level to the maximum so BigQuery reads less data and finishes faster","Output uncompressed split files or a block-compressed format such as Avro or Parquet instead of one gzip file","Ask them to switch the single file to another compression format such as bzip2 so BigQuery can decompress it in parallel","Buy additional slots for the load so that several slots read the single compressed file in parallel"],"eEn":"BigQuery cannot split a single gzip-compressed CSV to read it in parallel, so loading is slow. Multiple uncompressed files, or block-compressed Avro or Parquet, load in parallel. A higher compression level or another compression of one file does not change parallelism, and extra slots cannot split a single compressed file."},{"id":"h123","d":"D1","q":"配送先マスターの CSV をスキーマの自動検出でロードしたところ、郵便番号「0600001」が整数として扱われ、先頭の 0 が消えた。商品コードなど、数字だけで構成される識別子の列は他にもあり、毎日同じ形式のファイルが届く。再発を防ぐ最も適切な方法はどれですか。","o":["自動検出が参照するサンプル行数を増やして、列の型をより正確に推定させるようにロードの設定を変える","自動検出をやめて明示的なスキーマを定義し、識別子の列を STRING 型に固定する","ロード後に LPAD で郵便番号を 7 桁にそろえる SQL を毎回実行し、商品コードも同じ桁数に補正する","識別子の列を FLOAT64 で取り込み、表示するときに書式設定で先頭の 0 を補って見せるようにする"],"a":1,"e":"識別子は数値として扱わず、明示的なスキーマで STRING に固定すれば先頭の 0 が保たれます。サンプル行を増やしても数字だけの列は整数と推定されます。LPAD の後補正は桁数がそろわない商品コードに使えず、FLOAT64 で取り込むと元の 0 は失われ、表示書式で見せるだけでは値が復元されません。","qEn":"After loading a customer address master CSV with schema auto-detection, the postal code '0600001' was treated as an integer and lost its leading zero. Other columns, such as product codes, also consist only of digits, and files with the same format arrive every day. What is the most appropriate way to prevent a recurrence?","oEn":["Increase the number of sample rows that auto-detection inspects so it infers column types more accurately","Turn off auto-detection and define an explicit schema that fixes identifier columns as STRING","Run SQL after each load that pads postal codes to 7 digits with LPAD and adjusts product codes to the same width","Load the identifier columns as FLOAT64 and restore the leading zeros with display formatting when showing them"],"eEn":"Fixing identifiers as STRING in an explicit schema preserves leading zeros. More sample rows still infer all-digit columns as integers. LPAD cannot fix product codes whose lengths differ, and loading as FLOAT64 destroys the original zeros, which display formatting cannot truly restore."},{"id":"h124","d":"D1","q":"日次で届く Parquet ファイルには、アップストリームの改修により新しい列が不定期に追加される。BigQuery の既存テーブル (日付パーティション) へ WRITE_APPEND でロードしているが、新しい列を含むファイルはスキーマの不一致で失敗する。既存データは変更せず、新しい列を自動で受け入れたい。最も適切な設定はどれですか。","o":["スキーマ更新オプションに ALLOW_FIELD_RELAXATION を指定して、列の追加も一緒に許可されるようにする","書き込み設定を WRITE_TRUNCATE に変更して、毎回テーブルをスキーマごと置き換えてからロードする","ignore_unknown_values を有効にして、テーブルにない新しい列の値は読み飛ばしたうえで取り込む","ロードジョブのスキーマ更新オプションに ALLOW_FIELD_ADDITION を指定して列を追加させる"],"a":3,"e":"ALLOW_FIELD_ADDITION は、追記のロード時にファイルにある新しい列をテーブルへ追加します。ALLOW_FIELD_RELAXATION は REQUIRED を NULLABLE に緩める設定で列は増えません。WRITE_TRUNCATE は既存データを失い、ignore_unknown_values は新しい列の値を捨てるため、受け入れたいという要件に反します。","qEn":"Daily Parquet files occasionally gain new columns because of upstream changes. They are loaded with WRITE_APPEND into an existing BigQuery table (date-partitioned), but files with new columns fail with a schema mismatch. The team wants to accept the new columns automatically without altering existing data. Which setting is most appropriate?","oEn":["Specify ALLOW_FIELD_RELAXATION as the schema update option so that adding columns is permitted along with it","Change the write disposition to WRITE_TRUNCATE so the table, schema included, is replaced on every load","Enable ignore_unknown_values so values for new columns that the table lacks are skipped while the rest is loaded","Specify ALLOW_FIELD_ADDITION as the schema update option on the load job so new columns are added to the table"],"eEn":"ALLOW_FIELD_ADDITION adds new columns found in the file during an append load. ALLOW_FIELD_RELAXATION only relaxes REQUIRED to NULLABLE and adds no columns. WRITE_TRUNCATE destroys existing data, and ignore_unknown_values discards the new columns' values, contradicting the goal of accepting them."},{"id":"h125","d":"D1","q":"Cloud Storage に gs://lake/events/dt=2026-10-01/ のようなフォルダ構成で Parquet が毎日追加される。BigQuery では dt を列として使い、日付で絞ったときにその日のファイルだけを読ませたい。データは BigQuery に移さず、ロードジョブも実行しない。最も適切な設定はどれですか。","o":["毎日 bq load で BigQuery のネイティブテーブルへロードして、dt 列をテーブルのパーティション列にする","パーティショニングを設定しない外部テーブルを作成し、dt を含むフォルダ名はクエリ側では無視する","外部テーブルのスキーマに dt という STRING 列を手作業で定義し、ファイルの中身から値を読み取らせる","Hive パーティショニングを自動検出 (AUTO) にした外部テーブルを作成し、パーティションフィルタを必須に設定する"],"a":3,"e":"外部テーブルで Hive パーティショニングを AUTO にすると、パスの dt=… がパーティション列になり、フィルタに合うフォルダだけを読めます。パーティションフィルタ必須で全件スキャンも防げます。ロードはデータを移さない要件に反し、パーティションなしでは dt が使えず、手書きの dt 列はパスから値が入らず NULL になります。","qEn":"Parquet files are added daily to Cloud Storage under folders such as gs://lake/events/dt=2026-10-01/. In BigQuery the team wants to use dt as a column and read only that day's files when filtering by date. The data must not be moved into BigQuery and no load job should run. Which setting is most appropriate?","oEn":["Run bq load every day into a native BigQuery table and make the dt column the table's partitioning column","Create an external table without partitioning and ignore the dt folder names on the query side","Define a STRING column named dt in the external table schema by hand and have it read values from the file contents","Create an external table with Hive partitioning mode set to AUTO and require a partition filter on it"],"eEn":"With Hive partitioning set to AUTO, the dt=... path segment becomes a partition column and only matching folders are read; requiring the filter also prevents full scans. A load contradicts the no-move rule, no partitioning leaves dt unusable, and a hand-defined dt column gets no value from the path and returns NULL."},{"id":"h126","d":"D1","q":"Dataflow のバッチパイプラインが 2 億行を BigQuery に書き込む。途中で失敗したときに一部のデータだけがテーブルに見える状態は許されず、全件の書き込みが終わった時点で一括して参照できるようにしたい。ストリーミング用の高スループットな書き込み経路を使いたい。最も適切な方法はどれですか。","o":["Storage Write API のコミット済み (committed) ストリームに書き込み、行ごとにすぐ読み取れるようにする","Storage Write API の既定ストリームに書き込み、失敗した場合は同じ行を最初から再送し直す","レガシーのストリーミング挿入 (insertAll) で、各行に insertId を付けて、書き込みの重複を避ける","Storage Write API の保留 (pending) ストリームに書き込み、すべて完了してから一括でコミットする"],"a":3,"e":"保留ストリームは、コミットするまで書き込んだ行が読み取れず、全件の書き込み後に一括でコミットして可視化できます。コミット済みストリームと既定ストリームは書いた行がすぐ見えるため、途中失敗で一部だけが参照されます。insertAll も書いた行がすぐ見え、重複排除もベストエフォートです。","qEn":"A Dataflow batch pipeline writes 200 million rows to BigQuery. If it fails midway, a partially written state must never be visible in the table; all rows should become queryable at once after the full write finishes. The team wants a high-throughput streaming write path. What is the most appropriate method?","oEn":["Write to a Storage Write API committed stream so that each row can be read immediately after it is written","Write to the Storage Write API default stream and resend the same rows from the start if a failure occurs","Use legacy streaming inserts (insertAll) and attach an insertId to each row to avoid duplicate writes","Write to a pending stream of the Storage Write API and commit all streams once everything is written"],"eEn":"Rows in a pending stream stay invisible until committed, so they can be committed together after the whole write completes. Committed and default streams make rows visible immediately, exposing partial data after a failure. insertAll also exposes rows immediately, and its deduplication is best effort."},{"id":"h127","d":"D1","q":"決済アプリが BigQuery に取引を 1 件ずつ書き込む。ネットワーク障害でリトライしても同じ取引が二重に入らないことを、BigQuery 側の仕組みで保証したい。書き込んだ行はすぐクエリできる必要がある。最も適切な方法はどれですか。","o":["Storage Write API の既定ストリームに書き込み、BigQuery が重複した行を自動的に取り除くのを待つ","レガシーのストリーミング挿入で insertId を付け、重複が取り除かれることを保証として扱う","保留ストリームに書き込み、リトライのたびにストリームを作り直してから、一括でコミットする","コミット済みストリームにオフセットを指定して書き込み、リトライ時の重複を拒否させる"],"a":3,"e":"コミット済みストリームでは、書き込み時にオフセットを指定すると、同じオフセットの再送が拒否され exactly-once になり、行もすぐクエリできます。既定ストリームは at-least-once で重複を除きません。insertId による排除はベストエフォートで保証にならず、保留ストリームはコミットまで行が見えません。","qEn":"A payment app writes transactions to BigQuery one at a time. The team wants BigQuery itself to guarantee that retries after network failures never insert the same transaction twice, and the written rows must be queryable immediately. What is the most appropriate method?","oEn":["Write to the Storage Write API default stream and wait for BigQuery to remove duplicate rows automatically","Use legacy streaming inserts with an insertId and treat the removal of duplicates as a guarantee","Write to a pending stream and recreate the stream on every retry before committing everything in bulk","Write to a Storage Write API committed stream with explicit row offsets so duplicate retries are rejected"],"eEn":"In a committed stream, specifying offsets makes a resend of the same offset get rejected, giving exactly-once writes with rows queryable immediately. The default stream is at-least-once and does not remove duplicates, insertId deduplication is best effort rather than a guarantee, and a pending stream hides rows until commit."},{"id":"h128","d":"D1","q":"Cloud Storage 上の 600 GB の CSV を外部テーブルとして公開しているが、営業ダッシュボードの集計が毎回遅く、処理するバイト数も多い。データは日次で追加されるだけで、集計は常に直近 90 日と顧客 ID で絞る。最も適切な改善はどれですか。","o":["ネイティブテーブルにロードし、日付でパーティション分割、顧客 ID でクラスタリングする","外部テーブルのクエリ結果キャッシュを有効にして、すべてのクエリ結果を永続的に再利用させる","CSV を gzip で圧縮して Cloud Storage に保存し直し、外部テーブルが読み取るバイト数を減らす","ダッシュボードのクエリに LIMIT を付けて、外部テーブルの読み取りを途中で打ち切らせる"],"a":0,"e":"ネイティブテーブルにロードし、日付のパーティションと顧客 ID のクラスタリングを設定すれば、BigQuery のストレージ最適化と読み取り範囲の絞り込みが効きます。キャッシュは同一クエリにしか効かず永続的でもありません。gzip 圧縮は読み取りを遅くし、LIMIT は走査するバイト数を減らしません。","qEn":"A 600 GB set of CSV files in Cloud Storage is exposed as an external table, but the sales dashboard's aggregations are slow every time and process many bytes. Data is only appended daily, and the aggregations always filter on the last 90 days and a customer ID. Which improvement is most appropriate?","oEn":["Load the data into a native table, partition it by date, and cluster by customer ID","Enable query result caching for the external table so every query result is reused permanently","Recompress the CSV files with gzip in Cloud Storage so the external table reads fewer bytes","Add LIMIT to the dashboard queries so that reading from the external table is cut off partway"],"eEn":"Loading into a native table with date partitioning and customer ID clustering enables BigQuery's storage optimizations and narrows the data read. The cache only helps identical queries and is not permanent, gzip slows reading, and LIMIT does not reduce the bytes scanned."},{"id":"h129","d":"D1","q":"分析チームが、BigQuery の 3 TB のテーブルを Spark ジョブの入力として Cloud Storage に Parquet で書き出したい。出力 URI を単一のファイル名にして EXPORT DATA を実行したところ、1 ファイルのサイズ上限を超えたというエラーになった。最も適切な修正はどれですか。","o":["出力 URI にワイルドカード (part-*.parquet) を含めて、複数ファイルに分割して書き出す","出力形式を CSV に変更して、1 ファイルのサイズに制限なく単一ファイルとして書き出せるようにする","テーブルを 1 行ずつ SELECT し、クライアントから Cloud Storage の Parquet オブジェクトへ追記していく","EXPORT DATA を実行するプロジェクトのスロット予約を増やして、1 ファイルあたりの上限を引き上げる"],"a":0,"e":"BigQuery のエクスポートは 1 ファイルのサイズに上限があり、大きなテーブルは URI にワイルドカードを入れて複数ファイルに分割します。形式を変えても上限は同じで、1 行ずつ取得して追記する方法は非現実的です。スロット予約はクエリの処理能力で、ファイルサイズの上限を変えません。","qEn":"An analytics team wants to write a 3 TB BigQuery table to Cloud Storage as Parquet to feed a Spark job. Running EXPORT DATA with a single file name as the output URI fails with an error that the file size limit was exceeded. What is the most appropriate fix?","oEn":["Include a wildcard such as part-*.parquet in the output URI so the export splits into multiple files","Change the output format to CSV so the table can be written as a single file without any size limit","Read the table row by row with SELECT and append the rows to a Parquet object in Cloud Storage from a client","Increase the slot reservation of the project that runs EXPORT DATA to raise the per-file size limit"],"eEn":"BigQuery exports have a per-file size limit, so large tables need a wildcard URI to split into multiple files. Changing the format keeps the same limit, and row-by-row retrieval is impractical. Slot reservations add query capacity and do not change the file size limit."},{"id":"h130","d":"D1","q":"アプリが出力した Avro ファイルのイベント時刻の列は、Avro の timestamp-micros 論理型で書かれている。BigQuery にロードしたところ、この列が TIMESTAMP ではなく INT64 の数値として取り込まれた。テーブルのスキーマは自動検出に任せている。最も適切な対処はどれですか。","o":["ロードジョブの書き込み設定を WRITE_TRUNCATE に変更し、再ロードによって Avro の論理型から列の型を再推定させる","スキーマ更新オプションに ALLOW_FIELD_RELAXATION を指定して、INT64 の列を TIMESTAMP 型に緩和させる","Avro スキーマ内の論理型の記述を削除し、この列を単なる整数として明示的に出力し直したファイルをロードする","Avro のロードで use_avro_logical_types を有効にし、TIMESTAMP として取り込ませる"],"a":3,"e":"BigQuery は Avro の論理型を既定では変換せず、timestamp-micros は INT64 として取り込まれます。ロード時に use_avro_logical_types を有効にすると TIMESTAMP や DATE などの型になります。書き込み設定の変更や ALLOW_FIELD_RELAXATION では型は変わらず、論理型を削除すると整数のままです。","qEn":"The event time column in Avro files produced by an app is written with the Avro timestamp-micros logical type. When loaded into BigQuery, the column was ingested as an INT64 number instead of TIMESTAMP. The table schema is left to auto-detection. What is the most appropriate fix?","oEn":["Change the write disposition to WRITE_TRUNCATE and reload so the column type is inferred again from the Avro logical types","Specify the ALLOW_FIELD_RELAXATION schema update option so the INT64 column is relaxed into a TIMESTAMP column","Delete the logical type declaration from the Avro schema and regenerate the files with the column output as a plain integer","Enable the Avro logical types setting (use_avro_logical_types) on the load so timestamp-micros is ingested as TIMESTAMP"],"eEn":"BigQuery does not convert Avro logical types by default, so timestamp-micros loads as INT64. Enabling use_avro_logical_types ingests it as TIMESTAMP, DATE, and similar types. Changing the write disposition or using ALLOW_FIELD_RELAXATION does not change types, and removing the logical type just leaves an integer."},{"id":"h131","d":"D1","q":"日付パーティションの BigQuery テーブルに、日次でロードしている売上データがある。2026-09-15 の分だけ元ファイルに誤りがあり、修正済みのファイルが届いた。他の日付のデータには一切触れず、その 1 日分だけを置き換えたい。置き換えの途中で、その日の行が欠けたり二重に見えたりする瞬間も作りたくない。最も適切な方法はどれですか。","o":["テーブル全体を宛先にして WRITE_TRUNCATE でロードし、修正済みの 1 日分のファイルだけでテーブルを置き換える","WRITE_APPEND でそのまま修正済みファイルをロードし、誤った行は後日まとめて手作業で削除する運用にする","該当日の行を DELETE で削除してから、別のジョブで修正済みファイルを INSERT するよう 2 つのジョブを順に実行する","宛先をパーティションデコレータ付き (sales$20260915) にして、WRITE_TRUNCATE でロードする"],"a":3,"e":"パーティションデコレータ付きの宛先に WRITE_TRUNCATE でロードすると、その日のパーティションだけが 1 つのジョブで原子的に置き換わり、他の日付には影響しません。テーブル全体への WRITE_TRUNCATE は全日付を失い、WRITE_APPEND は誤った行が残ります。DELETE と INSERT の 2 段は途中の状態が見えます。","qEn":"A date-partitioned BigQuery table receives daily sales loads. The source file for 2026-09-15 alone was wrong, and a corrected file has arrived. The team wants to replace just that one day without touching any other date, and without any moment where that day's rows appear missing or doubled. What is the most appropriate method?","oEn":["Load into the whole table with WRITE_TRUNCATE so that the table is replaced by the corrected file for that single day","Load the corrected file as it is with WRITE_APPEND and manually delete the wrong rows together at a later date","Run two jobs in sequence: delete that day's rows with DELETE and then insert the corrected file with INSERT","Load the corrected file with a WRITE_TRUNCATE load job into the partition decorator destination sales$20260915"],"eEn":"Loading with WRITE_TRUNCATE into a partition decorator replaces only that day's partition atomically in one job, leaving other dates untouched. WRITE_TRUNCATE on the whole table loses all other dates, WRITE_APPEND leaves the wrong rows, and a DELETE followed by an INSERT exposes intermediate states."},{"id":"h132","d":"D1","q":"モバイルアプリの利用者データが Firestore に保存されている。分析チームは、日次のスナップショットで十分で、全ドキュメントを読み出す独自コードは書かずに、Firestore のデータを BigQuery で SQL 分析したい。最も適切な手順はどれですか。","o":["SDK で Firestore の全ドキュメントを 1 件ずつ読み出して、BigQuery に挿入するジョブを毎日実行する","Firestore を BigQuery の外部データソースとして登録し、コレクションを直接クエリする SQL を書く","Firestore のコンソールから CSV としてデータをダウンロードして、BigQuery の画面からアップロードする","Firestore のマネージドエクスポートを Cloud Storage に出力し、BigQuery に日次でロードする"],"a":3,"e":"Firestore のマネージドエクスポートは Cloud Storage にスナップショットを出力し、BigQuery がそのエクスポートを直接ロードできるため、コード開発なしで日次の分析用コピーを作れます。SDK での全件読み出しは独自コードが必要で、BigQuery は Firestore を外部データソースとして参照できず、CSV のダウンロード機能もありません。","qEn":"End user data for a mobile app is stored in Firestore. The analytics team wants to analyze the Firestore data with SQL in BigQuery. A daily snapshot is enough, and the team does not want to write custom code that reads every document. What is the most appropriate procedure?","oEn":["Run a job every day that reads all Firestore documents one by one with an SDK and inserts them into BigQuery","Register Firestore as an external data source in BigQuery and write SQL that queries the collections directly","Download the data from the Firestore console as CSV and upload it through the BigQuery console","Run a Firestore managed export to Cloud Storage and load that export into BigQuery on a daily basis"],"eEn":"A Firestore managed export writes a snapshot to Cloud Storage that BigQuery can load directly, so a daily analytic copy needs no custom code. Reading every document with an SDK needs custom code, BigQuery cannot query Firestore as an external data source, and the console offers no CSV download."},{"id":"h133","d":"D1","q":"顧客マスターには、同じ customer_id の行が更新のたびに追記されて複数存在する (updated_at 列あり)。最新の 1 行だけを残したクリーンなテーブルを BigQuery の SQL で作りたい。SELECT DISTINCT では重複が消えなかった。最も適切なクエリの書き方はどれですか。","o":["SELECT DISTINCT customer_id, updated_at として、その結果を元のテーブルに結合して最新の行を取り出す","customer_id で GROUP BY し、他のすべての列に MAX を適用して、1 つの ID につき 1 行にまとめる","COUNT(*) OVER (PARTITION BY customer_id) で件数を数え、2 件以上ある ID の行をすべて削除する","customer_id ごとに updated_at の降順で ROW_NUMBER() を振って、QUALIFY で 1 の行だけを選ぶ"],"a":3,"e":"customer_id ごとに updated_at の降順で行番号を振り、QUALIFY で 1 番目だけを残せば、最新の 1 行を選べます。DISTINCT は updated_at が異なる行を重複とみなさず、全列への MAX は別々の行の値を混ぜてしまいます。2 件以上ある ID を削除すると顧客自体が消えます。","qEn":"The customer master has multiple rows for the same customer_id because a row is appended on every update (there is an updated_at column). The team wants to build a clean table with only the latest row per customer using BigQuery SQL. SELECT DISTINCT did not remove the duplicates. Which query approach is most appropriate?","oEn":["Run SELECT DISTINCT customer_id, updated_at and join that result back to the original table to pick the latest row","GROUP BY customer_id and apply MAX to every other column to collapse each ID into a single row","Count rows with COUNT(*) OVER (PARTITION BY customer_id) and delete every row whose ID appears two or more times","Number rows per customer_id by updated_at descending with ROW_NUMBER() and keep number 1 with QUALIFY"],"eEn":"Numbering rows per customer_id by updated_at descending and keeping number 1 with QUALIFY selects the latest row. DISTINCT does not treat rows with different updated_at as duplicates, and MAX across every column mixes values from different rows. Deleting IDs with two or more rows would remove the customers entirely."},{"id":"h134","d":"D1","q":"受注データの金額列が STRING で取り込まれ、「1,200」「N/A」「--」などの値が混在している。CAST で数値化するとクエリ全体がエラーで止まる。数値化できない行は止めずに、後で調べられるよう別に保管したい。最も適切な方法はどれですか。","o":["エラーになる値を LIKE '%N/A%' などのパターンで列挙して削除し、残った行だけを CAST で数値化する","カンマ除去後に SAFE_CAST を使い、元の値があって結果が NULL の行を隔離テーブルへ振り分ける","金額列を STRING のまま集計に使い、SUM の中で文字列として加算させて合計を求める","CAST のエラーが出るたびにクエリ全体を再実行し、問題の行を手作業で取り除いてから再試行する"],"a":1,"e":"SAFE_CAST は変換できない値を NULL にしてクエリを止めないため、元が NULL でないのに結果が NULL の行を隔離テーブルへ振り分けて後から調べられます。値を列挙して削除する方法は網羅できず行が失われ、STRING のままでは SUM できません。エラーのたびの手作業は運用になりません。","qEn":"An order data amount column was loaded as STRING and contains mixed values such as '1,200', 'N/A', and '--'. Converting with CAST stops the entire query with an error. Rows that cannot be converted should not halt processing and should be kept separately for later investigation. Which method is most appropriate?","oEn":["List the failing values with patterns such as LIKE '%N/A%', delete those rows, and CAST only the remaining rows","Strip commas, use SAFE_CAST, and send rows with a source value but a NULL result to a quarantine table","Leave the amount column as STRING and add the values as text inside SUM to obtain the total","Rerun the whole query each time a CAST error appears, removing the offending rows by hand before each retry"],"eEn":"SAFE_CAST returns NULL instead of stopping the query, so rows with a source value but a NULL result can be sent to a quarantine table for later review. Enumerating bad values to delete never covers them all and loses rows, STRING cannot be summed, and hand-fixing after every error is not an operating procedure."},{"id":"h135","d":"D1","q":"各支店が手作業で入力した売上 CSV の日付列に、「2026-10-01」「2026/10/1」「01-Oct-2026」の 3 形式が混在している。STRING のままロード済みで、DATE 型の列に正規化したい。解析できない行は NULL にして検出できるようにしたい。最も適切な SQL はどれですか。","o":["CAST(日付列 AS DATE) をそのまま適用し、書式が合わない行は BigQuery が自動で補完して変換させる","PARSE_DATE を 1 つの書式だけで適用し、その書式に合わない行は WHERE 句で除外して取り除く","SAFE.PARSE_DATE を 3 つの書式ごとに試し、COALESCE で最初に成功した結果を採用する","SUBSTR で先頭の 10 文字を切り出し、その文字列をそれ以上の処理なしで DATE にキャストする"],"a":2,"e":"SAFE.PARSE_DATE は書式に合わない値で NULL を返すため、複数の書式を COALESCE で順に試せば、3 形式を DATE にそろえつつ解析不能な行は NULL で検出できます。CAST は一部の書式しか読めずエラーで止まり、1 書式だけでは他の行が失われます。先頭 10 文字の切り出しは書式により崩れます。","qEn":"A sales CSV entered by hand at each branch mixes three formats in its date column: '2026-10-01', '2026/10/1', and '01-Oct-2026'. It was loaded as STRING and must be normalized to a DATE column, with unparseable rows left as NULL so they can be detected. Which SQL is most appropriate?","oEn":["Apply CAST(date_column AS DATE) as is and let BigQuery complete and convert rows whose format does not match","Apply PARSE_DATE with only one format and exclude the rows that do not match that format with a WHERE clause","Try SAFE.PARSE_DATE with each of the three formats and keep the first success using COALESCE","Cut out the first 10 characters with SUBSTR and cast that string straight to DATE without further handling"],"eEn":"SAFE.PARSE_DATE returns NULL for values that do not match a format, so trying each format in order with COALESCE normalizes all three formats and leaves unparseable rows as NULL. CAST reads only some formats and errors out, a single format loses the other rows, and taking 10 characters breaks on some formats."},{"id":"h136","d":"D1","q":"会員データの電話番号は、欠損が NULL の行、空文字 '' の行、空白だけの行が混在している。「電話番号が未登録の会員数」を COUNTIF(phone IS NULL) で出したところ、現場の実感より大幅に少なかった。正しく数えるための最も適切な前処理はどれですか。","o":["phone = '' の行だけを別に数えて、COUNTIF(phone IS NULL) の結果にその件数を足し合わせる","NULLIF(TRIM(phone), '') で空文字と空白のみを NULL にそろえ、IS NULL で数える","LENGTH(phone) が 10 未満の行をすべて未登録とみなして、IS NULL の件数と合算して報告する","phone 列を INT64 にキャストして、変換できなかった行をすべて未登録として数える"],"a":1,"e":"TRIM で空白を除いたうえで NULLIF により空文字を NULL に変換すれば、欠損の表現を NULL にそろえられ、IS NULL で正しく数えられます。空文字だけを足すと空白のみの行が漏れ、桁数での判定や INT64 へのキャストは、ハイフン付きの正しい番号や先頭の 0 を誤って未登録にしてしまいます。","qEn":"In member data, missing phone numbers appear as NULL in some rows, as an empty string '' in others, and as whitespace only in others. Counting 'members with no registered phone number' with COUNTIF(phone IS NULL) gave a figure far below what the field staff expected. Which preprocessing is most appropriate for counting correctly?","oEn":["Count the rows where phone = '' separately and add that number to the result of COUNTIF(phone IS NULL)","Normalize empty and whitespace-only values to NULL with NULLIF(TRIM(phone), '') and then count with IS NULL","Treat every row whose LENGTH(phone) is below 10 as unregistered and add it to the IS NULL count when reporting","Cast the phone column to INT64 and count every row that could not be converted as unregistered"],"eEn":"TRIM followed by NULLIF turns empty and whitespace-only values into NULL, so every kind of missing value is counted by IS NULL. Adding only empty strings misses whitespace-only rows, and judging by length or INT64 casts wrongly marks valid numbers with hyphens or leading zeros as unregistered."},{"id":"h137","d":"D1","q":"EC サイトの会員名簿を、店舗 POS の購入履歴と氏名・メールアドレスで突き合わせたい。入力元によって英数字が全角と半角、カタカナが半角と全角で混在しており、等値結合が一致しない。最も適切な正規化はどれですか。","o":["結合キーの両側に LOWER と TRIM を適用して、大文字小文字と前後の空白をそろえてから結合するようにする","結合キーの両側に NORMALIZE(列, NFD) を適用して、文字を分解した形式にそろえてから結合する","結合キーの両側に NORMALIZE(列, NFKC) を適用して、全角と半角の表記をそろえる","REGEXP_REPLACE で全角文字をすべて空文字に置き換えて削除し、残った半角文字だけで結合する"],"a":2,"e":"NFKC 正規化は互換文字を統一し、全角の英数字を半角に、半角カナを全角にそろえるので、表記ゆれのある結合キーを一致させられます。LOWER と TRIM は文字幅を変えず、NFD は濁点などを分解するだけで互換文字の幅は統一しません。全角文字を削除すると氏名自体が失われます。","qEn":"The team wants to match an e-commerce member roster to store POS purchase history by name and email address. Depending on the source, alphanumerics are mixed full-width and half-width, and katakana is mixed half-width and full-width, so equality joins fail to match. Which normalization is most appropriate?","oEn":["Apply LOWER and TRIM to both join keys to unify letter case and surrounding whitespace before joining","Apply NORMALIZE(column, NFD) to both join keys to put the characters into decomposed form before joining","Apply NORMALIZE(column, NFKC) to both join keys so full-width and half-width forms are unified","Replace all full-width characters with an empty string using REGEXP_REPLACE and join on the remaining half-width characters only"],"eEn":"NFKC normalization unifies compatibility characters, turning full-width alphanumerics into half-width and half-width kana into full-width, so inconsistent join keys match. LOWER and TRIM do not change character width, NFD only decomposes characters without unifying width, and deleting full-width characters would destroy the names."},{"id":"h138","d":"D1","q":"工場のセンサーデータでは、欠測値が -9999 という値で記録されている。月次の平均温度を計算すると、実際より極端に低くなる。欠測を適切に扱い、平均が歪まないようにしたい。元データは監査のため上書きも削除もしない。最も適切な方法はどれですか。","o":["欠測の -9999 を 0 に置換して平均を計算し、欠測だった行も 0 度の測定値として平均の分母に含めて集計する","ビューで NULLIF(temperature, -9999) により欠測を NULL にし、AVG に無視させる","元のテーブルから -9999 の行を DELETE で削除して、残った行だけで平均を計算する","平均の代わりに MAX を使って月次の代表値を求め、極端に低い値の影響を受けないようにする"],"a":1,"e":"NULLIF で -9999 を NULL にした別のビューやテーブルを作れば、元データを保ったまま AVG が欠測を自動で無視します。0 に置換すると 0 度として平均を歪め、元テーブルの DELETE は監査要件に反します。MAX は平均ではなく別の指標になってしまいます。","qEn":"In factory sensor data, missing readings are recorded as the value -9999, which makes the monthly average temperature extremely low. The team wants to handle missing values properly so the average is not distorted. The original data must be neither overwritten nor deleted, for audit reasons. Which method is most appropriate?","oEn":["Replace -9999 with 0 and compute the average, counting the missing rows as readings of zero degrees","Create a cleansed view that turns -9999 into NULL with NULLIF so AVG skips missing readings","Delete the -9999 rows from the original table with DELETE and compute the average from the remaining rows","Use MAX instead of the average to get the monthly representative value so extreme low values have no effect"],"eEn":"Making a view or table where NULLIF turns -9999 into NULL keeps the original data and lets AVG skip missing readings. Replacing with 0 still distorts the average as zero degrees, DELETE on the original violates the audit requirement, and MAX is a different statistic rather than a corrected average."},{"id":"h139","d":"D1","q":"日本の工場が出力するログのタイムスタンプ列は、タイムゾーン情報のない DATETIME 型で、値は JST である。UTC の TIMESTAMP 型で保存されている他社システムのログと時系列で結合したいが、結合結果が 9 時間ずれる。最も適切な修正はどれですか。","o":["TIMESTAMP(datetime_col, 'Asia/Tokyo') で JST として解釈してから結合する","TIMESTAMP(datetime_col) をタイムゾーンの引数なしで適用して、その結果をそのまま結合キーとして使う","他社の TIMESTAMP 列を DATETIME にキャストして、そのまま DATETIME どうしで結合する","結合条件に前後 9 時間の許容幅を設けて、ずれた行も同じ時刻の行として一致させる"],"a":0,"e":"DATETIME は時刻帯を持たないので、TIMESTAMP(datetime, 'Asia/Tokyo') で JST として解釈してから UTC の TIMESTAMP と比較すれば、ずれが解消します。タイムゾーン指定なしの変換は UTC とみなされ、TIMESTAMP を DATETIME にキャストしても UTC 基準のままで 9 時間ずれます。許容幅は別の時刻の行と誤って一致します。","qEn":"A factory in Japan outputs log timestamps as DATETIME values with no time zone information, and the values are in JST. The team wants to join them chronologically with another company's logs stored as UTC TIMESTAMP values, but the join results are off by 9 hours. Which fix is most appropriate?","oEn":["Convert with TIMESTAMP(datetime_col, 'Asia/Tokyo') to read it as JST, then join","Apply TIMESTAMP(datetime_col) without a time zone argument and use the result as the join key","Cast the other company's TIMESTAMP column to DATETIME and join DATETIME values to each other as they are","Add a nine-hour tolerance window before and after the join condition so shifted rows still match the same instant"],"eEn":"DATETIME carries no time zone, so interpreting it as JST with TIMESTAMP(datetime, 'Asia/Tokyo') before comparing with UTC TIMESTAMPs removes the offset. Converting without a zone assumes UTC, casting TIMESTAMP to DATETIME keeps UTC-based values that are still nine hours apart from the JST side, and a tolerance window falsely matches rows from different times."},{"id":"h140","d":"D1","q":"会計データを BigQuery に取り込む。金額の列 (円と小数以下の補助単位まで) を FLOAT64 にしたところ、売上合計が会計システムの合計と数円ずれる。端数を厳密に扱いたい。最も適切な型の選択はどれですか。","o":["金額列を INT64 にして、小数以下の補助単位は切り捨てたうえで、整数として集計する","金額列を FLOAT64 のままにして、集計の最後にだけ ROUND をかけて端数をそろえる","金額列を STRING で保存し、集計のたびに FLOAT64 へ CAST して加算する処理を SQL に埋め込む","金額列を NUMERIC (桁数が大きければ BIGNUMERIC) 型に変更して、10 進数の厳密な演算で集計する"],"a":3,"e":"NUMERIC は 10 進の固定小数点で、加算でも誤差が出ず、会計の端数を厳密に扱えます。FLOAT64 は 2 進の浮動小数点で誤差が蓄積し、最後の ROUND では合計の差が解消しない場合があります。INT64 は補助単位を失い、STRING を都度 FLOAT64 に戻せば同じ誤差が出ます。","qEn":"Accounting data is being loaded into BigQuery. After the amount column (yen plus fractional currency units) was defined as FLOAT64, the sales total differs from the accounting system's total by a few yen. The team wants fractions handled exactly. Which type choice is most appropriate?","oEn":["Define the amount column as INT64, truncate the fractional currency units, and aggregate the result as integers","Keep the amount column as FLOAT64 and apply ROUND only at the very end of the aggregation to align the fractions","Store the amounts as STRING and embed SQL that casts them to FLOAT64 and adds them up at every aggregation","Define the amount column as NUMERIC (or BIGNUMERIC) and aggregate with exact decimal arithmetic"],"eEn":"NUMERIC is fixed-point decimal, so sums carry no binary rounding error and fractions are exact. FLOAT64 is binary floating point whose errors accumulate and may not be fixed by a final ROUND. INT64 discards the fractional units, and casting STRING to FLOAT64 on each aggregation brings back the same error."},{"id":"h141","d":"D1","q":"複数のアプリが送るイベントの payload は JSON で、フィールドがアプリごと・バージョンごとに変わる。先にスキーマを決めて取り込むとロードが頻繁に失敗する。まず生のまま取り込み、必要になった項目だけを後から SQL で取り出したい。最も適切な設計はどれですか。","o":["アプリのバージョンごとに専用のテーブルを作り、フィールドを個別に定義してからロードする","payload は取り込まずに破棄して、現時点で分かっているフィールドだけを列として取り込む","payload を STRING 列に入れ、必要な項目を毎回 LIKE '%field%' による部分一致で検索する","payload を JSON 型の列として取り込み、必要な項目を JSON_VALUE などで後から抽出する"],"a":3,"e":"JSON 型の列に生のまま取り込めば、スキーマ変更でロードが失敗せず、必要な項目を JSON_VALUE などで後から取り出せます。バージョンごとのテーブルは数が増えて管理が煩雑になり、payload の破棄は後で必要になる項目を失います。LIKE による文字列検索は誤検出が多く、性能も出ません。","qEn":"Events sent by several apps carry a JSON payload whose fields vary by app and by version. Deciding the schema first makes loads fail frequently. The team wants to ingest the data as it is first and extract only the needed fields with SQL later. Which design is most appropriate?","oEn":["Create a dedicated table for each app version and load the data with its fields defined individually","Discard the payload and load only the fields known today as columns of the table","Put the payload in a STRING column and search for each needed field every time with a LIKE '%field%' partial match","Load the payload into a BigQuery JSON column and extract the needed fields later with functions such as JSON_VALUE"],"eEn":"A JSON column takes the raw payload without load failures from schema changes, and JSON_VALUE and similar functions extract fields later. Per-version tables multiply and are hard to manage, discarding the payload loses fields needed later, and LIKE matching on strings gives false hits and poor performance."},{"id":"h142","d":"D1","q":"新規に取得したパートナーデータ (BigQuery 上のテーブル) を分析に使う前に、列ごとの NULL 率、ユニーク値の数、値の分布を把握して、クレンジングのルールを検討したい。コードは書かず、結果は後から参照できる形で残したい。最も適切な機能はどれですか。","o":["Knowledge Catalog のデータプロファイルスキャンを実行して、列ごとの統計を取得する","Cloud Logging のログベース指標を作成して、テーブルの列ごとの値の分布をクエリのログから集計して把握する","BigQuery のテーブルプレビューで先頭の数十行を目視して、欠損や偏りがあるかどうかを担当者が確認する","Pub/Sub のスキーマ検証を有効にして、テーブルの各列の値の範囲を自動で検証させる"],"a":0,"e":"Knowledge Catalog (旧 Dataplex Universal Catalog) のデータプロファイルスキャンは、BigQuery のテーブルについて列ごとの NULL 率、ユニーク値の数、分布などをコードなしで算出し、結果を保存して参照できます。ログベース指標はテーブルの値を見ず、プレビューは先頭の一部しか確認できません。Pub/Sub のスキーマはメッセージの形式検証用です。","qEn":"Before using newly acquired partner data (a BigQuery table) for analysis, the team wants to understand each column's NULL rate, number of unique values, and value distribution to design cleansing rules. They do not want to write code and want the results kept for later reference. Which feature is most appropriate?","oEn":["Run a data profile scan in Knowledge Catalog (formerly Dataplex Universal Catalog) to obtain per-column statistics","Create log-based metrics in Cloud Logging and aggregate the distribution of each column's values from the logs","Look at the first few dozen rows in the BigQuery table preview and check by eye whether values are missing or skewed","Enable Pub/Sub schema validation to automatically check the range of values in each column of the table"],"eEn":"A Knowledge Catalog data profile scan computes per-column NULL rate, unique count, and distribution for a BigQuery table without code and keeps the results for reference. Log-based metrics never see table values, the preview shows only the first rows, and Pub/Sub schemas validate message formats, not BigQuery tables."},{"id":"h143","d":"D1","q":"販売会社のオンプレミス PostgreSQL (Cloud VPN で接続済み) から、毎晩 3 つのテーブルを BigQuery に全件コピーしたい。Apache Beam のコードは書けず、チームには運用の余力が少ない。最も適切な方法はどれですか。","o":["Datastream のストリームを 3 テーブル分だけ作成し、毎晩ストリームを開始して朝に停止する運用にする","Dataflow の Google 提供テンプレート「JDBC to BigQuery」を使い、接続情報とクエリをパラメーターに指定して実行する","Cloud Run functions に Python の PostgreSQL ドライバーを組み込み、全行を取得して insertAll で 1 件ずつ書き込む","pg_dump の出力 SQL を BigQuery のクエリエディタに貼り付けて実行し、テーブルを毎晩作り直す"],"a":1,"e":"Dataflow の JDBC to BigQuery テンプレートは、Beam のコードなしで JDBC 経由のテーブルを BigQuery に取り込め、パラメーターだけで毎晩のバッチ実行ができます。Datastream は継続的な CDC 向けで、夜間だけの全件コピーには合いません。関数での行単位の挿入は実装と制限が重く、pg_dump の SQL は BigQuery で実行できません。","qEn":"A sales company wants to copy three on-premises PostgreSQL tables (connected over Cloud VPN) in full to BigQuery every night. The team cannot write Apache Beam code and has little operational capacity. What is the most appropriate method?","oEn":["Create Datastream streams for just the three tables and start them each night and stop them each morning","Run the Google-provided Dataflow template 'JDBC to BigQuery' with the connection and queries as parameters","Embed a Python PostgreSQL driver in Cloud Run functions, fetch every row, and write them one by one with insertAll","Paste the SQL output of pg_dump into the BigQuery query editor and recreate the tables every night"],"eEn":"The Dataflow JDBC to BigQuery template ingests tables over JDBC without Beam code, and nightly batch runs need only parameters. Datastream is for continuous CDC and does not suit nightly full copies, row-by-row inserts from functions are heavy to build and hit limits, and pg_dump SQL cannot run in BigQuery."},{"id":"h144","d":"D1","q":"モバイルゲームのアプリは、オフライン時にイベントを端末に溜め、再接続時にまとめて送信する。最大 2 時間遅れて Pub/Sub に届くイベントもある。Dataflow のストリーミングパイプラインで、イベントが実際に発生した時刻を基準に 1 時間ごとの売上を集計し、遅れて届いたデータも集計に反映したい。最も適切な設計はどれですか。","o":["Pub/Sub への到着時刻 (処理時間) でウィンドウを切り、遅れて届いたイベントは届いた時間帯の売上に加算する形で集計する","ウィンドウの許容遅延を 0 に設定し、ウォーターマークを過ぎて届いたイベントは破棄して集計に含めない","ストリーミングでの集計をやめて、翌日のバッチジョブで全イベントを集計し直し、売上の確定値とする","イベントの発生時刻で固定ウィンドウを作り、許容遅延と遅延データ用のトリガーを設定する"],"a":3,"e":"発生時刻を基準にした固定ウィンドウと、許容遅延・遅延データ用のトリガーを組み合わせれば、最大 2 時間遅れて届いたイベントも正しい時間帯の集計に反映できます。到着時刻基準では売上が別の時間帯に入り、許容遅延 0 では遅延データが捨てられます。翌日のバッチはストリーミング集計の要件を満たしません。","qEn":"A mobile game app stores events on the device while offline and sends them in bulk when it reconnects, so some events reach Pub/Sub up to two hours late. In a Dataflow streaming pipeline, the team wants hourly sales aggregated by the time the events actually occurred, with late data also reflected. Which design is most appropriate?","oEn":["Cut windows by Pub/Sub arrival time (processing time) and add late events to the sales of the hour in which they arrive","Set allowed lateness to zero and discard events that arrive after the watermark has passed so they are not aggregated","Stop aggregating in streaming and recompute all events in a next-day batch job to produce the final sales figures","Build fixed windows on the event occurrence timestamp and set allowed lateness plus triggers that handle late data"],"eEn":"Fixed windows on event time combined with allowed lateness and late-data triggers let events up to two hours late land in the correct hour. Arrival-time windows put sales in the wrong hour, zero lateness drops late data, and a next-day batch fails the streaming aggregation requirement."},{"id":"h145","d":"D1","q":"Pub/Sub から JSON を読んで BigQuery に書き込む Dataflow のストリーミングジョブで、スキーマに合わない不正なレコードが時々混ざる。現状は変換処理が例外を投げ、そのたびにワーカーが再試行を繰り返してパイプラインが滞る。正常なレコードの処理は止めず、不正なレコードは後で調べられるようにしたい。最も適切な修正はどれですか。","o":["例外を握りつぶして不正なレコードは黙って捨て、ログにも記録せずに処理を続けるようにする","ワーカーの台数を増やして、再試行の待ち時間を相対的に小さくし、滞留が目立たないようにする","パース失敗を捕捉してサイドアウトプットに振り分け、デッドレターへエラー内容つきで書き出す","BigQuery の全列を STRING 型に変更し、不正な値も正常なレコードと同じテーブルに受け入れる"],"a":2,"e":"パース失敗を捕捉して別の出力に振り分け、エラー情報とともにデッドレターへ書き出せば、正常なレコードの処理を止めずに不正なものだけを後から調査できます。黙って捨てると原因調査ができず、ワーカーの増加は例外の再試行を解決せず、全列 STRING は不正な値が本テーブルに混ざります。","qEn":"A Dataflow streaming job reads JSON from Pub/Sub and writes to BigQuery, and records that do not match the schema occasionally slip in. At present the transform throws an exception, workers retry repeatedly, and the pipeline stalls. The team wants valid records to keep flowing and the invalid ones to be available for later investigation. Which fix is most appropriate?","oEn":["Swallow the exception, silently discard the invalid records, and keep processing without even logging them","Add more workers so the retry waiting time becomes relatively smaller and the stall is less noticeable","Catch parse failures, send them to a side output, and write them with errors to a dead-letter location","Change every BigQuery column to STRING so invalid values are accepted into the same table as valid records"],"eEn":"Catching parse failures, routing them to a side output, and writing them to a dead-letter location with error details keeps valid records flowing while the bad ones can be investigated later. Silent discarding prevents root-cause analysis, more workers do not fix repeated retries of an exception, and all-STRING columns mix invalid values into the main table."},{"id":"h146","d":"D1","q":"データエンジニアが Python の Beam パイプラインを作った。独自のライブラリと社内の設定ファイルに依存しており、分析チームの担当者が Google Cloud コンソールのフォームから、入力パスと出力テーブルをパラメーターで変えて繰り返し実行できるようにしたい。最も適切な方法はどれですか。","o":["パイプラインをコンテナイメージにまとめて Dataflow Flex テンプレートに登録し、パラメーター付きで起動する","Google 提供のクラシックテンプレートをそのまま使い、独自のライブラリはワーカーに手作業でコピーして対応する","ソースコードを共有し、担当者が各自のローカル環境から DataflowRunner を指定して python main.py を実行する","パイプラインのコードをノートブックにコピーし、担当者に毎回パラメーターのセルを書き換えて実行してもらう"],"a":0,"e":"Flex テンプレートは、パイプラインとその依存関係をコンテナイメージにまとめ、パラメーターを渡して Google Cloud コンソールや API から繰り返し起動できます。Google 提供のクラシックテンプレートでは独自ライブラリを組み込めず、各自のローカル実行は環境と権限の管理が煩雑で、ノートブックの手作業は再現性に欠けます。","qEn":"A data engineer built a Python Beam pipeline that depends on custom libraries and an internal configuration file. The team wants an analyst to run it repeatedly from a form in the Google Cloud console, changing the input path and output table as parameters. Which method is most appropriate?","oEn":["Package the pipeline in a container image, register it as a Flex Template, and launch it with parameters","Use a Google-provided classic template as it is and copy the custom libraries to the workers by hand","Share the source code and have each analyst run python main.py from a local environment with DataflowRunner specified","Copy the pipeline code into a notebook and have the analyst rewrite the parameter cells and run them each time"],"eEn":"A Flex Template packages the pipeline and its dependencies in a container image and can be launched repeatedly from the console or API with parameters. A Google-provided classic template cannot include custom libraries, local runs make environments and permissions hard to manage, and manual notebook edits are not reproducible."},{"id":"h147","d":"D1","q":"保険会社が、顧客の個人番号を含むファイルを BigQuery に取り込む。社内規程により、個人番号を平文のまま、データレイクやウェアハウスを含むどの保存先にも置いてはならない。取り込みの前段で変換する方式を選びたい。最も適切な設計はどれですか。","o":["生のまま BigQuery の raw 層にロードし、一般の利用者向けには個人番号の列を隠したビューだけを公開し、raw 層へのアクセスは管理者に限って運用する","Dataflow で取り込み中に Sensitive Data Protection で個人番号をトークン化・マスキングしてから書き込む ETL にする","生のまま取り込み、列レベルのアクセス制御 (ポリシータグ) で個人番号の列を参照できる利用者を限定する","生データを Cloud Storage に平文のまま置き、BigQuery への取り込み時に SQL でマスキングする ELT にする"],"a":1,"e":"個人番号を平文で保存できないので、保存前に変換する ETL が必要で、Dataflow と Sensitive Data Protection でトークン化・マスキングしてから書き込みます。raw 層への平文のロードは、ビューやポリシータグで隠しても保存自体が規程に反します。Cloud Storage に平文で置く ELT も同様です。","qEn":"An insurer loads files containing customers' individual numbers into BigQuery. Company policy forbids storing individual numbers in plain text anywhere in the data lake or warehouse. The team must choose a method that transforms data before it is stored. Which design is most appropriate?","oEn":["Load the raw data as it is into a BigQuery raw layer and publish only views that hide the individual number column to general users","An ETL design where Dataflow tokenizes or masks individual numbers with Sensitive Data Protection before writing to BigQuery","Ingest it as it is and restrict who can read the individual number column with column-level access control (policy tags)","Keep the raw data in plain text in Cloud Storage and mask it with SQL when it is loaded into BigQuery, as an ELT design"],"eEn":"Because plain-text storage is prohibited, an ETL step must transform the data before storage: Dataflow with Sensitive Data Protection tokenizes or masks before writing. Loading plain text into a raw layer violates the policy even if views or policy tags hide it, and so does keeping plain text in Cloud Storage for ELT."},{"id":"h148","d":"D1","q":"広告代理店は、クリックログに適用する不正クリックの判定ルールを四半期ごとに見直している。見直しのたびに過去 3 年分を新ルールで再計算したい。取り込み時に判定を済ませて結果だけを保存する現行のパイプラインでは、過去分の再計算ができない。最も適切な設計の見直しはどれですか。","o":["判定ロジックを Dataflow に実装し直し、ルールを変えるたびにジョブを再デプロイして新しい判定結果だけを保存する","判定済みの結果テーブルを毎日バックアップして、過去のルールで判定した結果を比較できるように保管しておく","生ログを BigQuery にそのまま保持し、判定ルールは SQL の後段変換として適用する ELT にする","判定済みの結果から生ログを復元する関数を作り、ルールを変更するたびに復元した生ログへ新ルールを再適用する"],"a":2,"e":"生ログをそのまま保持し、ルールを SQL の後段変換として適用する ELT なら、ルール変更時に過去 3 年分を再計算できます。取り込み時判定のままでは Dataflow を直しても生ログがなく、結果のバックアップは過去のルールの結果を残すだけです。判定結果から生ログは復元できません。","qEn":"An ad agency revises the fraud-click detection rules applied to click logs every quarter and wants to recompute the past three years with the new rules each time. The current pipeline makes the decision at ingestion and stores only the result, so past data cannot be recomputed. Which redesign is most appropriate?","oEn":["Reimplement the decision logic in Dataflow and redeploy the job whenever the rules change, storing only the new decision results","Back up the decided results table every day so that results judged under past rules can be kept and compared","Keep raw logs unprocessed in BigQuery and apply the rules later as SQL transformations in an ELT design","Build a function that restores raw logs from the decided results and re-applies the new rules to the restored logs on every change"],"eEn":"Keeping raw logs and applying the rules as downstream SQL transformations (ELT) lets the past three years be recomputed whenever rules change. Deciding at ingestion leaves no raw logs even if Dataflow is fixed, backups only preserve results under old rules, and raw logs cannot be restored from decision results."},{"id":"h149","d":"D1","q":"住宅メーカーの分析チームは、すでに BigQuery に取り込まれている 30 TB の取引ログから、毎日、集計用の中間テーブルを作る。変換は結合と集計が中心で、チームは SQL に習熟している。新しい基盤の導入やコード開発は避けたい。最も適切な変換の実行方法はどれですか。","o":["BigQuery からデータを読み出して Dataflow のバッチジョブで変換し、その結果を BigQuery に書き戻す","BigQuery 内で SQL により変換する ELT とし、スケジュールクエリや Dataform で毎日実行する","テーブルを Cloud Storage にエクスポートして、Spark ジョブで変換してから、結果を再ロードする","Cloud Data Fusion のパイプラインで BigQuery から読み出し、変換のうえ書き戻す処理を構築する"],"a":1,"e":"データがすでに BigQuery にあり、変換が結合と集計中心なら、BigQuery 内で SQL を実行する ELT が最も簡素で、スケジュールクエリや Dataform で毎日実行できます。Dataflow・Spark・Data Fusion はデータの移動と新しい基盤・コード開発を要し、30 TB の読み書きの負荷も増えます。","qEn":"An analytics team at a home builder builds daily aggregation staging tables from 30 TB of transaction logs already in BigQuery. The transformations are mostly joins and aggregations, and the team is skilled in SQL. It wants to avoid introducing new platforms or developing code. Which way of running the transformations is most appropriate?","oEn":["Read the data out of BigQuery, transform it in a Dataflow batch job, and write the results back to BigQuery","Transform with SQL inside BigQuery (ELT) and run it daily with scheduled queries or Dataform","Export the tables to Cloud Storage, transform them with a Spark job, and then reload the results into BigQuery","Build a Cloud Data Fusion pipeline that reads from BigQuery, transforms the data, and writes the results back"],"eEn":"When data is already in BigQuery and the work is joins and aggregations, SQL ELT inside BigQuery is simplest and can run daily with scheduled queries or Dataform. Dataflow, Spark, and Data Fusion require data movement, a new platform, or code, and add load for reading and writing 30 TB."},{"id":"h150","d":"D1","q":"取引先が毎日、約 2,000 個の CSV を Cloud Storage に置く。金額列に数値化できない値を含む行がときどき混ざるが、どのファイルが原因かが分からず、修正の依頼ができない。ロードする前に、不正な値を含む行がどのファイルにあるかを、SQL で一覧したい。最も適切な方法はどれですか。","o":["max_bad_records を 0 にしてロードジョブを実行し、失敗したジョブのエラーメッセージに出る行の位置を目視して調べる","全列を STRING とした外部テーブルを作り、SAFE_CAST で数値化できない行を _FILE_NAME ごとに集計する","いったんロードしてから金額列が NULL の行を探し、それがどの元ファイルの行なのかは取引先に調べてもらう","2,000 個のファイルを 1 つずつ gcloud storage cat で開き、金額列の値を担当者が手作業で確認していく"],"a":1,"e":"全列を STRING にした外部テーブルなら、型エラーでロードが止まらずに全行を読め、SAFE_CAST で数値化できない行を _FILE_NAME 疑似列でグループ化すれば、不正な値を含むファイルを SQL で特定できます。ロードのエラーメッセージは一部の行しか示さず、ロード後の NULL からは元のファイルが分からず、2,000 ファイルの手作業の確認は非現実的です。","qEn":"A partner places about 2,000 CSV files in Cloud Storage every day. Rows with values in the amount column that cannot be converted to numbers appear occasionally, but it is unclear which files are responsible, so the team cannot ask for corrections. Before loading, the team wants to list with SQL which files contain rows with invalid values. Which method is most appropriate?","oEn":["Run the load job with max_bad_records set to 0 and examine by eye the row positions shown in the failed job's error message","Create an all-STRING external table, find rows that SAFE_CAST cannot convert, and aggregate them by the _FILE_NAME pseudo-column","Load the data first and look for rows where the amount column is NULL, then ask the partner to work out which original file each row came from","Open each of the 2,000 files one by one with gcloud storage cat and have staff check the amount column values by hand"],"eEn":"An external table with every column as STRING reads all rows without stopping on type errors, and grouping rows that SAFE_CAST cannot convert by the _FILE_NAME pseudo-column identifies the offending files in SQL. A load error message shows only some rows, NULLs after loading do not reveal the source file, and hand checking 2,000 files is impractical."},{"id":"h151","d":"D1","q":"ある企業は、外部パートナーから届く CSV を BigQuery に取り込む。不正な形式の行の除外と、型・日付形式の正規化といった軽い整形だけは、取り込みの時点で済ませたい。一方、マスタとの結合や売上集計のような重い変換は、取り込み後に BigQuery の SQL で行いたい。この方式の呼び名と構成として最も適切なものはどれですか。","o":["ETLT。取り込み時に Dataflow で軽い整形を行い、結合や集計などの重い変換は BigQuery 内の SQL で行う","ETL。結合や集計を含むすべての変換を Dataflow で済ませてから、完成した結果だけを BigQuery に書き込む","ELT。いっさい整形せずに生のまま取り込み、不正な行の除外から集計までのすべてを BigQuery の SQL で行う","ETL。すべての変換を Cloud Storage 上のファイルに対する Spark ジョブで行い、結果を BigQuery に再ロードする"],"a":0,"e":"取り込み時に軽い整形 (T) を行い、ロード (L) した後に BigQuery 内で重い変換 (T) をする方式が ETLT です。すべてを取り込み前に変換する方式は ETL、整形せず生のまま取り込んですべて後段で行う方式は ELT で、どちらも要件の分担と合いません。","qEn":"A company loads CSV files from external partners into BigQuery. It wants only light cleanup, such as excluding malformed rows and normalizing types and date formats, done at ingestion, while heavy transformations such as joins with master data and sales aggregation should run later as SQL in BigQuery. Which name and structure best describe this approach?","oEn":["ETLT: do light cleanup with Dataflow at ingestion and run the heavy joins and aggregations as SQL inside BigQuery","ETL: do every transformation, including joins and aggregations, in Dataflow and write only the finished result to BigQuery","ELT: ingest the raw data with no cleanup at all and do everything from removing bad rows to aggregation in BigQuery SQL","ETL: do all transformations with a Spark job on files in Cloud Storage and reload the results into BigQuery"],"eEn":"Light transformation at ingestion followed by loading and heavy transformation inside BigQuery is ETLT. Transforming everything before loading is ETL, and loading raw data with all transformation afterward is ELT; neither matches the division of work required."},{"id":"h152","d":"D1","q":"スマートメーター 2,000 万台が 10 秒ごとに計測値を送る。書き込みは常時高スループットで、アプリは「特定のメーターの直近 1 日分」を数ミリ秒で取得する。行キーは meter_id と時刻で決められ、結合や複雑な SQL は不要である。取り込み先として最も適切なものはどれですか。","o":["Bigtable。行キーを meter_id と時刻で設計し、高スループットの書き込みと範囲読み取りを行う","Cloud SQL for PostgreSQL。計測値を 1 行ずつ INSERT して、meter_id と時刻にインデックスを作成する","BigQuery。ストリーミング挿入で書き込み、アプリからは SELECT で直近 1 日分を取得する","Firestore。メーターごとに 1 つのドキュメントを作り、計測値を配列に追記していく"],"a":0,"e":"毎秒 200 万件規模の書き込みと、行キーによる数ミリ秒の範囲読み取りには Bigtable が適しています。Cloud SQL はこの書き込みスループットに水平スケールできず、BigQuery は分析向けで低遅延の点参照に向きません。Firestore の 1 ドキュメント配列は容量と更新頻度の制約に当たります。","qEn":"20 million smart meters send readings every 10 seconds. Writes are continuous and high-throughput, and the app retrieves 'the last day for a specific meter' in a few milliseconds. The row key can be built from meter_id and time, and joins or complex SQL are not needed. Which ingestion target is most appropriate?","oEn":["Bigtable, using a row key of meter_id and time for high-throughput writes and range reads","Cloud SQL for PostgreSQL, inserting readings row by row and creating indexes on meter_id and time","BigQuery, writing with streaming inserts and having the app fetch the last day with SELECT","Firestore, creating one document per meter and appending readings to an array in that document"],"eEn":"About two million writes per second and millisecond range reads by row key suit Bigtable. Cloud SQL cannot scale horizontally to that write throughput, BigQuery is analytical and poor for low-latency point reads, and a single array-per-meter document in Firestore hits size and update-rate limits."},{"id":"h153","d":"D1","q":"グローバルに展開するチケット販売サービスで、リージョンをまたいでも強い整合性が必要な在庫と注文のデータを、SQL とトランザクションで扱いたい。書き込みは水平にスケールさせたく、停止時間なしでスキーマ変更もしたい。取り込み先として最も適切なものはどれですか。","o":["Cloud SQL for MySQL。リードレプリカを各リージョンに置き、書き込みは単一のプライマリで受ける","Bigtable。行キーで在庫を管理し、複数行にまたがるトランザクションはアプリケーションで実装する","Spanner。複数リージョンの構成で、強い整合性のトランザクションと水平スケールを両立させる","BigQuery。注文を DML で更新し、在庫の引き当てを BigQuery のトランザクションで処理する"],"a":2,"e":"Spanner はリージョンをまたいだ強い整合性のトランザクションと SQL、水平スケール、オンラインのスキーマ変更を備えています。Cloud SQL は書き込みが単一プライマリに集中し、Bigtable は SQL と複数行トランザクションの保証が弱く、BigQuery は分析向けで高頻度の OLTP に向きません。","qEn":"A ticketing service deployed globally needs inventory and order data handled with SQL and transactions, with strong consistency even across regions. Writes must scale horizontally, and schema changes must be possible without downtime. Which ingestion target is most appropriate?","oEn":["Cloud SQL for MySQL, with read replicas in each region and writes accepted by a single primary","Bigtable, managing inventory by row key and implementing multi-row transactions in the application","Spanner, in a multi-region setup, for strongly consistent transactions and horizontal scale","BigQuery, updating orders with DML and handling inventory allocation with BigQuery transactions"],"eEn":"Spanner provides strongly consistent cross-region transactions with SQL, horizontal scale, and online schema changes. Cloud SQL concentrates writes on one primary, Bigtable lacks SQL and multi-row transaction guarantees, and BigQuery is analytical and unsuited to high-frequency OLTP."},{"id":"h154","d":"D1","q":"モバイルアプリが、ユーザーごとのプロファイルや設定を JSON に近い構造で保存する。オフライン時も端末で読み書きでき、オンライン復帰時に自動で同期されること、サーバー側の変更が他の端末にリアルタイムに反映されることを求めている。取り込み先として最も適切なものはどれですか。","o":["Firestore。ドキュメントとして保存し、モバイル SDK のオフライン永続化とリアルタイムリスナーを使う","Bigtable。ユーザー ID を行キーにして保存し、端末は定期的にポーリングして最新の値を取得する","Cloud SQL for PostgreSQL。ユーザーごとに行を作り、端末側の SQLite へ複製する同期処理をアプリで実装する","BigQuery。ユーザーの設定を行として挿入し、端末からクエリして最新の設定を読み出す"],"a":0,"e":"Firestore はドキュメントモデルで JSON に近い構造を扱え、モバイル SDK がオフライン時の読み書きと復帰時の同期、変更のリアルタイム通知を提供します。Bigtable や Cloud SQL では同期処理をアプリで実装することになり、BigQuery は分析用で端末からの低遅延の読み書きには向きません。","qEn":"A mobile app stores per-user profiles and settings in a structure close to JSON. It requires reads and writes to work on the device while offline, automatic synchronization when back online, and real-time reflection of server-side changes on other devices. Which ingestion target is most appropriate?","oEn":["Firestore, storing documents and using the mobile SDK's offline persistence and real-time listeners","Bigtable, keyed by user ID, with devices polling periodically to obtain the latest values","Cloud SQL for PostgreSQL, one row per user, with the app implementing the sync process that replicates to SQLite on the device","BigQuery, inserting each user's settings as rows and having devices query it to read the latest settings"],"eEn":"Firestore handles JSON-like documents, and its mobile SDK provides offline reads and writes, sync on reconnection, and real-time change notifications. With Bigtable or Cloud SQL the app would have to implement sync itself, and BigQuery is analytical and unsuited to low-latency reads and writes from devices."},{"id":"h155","d":"D1","q":"社内ツールの Cloud SQL for MySQL に、Cloud Storage 上にある 5 GB の CSV (列は表の列順と一致) を取り込みたい。ローカル端末を経由せず、データベースへの接続クライアントを用意する作業も避けたい。最も適切な手順はどれですか。","o":["Cloud SQL のインポート機能 (gcloud sql import csv) で、Cloud Storage の URI を指定する","CSV をローカルにダウンロードして、mysql クライアントの LOAD DATA LOCAL INFILE で取り込む手順にし、接続用の端末も用意する","BigQuery に CSV をロードしたあと、EXTERNAL_QUERY を使って Cloud SQL のテーブルへ書き戻す","Cloud SQL の自動バックアップのファイルとして CSV を Cloud Storage に置き、復元の操作で取り込ませる"],"a":0,"e":"Cloud SQL のインポートは Cloud Storage 上の CSV を直接テーブルへ取り込め、ローカル端末や接続クライアントが不要です (インスタンスのサービスアカウントにバケットの閲覧権限を付与します)。ローカル経由は要件に反し、EXTERNAL_QUERY は読み取り専用で、バックアップの復元は CSV に対応しません。","qEn":"The team wants to load a 5 GB CSV in Cloud Storage (columns matching the table's column order) into Cloud SQL for MySQL for an internal tool. It wants to avoid routing the file through a local machine and avoid preparing a database client. Which procedure is most appropriate?","oEn":["Use Cloud SQL import (console or gcloud sql import csv) with the Cloud Storage URI and target table","Download the CSV locally and make the procedure load it with LOAD DATA LOCAL INFILE from the mysql client","Load the CSV into BigQuery and then write it back to the Cloud SQL table with EXTERNAL_QUERY","Place the CSV in Cloud Storage as if it were an automatic backup file and have a restore operation ingest it"],"eEn":"Cloud SQL import reads a CSV directly from Cloud Storage into a table, with no local machine or client (the instance's service account needs read access to the bucket). The local route violates the requirement, EXTERNAL_QUERY is read-only, and backup restore does not accept CSV files."},{"id":"h156","d":"D1","q":"セキュリティチームは、Cloud Audit Logs の管理アクティビティ監査ログを BigQuery で SQL 分析したい。ログは過去 1 年分を保持し、日付で絞って参照する。コードは書きたくない。最も適切な方法はどれですか。","o":["Cloud Logging のシンクの宛先を BigQuery (パーティション分割) にし、書き込み用 ID に権限を付与する","ログビューアから CSV を手動でダウンロードして、毎週 bq load で BigQuery に取り込む運用にする","ログを Pub/Sub に出力し、Cloud Run functions で 1 件ずつ BigQuery に挿入する処理を実装して運用する","Cloud Monitoring のダッシュボードでログを可視化するだけにして、BigQuery にはログを取り込まない"],"a":0,"e":"ログシンクの宛先を BigQuery にすれば、コードなしで監査ログが継続的にテーブルへ書き込まれます。パーティション分割テーブルにすれば日付での絞り込みが効率的で、シンクの書き込み用 ID に権限を付与しておきます。手動のダウンロードやコード実装は運用負荷が高く、ダッシュボードだけでは SQL 分析ができません。","qEn":"A security team wants to analyze Cloud Audit Logs admin activity logs with SQL in BigQuery. The logs are kept for the past year and queried filtered by date. They do not want to write code. Which method is most appropriate?","oEn":["Create a Cloud Logging sink to BigQuery using partitioned tables and grant permissions to the sink's writer identity","Download CSV files manually from the Logs Explorer and load them into BigQuery with bq load every week","Export the logs to Pub/Sub and implement and operate Cloud Run functions that insert them into BigQuery one at a time","Only visualize the logs in a Cloud Monitoring dashboard and do not load them into BigQuery at all"],"eEn":"A sink with BigQuery as its destination writes audit logs continuously with no code. Partitioned tables make date filtering efficient, and the sink's writer identity needs permission. Manual downloads and custom code are heavy to operate, and a dashboard alone does not allow SQL analysis."},{"id":"h157","d":"D1","q":"マーケティング部門は、Google アナリティクス 4 (GA4) のイベントデータを BigQuery でユーザー単位に分析したい。集計済みのレポートではなく、イベント単位の生データを使い、ほぼリアルタイムのイベントも参照したい。コード開発は避けたい。最も適切な方法はどれですか。","o":["GA4 プロパティの BigQuery リンクを設定し、日次エクスポートとストリーミングエクスポートを有効にする","GA4 の画面から集計済みのレポートを CSV でダウンロードし、Cloud Storage 経由で BigQuery にロードする","BigQuery Data Transfer Service の Google 広告コネクタを設定して、GA4 のイベントデータを取り込む","Cloud Run functions から GA4 の Data API を毎時呼び出し、返ってきた集計結果を BigQuery に挿入する"],"a":0,"e":"GA4 の BigQuery リンクは、イベント単位の生データを日次エクスポートで、ほぼリアルタイムのデータをストリーミングエクスポートで BigQuery に自動で書き出し、コードが不要です。画面からの CSV や Data API は集計済みの結果でユーザー単位の分析に向かず、Google 広告コネクタは広告のデータ用です。","qEn":"A marketing department wants to analyze Google Analytics 4 (GA4) event data per user in BigQuery. It wants event-level raw data rather than aggregated reports, including near-real-time events, and wants to avoid code development. Which method is most appropriate?","oEn":["Set up the BigQuery link on the GA4 property and enable both the daily export and the streaming export","Download aggregated reports from the GA4 interface as CSV and load them into BigQuery via Cloud Storage","Configure the BigQuery Data Transfer Service Google Ads connector to ingest the GA4 event data","Call the GA4 Data API from Cloud Run functions every hour and insert the returned aggregated results into BigQuery"],"eEn":"The GA4 BigQuery link exports event-level raw data automatically, daily and via streaming for near-real-time, with no code. CSV downloads and the Data API return aggregated results unsuited to per-user analysis, and the Google Ads connector handles advertising data."},{"id":"h158","d":"D3","q":"Managed Service for Apache Airflow (旧 Cloud Composer) の環境で、多数の DAG ファイルの先頭 (モジュールのトップレベル) に、社内データベースへ接続して設定値を取得する処理と、大きな CSV の読み込みが書かれている。DAG が増えるにつれ、スケジューラの DAG ファイル解析に時間がかかり、タスクの起動が遅れている。最も適切な改善はどれですか。","o":["DAG ファイルの解析間隔を短く設定し、スケジューラがファイルをより頻繁に読み直して変更を早く拾うようにする","ワーカーの台数を増やして、DAG ファイルの解析処理がワーカー側に分散されるようにし、スケジューラの負荷を下げる","トップレベルの重い処理をタスクの実行時 (Python 関数の内部) に移して、DAG ファイルの解析を軽くする","すべての DAG を 1 つの巨大なファイルにまとめて、スケジューラが解析するファイルの数を減らす"],"a":2,"e":"DAG ファイルはスケジューラに繰り返し解析されるため、トップレベルでの DB 接続や大きな読み込みは解析のたびに実行され、遅延の原因になります。重い処理をタスク実行時に移せば解析が軽くなります。解析間隔を短くすると負荷が増え、解析はワーカーではなくスケジューラ側で行われ、1 ファイルへの統合は解析時間を悪化させます。","qEn":"In a Managed Service for Apache Airflow (formerly Cloud Composer) environment, many DAG files have code at the top level of the module that connects to an internal database to fetch settings and reads a large CSV. As DAGs increase, the scheduler takes longer to parse DAG files and task starts are delayed. Which improvement is most appropriate?","oEn":["Shorten the DAG file parsing interval so the scheduler re-reads the files more often and picks up changes sooner","Add more workers so that the parsing of DAG files is distributed to the workers, reducing the scheduler's load","Move the heavy top-level work into the tasks themselves (inside Python functions) so DAG parsing becomes light","Merge all DAGs into one huge file so that the scheduler has fewer files to parse"],"eEn":"The scheduler parses DAG files repeatedly, so DB connections and large reads at the top level run on every parse and cause delays; moving them into task execution makes parsing light. A shorter parse interval adds load, parsing is done by the scheduler rather than workers, and merging into one file makes parsing slower."},{"id":"h159","d":"D3","q":"Airflow の DAG が、BigQueryInsertJobOperator で重い集計ジョブを実行している。ジョブは 1 件あたり 1〜2 時間かかり、その間ワーカーのスロットを占有して、同時に実行できるタスク数が足りなくなっている。ワーカーを増やさずに、待機中のスロット占有を解消したい。最も適切な対処はどれですか。","o":["待機の確認間隔 (poke_interval) を短くして、ジョブの完了を早く検知し、スロットを占有する時間を縮める","Python 関数の中でジョブの状態をループで確認し、sleep で待つ処理を書いて、スロットの使い方を工夫する","並列度 (parallelism) の設定値を大きくして、ワーカーが同時に処理できるタスク数の上限を引き上げる","オペレーターを deferrable モードで実行し、待機を triggerer に任せてスロットを解放する"],"a":3,"e":"deferrable モードのオペレーターは、待機中にタスクを中断して triggerer の非同期イベントループへ処理を渡すため、ワーカースロットを使わずに長時間のジョブを待てます。poke_interval はセンサーの設定で占有は変わらず、Python の sleep ループはスロットを占有し続けます。parallelism を上げてもワーカーの資源は増えません。","qEn":"An Airflow DAG runs heavy BigQuery aggregation jobs with BigQueryInsertJobOperator. Each job takes one to two hours and holds a worker slot the whole time, so there are not enough slots for concurrent tasks. The team wants to stop waiting from occupying slots without adding workers. Which action is most appropriate?","oEn":["Shorten the polling interval (poke_interval) so completion is detected sooner and slots are held for less time","Write a loop inside a Python function that checks the job status and sleeps, to make better use of the slots","Raise the parallelism setting to increase the upper limit on the number of tasks workers can process at once","Run the operator in deferrable mode so the wait is handed to the triggerer and the worker slot is released"],"eEn":"A deferrable operator suspends the task and hands the wait to the triggerer's asynchronous event loop, so long jobs are awaited without a worker slot. poke_interval is a sensor setting and does not change occupancy, a sleeping Python loop keeps the slot, and raising parallelism does not add worker resources."},{"id":"h160","d":"D3","q":"DAG は、Managed Service for Apache Spark (旧 Dataproc) の一時クラスタを作成し、Spark ジョブを実行したあと、クラスタを削除する。ジョブが失敗した日はクラスタの削除タスクがスキップされ、クラスタが残って課金が続いた。ジョブの成否にかかわらず確実にクラスタを削除したい。最も適切な設定はどれですか。","o":["クラスタ削除タスクの trigger_rule を all_done に設定し、上流が失敗しても必ず実行させる","Spark ジョブのタスクの retries を大きな値に設定して、成功するまで何度でも再試行させる","削除タスクの trigger_rule を one_success に設定し、上流のうち 1 つでも成功したときに実行させる","クラスタにラベルを付け、担当者が週に一度、使われていないクラスタを手作業で削除する運用にする"],"a":0,"e":"trigger_rule を all_done にすると、上流のタスクが成功・失敗・スキップのいずれで終わっても削除タスクが実行されるため、失敗した日にもクラスタを確実に削除できます。retries を増やしても必ず成功する保証はなく、one_success では上流が失敗すると実行されません。手作業の削除は課金が続く期間を生みます。","qEn":"A DAG creates an ephemeral cluster on Managed Service for Apache Spark (formerly Dataproc), runs a Spark job, and then deletes the cluster. On days when the job failed, the delete task was skipped and the cluster remained and kept incurring charges. The team wants the cluster deleted reliably regardless of the job's outcome. Which setting is most appropriate?","oEn":["Set the delete task's trigger_rule to all_done so it runs whether upstream tasks succeed or fail","Set a large retries value on the Spark job task so it is retried as many times as needed until it succeeds","Set the delete task's trigger_rule to one_success so it runs only when at least one upstream task has succeeded","Label the clusters and have an operator manually delete the unused clusters once a week as an operating rule"],"eEn":"With trigger_rule all_done the delete task runs whether upstream tasks succeed, fail, or are skipped, so the cluster is deleted even on failure days. More retries do not guarantee success, one_success will not run when upstream fails, and a weekly manual cleanup leaves days of ongoing charges."},{"id":"h161","d":"D3","q":"日次 DAG のタスクが、Python コード内で datetime.now() を使って処理対象の日付を決めている。障害後に過去日のバックフィルを実行したところ、どの日付の実行でも当日のデータを処理してしまった。バックフィルや再実行のときに、その実行の対象日が正しく使われるようにしたい。最も適切な修正はどれですか。","o":["datetime.now() の代わりに datetime.utcnow() を使い、タイムゾーンの差による日付のずれをなくす","テンプレート変数 ({{ ds }} や data_interval_start) から対象日を受け取って処理する","バックフィルを実行する直前にワーカーのシステム時刻を対象の過去日に合わせてから、タスクを実行する","DAG の start_date を毎日書き換えて再デプロイし、その日のデータだけを処理するようにする"],"a":1,"e":"Airflow の実行は論理的な日付 (data interval) を持ち、{{ ds }} や data_interval_start で受け取れば、バックフィルや再実行でもその実行の対象日を処理できます。utcnow() も現在時刻で結果は変わらず、システム時刻の変更は他のタスクにも影響して現実的でなく、start_date の毎日の変更は運用を壊します。","qEn":"A daily DAG task determines the target date inside Python code with datetime.now(). When a past date was backfilled after an outage, every run processed the current day's data. The team wants each run's own target date to be used during backfills and reruns. Which fix is most appropriate?","oEn":["Use datetime.utcnow() instead of datetime.now() to remove date shifts caused by time zone differences","Take the target date from template variables ({{ ds }} or data_interval_start) and process that date","Set the worker's system clock to the past target date just before the backfill and then run the tasks","Rewrite the DAG's start_date every day and redeploy so that it processes only that day's data"],"eEn":"Each Airflow run has a logical date (data interval), and receiving it through {{ ds }} or data_interval_start lets backfills and reruns process their own target date. utcnow() is still the current time, changing the system clock affects other tasks and is impractical, and rewriting start_date daily breaks operations."},{"id":"h162","d":"D3","q":"DAG が外部 SaaS の API キーを Airflow の変数に平文で保存している。キーは月次でローテーションされ、そのたびに DAG の変更や環境の再起動は避けたい。キーへのアクセスを監査できる形にもしたい。最も適切な構成はどれですか。","o":["API キーを DAG のソースコードに定数として記述し、Git リポジトリでレビューしながら管理して、変更はデプロイで反映する","Secret Manager を Airflow のシークレットバックエンドとして構成し、接続情報や変数を取得する","API キーを環境変数に設定し、ローテーションのたびに環境の設定を更新して環境を再起動する","API キーを書いたテキストファイルを dags/ フォルダに置き、各タスクがそのファイルを読み込んで使う"],"a":1,"e":"Secret Manager をシークレットバックエンドにすれば、キーを更新するだけで DAG の変更や再起動なしに新しい値が使われ、アクセスは Cloud Audit Logs で監査できます。ソースコードへの記述は漏えいと変更が必要になり、環境変数は再起動を伴い、dags/ フォルダのファイルは開発者全員に見え、監査もできません。","qEn":"A DAG stores an external SaaS API key in plain text in an Airflow variable. The key is rotated monthly, and the team wants to avoid DAG changes or environment restarts each time. Access to the key should also be auditable. Which configuration is most appropriate?","oEn":["Write the API key into the DAG source code as a constant and manage it through review in the Git repository","Configure Secret Manager as the Airflow secrets backend and obtain connections and variables from Secret Manager","Set the API key as an environment variable and update the environment configuration and restart it at each rotation","Put a text file containing the API key in the dags/ folder and have each task read that file when it needs the key"],"eEn":"With Secret Manager as the secrets backend, rotating the key takes effect without DAG changes or restarts, and access is auditable through Cloud Audit Logs. Hardcoding leaks the key and needs changes, environment variables need a restart, and a file in dags/ is visible to all developers with no audit."},{"id":"h163","d":"D3","q":"Airflow の DAG が BigQuery のクエリを実行するタスクで、bigquery.jobs.create の権限がないというエラーで失敗した。DAG の作者個人は BigQuery の権限を持っている。最小権限の原則を守りつつ解消する、最も適切な方法はどれですか。","o":["環境が使うサービスアカウントに、BigQuery ジョブユーザーと対象データセットに必要なロールだけを付与する","DAG の作者個人の Google アカウントに BigQuery 管理者を付与し、タスクがその認証情報で実行されるようにする","環境のサービスアカウントにプロジェクトのオーナーロールを付与して、あらゆる権限エラーを一度に解消する","DAG のコード内にサービスアカウントキーの JSON を埋め込み、そのキーで BigQuery に認証させる"],"a":0,"e":"Airflow のタスクは環境のサービスアカウントの権限で実行されるため、そのアカウントに必要最小限のロール (ジョブユーザーと対象データセットのロール) を付与します。作者個人への付与はタスクの認証に使われず、オーナーロールは権限が過大で、コードへのキー埋め込みは漏えいの危険があります。","qEn":"An Airflow DAG task that runs a BigQuery query failed with an error saying it lacks the bigquery.jobs.create permission. The DAG's author personally has BigQuery permissions. Which is the most appropriate way to resolve this while following least privilege?","oEn":["Grant the environment's service account the BigQuery Job User role and only the needed dataset roles","Grant BigQuery Admin to the DAG author's personal Google account so tasks run with that account's credentials","Grant the Owner role on the project to the environment's service account to clear all permission errors at once","Embed a service account key JSON in the DAG code and use that key to authenticate to BigQuery"],"eEn":"Airflow tasks run with the environment's service account, so grant that account the minimum roles needed (job user plus roles on the target datasets). Granting the author does not affect task authentication, Owner is excessive, and embedding a key in code risks leakage."},{"id":"h164","d":"D3","q":"開発チームが DAG を Git で管理している。レビュー済みのコードだけを本番環境に反映したいが、現状は担当者が手作業でバケットにファイルをアップロードしており、構文エラーを含む DAG が混入する事故があった。最も適切な運用はどれですか。","o":["Git へのマージを契機に Cloud Build で構文検証とテストを行い、成功時のみ dags/ フォルダへ同期する","本番環境のバケットを開発者全員に書き込み可能にして、各自が確認したうえで直接アップロードできるようにする","本番環境で DAG を有効にしたあとに Airflow の画面でエラーを確認し、問題があれば修正して再アップロードする","毎晩 Cloud Scheduler から開発用リポジトリの最新の状態を dags/ フォルダへコピーし、レビューの有無は問わない"],"a":0,"e":"マージを契機に Cloud Build で構文検証と単体テストを行い、成功した場合だけ環境のバケットへ同期すれば、レビュー済みで検証済みの DAG だけが本番に反映されます。全員に書き込みを許す運用や、本番で確認する運用は事故を防げず、レビューを問わず毎晩コピーする方式も未検証のコードを本番に載せます。","qEn":"A development team manages DAGs in Git. It wants only reviewed code deployed to production, but currently staff upload files to the bucket by hand, and a DAG with a syntax error once slipped in. Which operating procedure is most appropriate?","oEn":["On merge to Git, run syntax checks and unit tests in Cloud Build and sync to the dags/ folder only on success","Make the production bucket writable by all developers so each person can upload directly after checking their own work","Enable the DAG in production first, check for errors in the Airflow UI afterward, and fix and re-upload if there are problems","Have Cloud Scheduler copy the latest state of the development repository into the dags/ folder every night regardless of review"],"eEn":"Validating and unit testing in Cloud Build on merge and syncing to the environment bucket only on success puts only reviewed, verified DAGs in production. Open write access and checking in production do not prevent incidents, and a nightly copy regardless of review puts unverified code in production."},{"id":"h165","d":"D3","q":"毎時実行の DAG が、データ量の多い日は 1 回の実行に 90 分かかる。実行が重なり、同じテーブルに対する複数の実行が同時に書き込んで結果が不整合になる。重なった実行は待たせて、順に処理したい。最も適切な設定はどれですか。","o":["スケジュール間隔を 1 時間から 30 分に短縮して、1 回あたりの処理量を減らし、実行が重ならないようにする","catchup を True にして、遅れた実行を取り戻せるようにし、テーブルへの書き込みの順序を保つ","DAG の max_active_runs を 1 に設定し、前の実行が終わるまで次の実行を開始させない","タスクの retries を増やして、書き込みが衝突して失敗したときに自動で再実行されるようにする"],"a":2,"e":"max_active_runs を 1 にすると、前の実行が完了するまで次の実行が待機し、同じテーブルへの同時書き込みを防げます。間隔の短縮は重なりをむしろ増やし、catchup は過去分の実行を生成するだけで同時実行を制限しません。retries は衝突後の再実行で、不整合そのものは防げません。","qEn":"An hourly DAG takes 90 minutes per run on high-volume days. Runs overlap, and multiple runs write to the same table at the same time, making results inconsistent. The team wants overlapping runs to wait and be processed in order. Which setting is most appropriate?","oEn":["Shorten the schedule interval from one hour to 30 minutes to reduce the work per run and prevent runs from overlapping","Set catchup to True so delayed runs can be made up and the order of writes to the table is preserved","Set the DAG's max_active_runs to 1 so the next run does not start until the previous run finishes","Increase task retries so that tasks whose writes collide and fail are automatically rerun"],"eEn":"max_active_runs of 1 makes the next run wait for the previous one to finish, preventing simultaneous writes to the same table. A shorter interval increases overlap, catchup only generates past runs and does not limit concurrency, and retries rerun after a collision without preventing inconsistency."},{"id":"h166","d":"D3","q":"20 個の並列タスクが同じ外部 API を呼び出すが、API は同時 3 接続までしか許容せず、超えると 429 を返して失敗する。DAG 全体の並列度は他のタスクのために下げたくない。外部 API を呼ぶタスクだけ同時実行数を絞りたい。最も適切な方法はどれですか。","o":["DAG 全体の max_active_tasks を 3 に下げて、すべてのタスクの同時実行数を 3 以下に制限する","API を呼ぶタスクの retries を多めに設定して、429 が返るたびに自動で再試行させる","スロット数 3 の Airflow プールを作成し、API を呼ぶタスクにそのプールを割り当てる","環境のワーカーの台数を 3 台に固定して、同時に動くタスクの数が 3 を超えないようにする"],"a":2,"e":"プールはタスク群の同時実行数をスロット数で制限でき、API を呼ぶタスクだけを 3 つに絞れます。DAG 全体の max_active_tasks を下げると他のタスクも遅くなり、retries は 429 を何度も受けて無駄な再試行を生みます。ワーカー台数の固定では 1 台が複数のタスクを並行して実行できるため制限になりません。","qEn":"Twenty parallel tasks call the same external API, which allows only three simultaneous connections and returns 429 and fails beyond that. The team does not want to lower the DAG-wide parallelism because other tasks need it. Only the tasks calling the external API should have their concurrency limited. Which method is most appropriate?","oEn":["Lower the whole DAG's max_active_tasks to 3 so the concurrency of all tasks is limited to three or fewer","Set a generous retries value on the API-calling tasks so each 429 response triggers an automatic retry","Create an Airflow pool with three slots and assign the API-calling tasks to it","Fix the number of environment workers at three so that no more than three tasks can run at the same time"],"eEn":"A pool limits concurrency for a group of tasks by slot count, so only the API-calling tasks are held to three. Lowering max_active_tasks slows other tasks, retries just absorb repeated 429s with wasted attempts, and fixing the worker count does not limit concurrency because one worker can run several tasks in parallel."},{"id":"h167","d":"D3","q":"特定のタスクが、外部システムの応答待ちで数日間ハングし、ワーカースロットを占有したままになる。ハングしたタスクを自動的に失敗させ、リトライや失敗通知の対象にしたい。最も適切な設定はどれですか。","o":["DAG のスケジュール間隔を長くして、タスクが実行される頻度を下げ、ハングが起きる機会を減らす","タスクの retries を 0 に設定して、失敗した場合に再試行が行われないようにしてスロットを空ける","execution_timeout を設定し、超過したら失敗させてリトライや通知につなげる","ワーカーを毎日定時に再起動して、ハングしているタスクを強制的に終了させる運用にする"],"a":2,"e":"execution_timeout を設定すると、実行時間が上限を超えたタスクが自動で失敗扱いになり、スロットが解放されてリトライや失敗通知の対象になります。スケジュール間隔の変更や retries の 0 設定ではハングが解消せず、ワーカーの定時再起動は正常に動いているタスクまで巻き込みます。","qEn":"A particular task hangs for days waiting for a response from an external system and keeps holding a worker slot. The team wants hung tasks to fail automatically and become subject to retries and failure notifications. Which setting is most appropriate?","oEn":["Lengthen the DAG's schedule interval to lower how often the task runs and reduce the chances of a hang","Set the task's retries to 0 so that no retry is performed when it fails and the slot is freed","Set execution_timeout so the task fails after the limit and feeds into retries and notifications","Restart the workers at a fixed time every day to forcibly terminate any hung tasks as an operating rule"],"eEn":"With execution_timeout, a task exceeding the limit fails automatically, frees its slot, and becomes subject to retries and failure notifications. Changing the schedule interval or setting retries to 0 does not remove hangs, and daily worker restarts also kill healthy tasks."},{"id":"h168","d":"D3","q":"毎時の DAG は、パートナーが Cloud Storage に置く差分ファイルを取り込む。ファイルが置かれていない時間帯は、後続のロードや集計を実行せずにスキップしたい。その時間帯の実行を失敗扱いにしたり、タスクが待ち続けてスロットを占有したりすることは避けたい。最も適切な実装はどれですか。","o":["ファイルの有無を確認するタスクで、無ければ例外を投げて失敗させ、下流のタスクが実行されない状態にする","ファイルの有無を確認し、無ければ ShortCircuitOperator で下流のタスクをスキップさせる","GCSObjectExistenceSensor をタイムアウトなしで置き、ファイルが届くまで待ち続けるようにする","DAG のスケジュールを日次に変更して、1 日に 1 回だけファイルの有無を確認する"],"a":1,"e":"ShortCircuitOperator は条件が偽のとき下流をスキップするので、ファイルが無い時間帯を失敗にも待機にもせずに終えられます。例外で失敗させると実行が失敗扱いになり、タイムアウトなしのセンサーはスロットを占有し続けます。日次への変更は毎時で取り込むという要件を変えてしまいます。","qEn":"An hourly DAG ingests delta files that a partner places in Cloud Storage. In hours when no file is present, the team wants the downstream load and aggregation skipped. It does not want that hour's run marked as failed, and does not want a task to keep waiting and occupying a slot. Which implementation is most appropriate?","oEn":["Check for the file in a task and, if it is absent, raise an exception so it fails and downstream tasks are not run","Check for the file in a task and, if it is absent, use ShortCircuitOperator to skip the downstream tasks","Place a GCSObjectExistenceSensor with no timeout and make it keep waiting until the file arrives","Change the DAG schedule to daily and check for the file only once a day"],"eEn":"ShortCircuitOperator skips downstream tasks when its condition is false, so hours without a file end without failure or waiting. Raising an exception marks the run failed, a sensor with no timeout keeps holding a slot, and switching to daily changes the hourly ingestion requirement."},{"id":"h169","d":"D3","q":"日次 DAG は、その日に届いたファイルごとに変換タスクを実行する。ファイル数は日によって 10 個から 3,000 個まで変動し、事前には分からない。ファイル単位で並列に実行し、失敗したファイルだけを再試行したい。最も適切な実装はどれですか。","o":["最大数の 3,000 個のタスクを固定で定義しておき、ファイルが無い日は使わないタスクを失敗させる","1 つの PythonOperator の中でループを回し、その日のすべてのファイルを順番に処理する","動的タスクマッピング (expand) で、実行時点のファイル一覧からファイルごとのタスクを生成する","ファイル数が変わるたびに、DAG ファイルのタスク定義を書き換えて再デプロイする"],"a":2,"e":"動的タスクマッピングは、実行時のファイル一覧から要素数分のタスクを生成するので、ファイル数が変動しても並列実行とファイル単位の再試行ができます。固定の 3,000 タスクは使わない分が失敗し、単一タスクのループは並列化も個別の再試行もできず、DAG の書き換えは手作業の運用になります。","qEn":"A daily DAG runs a transformation task for each file that arrives that day. The number of files varies from 10 to 3,000 depending on the day and is unknown in advance. The team wants per-file parallel execution and retries only for the files that fail. Which implementation is most appropriate?","oEn":["Define the maximum of 3,000 tasks statically and make the unused tasks fail on days with fewer files","Run a loop inside a single PythonOperator that processes all of that day's files one after another","Use dynamic task mapping (expand) to create one task per file from the runtime file list","Rewrite the task definitions in the DAG file and redeploy whenever the number of files changes"],"eEn":"Dynamic task mapping creates as many tasks as there are items in the runtime file list, giving parallel execution and per-file retries as the count varies. Fixed 3,000 tasks leave unused ones failing, a single-task loop gives neither parallelism nor individual retries, and rewriting the DAG is a manual operation."},{"id":"h170","d":"D3","q":"パートナーのファイルが不定期に Cloud Storage に届く。届いたら Airflow の DAG を直ちに 1 回実行したい。現状はセンサータスクが 30 秒ごとにファイルを確認しており、ワーカースロットを常に占有している。最も適切な構成はどれですか。","o":["センサーの確認間隔 (poke_interval) を 1 秒に短縮して、ファイルの到着をより早く検知できるようにし、同時に使うスロットも増やしておく","Eventarc で作成イベントを受け、Cloud Run functions から Airflow の REST API 経由で DAG を起動する","DAG のスケジュールを毎分に設定して、毎回の先頭でファイルの有無を確認するタスクを実行する","ファイルが届いたことを担当者がメールで受け取り、毎回手動で DAG を実行する運用にする"],"a":1,"e":"オブジェクト作成のイベントを Eventarc で受け、Cloud Run functions から Airflow の REST API で DAG を起動すれば、ポーリングもスロットの占有もなく、到着の直後に 1 回だけ実行できます。確認間隔の短縮はポーリングを増やし、毎分の実行は無駄が多く、手動実行は即時性に欠けます。","qEn":"Partner files arrive in Cloud Storage at irregular times, and the team wants to run an Airflow DAG once immediately on arrival. Currently a sensor task checks for the file every 30 seconds and permanently occupies a worker slot. Which configuration is most appropriate?","oEn":["Shorten the sensor's polling interval (poke_interval) to 1 second so arrival is detected sooner","Receive the creation event with Eventarc and have Cloud Run functions start the DAG through the Airflow REST API","Schedule the DAG every minute and run a task at the start of each run that checks whether the file exists in the bucket","Have staff receive an email when a file arrives and run the DAG by hand every time"],"eEn":"Receiving the creation event with Eventarc and starting the DAG through the Airflow REST API from Cloud Run functions avoids polling and slot occupation and runs exactly once right after arrival. A shorter polling interval adds polling, a per-minute schedule wastes runs, and manual runs lack immediacy."},{"id":"h171","d":"D3","q":"タスク A が 2 GB の DataFrame を作り、タスク B に渡すために XCom に push したところ、環境のメタデータデータベースが肥大化して、環境全体が不安定になった。タスク間のデータ受け渡しを安全にしたい。最も適切な設計はどれですか。","o":["データ本体は Cloud Storage や BigQuery のテーブルに書き込み、XCom にはそのパスやテーブル名だけを渡す","XCom の保持日数を延ばして履歴を残し、後続のタスクが過去の値を再利用できるようにする運用に変える","DataFrame を pickle にして base64 に変換し、複数に分割して XCom に push してから後続のタスクで結合する","タスク A がワーカーのローカルディスクにファイルとして保存し、タスク B が同じパスからそのファイルを読み込む"],"a":0,"e":"XCom は小さなメタデータ向けで、大きなデータをメタデータ DB に載せると環境が不安定になります。データ本体を Cloud Storage や BigQuery に置き、パスだけを渡すのが定石です。保持日数の延長は肥大化を悪化させ、分割しても合計の容量は変わらず、ワーカーのローカルディスクはタスクごとに別のワーカーで動くため共有できません。","qEn":"Task A built a 2 GB DataFrame and pushed it to XCom to hand it to Task B, which bloated the environment's metadata database and made the whole environment unstable. The team wants a safe way to pass data between tasks. Which design is most appropriate?","oEn":["Write the data itself to Cloud Storage or a BigQuery table and pass only the path or table name through XCom","Extend the XCom retention period to keep the history so that later tasks can reuse past values","Pickle the DataFrame, convert it to base64, split it into pieces, push them to XCom, and reassemble them downstream","Have Task A save the data as a file on the worker's local disk and Task B read it from the same path"],"eEn":"XCom is meant for small metadata, and large data in the metadata DB destabilizes the environment; the standard approach stores the data in Cloud Storage or BigQuery and passes only its location. Longer retention worsens bloat, splitting leaves the total size unchanged, and a worker's local disk cannot be shared because tasks may run on different workers."},{"id":"h172","d":"D3","q":"DAG の PythonOperator が、数十 GB のデータを pandas で変換している。ワーカーのメモリ不足 (OOM) でタスクが頻繁に強制終了される。ワーカーを大きくし続けることは避けたい。最も適切な設計はどれですか。","o":["ワーカーのメモリを大きくした環境を新たに作成し、すべての DAG をその環境へ移行して運用を続ける","pandas の処理を複数の PythonOperator に分割して、同じワーカー上で順番に実行するようにする","重い変換は BigQuery の SQL や Dataflow に任せて、Airflow は起動と待機だけを行う","タスクの retries を増やして、OOM で終了するたびに自動で再実行されるようにしておく"],"a":2,"e":"Airflow はオーケストレーションの基盤で、重いデータ処理はスケールする BigQuery や Dataflow に任せ、起動と完了待ちだけを担当するのが適切です。大きなワーカーに移行する方法はコストが増え続け、分割しても同じワーカーのメモリで処理し、retries を増やしても同じ OOM が繰り返されます。","qEn":"A PythonOperator in a DAG transforms tens of gigabytes of data with pandas, and tasks are frequently killed by worker out-of-memory (OOM) errors. The team wants to avoid enlarging workers indefinitely. Which design is most appropriate?","oEn":["Create a new environment with larger worker memory and migrate all DAGs to that environment to keep operating","Split the pandas processing across several PythonOperators and run them one after another on the same worker","Delegate heavy transformations to BigQuery SQL or Dataflow and let Airflow only start and await them","Increase the task retries so that the task is automatically rerun each time it is terminated by OOM"],"eEn":"Airflow is an orchestration layer; heavy data processing belongs in scalable BigQuery or Dataflow, with Airflow just starting jobs and waiting. Bigger workers keep raising cost, splitting still uses the same worker's memory, and more retries repeat the same OOM."},{"id":"h173","d":"D3","q":"運用チームは、Airflow の DAG の実行が失敗したときに、DAG ごとのコードを変更せずに、Slack へ通知を出したい。環境は Managed Service for Apache Airflow (旧 Cloud Composer) 上にある。最も適切な方法はどれですか。","o":["すべての DAG のコードに on_failure_callback を追加して、Slack の Webhook を呼び出す処理を書く","運用担当者が毎朝 Airflow の画面で失敗した実行を確認し、その内容を Slack に手動で投稿する","Cloud Monitoring のログベース指標を条件にアラートポリシーを作り、通知先に Slack を指定する","BigQuery のスケジュールクエリで環境のメタデータデータベースを毎分確認し、失敗した行が見つかれば通知する"],"a":2,"e":"Cloud Monitoring のアラートポリシーなら、ログベース指標やメトリクスを条件に、DAG のコードを変えずに Slack へ通知できます。on_failure_callback はすべての DAG のコード変更が必要で、毎朝の手動確認は検知が遅れます。メタデータデータベースは利用者が直接クエリできる対象ではありません。","qEn":"The operations team wants a Slack notification whenever an Airflow DAG run fails, without changing the code of each DAG. The environment runs on Managed Service for Apache Airflow (formerly Cloud Composer). Which method is most appropriate?","oEn":["Add on_failure_callback to every DAG's code and write the processing that calls a Slack webhook","Have an operator check failed runs in the Airflow UI every morning and post the details to Slack by hand","Create a Cloud Monitoring alerting policy on log-based metrics or metrics with Slack as the notification channel","Use a BigQuery scheduled query to check the environment's metadata database every minute and notify if failed rows appear"],"eEn":"A Cloud Monitoring alerting policy based on log-based metrics or metrics can notify Slack without any DAG code changes. on_failure_callback requires editing every DAG, a manual morning check detects failures late, and the metadata database is not something users can query directly."},{"id":"h174","d":"D3","q":"夜間の処理では、Dataflow による取り込みが終わったあとに Dataform の変換を実行する。現状は取り込みを 1:00、Dataform の実行を 2:00 の固定時刻にそれぞれスケジュールしているが、取り込みが 2:00 を過ぎる日は、古いデータのまま変換が走ってしまう。最も適切な改善はどれですか。","o":["同じ DAG で、取り込みタスクの完了後に Dataform の実行タスクを依存関係で続ける","Dataform のスケジュールを 3:00 に遅らせて、取り込みが終わるまでの余裕をさらに大きくとる","Dataform の実行頻度を 15 分ごとに増やして、最新のデータが入ったらすぐ変換されるようにする","取り込みのジョブを 2 回実行して、必ず 2:00 までに終わるようにしてから変換を走らせる"],"a":0,"e":"処理の順序は、時刻のずらしではなく依存関係で表現するのが確実です。1 つの DAG で取り込みタスクの完了後に Dataform の実行タスクを続ければ、取り込みが遅れても変換は完了を待ちます。3:00 への変更は余裕を持たせても遅延が超えれば再発し、頻度を増やすと無駄な実行が増え、二重の取り込みは重複を生みます。","qEn":"A nightly process runs Dataform transformations after a Dataflow ingestion finishes. Currently ingestion is scheduled for 1:00 and Dataform for 2:00 as fixed times, but on days when ingestion runs past 2:00, the transformations run on stale data. Which improvement is most appropriate?","oEn":["In one DAG, run the Dataform invocation task after the ingestion task completes, linked by a dependency","Delay the Dataform schedule to 3:00 to leave an even larger margin until ingestion finishes","Increase the Dataform run frequency to every 15 minutes so the latest data is transformed as soon as it arrives","Run the ingestion job twice so that it always finishes by 2:00 before the transformation starts"],"eEn":"Ordering should be expressed with dependencies, not staggered times. In one DAG, running the Dataform task after the ingestion task makes the transformation wait however late ingestion is. Moving to 3:00 recurs once the delay exceeds the margin, more frequent runs waste work, and double ingestion creates duplicates."},{"id":"h175","d":"D3","q":"プライベート IP の構成で作成した Airflow 環境のタスクが、外部 SaaS の API を呼び出そうとしてタイムアウトする。環境のワーカーには外部 IP がなく、SaaS 側は特定の固定 IP からのアクセスだけを許可している。最も適切な対処はどれですか。","o":["ワーカーの VM に直接、一時的な外部 IP アドレスを割り当てて、タスクが SaaS に接続できるようにする","タスクのタイムアウトの値を長く設定して、接続が確立するまで待機する時間に十分な余裕を持たせる","限定公開の Google アクセスを有効にし、外部 SaaS へ Google の内部経路で接続できるようにする","Cloud NAT を構成して予約した固定の外部 IP を割り当て、その IP を SaaS 側に許可してもらう"],"a":3,"e":"外部 IP のないワーカーが外部へ出るには Cloud NAT が必要で、予約済みの固定 IP を割り当てれば、SaaS 側の許可リストに登録できます。ワーカーへの一時 IP の直接割り当ては管理された環境では扱えず、タイムアウトを延ばしても経路がないため接続できません。限定公開の Google アクセスは Google API 向けで、外部 SaaS には届きません。","qEn":"Tasks in an Airflow environment created with a private IP configuration time out when calling an external SaaS API. The environment's workers have no external IP, and the SaaS permits access only from specific fixed IP addresses. Which action is most appropriate?","oEn":["Assign an ephemeral external IP address directly to the worker VMs so that the tasks can reach the SaaS","Set a longer timeout on the tasks to leave plenty of time for a connection to be established","Enable Private Google Access so that the external SaaS is also reached over Google's internal route","Configure Cloud NAT with a reserved static external IP and have the SaaS allow that IP"],"eEn":"Workers without external IPs need Cloud NAT to reach the internet, and a reserved static IP can be registered on the SaaS allow list. Attaching ephemeral IPs directly to managed workers is not available, a longer timeout cannot help without a route, and Private Google Access covers Google APIs, not external SaaS."},{"id":"h176","d":"D3","q":"開発者が追加した新しい DAG ファイルが、dags/ フォルダへアップロードして数十分経っても Airflow の画面の DAG 一覧に表示されない。環境自体は正常に動作しており、他の DAG は問題なく実行されている。最初に確認すべき最も適切な箇所はどれですか。","o":["環境のワーカーの CPU 使用率を確認し、使用率が高いようなら新しい DAG の登録が遅れていないか調べる","BigQuery のジョブ履歴を確認し、新しい DAG が発行するはずのクエリが実行されていないかどうかを調べる","DAG インポートエラー表示や DAG プロセッサのログで、構文エラーや依存ライブラリの不足を確認する","Cloud Scheduler のジョブ一覧を確認し、新しい DAG を起動するためのジョブが作成されているかどうかを調べる"],"a":2,"e":"DAG が一覧に出ない主な原因は、ファイルの解析時のエラー (構文エラーや import の失敗) で、Airflow の画面のインポートエラー表示や DAG プロセッサのログで確認できます。ワーカーの CPU、BigQuery のジョブ履歴、Cloud Scheduler は、DAG の登録 (解析) の可否とは直接関係しません。","qEn":"A new DAG file added by a developer has still not appeared in the Airflow UI's DAG list tens of minutes after being uploaded to the dags/ folder. The environment itself is working normally and other DAGs run without problems. Which place is most appropriate to check first?","oEn":["Check worker CPU utilization and see whether high usage is delaying registration of the new DAG","Check BigQuery job history to see whether the queries the new DAG should issue have been executed","Check the UI's import errors or DAG processor logs for syntax errors or missing dependencies","Check the Cloud Scheduler job list to see whether a job that starts the new DAG has been created"],"eEn":"A DAG missing from the list is usually caused by an error while parsing the file, such as a syntax error or failed import, visible in the UI's import errors or the DAG processor logs. Worker CPU, BigQuery job history, and Cloud Scheduler are not directly related to whether a DAG is registered."},{"id":"h177","d":"D3","q":"DAG が社内で作成した Python パッケージ (公開の PyPI ではなく Artifact Registry に保存) をインポートするため、ImportError で失敗する。DAG ファイルと同じ dags/ フォルダにパッケージのソースを手でコピーする運用は、バージョン管理が煩雑で避けたい。最も適切な対処はどれですか。","o":["各 DAG のトップレベルで pip install を実行し、DAG ファイルが解析されるたびに最新版を取得する","パッケージのソースコードを、すべての DAG ファイルの先頭に貼り付けて、インポート自体を不要にする","ワーカーの VM に SSH で接続して手作業でパッケージをインストールし、再起動のたびにやり直す","環境の PyPI パッケージの設定に Artifact Registry 上のパッケージを追加してインストールする"],"a":3,"e":"環境のカスタム PyPI パッケージ設定で、Artifact Registry 上のパッケージを環境にインストールすれば、スケジューラ、ワーカー、triggerer の全体で同じバージョンが使われ、バージョン管理も一元化できます。DAG のトップレベルでの pip install は解析のたびに実行されて不安定になり、コードの貼り付けや手作業のインストールは再現性がありません。","qEn":"A DAG fails with an ImportError because it imports an internally built Python package (stored in Artifact Registry, not public PyPI). The team wants to avoid the practice of copying the package source into the dags/ folder by hand, since version management becomes messy. Which action is most appropriate?","oEn":["Run pip install at the top level of each DAG so the latest version is fetched every time the DAG file is parsed","Paste the package source at the top of every DAG file so that no import is needed at all","SSH into the worker VMs, install the package by hand, and repeat the work after every restart","Add the Artifact Registry package to the environment's PyPI packages configuration to install it"],"eEn":"Installing the Artifact Registry package through the environment's custom PyPI package settings gives the scheduler, workers, and triggerer the same version and centralizes version management. pip install at DAG top level runs on every parse and is unstable, and pasting code or manual installs are not reproducible."},{"id":"h178","d":"D3","q":"Workflows で、5 つの独立した地域別 API から売上を取得して合算する処理を実装している。各呼び出しに約 20 秒かかり、現在は順番に実行しているため合計 100 秒かかる。呼び出し同士に依存関係はない。実行時間を短縮する最も適切な方法はどれですか。","o":["各呼び出しの前に sys.sleep を入れて、API 側の負荷を分散してから順番に実行するようにする","5 つの呼び出しを 5 つの別々のワークフローに分割して、担当者が順に手動で起動する運用にする","parallel ステップで 5 つの呼び出しを並列に実行し、結果を共有変数に集約して合算する","各呼び出しのタイムアウトを短く設定して、遅い呼び出しを打ち切ったうえで残りの結果を合算する"],"a":2,"e":"parallel ステップなら独立した呼び出しを同時に実行でき、全体の時間をほぼ最も遅い 1 件分に短縮できます。結果は共有変数に集めて合算します。sleep の挿入は時間を延ばし、手動での分割起動は自動化に反し、タイムアウトで打ち切ると売上の一部が欠けた合計になります。","qEn":"A Workflows implementation fetches sales from five independent regional APIs and sums them. Each call takes about 20 seconds and they currently run sequentially for 100 seconds in total. The calls do not depend on each other. Which method most appropriately shortens the execution time?","oEn":["Insert sys.sleep before each call to spread the load on the APIs and then run the calls in sequence","Split the five calls into five separate workflows and have staff start them one after another by hand","Run the five calls in parallel branches and aggregate the results in a shared variable","Set a short timeout on each call to cut off slow calls and then sum whatever results remain"],"eEn":"A parallel step runs independent calls at the same time, cutting the total to roughly the slowest single call, with results collected in a shared variable. Adding sleeps lengthens the time, manual separate starts defeat automation, and cutting off slow calls yields a sum that is missing some sales."},{"id":"h179","d":"D3","q":"Workflows から BigQuery の集計クエリジョブを起動し、完了してから次のステップへ進みたい。ジョブは数分から数十分かかる。現在は HTTP 呼び出しでジョブを作成し、状態を取得するステップを sys.sleep つきでループさせる実装で、コードが長く壊れやすい。最も適切な書き換えはどれですか。","o":["ループ内の sys.sleep を長めに変更して、状態を取得する回数を減らし、コードの量も減らす","ジョブを非同期で起動したら、完了を待たずにそのまま次のステップへ進む構成に変更する","ワークフローを Cloud Run functions に書き換えて、関数の中でジョブの状態を確認し続ける","BigQuery コネクタ (jobs.insert など) を使って、ジョブの完了待ちをコネクタに任せる"],"a":3,"e":"Workflows の BigQuery コネクタは、ジョブの作成と完了待ちを内部で処理するため、ポーリングのループを自分で書く必要がなくなります。sleep を長くしても実装の複雑さは変わらず、完了を待たずに進むと後続が未完了のデータを使う恐れがあります。関数への書き換えはタイムアウトと実装の負担が増えます。","qEn":"A Workflows definition starts a BigQuery aggregation query job and must proceed to the next step only after it completes. Jobs take minutes to tens of minutes. The current implementation creates the job with an HTTP call and loops over a status-check step with sys.sleep, which makes the code long and fragile. Which rewrite is most appropriate?","oEn":["Lengthen the sys.sleep in the loop to reduce how often the status is fetched and also shorten the code","Change the design to start the job asynchronously and move straight on to the next step without waiting","Rewrite the workflow as Cloud Run functions and keep checking the job status inside the function","Use the BigQuery connector (such as jobs.insert) and let it handle waiting for job completion"],"eEn":"The Workflows BigQuery connector handles job creation and waiting for completion internally, so no hand-written polling loop is needed. A longer sleep does not simplify the implementation, proceeding without waiting risks later steps using incomplete data, and rewriting as functions adds timeout and implementation burdens."},{"id":"h180","d":"D3","q":"月次の決算ワークフローは、データ検証のあとに経理担当者の承認を受けてから確定処理へ進む。承認は数時間から数日かかる。承認待ちの間にポーリングや常駐プロセスで課金を発生させたくなく、承認者が承認した時点で処理を再開させたい。最も適切な実装はどれですか。","o":["コールバックエンドポイントを作成して待機し、承認システムの呼び出しで再開する","1 分ごとに承認の有無を確認するループを、sys.sleep を使ってワークフロー内に実装する","承認されるまで Cloud Run functions を実行し続けて、承認の状態を確認し続けるようにする","承認の有無にかかわらず確定処理まで進め、取り消しが必要になった場合は手動で元に戻す"],"a":0,"e":"Workflows のコールバックは、エンドポイントを作成して実行を一時停止し、外部システムが呼び出したときに再開できるため、ポーリングも常駐プロセスも要りません。sys.sleep のループは待機中も実行が続き、関数を動かし続ける方法はタイムアウトと課金の問題があります。承認なしの確定は要件に反します。","qEn":"A monthly closing workflow proceeds to finalization only after an accounting officer approves it following data validation. Approval takes hours to days. The team does not want to incur charges from polling or a resident process while waiting, and wants processing to resume as soon as the approver approves. Which implementation is most appropriate?","oEn":["Create a Workflows callback endpoint and wait on it, resuming when the approval system calls that endpoint","Implement a loop inside the workflow that checks every minute for approval, using sys.sleep","Keep a Cloud Run functions execution running until approval is granted, checking the approval status continuously","Proceed all the way to finalization regardless of approval and revert by hand if cancellation turns out to be needed"],"eEn":"A Workflows callback creates an endpoint, pauses the execution, and resumes when the external system calls it, so no polling or resident process is needed. A sys.sleep loop keeps the execution active while waiting, keeping a function running has timeout and cost issues, and finalizing without approval violates the requirement."},{"id":"h181","d":"D3","q":"Workflows が、BigQuery に一時テーブルを作成し、変換して本テーブルへ反映する。途中のステップが失敗した場合、作成済みの一時テーブルを削除してから、失敗をエラーとして記録して実行を終了させたい。最も適切な実装はどれですか。","o":["except で何もせずに握りつぶして、実行を正常終了として扱うようにする","削除のステップをワークフローの先頭に置いて、毎回の実行前に一時テーブルを消すだけにする","失敗した実行を担当者が手動でキャンセルし、一時テーブルはそのまま残して後日まとめて消す","try/except で捕捉して一時テーブルを削除し、raise でエラーを再送出する"],"a":3,"e":"try/except で失敗を捕捉して後始末 (一時テーブルの削除) を行い、raise で元のエラーを再送出すれば、片付けとエラーとしての記録を両立できます。握りつぶすと失敗が見えなくなり、実行前の削除では失敗直後に一時テーブルが残ります。手動キャンセルと放置は後始末を自動化する要件に反します。","qEn":"A Workflows definition creates a temporary table in BigQuery, transforms the data, and reflects it into the main table. If any step fails, the team wants the temporary table deleted and the failure recorded as an error before the execution ends. Which implementation is most appropriate?","oEn":["Swallow the failure in except without doing anything and treat the execution as finishing normally","Put the delete step at the start of the workflow so the temporary table is removed only before each run","Have staff cancel the failed execution by hand and leave the temporary table in place to delete in bulk later","Catch the failure with try/except, delete the temporary table, then re-raise the original error"],"eEn":"Catching the failure with try/except, doing the cleanup (deleting the temporary table), and re-raising the original error achieves both cleanup and error recording. Swallowing hides the failure, deleting at the start leaves the table right after a failure, and manual cancellation plus neglect contradicts the goal of automating cleanup."},{"id":"h182","d":"D3","q":"Workflows から、未認証の呼び出しを拒否している Cloud Run サービスを HTTP で呼び出すと、403 が返る。ワークフローの実行用サービスアカウントは設定済みである。最も適切な修正はどれですか。","o":["auth: type: OIDC を指定し、サービスアカウントに Cloud Run 起動元ロールを付与する","Cloud Run サービスに allUsers の起動元ロールを付与して、未認証でも呼び出せるようにして 403 を解消する","HTTP 呼び出しのヘッダーに、手元で発行したアクセストークンを固定の文字列として埋め込む","Cloud Run のサービス URL の代わりに、リビジョンの名前をそのまま呼び出し先として指定する"],"a":0,"e":"認証必須の Cloud Run を呼ぶには、HTTP 呼び出しで OIDC を指定してトークンを付与し、呼び出し元のサービスアカウントに起動元ロールを与えます。allUsers の付与は未認証のアクセスを許してしまい、固定のトークンは期限切れで失敗し、リビジョン名は呼び出し先として使えません。","qEn":"An HTTP call from Workflows to a Cloud Run service that rejects unauthenticated requests returns 403. The workflow's execution service account is already configured. Which fix is most appropriate?","oEn":["Use auth: type: OIDC on the call and grant the workflow's service account the invoker role","Grant the invoker role to allUsers on the Cloud Run service so it can be called without authentication","Embed an access token issued by hand in the HTTP call's headers as a fixed string","Specify the revision name as the call target instead of the Cloud Run service URL"],"eEn":"To call an authenticated Cloud Run service, specify OIDC on the HTTP call so a token is attached, and give the caller's service account the invoker role. Granting allUsers allows unauthenticated access, a fixed token expires and fails, and a revision name cannot serve as the call target."},{"id":"h183","d":"D3","q":"Workflows が、取引先 1,000 社の API を for ループで順に呼び出しており、全体で 3 時間かかっている。並列化したいが、各社の API は共通の基盤上にあり、同時に 20 を超えるリクエストを受けると障害が起きる。最も適切な実装はどれですか。","o":["for ループを parallel つきにして、同時実行数の上限を設けずに 1,000 社を一斉に呼び出す","1,000 社を 1 つずつ別のワークフロー実行として起動し、Cloud Scheduler から一斉に実行させる","for ループを parallel つきにして、concurrency_limit で同時実行数を 20 件に絞る","各呼び出しの前後に sys.sleep を入れて、1 社ずつの呼び出しの間隔を広げて順番に実行する"],"a":2,"e":"parallel の for ループに concurrency_limit を指定すると、並列化しながら同時実行数を 20 に抑えられ、共通基盤を保護できます。上限なしの一斉呼び出しは障害を起こし、1,000 件の同時起動も同様で、sleep を入れる方法は順次処理がさらに長くなります。","qEn":"A Workflows definition calls the APIs of 1,000 partners one after another in a for loop, taking three hours in total. The team wants to parallelize it, but all partners' APIs sit on a shared platform that fails if it receives more than 20 simultaneous requests. Which implementation is most appropriate?","oEn":["Make the for loop parallel with no limit on concurrency and call all 1,000 partners at once","Start one workflow execution per partner, 1,000 in all, and have Cloud Scheduler launch them all together","Make the for loop parallel and limit simultaneous execution to 20 with concurrency_limit","Insert sys.sleep before and after each call to widen the interval between sequential partner calls"],"eEn":"A parallel for loop with concurrency_limit parallelizes while capping simultaneous calls at 20, protecting the shared platform. Unlimited calls or 1,000 simultaneous starts would cause failures, and adding sleeps makes the sequential run even longer."},{"id":"h184","d":"D3","q":"米国拠点向けの日次レポート生成を、現地時間 (America/New_York) の毎朝 9:00 に Cloud Scheduler で起動したい。夏時間の開始・終了で UTC との差が変わっても、現地の 9:00 に起動し続ける必要がある。最も適切なジョブの設定はどれですか。","o":["タイムゾーンは UTC のままにして、cron 式を「0 14 * * *」に固定し、年間を通じて同じ式で運用する","ジョブのタイムゾーンを America/New_York に指定し、cron 式を「0 9 * * *」に設定する","夏時間用と冬時間用の 2 つのジョブを作り、夏時間の切り替え日に担当者が手動で一時停止と再開を行う","cron 式に夏時間の切り替え日を例外として書き足し、その日だけ 1 時間ずらした式を使うようにする"],"a":1,"e":"Cloud Scheduler はジョブにタイムゾーンを指定でき、America/New_York を指定すれば夏時間の切り替えを自動で考慮して現地の 9:00 に起動します。UTC の固定式は夏時間の期間中に現地時刻が 1 時間ずれ、2 ジョブの手動切り替えは運用が煩雑で漏れが出ます。cron 式に日付の例外を書く機能はありません。","qEn":"The team wants Cloud Scheduler to start a daily report job for the US office every morning at 9:00 local time (America/New_York). It must keep starting at 9:00 local time even when the offset from UTC changes at the start and end of daylight saving time. Which job configuration is most appropriate?","oEn":["Leave the time zone as UTC, fix the cron expression at '0 14 * * *', and use the same expression all year","Set the job's time zone to America/New_York and use the cron expression '0 9 * * *'","Create separate summer-time and winter-time jobs and have staff pause and resume them by hand on the changeover days","Add the daylight saving changeover dates to the cron expression as exceptions and use a shifted expression only on those days"],"eEn":"Cloud Scheduler lets you set a time zone on the job, and America/New_York automatically accounts for daylight saving so the job starts at 9:00 local time. A fixed UTC expression is off by an hour for part of the year, switching two jobs by hand is error prone, and cron expressions cannot take date exceptions."},{"id":"h185","d":"D3","q":"Cloud Scheduler が毎時、Cloud Run 上の取り込み API を HTTP で呼び出す。API は一時的に 503 を返すことがあり、そのたびにジョブが失敗扱いになる。再試行して成功させたいが、再試行や Scheduler の「少なくとも 1 回」の実行によって、同じ時間帯のデータが二重に取り込まれることは避けたい。最も適切な設計はどれですか。","o":["再試行を無効にして、失敗した時間帯は翌日に担当者が手動で再取り込みする運用にする","Scheduler の再試行設定を有効にし、API は時間帯をキーに冪等に処理する","再試行の回数を無制限に設定して、成功するまで繰り返し、API 側では重複の確認を行わない","同じ API を呼ぶジョブを 3 つ作って実行時刻をずらし、いずれかが成功すれば十分とみなす"],"a":1,"e":"再試行の設定で一時的な 503 を吸収し、API 側を時間帯 (予定時刻) をキーに冪等にすれば、再試行や重複した実行があっても二重の取り込みを防げます。再試行なしでは手動対応が増え、無制限の再試行で冪等性がなければ重複が起き、3 つのジョブは重複実行を増やします。","qEn":"Cloud Scheduler calls an ingestion API on Cloud Run over HTTP every hour. The API sometimes returns a temporary 503, marking the job as failed each time. The team wants retries to succeed, but wants to avoid ingesting the same hour's data twice because of retries or Scheduler's at-least-once execution. Which design is most appropriate?","oEn":["Disable retries and have staff re-ingest the failed hour by hand the next day as an operating rule","Enable Scheduler's retry settings and make the API process each time slot idempotently","Set retries to unlimited so it repeats until it succeeds, and do not check for duplicates on the API side","Create three jobs that call the same API at staggered times and treat success of any one of them as sufficient"],"eEn":"Retry settings absorb the temporary 503, and making the API idempotent by time slot prevents double ingestion even when retries or duplicate executions occur. Without retries manual work grows, unlimited retries without idempotency cause duplicates, and three jobs multiply duplicate executions."},{"id":"h186","d":"D3","q":"BigQuery のスケジュールクエリ (毎日、@run_date を使って前日分を集計して追記) が、上流の障害で 5 日間失敗した。上流は復旧した。失敗した 5 日分を、それぞれの日付のパラメーターで再実行したい。クエリの書き換えは避けたい。最も適切な方法はどれですか。","o":["失敗した日ごとにクエリを複製し、日付を手で書き換えて、コンソールから 1 つずつ順番に実行していく","スケジュールを 1 時間ごとに変更して、失敗した分を自動で追い付いて処理するのを待つ","スケジュールクエリのバックフィル機能で 5 日間を指定し、各日の @run_date で再実行する","追記先のテーブルを削除し、全期間を最初から作り直す新しいスケジュールを設定する"],"a":2,"e":"スケジュールクエリのバックフィルは、指定した期間の各実行日について @run_date を渡して再実行でき、クエリを書き換えずに欠けた 5 日分を埋められます。日付を手で変えた複製は手間とミスを生み、間隔を変えても過去の分は再実行されません。テーブルの作り直しは不要で、過去分を失う危険があります。","qEn":"A BigQuery scheduled query (daily, aggregating the previous day with @run_date and appending the result) failed for five days because of an upstream outage, which has now recovered. The team wants to rerun the five missed days, each with its own date parameter, and wants to avoid rewriting the query. Which method is most appropriate?","oEn":["Duplicate the query for each failed day, edit the date by hand, and run them one by one from the console","Change the schedule to hourly and wait for it to catch up on the missed days automatically","Run a scheduled query backfill over the five-day range so each run date is rerun with its own @run_date","Delete the destination table and set up a new schedule that rebuilds the whole period from the beginning"],"eEn":"A scheduled query backfill reruns each run date in the chosen range with its own @run_date, filling the five missing days without editing the query. Hand-edited copies are laborious and error prone, changing the interval does not rerun past dates, and rebuilding the table is unnecessary and risks losing history."},{"id":"h187","d":"D3","q":"部長個人の認証情報で作成された BigQuery のスケジュールクエリが多数あり、部長の異動でアカウントが無効化されると、クエリが実行できなくなる。担当者が変わっても継続して動かせる運用にしたい。最も適切な対処はどれですか。","o":["後任の担当者の認証情報でスケジュールクエリを作り直し、今後はその担当者のアカウントで実行する","異動後も部長のアカウントを無効化せず、休眠アカウントとしてそのまま残して運用を続ける","部長のパスワードを共有の保管庫に保存し、後任の担当者がそのアカウントでログインして使えるようにする","スケジュールクエリをサービスアカウントで実行するよう設定し、必要なロールを付与する"],"a":3,"e":"サービスアカウントで実行するよう設定すれば、個人の異動や退職に影響されずにスケジュールクエリが動き続けます。後任の認証情報で作り直しても同じ問題が再発し、無効化しないアカウントの放置やパスワード共有はセキュリティ上の問題があります。","qEn":"Many BigQuery scheduled queries were created with a department head's personal credentials, and if the account is disabled when the head transfers, the queries can no longer run. The team wants an operation that keeps running even when personnel change. Which action is most appropriate?","oEn":["Recreate the scheduled queries with the successor's credentials so they run under that person's account from now on","Do not disable the department head's account after the transfer and keep operating with it as a dormant account","Store the department head's password in a shared vault so the successor can log in with that account and use it","Configure the scheduled queries to run as a service account and grant it the required BigQuery roles"],"eEn":"Running the queries as a service account keeps them working regardless of transfers or departures. Recreating them under a successor's credentials brings back the same problem, and leaving the account enabled or sharing its password are security problems."},{"id":"h188","d":"D3","q":"BigQuery のスケジュールクエリが失敗したときに、運用チームの Slack チャンネルへ通知したい。スケジュールクエリごとの変更や、新たなコードの開発は避けたい。最も適切な構成はどれですか。","o":["各スケジュールクエリの SQL の末尾に、Slack の Webhook を呼び出すステートメントを追記して通知させる","担当者が毎朝 BigQuery のコンソールで転送の画面を開き、失敗した実行がないかを確認して Slack に連絡する","転送の失敗ログを条件に Cloud Monitoring のログベースアラートを作り、Slack に通知する","スケジュールクエリのメール通知を担当者の個人アドレスに設定し、受信したメールを手動で Slack に転送する"],"a":2,"e":"スケジュールクエリは Data Transfer Service の転送として実行され、失敗は Cloud Logging に記録されます。これを条件にしたログベースのアラートなら、新しいコードもクエリの変更もなく Slack に通知できます。SQL から Webhook は呼べず、毎朝の目視確認や手動転送は検知と連絡が遅れて運用負荷が高くなります。","qEn":"The operations team wants a notification to its Slack channel when a BigQuery scheduled query fails. It wants to avoid modifying each scheduled query or developing new code. Which configuration is most appropriate?","oEn":["Append a statement that calls a Slack webhook to the end of the SQL of every scheduled query so it sends notifications","Have staff open the transfers page in the BigQuery console every morning, check for failed runs, and tell Slack by hand","Create a Cloud Monitoring log-based alert on logs that indicate a failed transfer run and set Slack as the channel","Set email notifications on the scheduled queries to a staff member's address and forward received emails to Slack manually"],"eEn":"Scheduled queries run as Data Transfer Service transfers, and failures are recorded in Cloud Logging, so a log-based alert can notify Slack with no new code or query changes. SQL cannot call a webhook, and morning eyeballing or manual forwarding delays detection and adds operational burden."},{"id":"h189","d":"D3","q":"Dataform のリポジトリに数百の SQLX があり、アクションには daily タグを付けてある。毎朝 3:00 (JST) に、daily タグのアクションとその依存先だけを、最新のコミットをコンパイルして実行したい。別のオーケストレーション基盤は新設したくない。最も適切な方法はどれですか。","o":["Managed Service for Apache Airflow の環境を新たに作成し、Dataform の実行オペレーターを使う DAG を毎朝動かす","リリース構成でコンパイルし、ワークフロー構成で daily タグを対象に cron (Asia/Tokyo) で実行する","各 SQLX が生成する SQL をコピーして BigQuery のスケジュールクエリに貼り付け、3:00 に順番に実行する","Cloud Scheduler から毎分、リポジトリ全体の実行を要求して、daily 以外のアクションも含めて走らせる"],"a":1,"e":"Dataform には、コンパイルを行うリリース構成と、タグや依存先を指定して cron で実行するワークフロー構成があり、追加の基盤なしで毎朝の実行を設定できます。Airflow 環境の新設は別基盤の追加にあたり、SQL の貼り付けは依存関係の管理を失い、毎分の全体実行は対象外のアクションも動かします。","qEn":"A Dataform repository has hundreds of SQLX files, with actions tagged daily. Every morning at 3:00 (JST), the team wants to compile the latest commit and run only the daily-tagged actions and their dependencies. It does not want to set up a separate orchestration platform. Which method is most appropriate?","oEn":["Create a new Managed Service for Apache Airflow environment and run a DAG every morning that uses the Dataform invocation operator","Compile with a release configuration and run a workflow configuration for the daily tag on a cron schedule (Asia/Tokyo)","Copy the SQL generated by each SQLX file into BigQuery scheduled queries and run them in order at 3:00","Have Cloud Scheduler request a run of the entire repository every minute, including actions other than daily"],"eEn":"Dataform has release configurations that compile and workflow configurations that run selected tags and dependencies on a cron schedule, so a morning run needs no extra platform. A new Airflow environment adds a platform, pasted SQL loses dependency management, and per-minute full runs also execute out-of-scope actions."},{"id":"h190","d":"D3","q":"Dataform の日次の変換が、10 TB のイベントテーブル全体を毎日作り直しており、実行時間とスキャン量が膨らんでいる。イベントは追記のみで、直近 2 日分以外は変わらない。再実行しても重複しないようにしつつ、処理量を減らしたい。最も適切な定義はどれですか。","o":["type を incremental にして新しい期間だけを処理し、uniqueKey で重複を防ぐ","テーブルの type を view に変更して、参照のたびに全データを再計算させ、結果を保存せずに最新を返すようにする","type はそのままにして、実行頻度を週 1 回に減らし、全体を再作成する回数を減らして処理量を抑える","アサーションを追加して、全件の再作成が失敗した場合には処理を止めるようにする"],"a":0,"e":"incremental テーブルは、新しい期間の行だけを処理して追加・更新するため、実行時間とスキャン量が減り、uniqueKey を指定すれば再実行しても重複しません。view は参照のたびに全件を再計算してコストが増え、週 1 回への減少は鮮度を損ない、アサーションは検証であり処理量を減らしません。","qEn":"A daily Dataform transformation rebuilds an entire 10 TB events table every day, and run time and bytes scanned have ballooned. Events are append-only and nothing except the last two days changes. The team wants to reduce the processing volume without creating duplicates on reruns. Which definition is most appropriate?","oEn":["Set the table type to incremental, process only new data, and use uniqueKey to prevent duplicates","Change the table type to view so that all data is recomputed whenever the table is queried","Leave the type as it is and reduce the run frequency to once a week to cut the number of full rebuilds","Add an assertion so that processing stops if the full rebuild fails partway through"],"eEn":"An incremental table processes only rows from the new period, cutting run time and bytes scanned, and uniqueKey prevents duplicates on reruns. A view recomputes everything on each query and raises cost, weekly runs hurt freshness, and an assertion is validation that does not reduce processing."},{"id":"h191","d":"D3","q":"Dataform で、顧客マスターの変換後に重複キーと NULL を検出したい。問題があれば、そのテーブルに依存する下流の集計テーブルの更新を止めて、壊れたデータが広がらないようにしたい。最も適切な構成はどれですか。","o":["下流のテーブルの実行が終わったあとに、担当者が別途 SQL を手動で実行して、重複の有無を確認する","アサーション (uniqueKey と nonNull) を設定し、下流をそれに依存させる","アサーションを設定するが依存関係には含めず、下流のアクションと並列に実行して結果を後で見る","重複を検出したらログに警告だけを出力して、下流の更新はそのまま続行する構成にする"],"a":1,"e":"アサーションに uniqueKey と nonNull を設定し、下流のアクションをそのアサーションに依存させれば、検証が失敗したときに下流の更新が実行されません。事後の手動確認や、依存させずに並列で実行する構成は壊れたデータの伝播を防げず、警告だけで続行する構成も同様です。","qEn":"In Dataform, the team wants to detect duplicate keys and NULLs after transforming the customer master. If problems are found, it wants the update of downstream aggregation tables that depend on it to stop so that broken data does not spread. Which configuration is most appropriate?","oEn":["Have staff run SQL by hand to check for duplicates after the downstream tables have finished running","Set assertions (uniqueKey and nonNull) on the transformed table and make downstream actions depend on them","Define the assertions but leave them out of the dependencies, running in parallel with downstream actions and reviewing results later","Only log a warning when duplicates are detected and let the downstream updates continue as they are"],"eEn":"With uniqueKey and nonNull assertions and downstream actions depending on them, a failed check prevents the downstream updates from running. Manual checks afterward, running assertions in parallel without dependencies, or continuing after a warning do not stop broken data from propagating."},{"id":"h192","d":"D3","q":"Dataform のリポジトリを、開発用と本番用の BigQuery データセットで使い分けたい。同じコードから、開発環境ではデータセット名の末尾に _dev を付け、本番では何も付けずに作成させたい。コードのコピーを 2 つ持つことは避けたい。最も適切な方法はどれですか。","o":["リポジトリを開発用と本番用の 2 つに複製し、それぞれのコード内のデータセット名の部分を手作業で書き換える","SQLX の中にデータセット名を直接書き込み、本番へ反映するたびに該当箇所を手動で置換していく","本番用のデータセットだけを用意して、開発者も本番のデータセットに直接書き込んでテストする","リリース構成ごとにコンパイルのオーバーライド (スキーマのサフィックスなど) を設定し、出力先を切り替える"],"a":3,"e":"リリース構成ごとにスキーマのサフィックスなどのコンパイルのオーバーライドを設定すれば、同じコードから開発用と本番用の出力先を作り分けられます。リポジトリの複製や手作業の置換はコードの二重管理と転記ミスを生み、本番への直接書き込みは本番データを壊す危険があります。","qEn":"A team wants to use one Dataform repository with separate BigQuery datasets for development and production. From the same code, development should create datasets with a _dev suffix on the dataset name and production should create them without any suffix. It wants to avoid keeping two copies of the code. Which method is most appropriate?","oEn":["Duplicate the repository into development and production copies and rewrite the dataset names in each by hand","Write the dataset names directly in the SQLX files and replace them manually each time the code is promoted to production","Prepare only the production datasets and have developers write and test directly in them","Set compilation overrides (such as a schema suffix) in each release configuration to switch the output target"],"eEn":"Compilation overrides such as a schema suffix on each release configuration produce development and production outputs from the same code. Duplicating repositories or hand replacement doubles code management and causes transcription errors, and writing directly to production risks damaging production data."},{"id":"h193","d":"D3","q":"Cloud Storage のオブジェクト作成イベントを Eventarc 経由で受けた Cloud Run functions が、そのファイルを BigQuery にロードしている。まれに同じイベントが再配信され、ファイルが 2 回ロードされてデータが重複する。イベントの再配信は避けられない。最も適切な対策はどれですか。","o":["Eventarc の配信保証の設定を「1 回のみ」に変更して、イベントの再配信が発生しないようにする","バケット名と世代番号から決定的なジョブ ID を作ってロードし、再処理を拒否させる","関数の同時実行数を 1 に制限して、同じファイルが並行してロードされないようにする","ロードの後に、テーブル内の重複行を毎週担当者が手作業で見つけて削除する運用にする"],"a":1,"e":"イベントは少なくとも 1 回届くため、処理側を冪等にします。バケットとオブジェクトの世代から決めた ID でロードジョブを作れば、同じ ID のジョブは作成が拒否され、再配信されても 1 回しかロードされません。配信を 1 回のみにする設定はなく、同時実行数の制限では逐次の再配信は防げず、事後の削除は運用負荷が高いです。","qEn":"A Cloud Run functions function that receives Cloud Storage object-creation events through Eventarc loads each file into BigQuery. Occasionally the same event is redelivered, the file is loaded twice, and data is duplicated. Redelivery cannot be avoided. Which measure is most appropriate?","oEn":["Change Eventarc's delivery guarantee setting to exactly once so that events are never redelivered to the function","Build a deterministic load job ID from the bucket and object generation so a reprocessed event is rejected","Limit the function's concurrency to 1 so that the same file is never loaded in parallel by two instances","Have staff find and delete the duplicate rows in the table by hand every week after the loads"],"eEn":"Events arrive at least once, so processing must be idempotent: a load job whose ID is derived from the bucket and object generation is rejected on creation if the ID already exists, so redelivery loads the file only once. There is no exactly-once setting, limiting concurrency does not stop sequential redeliveries, and cleaning up afterward is heavy manual work."},{"id":"h194","d":"D3","q":"パートナーが毎日、1 日分として数十個のファイルを順に Cloud Storage へアップロードし、最後に空の _SUCCESS ファイルを置く。全ファイルが揃う前に取り込みが始まると、不完全な集計になってしまう。全ファイルが揃った時点で、1 回だけ取り込みを開始したい。最も適切な設計はどれですか。","o":["各ファイルの作成イベントごとに取り込みを起動し、最後に起動した処理で全ファイルが揃っていることを願う","_SUCCESS の作成だけを条件にした Eventarc トリガーで起動し、フォルダ全体を取り込む","毎日 7:00 に固定でロードを実行して、遅れて届いたファイルは翌日の取り込みに回す運用にする","ファイルの数が数十個に達するまで、関数の中でポーリングを続けて待機してから取り込みを始める"],"a":1,"e":"_SUCCESS は全ファイルの後に置かれる完了の合図なので、そのオブジェクト作成だけを Eventarc のトリガーの条件にすれば、揃った時点で 1 回だけ起動できます。ファイルごとの起動は途中の不完全な状態で取り込み、固定時刻は遅れに弱く、関数内の待機はタイムアウトや費用の問題があります。","qEn":"Every day a partner uploads several dozen files in sequence to Cloud Storage as one day's data and finally places an empty _SUCCESS file. If ingestion starts before all the files are in place, aggregation becomes incomplete. The team wants ingestion to start exactly once when all files are present. Which design is most appropriate?","oEn":["Start ingestion on each file's creation event and hope that the last invocation sees every file in place","Start processing with an Eventarc trigger filtered to _SUCCESS creation only and ingest the whole folder","Run the load at a fixed 7:00 every day and leave any files that arrive late for the next day's ingestion","Keep polling inside a function until the number of files reaches several dozen and only then begin ingestion"],"eEn":"_SUCCESS is the completion signal placed after all files, so using only its creation as the Eventarc trigger condition starts processing once, when everything is present. Per-file starts ingest partial data, a fixed time is fragile to delays, and waiting inside a function has timeout and cost problems."},{"id":"h195","d":"D3","q":"毎晩、約 4,000 枚の画像をまとめて変換する処理がある。1 枚あたり数秒、全体では 1 時間以上かかる。処理は互いに独立で、失敗した分だけ再試行したい。サーバー管理を避け、並列度を調整したい。最も適切な実行基盤はどれですか。","o":["Cloud Run functions の HTTP 関数 1 つで、4,000 枚の画像をすべて 1 回の実行の中で順番に処理する","Cloud Run ジョブで複数タスクを並列に実行し、タスク単位のリトライを設定して Scheduler から起動する","常時稼働の Compute Engine の VM に、変換のシェルスクリプトを cron で毎晩実行させる","Pub/Sub に 4,000 件を発行し、1 つのサブスクライバが届いた順に 1 件ずつ処理していく"],"a":1,"e":"Cloud Run ジョブは、独立したタスクを並列度を指定して実行でき、タスク単位で再試行され、HTTP のタイムアウトに縛られず長時間の処理もできます。Cloud Scheduler から起動すればサーバー管理は不要です。単一の関数は実行時間の上限に当たり、VM の cron は管理が必要で、単一のサブスクライバでは並列になりません。","qEn":"Every night a job converts about 4,000 images in one batch, a few seconds each and over an hour in total. The items are independent and only the failed ones should be retried. The team wants to avoid server management and be able to tune parallelism. Which execution platform is most appropriate?","oEn":["Process all 4,000 images one after another inside a single execution of one Cloud Run functions HTTP function","Run a Cloud Run job with multiple tasks in parallel, set per-task retries, and start it from Cloud Scheduler","Run the conversion shell script from cron every night on an always-on Compute Engine VM","Publish 4,000 messages to Pub/Sub and have a single subscriber process them one by one in order of arrival"],"eEn":"Cloud Run jobs run independent tasks with configurable parallelism, retry per task, and are not bound by HTTP timeouts, and Cloud Scheduler starts them with no server management. A single function hits its time limit, a VM with cron needs management, and one subscriber is not parallel."},{"id":"h196","d":"D3","q":"DAG の BigQuery ロードタスクは、Cloud Storage のファイル群をテーブルに追記する。ネットワークの瞬断でロードジョブが失敗し、タスクが失敗した。ジョブが失敗した場合に、テーブルに一部の行だけが書き込まれていないか不安がある。タスクの再試行について最も適切な理解と対応はどれですか。","o":["一部の行が書き込まれている可能性があるため、失敗した日付の行をテーブルから削除してから再試行する","再試行すると二重に書き込まれるので、タスクの retries を 0 にして、手動で状況を確認してから再実行する","ロードジョブは全件成功か全件不成立の原子的な処理なので、後始末なしでタスクをそのまま再試行する","書き込み済みの行数を数え、その行数を飛ばして残りだけを追記する再開用のロードジョブを作る"],"a":2,"e":"BigQuery のロードジョブは原子的で、失敗したジョブはテーブルに何も書き込みません。そのため、後始末をせずにタスクを再試行しても重複や欠落は生じません。失敗日の行を削除する処理は不要で、retries を 0 にすると自動復旧を失い、部分的な書き込みを前提とした再開用ジョブも不要です。","qEn":"A DAG's BigQuery load task appends a set of Cloud Storage files to a table. A brief network interruption made the load job fail, and the task failed. The team worries that only some rows may have been written to the table. What is the most appropriate understanding and response for retrying the task?","oEn":["Some rows may have been written, so delete the failed day's rows from the table before retrying","Retrying would write data twice, so set retries to 0 and rerun by hand after checking the situation","A load job is atomic and writes nothing when it fails, so the task can simply be retried with no cleanup","Count the rows already written and build a resume load job that skips them and appends only the remainder"],"eEn":"BigQuery load jobs are atomic, and a failed job writes nothing to the table, so retrying without cleanup causes neither duplicates nor gaps. Deleting the day's rows is unnecessary, setting retries to 0 loses automatic recovery, and a resume job built on partial writes is not needed."},{"id":"h197","d":"D3","q":"Cloud Data Fusion で、取り込みパイプライン A が成功した直後にだけ、変換パイプライン B を起動したい。A が失敗したときは B を実行しない。パイプラインの外に新しいスケジューラを用意したくない。最も適切な設定はどれですか。","o":["A と B を同じ時刻にスケジュールして並行して実行させ、B 側に A の結果を待つ処理を入れる","B を A の 30 分後にスケジュールして、A が終わる頃に走るようにしておく","A の成功時にも失敗時にも B を起動するトリガーを設定し、続行するかどうかは B の中で判定する","パイプライン B にトリガーを設定し、A の成功を条件として B を自動で起動する"],"a":3,"e":"Data Fusion のパイプライン間のトリガーは、あるパイプラインの完了状態 (成功など) を条件に別のパイプラインを自動で起動できるため、A が成功したときだけ B を実行できます。同時刻や 30 分後の固定のスケジュールは A の完了を保証せず、成功時と失敗時の両方で起動すると失敗時にも B が走ってしまいます。","qEn":"In Cloud Data Fusion, the team wants transformation pipeline B to start only right after ingestion pipeline A succeeds, and not to run if A fails. It does not want to set up a new scheduler outside the pipelines. Which setting is most appropriate?","oEn":["Schedule A and B at the same time, run them in parallel, and add logic in B that waits for A's result","Schedule B 30 minutes after A so that it runs around the time A is expected to finish","Set a trigger that starts B on both success and failure of A and let B decide whether to continue","Set a trigger on pipeline B that starts it automatically on the condition that A succeeds"],"eEn":"A Data Fusion trigger between pipelines starts one pipeline on another's completion state, such as success, so B runs only when A succeeds. Fixed schedules at the same time or 30 minutes later do not guarantee A has finished, and triggering on both outcomes would run B after a failure too."},{"id":"h198","d":"D3","q":"Cloud Data Fusion の取り込みパイプラインは毎晩 30 分だけ実行されるが、実行に使う既存の Managed Service for Apache Spark (旧 Dataproc) のクラスタが 24 時間稼働しており、費用が膨らんでいる。パイプラインの実行時だけ計算資源を使うようにしたい。最も適切な設定はどれですか。","o":["コンピュートプロファイルをエフェメラルにして、実行のたびにクラスタを作成・削除させる","既存のクラスタのワーカー数を最小の 1 台に固定して、24 時間稼働のまま費用を下げる","Data Fusion のインスタンスを毎晩の実行前に作成し、実行後に削除するスクリプトを組んで運用する","パイプラインのスケジュールを 1 時間ごとに変更し、稼働中のクラスタを有効に使い切るようにする"],"a":0,"e":"Data Fusion のエフェメラルなコンピュートプロファイルは、実行の開始時に Spark クラスタを作成して終了時に削除するため、30 分の実行分だけ課金されます。既存クラスタの 1 台化は稼働の無駄と性能の問題が残り、インスタンスの作成・削除は時間がかかり不適切で、頻度を増やすと無駄な実行が増えます。","qEn":"A Cloud Data Fusion ingestion pipeline runs for only 30 minutes each night, but the existing Managed Service for Apache Spark (formerly Dataproc) cluster it uses runs 24 hours a day, inflating costs. The team wants compute resources used only while the pipeline runs. Which setting is most appropriate?","oEn":["Make the compute profile ephemeral so a cluster is created for each run and deleted after it finishes","Fix the existing cluster at the minimum of one worker to cut cost while it keeps running 24 hours a day","Build a script that creates the Data Fusion instance before the nightly run and deletes it afterward","Change the pipeline schedule to hourly so that the running cluster is used up as fully as possible"],"eEn":"An ephemeral Data Fusion compute profile creates the Spark cluster at the start of a run and deletes it at the end, so only the 30 minutes are billed. A one-worker cluster still wastes uptime and risks performance, creating and deleting instances is slow and inappropriate, and running hourly adds wasted runs."},{"id":"h199","d":"D3","q":"毎晩、Spark ジョブでデータを抽出し、続けて Hive ジョブで集計する 2 段のバッチを、Managed Service for Apache Spark (旧 Dataproc) のクラスタで実行する。クラスタは処理中だけ存在させ、終了後は自動で削除したい。ジョブ間の依存を表現できれば十分で、Airflow のような汎用基盤は導入したくない。最も適切な方法はどれですか。","o":["ワークフローテンプレートで一時クラスタと 2 つのジョブの依存関係を定義し、Cloud Scheduler から起動する","常時稼働のクラスタを作り、2 つのジョブの投入時刻をずらして cron で順番に実行する","Managed Service for Apache Airflow の環境を新設し、クラスタの作成・削除を含む DAG を書く","処理を Dataflow のパイプラインに書き換えて、1 つのバッチジョブにまとめる"],"a":0,"e":"ワークフローテンプレートは、マネージドな一時クラスタの作成、ジョブ間の依存関係に沿った実行、完了後のクラスタ削除を 1 つの定義で行え、Cloud Scheduler から起動できます。常時稼働のクラスタと時刻ずらしの cron は費用と順序の保証に欠け、Airflow 環境の新設は汎用基盤の導入にあたり、Dataflow への書き換えは大きな移行です。","qEn":"Each night a two-stage batch, a Spark job that extracts data followed by a Hive job that aggregates it, runs on a Managed Service for Apache Spark (formerly Dataproc) cluster. The cluster should exist only during processing and be deleted automatically afterward. Expressing the dependency between the jobs is enough, and the team does not want to introduce a general platform like Airflow. Which method is most appropriate?","oEn":["Define the ephemeral cluster and the job dependency in a workflow template and start it from Cloud Scheduler","Create an always-on cluster and run the two jobs in order from cron by staggering their submission times","Set up a new Managed Service for Apache Airflow environment and write a DAG that includes creating and deleting the cluster","Rewrite the processing as a Dataflow pipeline and combine it into a single batch job"],"eEn":"A workflow template defines a managed ephemeral cluster, runs the jobs in dependency order, and deletes the cluster afterward, and Cloud Scheduler can start it. An always-on cluster with staggered cron lacks cost control and ordering guarantees, a new Airflow environment is a general platform, and rewriting for Dataflow is a large migration."},{"id":"h200","d":"D3","q":"Pub/Sub から読むストリーミングの Dataflow ジョブが、入力の急増で処理が追い付かなくなり、結果の反映が遅れることがある。ジョブ自体は失敗せず RUNNING のままのため、気づくのが遅い。処理の遅れを自動で検知して通知したい。最も適切な方法はどれですか。","o":["ジョブの状態が RUNNING 以外 (失敗や停止) になったときだけ通知するアラートを Cloud Monitoring に設定する","ワーカー VM の再起動回数が一定を超えたときに通知するアラートを設定して、異常の兆候を検知する","Dataflow のシステム遅延やデータ鮮度のメトリクスに、Cloud Monitoring のアラートを設定する","担当者が毎朝 Dataflow の画面でグラフを目視して、処理の遅れがないかどうかを確認する"],"a":2,"e":"ジョブは RUNNING のまま遅れるため、状態の監視では検知できません。システム遅延 (system lag) やデータの鮮度のメトリクスにしきい値を設けた Cloud Monitoring のアラートなら、処理の遅れを直接検知して通知できます。VM の再起動回数は遅れと対応せず、毎朝の目視は検知が遅れます。","qEn":"A streaming Dataflow job that reads from Pub/Sub sometimes cannot keep up with input surges, delaying results. Because the job does not fail and stays RUNNING, the delay is noticed late. The team wants to detect processing delay automatically and be notified. Which method is most appropriate?","oEn":["Set an alert that notifies only when the job state becomes something other than RUNNING, such as failed or stopped","Set an alert that notifies when the number of worker VM restarts exceeds a threshold, to catch signs of trouble","Set a Cloud Monitoring alert on Dataflow's system lag or data freshness metrics","Have staff look at the graphs on the Dataflow page every morning to check whether there are any delays"],"eEn":"The job stays RUNNING while falling behind, so state monitoring cannot detect it. Cloud Monitoring alerts with thresholds on system lag or data freshness directly detect processing delay. VM restart counts do not track lag, and a daily visual check detects it late."},{"id":"h201","d":"D3","q":"ストリーミングの Dataflow ジョブに、変換ロジックの軽微なバグ修正を適用したい。ジョブはウィンドウ集計の状態を保持しており、停止して新規ジョブを立てると状態と処理中のデータを失う。ダウンタイムとデータ欠落なしに修正版へ切り替えたい。最も適切な方法はどれですか。","o":["実行中のジョブをキャンセルして、修正版を新規のジョブとして起動し、再処理は行わないことにする","互換性のある変更として、update オプションで同じジョブ名に置き換える","実行中のジョブをドレインして完了させたうえで、修正版を新規のジョブとして起動し直す","新旧のジョブを同じサブスクリプションから同時に読ませ、新旧が安定したあとで旧ジョブを停止する"],"a":1,"e":"update オプションで互換性のある修正版に置き換えれば、実行中の状態を引き継いだまま、ダウンタイムとデータ欠落なしに切り替えられます。キャンセルは処理中のデータを失い、ドレインは未完了のウィンドウを早期に閉じて新規ジョブは状態を持たず、同じサブスクリプションからの同時読み取りはメッセージが新旧に分かれて集計が欠けます。","qEn":"The team wants to apply a minor bug fix in the transform logic of a streaming Dataflow job. The job holds window aggregation state, and stopping it and starting a new job would lose the state and in-flight data. It wants to switch to the fixed version without downtime or data loss. Which method is most appropriate?","oEn":["Cancel the running job and start the fixed version as a new job without reprocessing anything","Replace the job with the fixed pipeline under the same job name using the update option, as a compatible change","Drain the running job so that it completes, then start the fixed version again as a new job","Have the old and new jobs read from the same subscription at once and stop the old one after both have stabilized"],"eEn":"Replacing the job with a compatible fixed pipeline via the update option carries over running state and switches without downtime or data loss. Canceling loses in-flight data, draining closes unfinished windows early and a new job has no state, and reading the same subscription from both jobs splits messages between them so aggregates are incomplete."},{"id":"h202","d":"D3","q":"事業終了に伴い、ストリーミングの Dataflow ジョブを停止する。すでに Pub/Sub から受信してジョブ内にあるデータは、すべて処理して BigQuery に書き終えたい。新しい入力は取り込まなくてよい。最も適切な停止方法はどれですか。","o":["ジョブをキャンセルして、処理中のデータを破棄したうえで即座にジョブを停止させる","Pub/Sub のサブスクリプションを削除して、ジョブがそのまま自然に終了するのを待つ","ドレインして、新規の読み取りを止め、処理中のデータを完了させて終了する","ジョブのワーカー数を 0 に設定して、処理を一時停止の状態にしてデータを保持させる"],"a":2,"e":"ドレインは新規の読み取りを止め、すでに取り込んだデータの処理と書き込みを完了させてからジョブを終了するため、取りこぼしなく停止できます。キャンセルは処理中のデータを破棄します。サブスクリプションを削除してもストリーミングジョブは自然に終了せず、ワーカー数を 0 にする設定はできません。","qEn":"With the business ending, the team is stopping a streaming Dataflow job. Data already received from Pub/Sub and held in the job must be fully processed and written to BigQuery. New input need not be ingested. Which stopping method is most appropriate?","oEn":["Cancel the job so that the data in progress is discarded and it stops immediately","Delete the Pub/Sub subscription and wait for the job to finish on its own","Drain the job so it stops reading new input, finishes the data in progress, and then terminates","Set the job's worker count to 0 so that processing is put into a paused state that keeps the data"],"eEn":"Draining stops reading new input, completes processing and writing of data already taken in, and then ends the job, so nothing is lost. Cancel discards in-flight data, deleting the subscription does not make a streaming job end by itself, and a worker count of 0 cannot be set."},{"id":"h203","d":"D3","q":"取り込みサブスクライバのバグで、過去 6 時間分のメッセージが誤って処理され、ack されてしまった。バグは修正済みで、同じメッセージをもう一度処理し直したい。サブスクリプションは ack 済みメッセージを保持する設定になっており、パブリッシャへの再送依頼は避けたい。最も適切な方法はどれですか。","o":["サブスクリプションを問題発生前の時刻にシークし、ack 済みメッセージを再配信させる","サブスクリプションを削除して同じ名前で作り直し、トピックの過去のメッセージを先頭から再配信させる","ack 期限を最大に延長して、処理済みメッセージの再配信が自然に起きるのを待つ運用にする","デッドレタートピックの設定をやり直して、処理済みのメッセージが元のサブスクリプションへ戻るようにする"],"a":0,"e":"ack 済みメッセージを保持しているサブスクリプションを、問題発生前の時刻にシーク (seek) すると、その時点以降のメッセージが再配信され、パブリッシャへの再送依頼なしで再処理できます。作り直したサブスクリプションは新しいメッセージしか受け取らず、ack 期限の延長では ack 済みのものは戻らず、デッドレターは失敗した配信の退避先です。","qEn":"A bug in an ingestion subscriber caused the past six hours of messages to be processed wrongly and acked. The bug is fixed and the same messages must be processed again. The subscription is configured to retain acked messages, and the team wants to avoid asking publishers to resend. Which method is most appropriate?","oEn":["Seek the subscription to a time before the problem so the retained acked messages are redelivered","Delete the subscription and recreate it under the same name so past topic messages are redelivered from the start","Extend the ack deadline to the maximum and wait for redelivery of the processed messages to happen naturally","Reconfigure a dead-letter topic so that processed messages are returned to the original subscription"],"eEn":"Seeking a subscription that retains acked messages to a time before the problem redelivers messages from that point, so they can be reprocessed without asking publishers to resend. A recreated subscription receives only new messages, a longer ack deadline does not bring back acked messages, and dead-letter topics hold failed deliveries."},{"id":"h204","d":"D3","q":"新しく作成した Dataflow ジョブが、起動直後に「ワーカーがプロジェクトのリソースにアクセスできない」という権限エラーで失敗する。ジョブを起動した開発者本人は必要な権限を持っている。最も適切な解決方法はどれですか。","o":["開発者個人に Dataflow 管理者のロールを追加で付与して、同じ手順でジョブをもう一度起動する","ワーカーのサービスアカウントにプロジェクトのオーナーロールを付与して、すべての権限エラーを解消する","ワーカーのサービスアカウントに、Dataflow ワーカーロールと対象リソース用のロールを付与する","ジョブのリージョンを別のリージョンに変更して、同じパイプラインを再度起動してみる"],"a":2,"e":"Dataflow のワーカーは起動した開発者ではなく、ワーカーのサービスアカウントの権限で動くので、そのアカウントに Dataflow ワーカーロールと読み書き対象のリソースのロールを付与します。開発者個人への追加付与はワーカーの権限を変えず、オーナーロールは過大で、リージョンの変更は権限と無関係です。","qEn":"A newly created Dataflow job fails right after launch with a permission error saying workers cannot access project resources. The developer who launched the job has the necessary permissions. Which resolution is most appropriate?","oEn":["Grant the developer personally the Dataflow Admin role as well and launch the job again by the same procedure","Grant the Owner role on the project to the worker service account to clear every permission error","Grant the worker service account the Dataflow Worker role and roles on the resources it reads and writes","Change the job's region to a different region and try launching the same pipeline again"],"eEn":"Dataflow workers run with the worker service account's permissions, not the launching developer's, so that account needs the Dataflow Worker role and roles on the resources it reads and writes. Extra roles for the developer do not change worker permissions, Owner is excessive, and the region is unrelated to permissions."},{"id":"h205","d":"D3","q":"夜間バッチの Dataflow ジョブが、ワーカー数が多い日に IN_USE_ADDRESSES クォータの超過で起動できない。ワーカーはインターネットへ出る必要がなく、Google API とプライベートな VPC 内のリソースだけを使う。最も適切な対処はどれですか。","o":["ワーカー数の上限を 1 に固定して、外部 IP の使用数が常にクォータ内に収まるようにする","ジョブを起動するたびに、担当者が手動で外部 IP アドレスを追加で予約してから起動する","パイプラインを Cloud Run functions に書き換えて、Dataflow のワーカーを使わないようにする","ワーカーに外部 IP を割り当てない設定にして、サブネットで限定公開の Google アクセスを有効にする"],"a":3,"e":"外部 IP を持たないワーカーにすれば、IN_USE_ADDRESSES のクォータを消費せずに、サブネットの限定公開の Google アクセスで Google API へ接続できます。ワーカー数を 1 にすると処理が間に合わず、外部 IP の手動予約はクォータ自体を超え、関数への書き換えは大規模バッチに向きません。","qEn":"A nightly batch Dataflow job fails to start on days with many workers because it exceeds the IN_USE_ADDRESSES quota. The workers do not need internet access and use only Google APIs and resources inside the private VPC. Which action is most appropriate?","oEn":["Fix the maximum number of workers at 1 so that external IP usage always stays within the quota","Have staff reserve additional external IP addresses by hand before each job launch","Rewrite the pipeline as Cloud Run functions so that Dataflow workers are not used at all","Configure workers without external IPs and enable Private Google Access on the subnet"],"eEn":"Workers without external IPs do not consume the IN_USE_ADDRESSES quota and can still reach Google APIs through Private Google Access on the subnet. One worker cannot finish the batch in time, reserving more IPs by hand still hits the quota itself, and functions are unsuited to large batch jobs."},{"id":"h206","d":"D3","q":"夜間に多数のロードジョブとクエリが走る。朝、どのジョブが失敗し、どんなエラー理由だったかを SQL で一覧したい。追加のツールは導入したくない。最も適切な方法はどれですか。","o":["Cloud Logging のログビューアを開き、すべてのサービスのログから失敗の記録を手作業で探して書き出す","INFORMATION_SCHEMA.JOBS で error_result が NULL でない行を取り出す","INFORMATION_SCHEMA.COLUMNS を参照して、失敗したジョブが使った列の定義を確認する","Dataflow のジョブ一覧の画面を開いて、BigQuery のジョブの状態もまとめて確認する"],"a":1,"e":"INFORMATION_SCHEMA.JOBS にはジョブごとの状態とエラー情報が入っており、error_result が NULL でない行を時間範囲で絞って問い合わせれば、失敗したジョブとその理由を SQL で一覧できます。COLUMNS はテーブルの列定義の情報で、Dataflow の画面は BigQuery のジョブを網羅せず、ログの手作業の検索は SQL による一覧になりません。","qEn":"Many load jobs and queries run overnight. In the morning the team wants to list with SQL which jobs failed and why. It does not want to introduce additional tools. Which method is most appropriate?","oEn":["Open the Logs Explorer and manually search the logs of all services for failure records and write them out","Query INFORMATION_SCHEMA.JOBS, filtering on rows where error_result is not NULL and on a time range","Look at INFORMATION_SCHEMA.COLUMNS to check the column definitions used by the failed jobs","Open the Dataflow jobs list page and check the state of BigQuery jobs there as well"],"eEn":"INFORMATION_SCHEMA.JOBS holds each job's state and error information, so filtering rows with a non-NULL error_result by time range lists failed jobs and reasons in SQL. COLUMNS describes table columns, the Dataflow page does not cover BigQuery jobs, and manual log searches are not a SQL listing."},{"id":"h207","d":"D3","q":"毎朝 6:00 までに完了するはずの日次ロードがある。ロードが失敗した場合だけでなく、上流の遅れでジョブがそもそも実行されなかった場合も、7:00 までに成功の実績がなければ運用担当に知らせたい。最も適切なアラートの設計はどれですか。","o":["成功したロードのログベース指標を作り、指標の欠如 (absence) 条件でアラートを設定する","失敗したロードジョブのログベース指標が 1 件以上になったときにアラートを出すよう設定する","BigQuery のスロット使用率が 7:00 に一定の値を下回ったときにアラートを出すよう設定する","担当者が 7:00 にテーブルの行数を確認して、前日から増えていなければ連絡する運用にする"],"a":0,"e":"成功したロードジョブの指標が一定時間来ない状態を条件にした欠如のアラートなら、失敗だけでなく、実行されなかった場合も検知できます。失敗の指標は実行されない場合に何も出さず、スロット使用率は間接的で誤検知が多く、行数の手動確認は属人的で見落としやすい運用です。","qEn":"A daily load should complete by 6:00. Not only when the load fails, but also when the job never ran because of an upstream delay, the team wants to notify operations if there is no success record by 7:00. Which alert design is most appropriate?","oEn":["Create a log-based metric for successful loads and set an alert on the absence of that metric","Set an alert to fire when a log-based metric for failed load jobs reaches one or more","Set an alert to fire when BigQuery slot utilization at 7:00 falls below a certain value","Have staff check the table row count at 7:00 and report if it has not increased since the previous day"],"eEn":"An absence alert on the success metric fires when no success arrives in the window, detecting both failures and runs that never happened. A failure metric emits nothing when the job does not run, slot utilization is indirect and noisy, and manual row-count checks are person-dependent and easy to miss."},{"id":"h208","d":"D3","q":"Pub/Sub のサブスクリプションを読む下流の Cloud Run サービスが、デプロイ後に応答しなくなり、メッセージが ack されずに溜まる。サービスの死活監視は設定されているが、メッセージの滞留自体を検知してアラートを出したい。最も適切なメトリクスはどれですか。","o":["最も古い未 ack メッセージの経過時間 (oldest_unacked_message_age)","トピックに対するパブリッシュ操作の回数 (send_message_operation_count) の増加の度合い","トピックの課金対象になっているパブリッシュ済みバイト数の累計値","Cloud Run のコンテナインスタンスが使用しているメモリの使用率 (memory/utilizations)"],"a":0,"e":"最も古い未 ack メッセージの経過時間は、メッセージが ack されずに滞留すると増え続けるため、下流が止まったことを直接検知できます。パブリッシュ回数の増加は入力が増えただけでも起こり、パブリッシュ済みバイト数の累計は滞留の有無を示しません。Cloud Run のメモリ使用量は応答しない原因と一致するとは限りません。","qEn":"A downstream Cloud Run service that reads a Pub/Sub subscription stops responding after a deployment, and messages pile up unacked. Liveness monitoring of the service is configured, but the team wants an alert on the backlog itself. Which metric is most appropriate?","oEn":["The age of the oldest unacknowledged message in the subscription (oldest_unacked_message_age)","The degree of increase in the number of publish operations on the topic (send_message_operation_count)","The cumulative number of published bytes that are billed to the topic over the billing period","The memory utilization of the Cloud Run container instances (memory/utilizations)"],"eEn":"The age of the oldest unacked message keeps growing when messages pile up unacknowledged, directly detecting that the downstream has stalled. Rising publish counts can come from more input alone, cumulative published bytes show nothing about backlog, and Cloud Run memory use need not match the cause of the stall."},{"id":"h209","d":"D3","q":"テンプレートから起動した Dataflow のバッチジョブが、入力ファイルの 1 つの形式不備で失敗した。ファイルを修正したので、前回と同じパラメーターで、出力先だけ日付を変えて再実行したい。コンソールの操作で最も適切な方法はどれですか。","o":["失敗したジョブの画面で再開 (resume) を選び、失敗した地点から処理を続行させるようにする","ジョブを新規作成する画面で、テンプレートとすべてのパラメーターを最初から手作業で入力し直す","失敗したジョブを更新 (update) して、修正済みのファイルのパスに入力を差し替えるようにする","失敗したジョブをクローンして、パラメーターを引き継いだまま出力先だけを変更して、ジョブを起動し直す"],"a":3,"e":"Dataflow のコンソールには、既存のジョブをクローンして、同じテンプレートとパラメーターを引き継いだまま一部を変更して起動する機能があります。バッチジョブには失敗地点からの再開はなく、update はストリーミングジョブの置き換え用です。すべてを手作業で入力し直すのは、入力ミスを招く非効率な方法です。","qEn":"A batch Dataflow job launched from a template failed because of a format defect in one input file. The file has been fixed, and the team wants to rerun it with the same parameters but with only the output location changed to a new date. Which console operation is most appropriate?","oEn":["Choose resume on the failed job's page so that processing continues from the point of failure","Go to the create-job page and re-enter the template and every parameter by hand from scratch","Update the failed job so that its input is swapped over to the path of the corrected file","Clone the failed job, keep its parameters, change only the output location, and launch it"],"eEn":"The Dataflow console can clone an existing job, carrying over the template and parameters while letting you change some before launching. Batch jobs have no resume from the point of failure, update is for replacing streaming jobs, and re-entering everything by hand invites input mistakes."},{"id":"h210","d":"D2","q":"ログ分析チームの BigQuery には、日付列で日単位パーティション分割された約 40 TB のアクセスログテーブルがある。アナリストが日付条件を付け忘れたクエリを実行して全期間をスキャンし、オンデマンド課金が急増する事故が月に数回起きている。注意喚起ではなく仕組みで再発を防ぎたい。どう設定するのが最も適切か。","o":["テーブルに行レベルのアクセスポリシーを追加し、直近 1 日分の行だけが各アナリストに見えるようにする","クエリのたびに LIMIT 1000 を付けることを運用ルールとして定め、新人研修とクエリレビューで全員に徹底する","データセットの既定のテーブル有効期限を 1 日に設定し、古いパーティションが自動的に消えるようにする","require_partition_filter を TRUE にして、パーティション列での絞り込みを必須にさせる"],"a":3,"e":"require_partition_filter を TRUE にすると、パーティション列で絞り込まないクエリはエラーになり、全期間の誤スキャンを防げる。LIMIT はスキャン量を減らさず、行レベルポリシーは課金制御の機能ではなく、有効期限の短縮はデータ自体を消してしまう。","qEn":"A BigQuery access-log table of about 40 TB is partitioned daily on a date column. Several times a month an analyst forgets the date condition, scans every partition, and on-demand charges spike. The team wants to prevent this by mechanism rather than by reminders. What is the most appropriate setting?","oEn":["Add a row-level access policy to the table so that each analyst sees only the most recent day of rows","Make it an operating rule to append LIMIT 1000 to every query and enforce it for everyone through onboarding training and query review","Set the dataset default table expiration to one day so that old partitions disappear automatically","Set require_partition_filter to TRUE so queries must filter on the partition column"],"eEn":"With require_partition_filter set to TRUE, a query that does not filter on the partition column fails, which prevents accidental full scans. LIMIT does not reduce bytes scanned, row-level policies are not a cost control, and a short expiration deletes the data itself."},{"id":"h211","d":"D2","q":"EC サイトの購買イベントテーブル（約 8 億行、顧客数は数千万）で、分析クエリの大半が WHERE customer_id = ... で特定顧客の履歴を引いている。現在のテーブルは未分割で、毎回全件スキャンになっている。顧客 ID は取り得る値が非常に多く、日付での絞り込みはほとんど使われない。スキャン量を最も効果的に減らす設計はどれか。","o":["customer_id の値の範囲ごとに 1 つずつパーティションができるよう、整数範囲パーティションを細かく設定する","顧客ごとに別々のテーブルを作成し、クエリ側で顧客 ID に応じてテーブル名を切り替える","customer_id をクラスタリング列に指定したクラスタ化テーブルにする","customer_id に B-tree インデックスを作成して、行単位の検索に切り替える"],"a":2,"e":"取り得る値が非常に多い列での絞り込みにはクラスタリングが向き、不要なブロックを読み飛ばせる。細かすぎるパーティションは数の上限と管理負荷に突き当たり、顧客別テーブルは運用が破綻する。BigQuery に B-tree インデックスはない。","qEn":"Most analytical queries on an e-commerce purchase-event table (about 800 million rows, tens of millions of customers) use WHERE customer_id = ... to pull one customer's history. The table is unpartitioned, so every query scans it all. Customer IDs have very high cardinality and date filters are rarely used. Which design reduces bytes scanned most effectively?","oEn":["Configure integer-range partitioning so finely that each range of customer_id values gets its own partition","Create a separate table for each customer and switch the table name in the query by customer ID","Make it a clustered table with customer_id as the clustering column","Create a B-tree index on customer_id to switch to row-level lookups"],"eEn":"Clustering suits filters on very high-cardinality columns because it lets BigQuery skip irrelevant blocks. Overly fine partitions hit partition-count limits and add management cost, per-customer tables are unmanageable, and BigQuery has no B-tree indexes."},{"id":"h212","d":"D2","q":"売上テーブルは region（10 種類程度）、store_id（数千種類）の順にクラスタ化されている。新しく始まったレポートは region を指定せず store_id だけで絞り込むが、期待したほどスキャン量が減らない。クラスタリングの仕組みを踏まえ、最も適切な対応はどれか。","o":["絞り込みの多い store_id をクラスタリング列の先頭にして、テーブルを作り直す","クエリの WHERE 句で store_id の条件を先頭に書き直せば、保存順に関係なく読み飛ばしが効くようになる","region ごとにパーティション分割を追加し、各パーティション内で store_id の絞り込みを効かせる","クラスタリングを解除して日付パーティションだけの構成に戻し、スキャン範囲を日付で制限する"],"a":0,"e":"クラスタ化テーブルはクラスタリング列の指定順に並べ替えて保存されるため、先頭の列で絞り込むと最も効く。絞り込みの多い store_id を先頭にする。条件の書く順序は影響せず、文字列の region ではパーティション分割できず、クラスタ解除は逆効果。","qEn":"A sales table is clustered by region (about 10 values) and then store_id (thousands of values). A new report filters only on store_id without specifying region, and bytes scanned fall far less than expected. Given how clustering works, what is the most appropriate response?","oEn":["Rebuild the table with store_id, the most-filtered column, as the first clustering column","Rewrite the WHERE clause so the store_id condition comes first, which makes block skipping work regardless of storage order","Add partitioning by region so that the store_id filter works within each partition","Remove clustering and return to a date-partition-only layout, limiting the scan range by date"],"eEn":"A clustered table is stored sorted in the order of its clustering columns, so filtering on the leading column works best; put the most-filtered store_id first. The order of conditions in WHERE does not matter, a string region cannot be a partition column, and removing clustering is counterproductive."},{"id":"h213","d":"D2","q":"IoT 機器から届くセンサーデータを BigQuery に取り込んでいる。通信障害のため、イベント発生時刻から最大 3 日遅れて届くデータが頻繁にあり、ダッシュボードはイベント発生日を日付条件にして集計を表示する。パーティション設計として最も適切なものはどれか。","o":["取り込み時間パーティションにして、ダッシュボードでは取り込み日をイベント発生日の代わりに使う","取り込み日ごとに events_YYYYMMDD という名前のシャードテーブルを作り、ワイルドカードテーブルで参照する構成にする","イベント発生時刻の列で時間単位列パーティションにする","パーティションを設けずに 1 つの未分割テーブルへ追記し、WHERE でイベント発生日を絞り込む"],"a":2,"e":"絞り込みはイベント発生日なので、その列で列パーティションにすれば遅延到着分も正しい日に入り、日付条件でプルーニングが効く。取り込み時間パーティションは発生日とずれ、日付シャードは管理が煩雑で、未分割は毎回全件スキャンになる。","qEn":"Sensor data from IoT devices is loaded into BigQuery. Because of connectivity failures, records often arrive up to three days after the event time, and the dashboard filters by event date. Which partition design is most appropriate?","oEn":["Use ingestion-time partitioning and have the dashboard treat the ingestion date as the event date","Create events_YYYYMMDD sharded tables by ingestion date and query them with a wildcard","Use time-unit column partitioning on the event timestamp column","Append everything to a single unpartitioned table and filter on event date in WHERE"],"eEn":"Because dashboards filter by event date, partitioning on that column places late records in the correct day and lets date filters prune. Ingestion-time partitions drift from event dates, date shards are cumbersome, and an unpartitioned table is fully scanned every time."},{"id":"h214","d":"D2","q":"新人アナリストが巨大な未分割テーブルの中身を確認するために SELECT * FROM sales.fact_orders LIMIT 100 を実行し、予想外に高い課金が発生した。同様の中身確認を、課金なしで安全にできるようにしたい。最も適切な方法はどれか。","o":["LIMIT の値を 10 まで小さくすれば、スキャン量も LIMIT に比例して減るので、課金額もほぼ同じ割合で下がる","コンソールのテーブルプレビューや bq head でテーブルの行を確認する","SELECT * をやめて全列名を列挙すれば、列数に関係なく課金が発生しなくなる","クエリキャッシュを有効にしておけば、初回の実行でもスキャン課金は発生しない"],"a":1,"e":"テーブルプレビューや bq head はクエリを実行せず行を読むだけなので課金されない。非クラスタ化テーブルでは LIMIT を付けても対象列の全データがスキャンされ、列を列挙しても課金は消えない。キャッシュは同一クエリの再実行にしか効かない。","qEn":"A new analyst ran SELECT * FROM sales.fact_orders LIMIT 100 on a huge unpartitioned table just to look at its contents and was charged far more than expected. The team wants such content checks to be safe and free of charge. What is the most appropriate method?","oEn":["Reduce LIMIT to 10 so that bytes scanned fall in proportion to the limit, and therefore the charge falls by about the same ratio","Check rows with the console table preview or bq head","Stop using SELECT * and list every column name so that no charge is incurred regardless of column count","Keep the query cache enabled so that even the first execution incurs no scan charge"],"eEn":"Table preview and bq head read rows without running a query, so there is no charge. On a non-clustered table LIMIT still scans all data in the referenced columns, listing columns does not remove the charge, and the cache only helps repeated identical queries."},{"id":"h215","d":"D2","q":"データサイエンティストが 50 TB のログテーブルの分布を把握するため、試行的なクエリを数百回回したい。厳密さは不要で、おおまかな傾向が見えれば十分である。1 回あたりのスキャン量と課金を抑える最も適切な書き方はどれか。","o":["WHERE RAND() < 0.01 を条件に加えて、1% の行だけに絞り込む","ORDER BY RAND() LIMIT 100000 で無作為に行を取り出し、そのサンプルに対して調べる","先に GROUP BY で集計してから結果の行数を LIMIT で絞り込む","FROM 句でテーブルに TABLESAMPLE SYSTEM (1 PERCENT) を指定する"],"a":3,"e":"TABLESAMPLE SYSTEM はデータブロックの一部だけを読むので、スキャン量そのものが減る。WHERE RAND() や ORDER BY RAND() は全データを読んでから絞るためスキャン量は変わらず、GROUP BY と LIMIT も読み取り量を減らさない。","qEn":"A data scientist wants to run hundreds of exploratory queries against a 50 TB log table to understand its distribution. Precision is unnecessary; a rough trend is enough. Which way of writing the queries best reduces bytes scanned and cost per run?","oEn":["Add WHERE RAND() < 0.01 to narrow the data down to 1% of the rows before aggregating","Pull random rows with ORDER BY RAND() LIMIT 100000 and inspect them","Aggregate first with GROUP BY and then cut the result rows with LIMIT","Specify TABLESAMPLE SYSTEM (1 PERCENT) on the table in the FROM clause"],"eEn":"TABLESAMPLE SYSTEM reads only a subset of data blocks, so bytes scanned actually drop. WHERE RAND() and ORDER BY RAND() read everything before filtering, and neither GROUP BY nor LIMIT reduces the amount read."},{"id":"h216","d":"D2","q":"オンデマンド課金の BigQuery プロジェクトを全社で共有しており、誰かの誤ったクエリで月次予算が一晩で尽きることを懸念している。個々のクエリや利用者に上限をかけ、超過するクエリは実行前に拒否させたい。最も適切な制御はどれか。","o":["クエリの最大課金バイト数を設定し、プロジェクトとユーザーごとの日次クエリ使用量にカスタム割り当てを設ける","予算アラートのメール通知を設定し、超過の連絡を受けてから担当者が該当ユーザーのクエリを手動で調べて停止する","ジョブの優先度をバッチに変更すれば、スキャンが分散実行される結果として課金額に上限がかかるようになる","すべてのテーブルに require_partition_filter を設定すれば、全クエリの総額が一定以内に収まる"],"a":0,"e":"最大課金バイト数を超える見込みのクエリは課金されずに失敗し、カスタム割り当ては日次のクエリ量に上限をかける。予算アラートは通知だけで事前に止められず、バッチ優先度は課金額を制限せず、パーティションフィルタ必須化は総額を保証しない。","qEn":"A company shares one on-demand BigQuery project and worries that a single mistaken query could exhaust the monthly budget overnight. It wants limits per query and per user, with over-limit queries rejected before they run. Which control is most appropriate?","oEn":["Set a maximum bytes billed for queries and apply custom quotas on daily query usage per project and per user","Configure budget alert emails and have an operator manually investigate and stop the offending user's queries after being notified of an overrun","Change the job priority to batch, which caps the amount that can be billed because scanning is spread out over time","Set require_partition_filter on every table so that the total cost of all queries stays within a fixed amount"],"eEn":"A query expected to exceed the maximum bytes billed fails without being charged, and custom quotas cap daily query volume. Budget alerts only notify, batch priority does not limit cost, and forced partition filters do not guarantee a total."},{"id":"h217","d":"D2","q":"CDC で取り込んだ顧客テーブルには、更新のたびに同じ customer_id の行が追記され、updated_at が異なる履歴が複数残っている。アナリストは顧客ごとに最新の 1 行だけを、サブクエリを重ねずに簡潔な SQL で取得したい。最も適切な書き方はどれか。","o":["customer_id で GROUP BY し、updated_at を含むすべての列に MAX を適用して、顧客ごとの最大値だけを並べた 1 行にまとめる集計クエリを書く","QUALIFY ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY updated_at DESC) = 1","SELECT DISTINCT customer_id, updated_at を実行して重複する行を取り除く","クエリ全体の末尾に ORDER BY updated_at DESC LIMIT 1 を付けて最新の行を取り出す"],"a":1,"e":"QUALIFY は窓関数の結果で行を絞れ、ROW_NUMBER で顧客ごとに最新の行だけを残せる。列ごとの MAX は別々の行の値を混ぜてしまい、DISTINCT は履歴の行を残し、全体への LIMIT 1 は 1 顧客分しか返さない。","qEn":"A customer table loaded through CDC appends a row with the same customer_id on each update, leaving several history rows with different updated_at values. An analyst wants only the latest row per customer, in concise SQL without stacked subqueries. Which is the most appropriate approach?","oEn":["Group by customer_id and apply MAX to every column other than updated_at to collapse each customer to one row","QUALIFY ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY updated_at DESC) = 1","Run SELECT DISTINCT customer_id, updated_at to remove the duplicate rows","Append ORDER BY updated_at DESC LIMIT 1 to the whole query to retrieve the latest row"],"eEn":"QUALIFY filters on window-function results, and ROW_NUMBER keeps only the latest row per customer. Column-wise MAX mixes values from different rows, DISTINCT keeps the history rows, and a global LIMIT 1 returns just one customer."},{"id":"h218","d":"D2","q":"注文テーブルの line_items 列は ARRAY<STRUCT<sku STRING, qty INT64, unit_price NUMERIC>> 型で、1 注文に複数の明細が入っている。SKU ごとの売上金額（qty × unit_price）を集計したい。最も適切な SQL の書き方はどれか。","o":["SUM(line_items.qty * line_items.unit_price) のように、配列の列からフィールドを直接参照して SKU ごとに集計し、UNNEST による展開のための構文を省いて簡潔に書く","TO_JSON_STRING で line_items を文字列にし、正規表現で数量と単価を取り出して計算する","ARRAY_LENGTH(line_items) を SKU ごとに合計し、その件数に平均単価を掛けた値を売上金額として扱う","UNNEST(line_items) AS item で明細を行に展開し、item.sku で GROUP BY して SUM(item.qty * item.unit_price) を求める"],"a":3,"e":"配列は UNNEST で行に展開すると、要素の STRUCT フィールドを通常の列として GROUP BY や SUM に使える。配列への直接のフィールド参照はエラーになり、JSON 文字列化と正規表現は非効率で壊れやすく、ARRAY_LENGTH は件数であって金額にならない。","qEn":"The line_items column of an orders table is ARRAY<STRUCT<sku STRING, qty INT64, unit_price NUMERIC>>, holding several lines per order. You need revenue (qty x unit_price) per SKU. Which SQL approach is most appropriate?","oEn":["Aggregate with SUM(line_items.qty * line_items.unit_price), referencing fields directly on the array column","Convert line_items to a string with TO_JSON_STRING and extract quantity and price with regular expressions","Sum ARRAY_LENGTH(line_items) per SKU and multiply that count by an average unit price to treat it as the revenue amount","Flatten with UNNEST(line_items) AS item, then GROUP BY item.sku and compute SUM(item.qty * item.unit_price)"],"eEn":"UNNEST turns array elements into rows so their STRUCT fields can be used in GROUP BY and SUM. Referencing fields directly on an array errors out, JSON-string parsing is inefficient and brittle, and ARRAY_LENGTH is a count, not an amount."},{"id":"h219","d":"D2","q":"請求システムのデータを BigQuery に移行する。請求書（約 2 億件）と明細行（1 請求書あたり平均 6 行）は常に一緒に参照され、請求書単位でも明細単位でも集計される。結合に伴うシャッフルを減らし、分析クエリを速くしたい。最も適切なスキーマ設計はどれか。","o":["請求書と明細を第三正規形の別テーブルに分け、分析のたびに請求書 ID で結合し、必要な列だけを取り出して使う方式を採用する","明細の全項目を JSON 文字列にまとめた STRING 型の列を 1 つ作って保存する","請求書テーブルに明細を ARRAY<STRUCT> の繰り返しフィールドとして入れ子にして持たせる","請求書と明細を日付ごとのシャードテーブルに分けて、日別に保存する"],"a":2,"e":"常に一緒に参照する親子データは、入れ子の繰り返しフィールドにすると結合が不要になりシャッフルが減る。正規化は毎回結合のコストがかかり、JSON 文字列は型と列単位の読み取りの利点を失い、日付シャードは結合の問題を解決しない。","qEn":"Billing data is being migrated to BigQuery. Invoices (about 200 million) and line items (about 6 per invoice) are always read together and aggregated at both the invoice and line level. The goal is to cut join shuffles and speed up analysis. Which schema design is most appropriate?","oEn":["Split invoices and lines into separate third-normal-form tables and join them on invoice ID for every analysis","Store all line fields as one JSON string in a single STRING column","Nest the line items inside the invoice table as an ARRAY<STRUCT> repeated field","Split invoices and lines into per-date sharded tables and store them by day"],"eEn":"Parent-child data read together is best nested in a repeated field, which removes the join and its shuffle. Normalization pays for a join every time, JSON strings lose typing and column-level reads, and date shards do not address the join."},{"id":"h220","d":"D2","q":"営業レポートでは、地域・都道府県・店舗の売上を、各階層の小計と総合計も含めて 1 つの結果表に出す必要がある。いまは階層ごとの GROUP BY クエリ 4 本を UNION ALL しており、テーブルを 4 回スキャンしている。1 回のスキャンで同じ結果を得る最も適切な書き方はどれか。","o":["SUM(sales) OVER (PARTITION BY region, prefecture, store) の窓関数を使って、各階層の合計を行に付ける","GROUP BY 1, 2, 3 WITH TOTALS と書いて、階層ごとの小計と総合計の行を自動で追加させる","HAVING 句に小計の条件を書いて、集計後に小計の行だけを取り出す","GROUP BY ROLLUP(region, prefecture, store) を使う"],"a":3,"e":"ROLLUP は指定した列の階層に沿って、小計と総合計の行を 1 回のスキャンで生成する。窓関数は行を折りたたまず小計行を作れず、HAVING は集計後の絞り込みで小計を生まず、WITH TOTALS は BigQuery の構文ではない。","qEn":"A sales report must show revenue by region, prefecture, and store in one result table, including subtotals at each level and a grand total. It currently UNION ALLs four GROUP BY queries and scans the table four times. Which is the most appropriate way to get the same result in one scan?","oEn":["Use the window function SUM(sales) OVER (PARTITION BY region, prefecture, store) to attach each level's total to the rows","Write GROUP BY 1, 2, 3 WITH TOTALS to have subtotal rows for each level and a grand-total row added automatically","Write the subtotal condition in a HAVING clause and extract only the subtotal rows after aggregation","Use GROUP BY ROLLUP(region, prefecture, store)"],"eEn":"ROLLUP generates subtotal and grand-total rows along the listed column hierarchy in a single scan. Window functions do not collapse rows or create subtotal rows, HAVING only filters after aggregation, and WITH TOTALS is not BigQuery syntax."},{"id":"h221","d":"D2","q":"日次売上テーブルには、店舗の休業日の行が存在しない（売上 0 の日は行自体がない）。担当者は 7 日間移動平均を作るため AVG(sales) OVER (ORDER BY day ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) を使ったが、休業日をまたぐと実際の 7 日間より長い期間が対象になってしまう。正しい 7 日間にする最も適切な修正はどれか。","o":["ROWS を RANGE に書き換えるだけで、日付の欠けた日が自動的に補われて 7 日間の窓になる","窓の範囲を 6 PRECEDING から 10 PRECEDING に広げて、休業日が挟まる分を見込んだ長めの期間で平均を取り、期間のずれを吸収させる","GENERATE_DATE_ARRAY で連続した日付表を作り、売上を LEFT JOIN して欠けた日を 0 で補ってから同じ窓関数を改めて適用する","AVG(sales) をやめて、窓の範囲内の売上合計を固定値 7 で割る式に置き換える"],"a":2,"e":"ROWS は物理的な行数で窓を決めるため、日付が欠けると 7 日を超える期間になる。連続した日付表に LEFT JOIN して欠けた日を 0 にすれば、6 行前までがちょうど 7 日になる。RANGE への変更は欠損を補わず、幅の拡大や 7 での除算も期間のずれを直さない。","qEn":"A daily sales table has no row for days when the store is closed (zero-sales days have no row at all). An analyst built a 7-day moving average with AVG(sales) OVER (ORDER BY day ROWS BETWEEN 6 PRECEDING AND CURRENT ROW), but around closures the window covers more than seven calendar days. What is the most appropriate fix?","oEn":["Just rewrite ROWS as RANGE, which automatically fills the missing dates in the ordering column and therefore yields an exact 7-day calendar window","Widen the window from 6 PRECEDING to 10 PRECEDING to allow for the closed days when averaging","Build a continuous calendar with GENERATE_DATE_ARRAY, LEFT JOIN the sales, fill missing days with 0, and then apply the same window function","Drop AVG(sales) and divide the window's sales total by a fixed 7 instead"],"eEn":"ROWS counts physical rows, so missing dates stretch the window past seven days. Joining to a continuous calendar and filling gaps with 0 makes six rows back exactly seven days. RANGE does not fill gaps, and widening or dividing by 7 does not fix the span."},{"id":"h222","d":"D2","q":"商品別の月間売上ランキングで、売上額の上位 3 段階までの全商品を抽出したい。同額の商品は同順位とし、次の順位は欠番にせず連続させる（たとえば 1 位が 2 商品なら、次は 2 位）。QUALIFY 句で使う関数として最も適切なものはどれか。","o":["DENSE_RANK() OVER (ORDER BY sales DESC) <= 3","ROW_NUMBER() OVER (ORDER BY sales DESC) <= 3 と書いて、行番号が 3 以下の商品を残す","RANK() OVER (ORDER BY sales DESC) <= 3 と書いて、順位が 3 以下の商品を残す","NTILE(3) OVER (ORDER BY sales DESC) = 1 と書いて、先頭の等分割グループだけを残す"],"a":0,"e":"DENSE_RANK は同順位の次を欠番にせず連続した順位を付けるので、上位 3 段階の全商品を取れる。ROW_NUMBER は同額を恣意的に順序付け、RANK は同順位の後に欠番ができて 3 以下では 3 段階に届かず、NTILE は順位ではなく等分割である。","qEn":"For monthly product sales ranking, you want every product in the top three revenue tiers. Products with equal revenue share a rank, and the next rank continues without a gap (for example, if two products tie for 1st, the next is 2nd). Which function is most appropriate in the QUALIFY clause?","oEn":["DENSE_RANK() OVER (ORDER BY sales DESC) <= 3","ROW_NUMBER() OVER (ORDER BY sales DESC) <= 3, keeping the products whose row number is 3 or less","RANK() OVER (ORDER BY sales DESC) <= 3, keeping the products whose rank is 3 or less","NTILE(3) OVER (ORDER BY sales DESC) = 1, keeping only the first of three equal-sized groups"],"eEn":"DENSE_RANK assigns consecutive ranks with no gaps after ties, so it captures all products in the top three tiers. ROW_NUMBER orders ties arbitrarily, RANK leaves gaps so <= 3 falls short of three tiers, and NTILE splits into equal groups rather than ranking."},{"id":"h223","d":"D2","q":"CRM チームは顧客を直近 1 年の購入金額で 10 等分し、上位 10%（第 1 十分位）の顧客にだけ特別なキャンペーンを送りたい。各顧客がどの十分位に属するかを、BigQuery の 1 本のクエリで付与する最も適切な方法はどれか。","o":["PERCENTILE_CONT(total_spend, 0.9) を集計関数として GROUP BY customer_id と一緒に使い、境界値で分ける","NTILE(10) OVER (ORDER BY total_spend DESC) で十分位の番号を付ける","RANK() OVER (ORDER BY total_spend DESC) の値を 10 で割った商を、そのまま十分位の番号とみなす","APPROX_TOP_COUNT(customer_id, 10) で購入金額の上位 10 件を取り出し、それを十分位とする"],"a":1,"e":"NTILE(n) は並べ替えた行を n 個のほぼ等しい大きさのグループに分けて番号を付ける。RANK の商は 10 件ごとの区切りになるだけで十分位にならず、PERCENTILE_CONT は境界値を返す関数、APPROX_TOP_COUNT は頻出値の抽出で、各顧客への番号付与ではない。","qEn":"A CRM team wants to split customers into ten equal groups by spend over the past year and send a special campaign only to the top 10 percent (first decile). What is the most appropriate way to assign each customer's decile in a single BigQuery query?","oEn":["Use PERCENTILE_CONT(total_spend, 0.9) as an aggregate with GROUP BY customer_id and split on that boundary value","Assign decile numbers with NTILE(10) OVER (ORDER BY total_spend DESC)","Divide the value of RANK() OVER (ORDER BY total_spend DESC) by 10 and treat the quotient as the decile number","Extract the top 10 entries with APPROX_TOP_COUNT(customer_id, 10) and treat them as the decile"],"eEn":"NTILE(n) sorts rows into n nearly equal groups and numbers them. Dividing RANK by 10 just cuts every 10 rows, PERCENTILE_CONT returns a boundary value, and APPROX_TOP_COUNT extracts frequent values; none of them labels each customer."},{"id":"h224","d":"D2","q":"広告配信ログ（約 300 億行）の応答時間について、日次ダッシュボードに中央値と p95 を表示したい。完全に厳密な値は不要で、クエリ時間と処理コストを抑えたい。最も適切な方法はどれか。","o":["ORDER BY latency_ms で全行を並べ替え、行数の 50% と 95% の位置にある値を LIMIT と OFFSET で取得する","AVG(latency_ms) と STDDEV(latency_ms) から正規分布を仮定して p95 を計算式で推定し、その値を表示する","COUNT(DISTINCT latency_ms) の値を分位点の目安として使い、そこから中央値と p95 を割り出す","APPROX_QUANTILES(latency_ms, 100) の結果から OFFSET(50) と OFFSET(95) を取り出す"],"a":3,"e":"APPROX_QUANTILES は近似アルゴリズムで少ないメモリと処理量で分位点を求め、OFFSET で中央値や p95 を取り出せる。全行の並べ替えは巨大データでは重く、平均と標準偏差からの推定は分布が歪むと大きく外れ、COUNT(DISTINCT) は分位点と無関係である。","qEn":"A daily dashboard needs the median and p95 of response time from ad-serving logs of about 30 billion rows. Exact values are not required, and query time and processing cost should stay low. Which approach is most appropriate?","oEn":["Sort all rows with ORDER BY latency_ms and fetch the values at the 50% and 95% row positions using LIMIT and OFFSET","Assume a normal distribution and estimate p95 by a formula from AVG(latency_ms) and STDDEV(latency_ms), then display it","Use the value of COUNT(DISTINCT latency_ms) as a guide to quantiles and derive the median and p95 from it","Take OFFSET(50) and OFFSET(95) from the result of APPROX_QUANTILES(latency_ms, 100)"],"eEn":"APPROX_QUANTILES uses an approximate algorithm that needs little memory and work, and OFFSET extracts the median and p95. A full sort is heavy at this scale, mean-and-stddev estimates miss badly on skewed data, and COUNT(DISTINCT) is unrelated to quantiles."},{"id":"h225","d":"D2","q":"マーケティング担当が『一度も注文していない顧客』を調べるため SELECT * FROM customers WHERE customer_id NOT IN (SELECT customer_id FROM orders) を実行したところ、未購入の顧客が確実にいるのに結果が 0 行になった。orders.customer_id には NULL の行が混ざっている。原因を踏まえた最も適切な修正はどれか。","o":["サブクエリ側に DISTINCT を付けて重複を除けば、NULL が含まれていても NOT IN が正しく評価される","customers テーブルの customer_id 列も NULL を許容する列に変更し、両側の条件をそろえる","NOT EXISTS の相関サブクエリ（または LEFT JOIN と IS NULL の判定）に書き換える","NOT IN を IN に変更し、得られた顧客を全顧客の一覧から後で手作業で差し引いて未購入者を求める"],"a":2,"e":"NOT IN は右辺に NULL が 1 つでもあると比較結果が UNKNOWN になり、全行が除外される。NOT EXISTS や LEFT JOIN の IS NULL 判定は NULL の影響を受けない。DISTINCT では NULL が残り、顧客側を NULL 許容にしても解決せず、IN への変更は手作業が増えるだけである。","qEn":"To find customers who have never ordered, a marketer ran SELECT * FROM customers WHERE customer_id NOT IN (SELECT customer_id FROM orders). Although non-buyers certainly exist, zero rows came back. orders.customer_id contains NULL rows. What is the most appropriate fix given the cause?","oEn":["Add DISTINCT to the subquery so that NOT IN is evaluated correctly even when NULLs are present","Change customers.customer_id to a nullable column as well so that the conditions on both sides match","Rewrite it with a correlated NOT EXISTS subquery (or a LEFT JOIN with an IS NULL test)","Change NOT IN to IN and then subtract the resulting customers by hand from the full customer list to obtain non-buyers"],"eEn":"If the right-hand side of NOT IN contains even one NULL, the comparison becomes UNKNOWN and every row is excluded. NOT EXISTS and LEFT JOIN with IS NULL are unaffected by NULLs. DISTINCT keeps the NULL, a nullable customer column does not help, and switching to IN just adds manual work."},{"id":"h226","d":"D2","q":"アプリのエラーログを格納した BigQuery テーブル（数十億行）で、特定のリクエスト ID 文字列を含む行を探す調査クエリが、毎回全件スキャンになり時間もコストもかかっている。LIKE '%...%' の部分一致を使っているが、SEARCH 関数で高速に絞り込みたい。そのために最も適切な準備はどれか。","o":["対象列にクラスタリングを設定して、クエリは LIKE '%...%' の部分一致のままで実行する","LIKE の結果をあらかじめ集計するマテリアライズドビューを作成して、調査はそのビューに対して行う","対象のテキスト列に検索インデックスを作成し、SEARCH 関数で検索する","BI Engine の予約容量を増やし、メモリ上で高速に部分一致の走査ができるようにする"],"a":2,"e":"検索インデックスはテキストを語単位で索引化し、SEARCH 関数での絞り込み時に読むデータを減らす。クラスタリングは部分一致の LIKE ではほとんど効かず、マテリアライズドビューは任意の文字列検索を事前計算できず、BI Engine はインデックスの代わりにならない。","qEn":"On a BigQuery error-log table of billions of rows, an investigation query looking for a specific request-ID string scans everything every time, which is slow and costly. It uses LIKE '%...%' substring matching, and the team wants to narrow rows quickly with the SEARCH function. What is the most appropriate preparation?","oEn":["Set clustering on the target column and keep running the query with LIKE '%...%' substring matching","Create a materialized view that precomputes the results of LIKE and run the investigations against that view","Create a search index on the target text columns and query with the SEARCH function","Increase the BI Engine reservation so that substring matching can be scanned quickly in memory"],"eEn":"A search index tokenizes text so that SEARCH reads far less data. Clustering barely helps substring LIKE, a materialized view cannot precompute arbitrary string searches, and BI Engine is not a substitute for an index."},{"id":"h227","d":"D2","q":"今月の BigQuery 料金（オンデマンド）が前月の 3 倍になった。管理者は、過去 30 日間にどのユーザーのどのクエリが多くの課金バイトを消費したかを集計して、原因を特定したい。追加のツールを導入せずにできる、最も適切な調査方法はどれか。","o":["INFORMATION_SCHEMA.JOBS をユーザーとクエリごとに total_bytes_billed で集計する","INFORMATION_SCHEMA.TABLE_STORAGE を参照し、テーブルごとの保存容量が増えたかどうかから原因を推定する","Cloud Monitoring のダッシュボードでスロット使用率のグラフを確認し、ピークの時間帯から原因を探す","Dataplex のデータ品質スキャンの結果を開いて、クエリ別のコストの内訳を確認する"],"a":0,"e":"INFORMATION_SCHEMA.JOBS にはジョブごとのユーザー・クエリ文・課金バイト数が記録され、SQL で集計すれば原因のクエリと利用者を特定できる。TABLE_STORAGE は保存容量の情報で、スロット使用率はオンデマンド課金の内訳を示さず、データ品質スキャンはクエリコストを持たない。","qEn":"This month's on-demand BigQuery bill is three times last month's. An administrator wants to aggregate which users' queries consumed the most billed bytes over the last 30 days to find the cause, without adding tools. What is the most appropriate investigation method?","oEn":["Aggregate INFORMATION_SCHEMA.JOBS by user and query on total_bytes_billed","Look at INFORMATION_SCHEMA.TABLE_STORAGE and infer the cause from whether each table's stored size has grown","Check the slot-utilization graphs in a Cloud Monitoring dashboard and look for the cause in the peak time windows","Open the Dataplex data quality scan results and check the cost breakdown per query"],"eEn":"INFORMATION_SCHEMA.JOBS records the user, query text, and billed bytes per job, so aggregating it pinpoints the costly queries and users. TABLE_STORAGE describes storage, slot utilization does not break down on-demand charges, and data quality scans hold no query cost."},{"id":"h228","d":"D2","q":"夜間バッチの BigQuery クエリが、データ量は以前と変わらないのに 3 倍遅くなった。結合キーの特定の値（たとえば customer_id が NULL の行）に大量の行が集中しているのではないかと疑われる。原因を調べる最も適切な手段はどれか。","o":["同じクエリを再実行し、キャッシュされた結果が返ってくるかどうかを確認してから、遅延の傾向を判断する","クエリ実行グラフでステージごとの平均と最大のスロット時間を比べ、偏りのあるステージを探す","テーブルのパーティション有効期限の設定を確認し、期限切れで消えた行がないかを調べる","ジョブの優先度をインタラクティブからバッチに切り替え、実行時間にどれだけ差が出るかを比べる"],"a":1,"e":"実行グラフはステージごとに待機・読み取り・計算・書き込みの時間を示し、平均と最大の差が大きければデータの偏り（スキュー）を示す。キャッシュの確認や有効期限の確認は遅延の原因調査にならず、優先度の切り替えも原因を特定する手段ではない。","qEn":"A nightly BigQuery batch query has become three times slower even though data volume is unchanged. The team suspects that a huge number of rows have piled up on one join-key value (for example, rows where customer_id is NULL). What is the most appropriate way to investigate?","oEn":["Re-run the same query and check whether a cached result is returned, then judge the slowdown trend from that","Use the query execution graph to compare average and maximum slot time per stage and find the skewed stage","Check the table's partition expiration setting and look for rows that disappeared after expiring","Switch the job priority from interactive to batch and compare how much the run time changes"],"eEn":"The execution graph shows wait, read, compute, and write time per stage, and a large gap between average and maximum indicates data skew. Checking the cache or expiration does not diagnose slowness, and changing priority does not identify the cause."},{"id":"h229","d":"D2","q":"過去の運用で、日付ごとに作られた events_20250101 形式のシャードテーブルが 400 本残っている。直近 7 日分だけを集計するクエリを、全シャードを読まずに書きたい。ワイルドカードテーブルを使う場合、最も適切な書き方はどれか。","o":["FROM `proj.ds.events_*` とし、WHERE _TABLE_SUFFIX BETWEEN で直近 7 日の日付範囲を指定する","FROM `proj.ds.events_*` と書き、WHERE 句で event_date という通常の列を直近 7 日に絞り込む","FROM `proj.ds.events_2026*` のようにプレフィックスだけを書けば、BigQuery が最新 7 日分に自動で限定してくれると期待する","FROM `proj.ds.events_*$20260301` のようにパーティションデコレータを付けて、日付の範囲を指定する"],"a":0,"e":"ワイルドカードテーブルでは、疑似列 _TABLE_SUFFIX の条件で読むテーブルが決まる。通常の列への条件は全シャードを読んだうえで効くため課金は減らず、プレフィックスだけでは自動で絞られず、パーティションデコレータはワイルドカード名とは併用できない。","qEn":"Past operations left 400 date-sharded tables named like events_20250101. You want a query that aggregates only the last seven days without reading every shard. Using a wildcard table, which is the most appropriate way to write it?","oEn":["Use FROM `proj.ds.events_*` and specify the last seven days in WHERE _TABLE_SUFFIX BETWEEN","Use FROM `proj.ds.events_*` and narrow a regular column named event_date to the last seven days in WHERE","Write only a prefix such as FROM `proj.ds.events_2026*` and let BigQuery automatically limit it to the latest seven days","Attach a partition decorator such as FROM `proj.ds.events_*$20260301` to specify the date range"],"eEn":"With wildcard tables, a condition on the _TABLE_SUFFIX pseudo-column decides which tables are read. A condition on a regular column applies after reading every shard, so cost does not fall; a prefix alone does not narrow automatically; and partition decorators cannot be combined with wildcard names."},{"id":"h230","d":"D2","q":"週次売上レポートを DATE_TRUNC(order_date, WEEK) で集計したところ、週の開始日が日曜になり、月曜始まりの社内カレンダーと週の区切りがずれてしまった。月曜始まりの週で正しく集計し直す、最も適切な修正はどれか。","o":["DATE_TRUNC(order_date, WEEK) のまま集計し、結果の週開始日に 1 日を足して表示だけ月曜にそろえる","DATE_TRUNC(order_date, WEEK(MONDAY)) に変更する","FORMAT_DATE('%U', order_date) が返す週番号で GROUP BY し、月曜始まりの週として扱う","クエリを実行するセッションのタイムゾーンを Asia/Tokyo に設定してから集計する"],"a":1,"e":"DATE_TRUNC の WEEK は既定で日曜始まりなので、WEEK(MONDAY) のように開始曜日を指定する。表示だけ 1 日ずらしても集計の境界は日曜のままで、%U は日曜始まりの週番号であり、タイムゾーンの設定は週の開始曜日を変えない。","qEn":"A weekly sales report aggregated with DATE_TRUNC(order_date, WEEK) starts weeks on Sunday, so its week boundaries differ from the company's Monday-start calendar. What is the most appropriate fix to aggregate correctly by Monday-start weeks?","oEn":["Aggregate with DATE_TRUNC(order_date, WEEK) as is and add one day to the resulting week start so only the display shows Monday","Change it to DATE_TRUNC(order_date, WEEK(MONDAY))","Group by the week number returned by FORMAT_DATE('%U', order_date) and treat it as Monday-start weeks","Set the time zone of the querying session to Asia/Tokyo before aggregating"],"eEn":"WEEK in DATE_TRUNC defaults to Sunday starts, so specify the start day as in WEEK(MONDAY). Shifting only the display leaves Sunday boundaries, %U is a Sunday-based week number, and a time zone setting does not change the week start."},{"id":"h231","d":"D2","q":"BigQuery の events テーブルのイベント時刻は TIMESTAMP 型（UTC で保持）である。日本の営業日（JST）単位の日次売上を DATE(event_ts) で集計したところ、午前 0 時から 9 時までの売上が前日に計上され、現場の数字と合わない。最も適切な修正はどれか。","o":["event_ts 列の型を DATETIME に変更すれば、自動的に日本時間の値として保存し直される","BigQuery のプロジェクト設定でタイムゾーンを Asia/Tokyo に変更し、以後のクエリ結果を日本時間にする","DATE(event_ts, 'Asia/Tokyo') で JST の日付に変換してから集計する","ETL で event_ts に 9 時間を足した値を TIMESTAMP 列へ上書き保存して、以後はその列を DATE() で集計する"],"a":2,"e":"TIMESTAMP は UTC で保持され、DATE() のタイムゾーン引数に Asia/Tokyo を渡すと JST の暦日に変換できる。列を DATETIME に変えても値は変わらず、プロジェクト単位のタイムゾーン設定はなく、9 時間を足して上書きすると保存値が壊れて他の分析も誤る。","qEn":"The event time in a BigQuery events table is a TIMESTAMP (held in UTC). Daily sales by Japanese business day (JST) aggregated with DATE(event_ts) put sales from midnight to 9 a.m. on the previous day, so the figures do not match the stores. What is the most appropriate fix?","oEn":["Change the event_ts column type to DATETIME so that values are automatically re-stored as Japan time","Change the time zone in the BigQuery project settings to Asia/Tokyo so that later query results are in Japan time","Convert to JST dates with DATE(event_ts, 'Asia/Tokyo') before aggregating","Have the ETL overwrite the TIMESTAMP column with event_ts plus nine hours and aggregate that column with DATE() from then on"],"eEn":"A TIMESTAMP is held in UTC, and passing Asia/Tokyo as the time zone argument of DATE() converts to the JST calendar day. Changing the type to DATETIME does not alter values, there is no project-level time zone setting, and overwriting with +9 hours corrupts stored values and other analyses."},{"id":"h232","d":"D2","q":"ログテーブルの payload 列は JSON 型で、{\"user\": {\"id\": \"u123\", \"plan\": \"pro\"}, \"latency\": 120} のような、レコードごとに構造が変わりうるデータが入っている。アナリストは plan ごとの平均 latency を SQL で集計したい。最も適切な書き方はどれか。","o":["payload を SPLIT で区切り文字ごとに分割し、配列の添字で plan と latency の位置の値を取り出す","JSON_VALUE(payload, '$.user.plan') で GROUP BY し、latency を CAST して AVG を求める","payload を TO_JSON_STRING で文字列に戻したうえで、LIKE '%pro%' に一致する行を plan が pro のレコードとして数える","取り込み時にすべてのキーを個別の列へ平坦化しない限り、BigQuery では JSON の値を集計に使えない"],"a":1,"e":"JSON 型の列は、JSON_VALUE などの JSON 関数でパスを指定して値を取り出せ、CAST すれば数値として集計できる。SPLIT の添字指定や LIKE の文字列判定は構造が変わると壊れ、BigQuery は事前に平坦化しなくても JSON を直接扱える。","qEn":"The payload column of a log table is of JSON type and holds data whose structure can vary per record, such as {\"user\": {\"id\": \"u123\", \"plan\": \"pro\"}, \"latency\": 120}. An analyst wants average latency per plan in SQL. Which approach is most appropriate?","oEn":["Split payload on delimiters with SPLIT and pick the plan and latency values by array position","GROUP BY JSON_VALUE(payload, '$.user.plan') and compute AVG over the CAST latency","Convert payload back to a string with TO_JSON_STRING and count rows matching LIKE '%pro%' as records whose plan is pro","Unless every key is flattened into its own column at load time, BigQuery cannot use JSON values in aggregations"],"eEn":"JSON-typed columns let you extract values by path with functions such as JSON_VALUE, and CAST makes them numeric for aggregation. Index-based SPLIT and LIKE string tests break when structure changes, and BigQuery handles JSON directly without prior flattening."},{"id":"h233","d":"D2","q":"データ基盤チームは、BigQuery の夜間 ETL と日中のダッシュボードのクエリが同じオンデマンドのスロットを奪い合い、朝の経営ダッシュボードが遅くなることに悩んでいる。ワークロードごとに処理能力を分離し、ETL が重くてもダッシュボードの性能を一定に保ちたい。最も適切な構成はどれか。","o":["ETL のジョブをすべてバッチ優先度に切り替えたうえで、同じオンデマンドのスロットのまま運用する","ダッシュボード用クエリの結果を毎回 CSV にエクスポートし、Looker Studio からはその CSV を読み込ませる","テーブルをすべてパーティション分割し直し、スロットの競合が起きないように読み取り範囲を小さくする","容量ベースの予約を作成し、ETL とダッシュボードのプロジェクトを別々の予約に割り当てる"],"a":3,"e":"予約（エディションの容量）を作り、プロジェクトを別々の予約に割り当てると、ワークロード間でスロットを分離して性能を安定させられる。バッチ優先度は同じ枠を使うので分離にならず、CSV のエクスポートは運用負荷が増え、パーティション化はスロット競合を解消しない。","qEn":"A data platform team finds that nightly ETL and daytime dashboard queries in BigQuery compete for the same on-demand slots, slowing the morning executive dashboard. They want to isolate capacity per workload so dashboard performance stays steady even when ETL is heavy. Which configuration is most appropriate?","oEn":["Switch every ETL job to batch priority while still running on the same on-demand slot pool shared with the dashboards","Export the dashboard query results to CSV every time and have Looker Studio load those CSV files","Re-partition every table so that read ranges shrink and slot contention no longer occurs","Create capacity-based reservations and assign the ETL and dashboard projects to separate reservations"],"eEn":"Creating reservations (edition capacity) and assigning projects to separate ones isolates slots between workloads and stabilizes performance. Batch priority still shares the same pool, CSV export adds operational burden, and partitioning does not remove slot contention."},{"id":"h234","d":"D2","q":"売上テーブル orders（1 注文 1 行）と、1 注文に複数行ある shipments テーブルを order_id で結合して SUM(order_amount) を求めたところ、集計額が実際の売上の約 1.8 倍になった。原因を踏まえた最も適切な修正はどれか。","o":["SELECT DISTINCT を付けて重複した行を取り除いてから SUM を計算すれば、注文ごとの金額が 1 回だけ数えられる","INNER JOIN を LEFT JOIN に変更すれば、結合時の行の重複が起きなくなる","SUM(order_amount) を SUM(DISTINCT order_amount) に変更して、同じ金額の行を 1 回だけ数える","shipments を order_id 単位に集約してから結合する"],"a":3,"e":"1 対多の結合では orders の行が shipments の行数分だけ複製され、SUM が水増しされる。結合前に shipments を 1 注文 1 行にたたむのが正しい。DISTINCT や SUM(DISTINCT) は同額の別注文まで消し、LEFT JOIN への変更では複製を防げない。","qEn":"Joining orders (one row per order) with shipments (several rows per order) on order_id and computing SUM(order_amount) produced about 1.8 times the actual revenue. What is the most appropriate fix given the cause?","oEn":["Add SELECT DISTINCT to drop duplicate rows before computing SUM, so each order's amount is counted only once","Change INNER JOIN to LEFT JOIN so that rows are no longer duplicated by the join","Change SUM(order_amount) to SUM(DISTINCT order_amount) so that identical amounts are counted once","Aggregate shipments to one row per order_id before joining"],"eEn":"In a one-to-many join, each order row is duplicated per shipment row, inflating SUM; collapsing shipments to one row per order first is correct. DISTINCT and SUM(DISTINCT) also remove different orders with equal amounts, and LEFT JOIN does not prevent duplication."},{"id":"h235","d":"D2","q":"通信会社のデータ分析チームは、契約年数・利用量・問い合わせ回数など 40 列ほどの表形式データから、翌月に解約するかどうかを予測したい。データはすべて BigQuery にあり、特徴量どうしの複雑な非線形の関係も捉えて精度を高めたい。ML 専用の基盤は新たに用意せず、SQL で完結させたい。最も適切なモデルタイプはどれか。","o":["ARIMA_PLUS（過去の値の推移から将来の値を予測する時系列予測のモデル）","KMEANS（ラベルを使わず、似たデータどうしをいくつかのグループに分けるクラスタリング）","MATRIX_FACTORIZATION（ユーザーと商品の関係を行列で表し、おすすめを導くレコメンド用のモデル）","BOOSTED_TREE_CLASSIFIER（勾配ブースティング木による分類）"],"a":3,"e":"表形式データの二値分類で非線形な関係も捉えたい場合は、勾配ブースティング木の分類モデルが適する。ARIMA_PLUS は時系列予測、KMEANS はラベルなしの群分け、MATRIX_FACTORIZATION はユーザーと商品の推薦用で、解約か否かを予測する分類モデルではない。","qEn":"A telecom analytics team wants to predict whether customers will cancel next month from about 40 columns of tabular data such as contract years, usage, and contact counts. All data is in BigQuery, and the team wants higher accuracy by capturing complex non-linear relations among features, without a dedicated ML platform and entirely in SQL. Which model type is most appropriate?","oEn":["ARIMA_PLUS (a time-series forecasting model that predicts future values from the history of past values)","KMEANS (clustering that divides similar data into several groups without using labels)","MATRIX_FACTORIZATION (a recommendation model that represents user-item relations as a matrix to derive suggestions)","BOOSTED_TREE_CLASSIFIER (gradient-boosted tree classification)"],"eEn":"For binary classification on tabular data with non-linear relations, a gradient-boosted tree classifier fits. ARIMA_PLUS is for time series, KMEANS for unlabeled grouping, and MATRIX_FACTORIZATION for user-item recommendation; none predicts cancel or not."},{"id":"h236","d":"D2","q":"動画配信サービスのチームは、ユーザーごとの視聴履歴（視聴時間という暗黙的なフィードバック）から、各ユーザーにおすすめの作品を提示したい。データは BigQuery にあり、SQL で推薦モデルを学習したい。最も適切な方法はどれか。","o":["MATRIX_FACTORIZATION を IMPLICIT で学習し、ML.RECOMMEND で推薦を出す","KMEANS でユーザーを 5 つの群に分け、各群でよく見られている作品を群内の全員に一律で表示する運用にし、群の構成は月次で見直す","ARIMA_PLUS でユーザーごとの視聴時間を時系列予測し、予測値の大きい作品を順に推薦する","PCA でユーザーの特徴を少数の主成分に圧縮し、その座標の値をそのまま作品の推薦スコアとして出力する"],"a":0,"e":"ユーザーと作品の相互作用行列から推薦するには行列分解が適し、視聴時間のような暗黙的な反応は feedback_type を IMPLICIT にして学習する。KMEANS は群分け、ARIMA_PLUS は時系列予測、PCA は次元削減であり、個々のユーザーへの推薦スコアを直接出す手法ではない。","qEn":"A video streaming team wants to suggest titles to each user from viewing history, where watch time is implicit feedback. The data is in BigQuery, and the team wants to train the recommender in SQL. What is the most appropriate approach?","oEn":["Train MATRIX_FACTORIZATION with feedback_type IMPLICIT and generate recommendations with ML.RECOMMEND","Divide users into five groups with KMEANS and show every user in a group the titles most viewed within that group","Forecast each user's watch time with ARIMA_PLUS as a time series and recommend titles in descending order of the forecast","Compress user features into a few principal components with PCA and output those coordinates as recommendation scores for titles"],"eEn":"Matrix factorization suits recommending from a user-item interaction matrix, and implicit reactions such as watch time are trained with feedback_type IMPLICIT. KMEANS groups, ARIMA_PLUS forecasts time series, and PCA reduces dimensions; none outputs per-user recommendation scores."},{"id":"h237","d":"D2","q":"ある小売チェーンは 300 店舗 × 50 商品、約 1.5 万系列の日次販売数を予測したい。系列ごとに別々のモデルを作って管理するのは運用が煩雑になる。BigQuery ML の CREATE MODEL を 1 回だけ実行して、店舗と商品の組み合わせごとの予測をまとめて学習する最も適切な方法はどれか。","o":["ARIMA_PLUS で TIME_SERIES_ID_COL に店舗と商品の列を指定して学習する","KMEANS で店舗と商品の組み合わせをクラスタに分け、各クラスタの平均販売数をそのまま将来の予測値とする","LINEAR_REG に店舗・商品・日付を数値化した値を特徴量として与え、日付の増加に対する販売数を直線回帰する","学習済みモデルを作らずに、ML.FORECAST をテーブルに対して直接実行して系列ごとの予測を得る"],"a":0,"e":"ARIMA_PLUS は TIME_SERIES_ID_COL に系列を識別する列を指定すると、1 回の CREATE MODEL で多数の系列を並行して学習し、系列ごとに季節性とトレンドを扱える。KMEANS は予測を行わず、LINEAR_REG は季節性を自動で扱えず、ML.FORECAST は学習済みモデルを必要とする。","qEn":"A retail chain wants to forecast daily sales for 300 stores x 50 products, about 15,000 series. Building and managing a separate model per series is operationally cumbersome. What is the most appropriate way to train forecasts for every store-product combination with a single BigQuery ML CREATE MODEL statement?","oEn":["Train ARIMA_PLUS with the store and product columns specified in TIME_SERIES_ID_COL","Cluster store-product combinations with KMEANS and use each cluster's average sales directly as the future forecast","Give LINEAR_REG the store, product, and a numeric date as features and fit a straight line of sales against the passage of dates","Skip creating a trained model and run ML.FORECAST directly against the table to get a forecast per series"],"eEn":"Specifying identifier columns in TIME_SERIES_ID_COL lets ARIMA_PLUS train many series in one CREATE MODEL while handling each series' seasonality and trend. KMEANS does not forecast, LINEAR_REG does not handle seasonality automatically, and ML.FORECAST needs a trained model."},{"id":"h238","d":"D2","q":"決済サービスのチームは、分単位の取引件数の時系列から、障害や不正の兆候となる急な増減を自動で検出したい。すでに過去 6 か月のデータで ARIMA_PLUS モデルを学習済みで、新しく届いた直近 1 時間のデータが異常かどうかを判定したい。最も適切な方法はどれか。","o":["ML.FORECAST の予測値と実績との差を計算し、あらかじめ決めた固定のしきい値（たとえば 100 件）を超えた時点を異常と判定して担当者へ通知する","ML.EVALUATE を直近のデータに実行し、返ってきた誤差の指標が大きければその時間帯を異常と判断する","ML.TRAINING_INFO を実行して学習時の損失の推移を調べ、損失が急に変化した時間帯を異常とみなす","ML.DETECT_ANOMALIES に学習済みモデルと直近データを渡し、anomaly_prob_threshold を指定する"],"a":3,"e":"ML.DETECT_ANOMALIES は ARIMA_PLUS の予測区間を基準に、各時点が異常かどうかを anomaly_prob_threshold で判定して返す。固定のしきい値は季節性や変動幅を無視してしまい、ML.EVALUATE は時点ごとの異常を返さず、ML.TRAINING_INFO は学習履歴で新しいデータの異常は分からない。","qEn":"A payment service team wants to automatically detect sudden rises or drops in per-minute transaction counts that may signal failures or fraud. An ARIMA_PLUS model is already trained on six months of data, and the team wants to judge whether the newest hour of data is anomalous. What is the most appropriate method?","oEn":["Compute the gap between ML.FORECAST values and actuals and flag points that exceed a predetermined fixed threshold such as 100 transactions","Run ML.EVALUATE on the recent data and judge that time window anomalous if the returned error metrics are large","Run ML.TRAINING_INFO, examine how the loss changed during training, and regard the time windows of sudden change as anomalies","Pass the trained model and the recent data to ML.DETECT_ANOMALIES and specify anomaly_prob_threshold"],"eEn":"ML.DETECT_ANOMALIES judges each point against the ARIMA_PLUS prediction interval using anomaly_prob_threshold. A fixed threshold ignores seasonality and variability, ML.EVALUATE does not flag individual points, and ML.TRAINING_INFO describes training history, not anomalies in new data."},{"id":"h239","d":"D2","q":"与信審査チームは、BigQuery ML のブースティング木で貸倒リスクのスコアを出している。審査担当者から、否決時の説明のために、申込者ごとに『どの特徴量がそのスコアをどれだけ押し上げたか』を示したいという要望があった。最も適切な関数はどれか。","o":["ML.FEATURE_IMPORTANCE でモデル全体の特徴量の重要度を取得し、その値をすべての申込者の説明にそのまま使う","ML.EVALUATE でモデルの精度指標を取得し、精度への貢献が大きい特徴量を各申込者の理由として示す","ML.EXPLAIN_PREDICT で予測ごとの特徴量の寄与度を取得する","ML.TRAINING_INFO で学習の反復ごとの損失を取得し、損失を大きく下げた特徴量を各申込者の理由として示す"],"a":2,"e":"ML.EXPLAIN_PREDICT は予測ごとに各特徴量の寄与度を返すので、個別の説明に使える。ML.FEATURE_IMPORTANCE はモデル全体の傾向で個々の申込者の理由にならず、ML.EVALUATE と ML.TRAINING_INFO は精度や学習履歴を返すだけで、特徴量の寄与は示さない。","qEn":"A credit review team scores default risk with a BigQuery ML boosted tree. Reviewers want to show, for each applicant, which features pushed the score up and by how much, to explain rejections. Which function is most appropriate?","oEn":["Get model-wide feature importance with ML.FEATURE_IMPORTANCE and use those values as the explanation for every applicant","Get accuracy metrics with ML.EVALUATE and present the features that contribute most to accuracy as each applicant's reasons","Get per-prediction feature attributions with ML.EXPLAIN_PREDICT","Get per-iteration loss with ML.TRAINING_INFO and present the features that reduced loss the most as each applicant's reasons"],"eEn":"ML.EXPLAIN_PREDICT returns each feature's contribution per prediction, so it supports individual explanations. ML.FEATURE_IMPORTANCE shows model-wide trends, and ML.EVALUATE and ML.TRAINING_INFO return accuracy or training history without feature contributions."},{"id":"h240","d":"D2","q":"BigQuery ML のロジスティック回帰で購買予測モデルを学習した。ML.TRAINING_INFO を見ると、学習データの損失は下がり続ける一方、評価データの損失は途中から上昇している。モデルが学習データに過剰適合している。この状況への最も適切な対処はどれか。","o":["MAX_ITERATIONS を大幅に増やして、損失が十分に下がり切るまで学習を続ける","評価データの割合を 0 にして、手元のすべてのデータを学習に使って再学習する","L2 正則化を強め、早期停止を有効にし、不要な特徴量を減らして再学習する","特徴量を追加して、モデルがより複雑な関係を表現できるように表現力を高める"],"a":2,"e":"評価損失だけが上がるのは過剰適合のサインで、正則化の強化・早期停止・特徴量の削減でモデルの複雑さを抑えるのが定石。反復回数の増加や特徴量の追加は過剰適合を悪化させ、評価データを使わない学習は過剰適合に気づけなくなるだけである。","qEn":"A purchase-prediction model was trained with BigQuery ML logistic regression. ML.TRAINING_INFO shows training loss still falling while evaluation loss rises from some point on, so the model overfits the training data. What is the most appropriate response?","oEn":["Greatly increase MAX_ITERATIONS and keep training until the loss has fully bottomed out","Set the evaluation fraction to 0 and retrain using all the available data for training","Strengthen L2 regularization, enable early stop, trim unnecessary features, and retrain","Add features so that the model gains more expressive power to represent more complex relations"],"eEn":"Rising evaluation loss alone signals overfitting, and the standard remedy is to reduce complexity through stronger regularization, early stop, and fewer features. More iterations or features worsen it, and training without evaluation data only hides it."},{"id":"h241","d":"D2","q":"分析チームは BigQuery ML のブースティング木で需要の増減を分類しており、木の深さや学習率の最適な組み合わせが分からない。手動で CREATE MODEL を何十回も繰り返す運用をやめ、SQL のまま自動で探索したい。最も適切な方法はどれか。","o":["NUM_TRIALS を指定し、HPARAM_RANGE で探索範囲を与えてハイパーパラメータ調整を実行する","MAX_TREE_DEPTH と LEARN_RATE に適当な固定値を入れて 1 回だけ学習し、その結果をそのまま本番に採用する","AUTO_CLASS_WEIGHTS を TRUE にして、木の深さや学習率が自動で最適化されるようにする","ML.PREDICT を設定の違うモデルに対して何度も実行し、予測が当たった設定を手作業で表に記録する"],"a":0,"e":"NUM_TRIALS を指定するとハイパーパラメータ調整が有効になり、HPARAM_RANGE で探索範囲を与えれば複数の試行を自動で行って最良のモデルを選べる。固定値での 1 回学習は探索にならず、AUTO_CLASS_WEIGHTS は不均衡への対策で、ML.PREDICT の手作業は自動探索ではない。","qEn":"An analytics team classifies demand changes with a BigQuery ML boosted tree and does not know the best combination of tree depth and learning rate. They want to stop repeating CREATE MODEL dozens of times by hand and search automatically while staying in SQL. What is the most appropriate method?","oEn":["Specify NUM_TRIALS and give search ranges with HPARAM_RANGE to run hyperparameter tuning","Put arbitrary fixed values into MAX_TREE_DEPTH and LEARN_RATE, train once, and adopt that result for production as is","Set AUTO_CLASS_WEIGHTS to TRUE so that tree depth and learning rate are optimized automatically","Run ML.PREDICT repeatedly against models built with different settings and manually record in a table the settings whose predictions hit"],"eEn":"Specifying NUM_TRIALS enables hyperparameter tuning, and with HPARAM_RANGE it runs several trials automatically and picks the best model. A single fixed-value run is no search, AUTO_CLASS_WEIGHTS addresses imbalance, and manual ML.PREDICT comparison is not automated search."},{"id":"h242","d":"D2","q":"不正検知の二値分類モデルを BigQuery ML で学習する。不正ラベルは全体の 0.3% しかなく、そのまま学習するとほぼすべてを正常と予測するモデルになってしまう。データの再サンプリングは避け、学習時のオプションだけで少数クラスを重視させたい。最も適切な方法はどれか。","o":["DATA_SPLIT_EVAL_FRACTION を 0.9 に上げて、評価用のデータを大量に確保してから学習する","L1_REG を 0 に設定して正則化を無効にし、少数クラスの特徴が薄まらないようにして学習する","MODEL_TYPE を KMEANS に変更し、NUM_CLUSTERS を 2 にしてラベルを使わずに不正を群として検出する","CREATE MODEL のオプションで AUTO_CLASS_WEIGHTS を TRUE にする"],"a":3,"e":"AUTO_CLASS_WEIGHTS を TRUE にすると、クラスの出現頻度に応じた重みが自動で付き、少数クラスの誤りが損失に大きく反映される。評価データを増やしても学習の偏りは直らず、正則化の無効化は不均衡と無関係で、KMEANS へ変えるとラベルを使わなくなる。","qEn":"A binary fraud-detection model is trained in BigQuery ML, but only 0.3 percent of rows carry the fraud label, so training as is yields a model that predicts almost everything as normal. The team wants to avoid resampling and emphasize the minority class through training options alone. What is the most appropriate method?","oEn":["Raise DATA_SPLIT_EVAL_FRACTION to 0.9 to reserve a large amount of evaluation data before training","Set L1_REG to 0 to disable regularization so that the features of the minority class are not diluted during training","Change MODEL_TYPE to KMEANS with NUM_CLUSTERS set to 2 and detect fraud as a cluster without using labels","Set AUTO_CLASS_WEIGHTS to TRUE in the CREATE MODEL options"],"eEn":"AUTO_CLASS_WEIGHTS TRUE assigns weights by class frequency so errors on the minority class weigh more in the loss. A larger evaluation share does not fix training skew, disabling regularization is unrelated to imbalance, and KMEANS discards the labels."},{"id":"h243","d":"D2","q":"解約予測モデルを BigQuery ML で作ったところ、評価データで AUC がほぼ 1.0 に達した。ところが本番では精度が大きく落ちた。特徴量を確認すると、『解約手続きが完了済みか』を示す列が含まれていた。この現象の原因と最も適切な対処はどれか。","o":["学習データが少なすぎたための過少適合なので、学習データの件数を増やしてから同じ特徴量で再学習する","AUC が極端に高いのはハイパーパラメータ調整がうまくいった結果なので、問題はなく、そのまま本番に展開する","結果を反映した列が学習に混入したデータリークなので、予測時点で得られない列を特徴量から除いて再学習する","評価指標の選択が誤っているので、AUC をやめて平均絶対誤差の MAE で評価し直せば本番の精度と一致する"],"a":2,"e":"解約手続きの完了は解約という結果そのものを反映しており、予測時点では得られない。こうした列が混じるデータリークは、評価だけを異常に良く見せる。除外して再学習するのが正しい。過少適合や調整の成功ではなく、評価指標を MAE に替えても漏えいは解消しない。","qEn":"A churn model built with BigQuery ML reached an AUC close to 1.0 on evaluation data, but accuracy dropped sharply in production. The features include a column showing whether the cancellation procedure is complete. What is the cause and the most appropriate response?","oEn":["Underfitting caused by too little training data, so add more training rows and retrain with the same features, expecting evaluation to become realistic","An extremely high AUC means hyperparameter tuning went well, so there is no problem and the model can be deployed as is","This is data leakage from a column that reflects the outcome, so remove columns unavailable at prediction time from the features and retrain","The evaluation metric was wrongly chosen, so switching from AUC to mean absolute error (MAE) would make evaluation match production accuracy"],"eEn":"Completion of cancellation reflects the outcome itself and is unavailable at prediction time; such leakage makes only the evaluation look unrealistically good, so remove it and retrain. It is not underfitting or tuning success, and switching the metric to MAE does not remove the leak."},{"id":"h244","d":"D2","q":"小売の日次データを使い、BigQuery ML のブースティング木で『翌日の売上が目標を超えるか』を予測する。ランダムに分割して評価すると未来のデータが学習に混ざって精度が楽観的に出てしまう。過去のデータで学習し、直近のデータで評価したい。最も適切なオプションはどれか。","o":["DATA_SPLIT_METHOD を 'SEQ' にして、DATA_SPLIT_COL に日付の列を指定する","DATA_SPLIT_METHOD を 'RANDOM' のままにして、DATA_SPLIT_EVAL_FRACTION だけを 0.3 に増やす","DATA_SPLIT_METHOD を 'NO_SPLIT' にして、学習に使ったすべてのデータでそのまま評価する","DATA_SPLIT_METHOD を 'CUSTOM' にして、DATA_SPLIT_COL に売上金額の列を指定する"],"a":0,"e":"日付順に分けるには、SEQ を DATA_SPLIT_COL とあわせて指定し、古いデータで学習して新しいデータで評価する。RANDOM は未来のデータが学習に混ざり、NO_SPLIT は学習データで評価して楽観的になり、CUSTOM は真偽値の列で分けるもので売上金額の列は指定できない。","qEn":"Using daily retail data, a BigQuery ML boosted tree predicts whether tomorrow's sales will exceed the target. Evaluating with a random split lets future data leak into training and makes accuracy look optimistic. The team wants to train on older data and evaluate on the most recent. Which option is most appropriate?","oEn":["Set DATA_SPLIT_METHOD to 'SEQ' and specify the date column in DATA_SPLIT_COL","Leave DATA_SPLIT_METHOD at 'RANDOM' and only increase DATA_SPLIT_EVAL_FRACTION to 0.3","Set DATA_SPLIT_METHOD to 'NO_SPLIT' and evaluate directly on all of the data used for training","Set DATA_SPLIT_METHOD to 'CUSTOM' and specify the sales amount column in DATA_SPLIT_COL"],"eEn":"To split chronologically, specify SEQ together with DATA_SPLIT_COL, training on older data and evaluating on newer. RANDOM mixes future data into training, NO_SPLIT evaluates on training data optimistically, and CUSTOM splits on a boolean column, not a sales amount."},{"id":"h245","d":"D2","q":"銀行の与信チームは、BigQuery ML で融資の可否を予測するモデルを作る。金融当局への説明責任のため、各特徴量が結果にどの方向にどの程度寄与するかを、係数として監査人に示せることを最優先する。わずかな精度の差よりも説明可能性を重視する。最も適切な方法はどれか。","o":["DNN_CLASSIFIER で学習し、隠れ層の重みの値をそのまま監査人に提示して根拠とする","AUTOENCODER で特徴量を少数の次元に圧縮し、圧縮後の次元の値を融資判断の根拠として示す","LOGISTIC_REG で学習し、ML.WEIGHTS で特徴量ごとの係数を提示する","KMEANS で申込者を群に分け、各群の重心の値を融資可否の判断の根拠として示す"],"a":2,"e":"ロジスティック回帰は特徴量ごとの係数を直接読めるので、ML.WEIGHTS で方向と大きさを監査人に説明できる。DNN の隠れ層の重みは個々の特徴量の意味に結び付けにくく、AUTOENCODER の圧縮次元や KMEANS の重心も、可否を予測する係数ではない。","qEn":"A bank's credit team builds a loan approval model in BigQuery ML. For accountability to regulators, the top priority is to show auditors, as coefficients, the direction and size of each feature's contribution; explainability outweighs small accuracy differences. What is the most appropriate method?","oEn":["Train with DNN_CLASSIFIER and present the hidden-layer weight values directly to auditors as the rationale","Compress features into a few dimensions with AUTOENCODER and present the compressed dimension values as the basis for loan decisions","Train with LOGISTIC_REG and present per-feature coefficients with ML.WEIGHTS","Divide applicants into groups with KMEANS and present each group's centroid values as the basis for approval decisions"],"eEn":"Logistic regression coefficients can be read per feature, so ML.WEIGHTS lets you explain direction and size to auditors. DNN hidden weights are hard to tie to features, and AUTOENCODER dimensions or KMEANS centroids are not coefficients that predict approval."},{"id":"h246","d":"D2","q":"需要計画チームは ARIMA_PLUS モデルで今後 30 日の売上を予測し、発注の安全在庫を決める。点予測だけでなく、『90% の確率でこの範囲に入る』という上限と下限も欲しい。ML.FORECAST でどのように取得するのが最も適切か。","o":["STRUCT(30 AS horizon) だけを指定し、返された予測値に 0.9 と 1.1 を掛けて、その範囲を安全在庫の幅として計算する","STRUCT(30 AS horizon, 0.9 AS confidence_level) を指定して、予測区間の上限と下限の各列を利用する","ML.EVALUATE の戻り値にある標準誤差の列から、将来の各日の上限と下限を直接取り出す","ML.FORECAST を 90 回繰り返し実行して、各日の最大値と最小値を集めて範囲とする"],"a":1,"e":"ML.FORECAST の confidence_level で信頼水準を指定すると、予測値に加えて予測区間の上限・下限の列が返る。0.9 と 1.1 を掛ける方法は根拠のない固定幅で、ML.EVALUATE は過去に対する精度指標で将来の区間を返さず、同じ関数を繰り返しても結果は変わらない。","qEn":"A demand planning team forecasts the next 30 days of sales with an ARIMA_PLUS model to set safety stock. Beyond point forecasts, they want upper and lower bounds meaning 'a 90 percent chance of falling in this range'. What is the most appropriate way to get them from ML.FORECAST?","oEn":["Specify only STRUCT(30 AS horizon) and compute the range by multiplying the returned forecast by 0.9 and 1.1 to use as the safety-stock band","Specify STRUCT(30 AS horizon, 0.9 AS confidence_level) and use the prediction interval lower and upper bound columns","Take the upper and lower bounds for each future day directly from the standard-error columns of ML.EVALUATE output","Run ML.FORECAST 90 times and collect each day's maximum and minimum as the range"],"eEn":"Specifying confidence_level in ML.FORECAST returns lower and upper prediction-interval columns along with the forecast. A fixed x0.9 and x1.1 has no basis, ML.EVALUATE reports past accuracy rather than future intervals, and repeating the same function returns the same result."},{"id":"h247","d":"D2","q":"日本国内のドラッグストアチェーンが、日次の来店数を ARIMA_PLUS で予測している。ゴールデンウィークや年末年始に実績が大きく変動するが、モデルがこれらを単なる外れ値として扱ってしまい、予測が外れる。モデルの設定で日本の祝日の影響を考慮させるには、どうするのが最も適切か。","o":["DATA_FREQUENCY を 'WEEKLY' に変更して、祝日を含む週の単位にデータを集約してから学習する","CLEAN_SPIKES_AND_DIPS を TRUE にして、祝日に起きる変動もすべてスパイクとして取り除いてから学習する","CREATE MODEL のオプションで HOLIDAY_REGION に 'JP' を指定する","AUTO_ARIMA を FALSE にして、祝日の影響を表す次数の値を手作業で指定してから学習する"],"a":2,"e":"ARIMA_PLUS は HOLIDAY_REGION に国や地域の識別子（日本は JP）を指定すると、その地域の祝日の影響をモデル化して予測に反映する。週単位への集約は日次の祝日効果を失わせ、スパイク除去は祝日の変動を消してしまい、AUTO_ARIMA を切っても祝日は扱われない。","qEn":"A Japanese drugstore chain forecasts daily store visits with ARIMA_PLUS. Actuals swing sharply in Golden Week and the New Year period, but the model treats them as mere outliers and misses the forecast. What is the most appropriate model setting to account for Japanese holidays?","oEn":["Change DATA_FREQUENCY to 'WEEKLY' and aggregate data into weeks that include holidays before training","Set CLEAN_SPIKES_AND_DIPS to TRUE and remove all fluctuations occurring on holidays as spikes before training","Specify 'JP' for HOLIDAY_REGION in the CREATE MODEL options","Set AUTO_ARIMA to FALSE and manually specify order values representing the holiday effect before training"],"eEn":"Specifying a region identifier (JP for Japan) in HOLIDAY_REGION makes ARIMA_PLUS model that region's holiday effects. Weekly aggregation loses daily holiday effects, spike cleaning erases holiday swings, and turning off AUTO_ARIMA does not add holidays."},{"id":"h248","d":"D2","q":"データサイエンスチームは、BigQuery ML で学習した分類モデルを、ECサイトのアプリから数十ミリ秒の応答で 1 件ずつ呼び出したい。バッチ予測では間に合わない。学習済みのモデルを活かしつつオンライン推論を実現する最も適切な方法はどれか。","o":["アプリから ML.PREDICT を含むクエリを 1 リクエストごとに BigQuery へ発行して、結果をそのまま返す","ML.PREDICT の結果を毎分 Looker Studio のデータソースへ書き出し、アプリは毎回そのデータソースを参照して予測結果を取得する","BI Engine を有効にして ML.PREDICT のクエリ結果をメモリに載せ、アプリのリクエストを高速化する","モデルを Vertex AI Model Registry に登録し、Vertex AI のエンドポイントにデプロイしたうえでオンライン予測を行う"],"a":3,"e":"BigQuery ML のモデルは Vertex AI Model Registry に登録してエンドポイントへデプロイでき、低遅延のオンライン予測を提供できる。リクエストごとのクエリ発行は応答時間と同時実行の面で向かず、Looker Studio は推論基盤ではなく、BI Engine は ML.PREDICT のオンライン推論基盤にならない。","qEn":"A data science team wants an e-commerce app to call a BigQuery ML classification model one request at a time with tens of milliseconds of latency; batch prediction is too slow. What is the most appropriate way to enable online inference while reusing the trained model?","oEn":["Issue a query containing ML.PREDICT to BigQuery for every app request and return the result as is","Write ML.PREDICT results to a Looker Studio data source every minute and have the app refer to that data source","Enable BI Engine to hold ML.PREDICT query results in memory and speed up the app's requests","Register the model in Vertex AI Model Registry and deploy it to a Vertex AI endpoint for online prediction"],"eEn":"BigQuery ML models can be registered in Vertex AI Model Registry and deployed to an endpoint for low-latency online prediction. Per-request queries suit neither latency nor concurrency, Looker Studio is not an inference platform, and BI Engine is not an online serving layer for ML.PREDICT."},{"id":"h249","d":"D2","q":"サポート部門は BigQuery に蓄積した約 200 万件の問い合わせ文を、『返品』『配送遅延』『故障』などのカテゴリに分類したい。教師データを用意する時間はなく、エクスポート処理や別の基盤を作らずに SQL だけで実行したい。最も適切な方法はどれか。","o":["LINEAR_REG を学習し、問い合わせ文の文字数を説明変数にして、カテゴリの番号を回帰で予測する","テキストを数値化せずに KMEANS でクラスタリングし、得られたクラスタ番号をそのままカテゴリ名として使う","LIKE '%返品%' などのキーワード一致を CASE 式にいくつも並べて、あらゆる表現のゆれを網羅して分類する方式にする","Vertex AI の Gemini を参照するリモートモデルを作り、SQL からプロンプトとともに文面を毎回渡して分類する"],"a":3,"e":"ラベルなしの文章分類は、Gemini を参照するリモートモデルを作り、SQL からプロンプトを渡して分類させると、別基盤を作らずに実行できる。LINEAR_REG は文字数で分類できず、数値化なしの KMEANS は意味のあるカテゴリを作れず、キーワード一致は表現のゆれを網羅できない。","qEn":"A support department wants to classify about 2 million inquiry texts stored in BigQuery into categories such as returns, delivery delays, and malfunctions. There is no time to prepare labeled data, and the team wants to do it in SQL alone without building export jobs or another platform. What is the most appropriate method?","oEn":["Train LINEAR_REG using the character count of each inquiry as the explanatory variable and predict the category number by regression","Cluster the texts with KMEANS without converting them to numbers and use the resulting cluster numbers directly as category names","Line up keyword matches such as LIKE '%return%' in a CASE expression and cover every variation in wording to classify","Create a remote model that references Gemini on Vertex AI and pass each text with a prompt from SQL to classify it"],"eEn":"For unlabeled text classification, a remote model referencing Gemini lets you pass prompts from SQL and classify without another platform. LINEAR_REG cannot classify by character count, KMEANS without vectorizing yields no meaningful categories, and keyword matching cannot cover wording variation."},{"id":"h250","d":"D2","q":"ナレッジ管理チームは、BigQuery に蓄積した 500 万件の社内ナレッジ記事から、利用者の質問と意味が近い記事を探したい。質問と記事の語句が一致しなくても、関連する記事を見つけたい。最も適切な構成はどれか。","o":["記事本文の埋め込みを生成して保存し、ベクトルインデックスを作成して VECTOR_SEARCH で近傍検索する","記事本文に検索インデックスを作成し、SEARCH 関数で質問に含まれる語句をそのまま含む記事を探す","記事ごとに KMEANS のクラスタ番号を付け、質問と同じ番号に属する記事をすべて返す","質問を分かち書きした語を REGEXP_CONTAINS で OR に並べ、いずれかの語に一致する記事をすべて返す方式にする"],"a":0,"e":"文章を埋め込みベクトルにし、ベクトルインデックスと VECTOR_SEARCH で近傍検索すれば、語句が一致しなくても意味の近い記事を探せる。SEARCH や REGEXP_CONTAINS は語句の一致に依存し、同一クラスタの全件返しは粗すぎて近さの順位を付けられない。","qEn":"A knowledge management team wants to find, among 5 million internal knowledge articles stored in BigQuery, those semantically close to a user's question, even when the wording of the question and article does not match. Which configuration is most appropriate?","oEn":["Generate and store embeddings of article text, create a vector index, and run nearest-neighbor search with VECTOR_SEARCH","Create a search index on the article text and use the SEARCH function to find articles containing the exact words in the question","Assign each article a KMEANS cluster number and return every article that belongs to the same number as the question","Tokenize the question into words, line them up with OR in REGEXP_CONTAINS, and return articles matching any word"],"eEn":"Embedding text as vectors and searching nearest neighbors with a vector index and VECTOR_SEARCH finds semantically close articles even without matching words. SEARCH and REGEXP_CONTAINS depend on word matches, and returning a whole cluster is too coarse to rank closeness."},{"id":"h251","d":"D2","q":"BigQuery ML で問い合わせ内容を『請求』『技術』『契約』『その他』の 4 クラスに分類するモデルを作った。全体の正解率は高いが、現場からは『契約』の問い合わせが『その他』に流れているという声がある。どのクラス間で誤分類が多いかを調べる、最も適切な関数はどれか。","o":["ML.CONFUSION_MATRIX で、実際のクラスと予測したクラスの件数表を確認する","ML.ROC_CURVE を実行して、しきい値ごとの再現率と偽陽性率の曲線を確認し、誤分類の多い組み合わせを探す","ML.FEATURE_INFO を実行して、各特徴量の最小値・最大値・欠損の件数を確認し、誤分類の原因を探る","ML.TRAINING_INFO を実行して、学習の反復ごとの損失の推移を確認し、誤分類の多いクラスを特定する"],"a":0,"e":"ML.CONFUSION_MATRIX は実際のクラスと予測クラスの組み合わせごとの件数を返すので、『契約』が『その他』に誤分類される件数を直接確認できる。ROC 曲線はしきい値ごとの判別力、FEATURE_INFO は入力列の統計、TRAINING_INFO は学習の損失であり、クラス間の誤分類は示さない。","qEn":"A BigQuery ML model classifies inquiries into four classes: billing, technical, contract, and other. Overall accuracy is high, but the field reports that contract inquiries are drifting into other. Which function is most appropriate for finding which classes are most often confused?","oEn":["Check the table of counts of actual versus predicted classes with ML.CONFUSION_MATRIX","Run ML.ROC_CURVE and examine the recall versus false-positive-rate curve by threshold to find combinations with many misclassifications","Run ML.FEATURE_INFO and examine each feature's minimum, maximum, and missing counts to look for the cause of misclassification","Run ML.TRAINING_INFO and examine the loss trend per iteration to identify the classes with many misclassifications"],"eEn":"ML.CONFUSION_MATRIX returns counts per actual-versus-predicted pair, so you can directly see how many contract inquiries are labeled other. ROC shows discrimination by threshold, FEATURE_INFO shows input-column statistics, and TRAINING_INFO shows loss, none of which reveals class confusion."},{"id":"h252","d":"D2","q":"人事部門の BigQuery テーブルには部署ごとの行レベルアクセスポリシーが設定され、各マネージャーは自分の部署の行しか見られない。このテーブルを Looker Studio のレポートで共有したところ、全マネージャーが全部署のデータを閲覧できてしまった。データソースの認証設定として、最も適切な修正はどれか。","o":["認証情報は所有者の認証情報のままにして、レポートの共有範囲だけを編集者の権限に絞り込む","認証情報を閲覧者の認証情報に切り替え、閲覧者本人の権限で BigQuery にアクセスさせる","レポートに部署のフィルタ コントロールを置き、各マネージャーが自分の部署を選ぶ運用をルールとして徹底する","BigQuery 側のポリシーは変更せずに、レポートの編集権限を持つ人数を減らして誤操作のリスクを下げる"],"a":1,"e":"所有者の認証情報では全閲覧者が所有者の権限でクエリされるため、行レベルポリシーは所有者を基準に評価される。閲覧者の認証情報にすれば、閲覧者本人の IAM とポリシーが適用される。フィルタ コントロールは自己選択にすぎず、編集者の人数を減らしても閲覧時の権限は変わらない。","qEn":"A BigQuery HR table has per-department row-level access policies so each manager sees only their own department's rows. After the table was shared through a Looker Studio report, every manager could see all departments' data. What is the most appropriate correction to the data source credentials?","oEn":["Keep the owner's credentials and only narrow the sharing scope of the report to editor permissions","Switch the credentials to viewer's credentials so that BigQuery is accessed with each viewer's own permissions","Place a department filter control in the report and enforce, as a rule, that each manager selects their own department","Leave the BigQuery policies unchanged and reduce the number of people with edit rights on the report to lower the risk of mistakes"],"eEn":"With owner's credentials, every viewer queries with the owner's permissions, so row-level policies are evaluated for the owner. Viewer's credentials apply each viewer's own IAM and policies. Filter controls are self-selection, and fewer editors does not change viewing permissions."},{"id":"h253","d":"D2","q":"Looker Studio のダッシュボードが BigQuery のカスタムクエリをデータソースにしている。クエリは大きな日次パーティションテーブルを SELECT しているが、日付範囲コントロールを変えても毎回全パーティションをスキャンし、遅く、料金も高い。日付範囲に応じて読むパーティションを絞る最も適切な設定はどれか。","o":["データソースのデータの鮮度を最短に設定して、日付範囲を変えるたびに新しい結果が必ず取得されるようにし、キャッシュされた古い結果が使われる余地をなくす","日付範囲パラメータを有効にし、WHERE 句で @DS_START_DATE と @DS_END_DATE を使ってパーティション列を絞る","カスタムクエリの末尾に LIMIT を付けて、Looker Studio が取得する行数を少なく制限する","データソースの認証情報を閲覧者の認証情報に切り替えて、閲覧者ごとに読み取り範囲が決まるようにする"],"a":1,"e":"BigQuery のカスタムクエリでは、日付範囲パラメータ @DS_START_DATE と @DS_END_DATE を WHERE 句で使うと、ダッシュボードの期間に合わせて読むパーティションが絞られる。鮮度を短くしても再実行が増えるだけで、LIMIT はスキャン量を減らさず、認証情報の切り替えは読み取り範囲と無関係である。","qEn":"A Looker Studio dashboard uses a BigQuery custom query as its data source. The query selects from a large daily-partitioned table, but whatever the date range control says, it scans every partition, which is slow and expensive. What is the most appropriate setting to limit partitions read to the selected date range?","oEn":["Set the data source freshness to the shortest option so that fresh results are always fetched whenever the date range changes","Enable date range parameters and use @DS_START_DATE and @DS_END_DATE in the WHERE clause to restrict the partition column","Append LIMIT to the end of the custom query so that Looker Studio retrieves fewer rows","Switch the data source credentials to viewer's credentials so that the read range is determined per viewer"],"eEn":"In a BigQuery custom query, using the date range parameters @DS_START_DATE and @DS_END_DATE in WHERE limits the partitions read to the dashboard's period. Shorter freshness only adds re-runs, LIMIT does not reduce bytes scanned, and credentials do not affect read range."},{"id":"h254","d":"D2","q":"全社の営業レポートを Looker Studio で運用してきたが、作成者が異動や退職をすると、その個人の Google アカウントが所有するレポートとデータソースの管理者が不在になる問題が頻発している。資産を組織として所有し、メンバーの役割で権限を管理したい。最も適切な対応はどれか。","o":["Looker Studio Pro のチーム ワークスペースを作成して資産を移し、役割ベースで権限を管理する","すべてのレポートの所有者を共通の共有メールアドレス 1 つに変更し、そのパスワードを担当者の間で共有する","レポートの共有設定をリンクを知っている全員が編集できる状態に変更して、誰でも修復できるようにする","毎月レポートを PDF にエクスポートして Cloud Storage に保管し、元のレポートは作り直す前提で運用する"],"a":0,"e":"Looker Studio Pro のチーム ワークスペースでは、資産が個人ではなく組織の Google Cloud プロジェクトに属し、役割ごとに権限を管理できるので、担当者が抜けても資産が孤立しない。共通アカウントのパスワード共有は統制を損ない、リンク共有は権限管理にならず、PDF の保管は管理者不在を解決しない。","qEn":"A company runs its sales reports in Looker Studio, but when an author transfers or leaves, the reports and data sources owned by that personal Google account lose their administrator. The company wants the organization to own the assets and to manage permissions by member role. What is the most appropriate response?","oEn":["Create a Looker Studio Pro team workspace, move the assets into it, and manage permissions by role","Change the owner of every report to one shared email address and share its password among the people in charge","Change the sharing setting so that anyone with the link can edit, allowing anybody to repair the reports","Export the reports to PDF every month and keep them in Cloud Storage, operating on the premise that the originals will be rebuilt"],"eEn":"In a Looker Studio Pro team workspace, assets belong to the organization's Google Cloud project rather than a person and permissions are managed by role, so they are not orphaned when someone leaves. Shared passwords weaken control, link sharing is not permission management, and PDFs do not solve the missing administrator."},{"id":"h255","d":"D2","q":"Looker Studio のレポートが、数億行のイベント表とユーザーマスタをデータのブレンドで結合しており、表示のたびに非常に遅い。結合キーは一意で、ビジネスロジックも固定されている。性能を最も改善できる対応はどれか。","o":["ブレンドの結合の種類を左外部結合から完全外部結合に変更し、結合処理が複数のワーカーで並列に実行されるようにする","ブレンドに使うデータソースの数を増やし、結合処理を複数のデータソースで分担して実行させる","BigQuery 側で結合済み（必要なら集計済み）のビューやテーブルを事前に作り、単一のデータソースとして使う","テーブル形式のチャートを円グラフに置き換えて、描画に必要な処理の負荷を下げる"],"a":2,"e":"ブレンドは Looker Studio 側で結合するため、大規模データでは重くなる。結合や集計を BigQuery 側で済ませて単一のデータソースにすると、性能が安定し、キャッシュも効きやすい。結合の種類やデータソース数を変えても負荷は減らず、円グラフへの変更は描画以外の遅さを解決しない。","qEn":"A Looker Studio report joins an event table of hundreds of millions of rows with a user master through data blending and is very slow on every view. The join key is unique and the business logic is fixed. Which action improves performance the most?","oEn":["Change the blend's join type from left outer to full outer so that the join runs in parallel across several workers","Increase the number of data sources used in the blend so that the join work is shared among multiple data sources","Create a pre-joined (and, if needed, pre-aggregated) view or table in BigQuery and use it as a single data source","Replace the table chart with a pie chart to reduce the processing load needed for rendering"],"eEn":"Blending joins inside Looker Studio, which gets heavy at large scale. Doing the join and aggregation in BigQuery as a single data source stabilizes performance and caches well. Changing join type or source count does not cut the load, and a pie chart does not fix slowness outside rendering."},{"id":"h256","d":"D2","q":"Looker に、夜間 ETL が完了した後にだけ再構築したい高コストな派生テーブル（PDT）がある。ETL の完了時刻は日によって変わり、固定の時刻に再構築すると、未完了のデータで作られてしまうことがある。最も適切な LookML の設定はどれか。","o":["PDT に persist_for で 24 時間を指定して、毎日同じ時刻の前後に自動で再構築されるようにする","PDT を永続化しない通常の派生テーブルに変更し、クエリを実行するたびに毎回その場で計算する方式にして、再構築のタイミングという概念自体をなくす","ETL 完了を判定する sql_trigger の datagroup を定義し、PDT の datagroup_trigger に指定しておく","ダッシュボードのスケジュール配信を毎朝 6 時に設定して、配信時のクエリで PDT が再構築されるようにする"],"a":2,"e":"datagroup の sql_trigger で ETL 完了を示す値（最終更新時刻など）を監視し、PDT の datagroup_trigger に指定すれば、完了後にだけ再構築される。persist_for は経過時間で保持を切るだけで ETL を見ず、非永続化は毎回高コストな計算になり、固定時刻の配信は未完了のデータを使いうる。","qEn":"Looker has an expensive persistent derived table (PDT) that should be rebuilt only after the nightly ETL finishes. The ETL completion time varies by day, and rebuilding at a fixed time sometimes builds it from incomplete data. Which LookML setting is most appropriate?","oEn":["Specify persist_for of 24 hours on the PDT so that it is rebuilt automatically around the same time every day","Change the PDT to a regular non-persistent derived table and compute it on the spot every time a query runs","Define a datagroup with a sql_trigger that detects ETL completion and set it as the PDT's datagroup_trigger","Schedule a dashboard delivery at 6 a.m. every morning so that the delivery query triggers a rebuild of the PDT"],"eEn":"Watching a value that signals ETL completion, such as a last-update time, in a datagroup sql_trigger and using it as the PDT's datagroup_trigger rebuilds only after completion. persist_for just expires by elapsed time, non-persistence recomputes expensively every query, and a fixed-time delivery may use incomplete data."},{"id":"h257","d":"D2","q":"Looker で、販売代理店ごとにダッシュボードを埋め込んで提供する。各代理店のユーザーには自社の行だけを見せ、他社のデータは決して見せてはならない。LookML の Explore でこれを強制する最も適切な方法はどれか。","o":["ダッシュボードごとに代理店 ID のフィルタ値を設定して、閲覧者がフィルタを変更できる状態で共有する","代理店ごとに別の Looker インスタンスを構築し、それぞれにモデルと LookML プロジェクトをコピーして個別に運用し、更新も各インスタンスで適用する","Explore の always_filter に特定の代理店 ID の固定値を書き込み、すべてのユーザーに同じ条件で適用する","ユーザー属性に代理店 ID を持たせ、Explore に access_filter を定義して代理店 ID の列と結び付ける"],"a":3,"e":"ユーザー属性と access_filter を組み合わせると、ログインしたユーザーの属性値で行が必ず絞り込まれ、利用者が外せない。ダッシュボードのフィルタ値は閲覧者が変更でき、always_filter の固定値は全員に同じ代理店を見せてしまい、インスタンスの複製は運用負荷が過大である。","qEn":"In Looker, dashboards are embedded and provided to each sales distributor. Each distributor's users must see only their own company's rows and never other companies' data. What is the most appropriate way to enforce this in a LookML Explore?","oEn":["Set a distributor ID filter value on each dashboard and share it with viewers able to change the filter","Build a separate Looker instance for each distributor and run it with copies of the model and LookML project","Write a fixed value for one specific distributor ID into the Explore's always_filter and apply the same condition to all users","Give users a distributor ID user attribute and define an access_filter on the Explore tied to the distributor ID column"],"eEn":"Combining user attributes with access_filter always narrows rows by the logged-in user's attribute value, and users cannot remove it. Dashboard filter values can be changed by viewers, a fixed always_filter shows everyone the same distributor, and duplicating instances is far too heavy to operate."},{"id":"h258","d":"D2","q":"Looker で orders ビューと order_items ビューを結合した Explore を作ったところ、注文金額の合計がページ上で実際より水増しして表示される。orders と order_items は 1 対多の関係である。LookML での最も適切な対応はどれか。","o":["measure の type を sum から count に変更して、重複した行を二重に数えないようにする","各ビューに primary_key を定義し、結合の relationship を正しく指定して、対称集計が使われるようにする","結合の種類を inner から left_outer に変更して、子の行が存在しない親の行も残るようにし、集計の対象となる行をできるだけ広げる","ダッシュボードに表示する数値を、結果の先頭の 1 行の値だけに制限して水増しを避ける"],"a":1,"e":"1 対多の結合で親側の measure が水増しされるのは行の複製が原因で、各ビューに primary_key を定義し relationship を正しく指定すれば、Looker が対称集計で重複を除いて計算する。count への変更は意味が変わり、結合の種類は複製を防がず、先頭行の制限は誤りを隠すだけである。","qEn":"After building a Looker Explore joining the orders and order_items views, the total order amount displays inflated compared with the actual figure. orders to order_items is one-to-many. What is the most appropriate LookML response?","oEn":["Change the measure type from sum to count so that duplicated rows are not counted twice","Define a primary_key in each view and specify the join relationship correctly so that symmetric aggregates are used","Change the join type from inner to left_outer so that parent rows without child rows are also kept","Limit the number shown on the dashboard to the value of only the first row of the result to avoid an inflated total when several rows come back"],"eEn":"Inflated parent measures in a one-to-many join come from row duplication; with primary keys defined and the relationship set correctly, Looker uses symmetric aggregates to avoid it. Switching to count changes the meaning, join type does not prevent duplication, and showing only the first row hides the error."},{"id":"h259","d":"D2","q":"LookML の開発者が 5 人に増え、本番のダッシュボードを壊す変更が混ざる事故が起きた。変更はレビューを経てから本番に反映し、問題があれば元に戻せる運用にしたい。Looker での最も適切な運用はどれか。","o":["開発モードで各自のブランチに変更を加え、Git のプルリクエストでレビューしてから本番へデプロイする","全員が同じ開発ブランチを共有して同時に編集し、保存した時点で自動的に本番へ反映される設定にする","LookML ファイルを Cloud Storage にコピーしてバージョン番号を付け、手作業でファイルを差し替えて反映する","変更のたびに別名の新しい LookML プロジェクトを作成し、問題がなければ名前を元のプロジェクトに戻す"],"a":0,"e":"Looker は LookML を Git で管理し、開発モードで個人ブランチに変更し、プルリクエストでレビューしてから本番にデプロイできる。問題があれば前のコミットに戻せる。共有ブランチの自動反映はレビューを経ず、手作業の差し替えとプロジェクトの複製は履歴管理と再現性を欠く。","qEn":"LookML developers have grown to five, and a change that broke production dashboards slipped in. The team wants changes reviewed before reaching production, with the ability to roll back when there is a problem. What is the most appropriate way to operate in Looker?","oEn":["Make changes in development mode on individual branches, review them via Git pull requests, and then deploy to production","Have everyone share one development branch and edit simultaneously, with saves automatically reflected in production","Copy LookML files to Cloud Storage, attach version numbers, and apply changes by manually swapping the files","Create a new, differently named LookML project for each change and, if there are no problems, rename it back to the original project"],"eEn":"Looker manages LookML in Git: change on personal branches in development mode, review by pull request, and deploy to production, rolling back to an earlier commit if needed. Automatic propagation skips review, and manual swaps or project copies lack history and reproducibility."},{"id":"h260","d":"D2","q":"営業責任者は、Looker のダッシュボードにある『当日の受注件数』が閾値を下回ったら、毎回画面を開かなくてもメールで即座に知りたい。コードを書かずに実現する最も適切な方法はどれか。","o":["ダッシュボードのスケジュール配信を 1 分おきに設定して、毎回 PDF をメールで全員に送る","ブラウザの自動更新を有効にしたまま、担当者が常にダッシュボードの画面を開いて確認する","LookML の datagroup を設定して、閾値を下回ったときに PDT が再構築されるようにする","ダッシュボードのタイルにアラートを設定し、条件と通知先を指定して定期的に評価させる"],"a":3,"e":"Looker のアラートはタイルの値に条件を設定して定期的に評価し、満たしたときにメールなどの通知先へ送れる。1 分おきの PDF 配信は常時のノイズになり、自動更新は画面を開いている人にしか届かず、datagroup は PDT の再構築を制御する機能で通知用ではない。","qEn":"A sales head wants to be notified by email as soon as the 'orders today' tile on a Looker dashboard falls below a threshold, without opening the screen each time. What is the most appropriate way to achieve this without writing code?","oEn":["Schedule dashboard delivery every minute and email a PDF to everyone each time","Keep browser auto-refresh enabled and have the person in charge keep the dashboard open and watch it continuously throughout the working day","Configure a LookML datagroup so that a PDT is rebuilt when the value falls below the threshold","Set an alert on the dashboard tile, specifying the condition and recipients, and let it be evaluated periodically"],"eEn":"A Looker alert evaluates a condition on a tile's value periodically and sends notifications such as email when met. A one-minute PDF schedule is constant noise, auto-refresh only reaches people watching the screen, and datagroups control PDT rebuilds, not notifications."},{"id":"h261","d":"D2","q":"経理部門は Google スプレッドシートでの作業に慣れており、BigQuery にある 3 億行の取引データを、ピボットテーブルとグラフで集計・分析したい。CSV へのエクスポートやスプレッドシートの行数の上限は避けたい。最も適切な方法はどれか。","o":["Connected Sheets で BigQuery のテーブルに接続し、シート上でピボットやグラフを使って分析する","BigQuery の結果を CSV にエクスポートし、複数のシートに分割してインポートしてから、シート上の関数でまとめて集計する","Apps Script で BigQuery の全行を取得してシートに書き込み、シート上の数式で集計する","スプレッドシートの IMPORTDATA 関数に BigQuery のテーブル名を指定して、結果を直接取り込む"],"a":0,"e":"Connected Sheets は BigQuery の大規模データに接続し、データをシートに取り込まずにピボットテーブルやグラフ、数式で分析できるので、行数の上限や CSV の運用を避けられる。CSV の分割インポートや全行を書き込む Apps Script は行数の上限に当たり、IMPORTDATA は BigQuery に接続する関数ではない。","qEn":"The accounting department is used to working in Google Sheets and wants to aggregate and analyze 300 million rows of transaction data in BigQuery with pivot tables and charts, avoiding CSV exports and spreadsheet row limits. What is the most appropriate method?","oEn":["Connect to the BigQuery table with Connected Sheets and analyze with pivots and charts in the sheet","Export BigQuery results to CSV, split them across multiple sheets for import, and aggregate with functions","Retrieve all rows from BigQuery with Apps Script, write them to the sheet, and aggregate with formulas in the sheet","Specify the BigQuery table name in the spreadsheet IMPORTDATA function to import the results directly"],"eEn":"Connected Sheets connects to large BigQuery data and lets you analyze with pivots, charts, and formulas without loading the data into the sheet, avoiding row limits and CSV handling. Split CSV imports and writing all rows via Apps Script hit row limits, and IMPORTDATA does not connect to BigQuery."},{"id":"h262","d":"D2","q":"営業企画部門は、SQL を書けない現場担当者が『先月の地域別の売上は？』のような自然言語で質問し、全社で定義された指標に基づく一貫した答えを得られるようにしたい。指標の定義は LookML で一元管理されている。最も適切な方法はどれか。","o":["Looker の Conversational Analytics で、LookML のセマンティック レイヤーに基づいて質問させる","現場担当者それぞれに BigQuery コンソールで Gemini を使わせ、各自が指標の定義を指示文に書いて SQL を生成させる運用にする","Looker Studio の計算フィールドに各自が指標の式を書き、自然言語の質問に答えるレポートを個別に作らせる","指標の定義を社内チャットのピン留めメッセージに書いておき、担当者がそれを見ながら手計算で答えを出す"],"a":0,"e":"Looker のセマンティック レイヤー（LookML）に基づく自然言語の質問応答では、定義済みの指標とディメンションが使われるため、誰が聞いても一貫した答えになる。各自が SQL を生成すると定義がばらつき、計算フィールドの個別実装は定義が分散し、手計算は誤りと工数を招く。","qEn":"A sales planning department wants field staff who cannot write SQL to ask questions in natural language, such as 'What were last month's sales by region?', and get consistent answers based on company-defined metrics. The metric definitions are centrally managed in LookML. What is the most appropriate method?","oEn":["Use Looker's Conversational Analytics so staff ask questions grounded in the LookML semantic layer","Have each field person use Gemini in the BigQuery console and instruct it with their own metric definitions to generate SQL","Have each person write metric formulas in Looker Studio calculated fields and build individual reports that answer natural-language questions","Write the metric definitions in a pinned message in company chat and have staff work out answers by hand while looking at it"],"eEn":"Natural-language Q&A grounded in the Looker semantic layer (LookML) uses predefined metrics and dimensions, so everyone gets consistent answers. Self-generated SQL varies in definitions, individual calculated fields scatter them, and manual calculation invites errors and effort."},{"id":"h263","d":"D2","q":"新しく配属されたアナリストが、BigQuery にある見慣れない orders テーブルについて、どんな切り口で分析できるのか分からない。まずテーブルのメタデータを手がかりに、パターンや外れ値を探る SQL の例を自動で提案してほしい。最も適切な機能はどれか。","o":["Dataplex のデータ プロファイル スキャンを実行して、列ごとの NULL 率や最小値・最大値の一覧を確認する","INFORMATION_SCHEMA.JOBS から他のアナリストが過去に実行したクエリを探し、そのままコピーして自分の分析に流用する運用にする","Looker Studio にテーブルを接続して、既定で作られるチャートの種類の中から使えるものを選ぶ","Gemini in BigQuery のデータ分析情報（data insights）で、テーブルから生成されたクエリ例を確認する"],"a":3,"e":"Gemini in BigQuery のデータ分析情報は、テーブルのメタデータからパターン検出や統計分析のためのクエリを自動生成して提案する。データ プロファイルは列の統計を出すがクエリ例は提案せず、過去のクエリのコピーは対象テーブルに合うと限らず、既定のチャートは探索の切り口を示さない。","qEn":"A newly assigned analyst does not know what angles are available for analyzing an unfamiliar orders table in BigQuery. Starting from the table's metadata, they want example SQL queries for exploring patterns and outliers to be suggested automatically. Which feature is most appropriate?","oEn":["Run a Dataplex data profile scan and review the list of null rates and minimum and maximum values per column","Search INFORMATION_SCHEMA.JOBS for queries other analysts ran in the past, then copy and run them as is","Connect the table to Looker Studio and choose usable ones from the chart types created by default","Review the example queries generated from the table by Gemini in BigQuery data insights"],"eEn":"Gemini in BigQuery data insights automatically generates and suggests queries for pattern detection and statistical analysis from table metadata. Data profiles give column statistics without query examples, copied past queries may not fit this table, and default charts do not suggest angles of exploration."},{"id":"h264","d":"D2","q":"データアナリストは、複数のテーブルを探して結合し、結果を可視化して同僚と共有するまでの一連の探索作業を、SQL を一から書かずに自然言語の指示で進めたい。分析の流れを視覚的に残すことも重視している。最も適切な機能はどれか。","o":["Looker Studio のテンプレート ギャラリーから既成のレポートを選び、データソースだけを差し替える","Connected Sheets のピボットテーブルで、複数のテーブルの結合関係をシート上で組み立てる","BigQuery の data canvas で、自然言語によるテーブルの検索・結合・可視化を行う","Colab Enterprise のノートブックに既存の SQL セルをコピーして、順番に実行する"],"a":2,"e":"BigQuery の data canvas は、自然言語でテーブルの検索・結合・クエリ・可視化を行い、分析の流れをキャンバス上に残して共有できる。Looker Studio のテンプレートは既成レポートの流用で、Connected Sheets は結合を自然言語で組み立てる機能ではなく、既存 SQL のコピーは自然言語での探索ではない。","qEn":"A data analyst wants to carry out the whole exploration, from finding and joining several tables to visualizing results and sharing them with colleagues, using natural-language instructions without writing SQL from scratch, and values keeping the analysis flow visible. Which feature is most appropriate?","oEn":["Pick a ready-made report from the Looker Studio template gallery and just swap the data source","Assemble the join relations of several tables on the sheet with a Connected Sheets pivot table","Use BigQuery data canvas to search, join, and visualize tables by natural language","Copy existing SQL cells into a Colab Enterprise notebook and run them in order"],"eEn":"BigQuery data canvas lets you search, join, query, and visualize tables in natural language and keeps the analysis flow on a shareable canvas. Looker Studio templates reuse ready-made reports, Connected Sheets does not build joins from natural language, and copying SQL is not natural-language exploration."},{"id":"h265","d":"D2","q":"チームは Gemini in BigQuery の SQL 生成を使い、自然言語から集計クエリを作らせている。ところが、生成された SQL が列の意味を取り違えて（たとえば税込みと税抜きの売上列）、誤った集計をすることがある。精度を高め、結果を安全に使うための最も適切な対応はどれか。","o":["生成された SQL は常に正しいので、確認を省いて自動でスケジュールクエリとして登録し、毎日の集計と経営報告の数値に使う","テーブルと列に正確な説明を付けたうえで、生成された SQL を実行前に読んで確認し、少量のデータで結果を検証してから使う","列の説明は生成の際に参照されないので、列名をすべて英数字の短縮形に統一して、誤読の余地を減らす","Gemini の生成結果を使うのをやめ、すべての集計 SQL を新人が一から手作業で書き直す運用に戻す"],"a":1,"e":"生成 AI の SQL は列の意味を取り違えることがあるため、テーブルと列の説明などのメタデータを整え、実行前に内容を読み、少量のデータで結果を検証するのが安全である。無確認での自動運用は誤集計を広げ、列名の短縮は文脈を減らし、AI をやめて手作業に戻すのは効率化の目的を捨てる。","qEn":"A team uses SQL generation in Gemini in BigQuery to create aggregate queries from natural language, but generated SQL sometimes misreads column meanings (for example, tax-inclusive versus tax-exclusive sales columns) and aggregates incorrectly. What is the most appropriate response to improve accuracy and use results safely?","oEn":["Generated SQL is always correct, so skip checking and register it as a scheduled query for daily aggregation","Add accurate descriptions to tables and columns, read the generated SQL before running it, and verify results on a small amount of data","Column descriptions are not referenced during generation, so standardize all column names to short alphanumeric forms to reduce room for misreading","Stop using Gemini's output and return to having newcomers hand-write every aggregation SQL from scratch"],"eEn":"Generated SQL can misread column meanings, so it is safest to improve metadata such as table and column descriptions, read the SQL before running it, and verify results on small data. Unchecked automation spreads errors, shortening names removes context, and abandoning AI discards the efficiency goal."},{"id":"h266","d":"D2","q":"BigQuery Studio のノートブック（Colab Enterprise）で、数十人のデータサイエンティストがランタイムを起動したまま帰宅してしまい、夜間も Compute Engine の VM 料金が発生し続けている。利用者の作業に支障を出さずにコストを抑える最も適切な設定はどれか。","o":["全員のノートブックの共有を解除し、管理者が 1 つだけ起動したランタイムを全員で使い回してもらう","ノートブックの最終セルに sys.exit() を書き、すべてのコード実行後にランタイムも終了するようにする","ランタイム テンプレートにアイドル シャットダウンを設定し、一定時間操作がなければ自動停止させる","ランタイムのマシンタイプを最大のものに統一して、処理を短時間で終わらせ、起動時間を短縮する"],"a":2,"e":"Colab Enterprise のランタイムはユーザーごとの VM で、ランタイム テンプレートにアイドル シャットダウンを設定すると、操作がない一定時間後に自動停止して課金を止められる。ランタイムは共有できず、sys.exit() はカーネルを終了するだけで VM を止めず、大きなマシンタイプは料金が増えるだけである。","qEn":"In BigQuery Studio notebooks (Colab Enterprise), dozens of data scientists leave runtimes running when they go home, so Compute Engine VM charges continue overnight. What is the most appropriate setting to cut cost without hampering users' work?","oEn":["Remove sharing of everyone's notebooks and have a single runtime started by an administrator reused by all","Write sys.exit() in the final cell of each notebook so that the runtime also terminates after all code has run","Configure idle shutdown in the runtime template so that runtimes stop automatically after a period of inactivity","Standardize the runtime machine type to the largest one so that processing finishes quickly and runtime hours shrink"],"eEn":"A Colab Enterprise runtime is a per-user VM, and idle shutdown in the runtime template stops it automatically after inactivity to end billing. Runtimes cannot be shared, sys.exit() only ends the kernel without stopping the VM, and a larger machine type just raises cost."},{"id":"h267","d":"D2","q":"データサイエンティストが、数 TB・5 億行の BigQuery テーブルを pandas で分析しようとして to_pandas() でメモリ不足になった。pandas に近い書き方を保ちながら、計算を BigQuery 側で実行して大規模データを扱いたい。最も適切な方法はどれか。","o":["ノートブックのランタイムのメモリを増やして、全行をいったん pandas に読み込んでから同じコードを実行する","BigQuery DataFrames を使い、pandas 互換の API で BigQuery 上で処理する","テーブルを CSV にエクスポートしてローカル PC に保存し、pandas で分割して読み込みながら少しずつ処理する","pandas の head() で先頭の 1,000 行だけを取り出し、その傾向を全体の傾向として扱って分析する"],"a":1,"e":"BigQuery DataFrames は pandas 互換の API でデータを BigQuery 上に置いたまま処理を実行でき、全行をメモリに載せずに済む。数 TB を pandas に読み込むのは現実的でなく、CSV の分割処理は手間と遅延が大きく、先頭 1,000 行の傾向で全体を判断すると偏りで誤る。","qEn":"A data scientist tried to analyze a multi-terabyte, 500-million-row BigQuery table with pandas and ran out of memory at to_pandas(). They want to keep a pandas-like style while executing computation on the BigQuery side to handle large data. What is the most appropriate method?","oEn":["Increase the notebook runtime's memory, load every row into pandas first, and then run the same code","Use BigQuery DataFrames (bigframes) and run the processing in BigQuery through a pandas-compatible API","Export the table to CSV, save it on a local PC, and process it little by little while reading it in chunks with pandas","Take only the first 1,000 rows with pandas head() and treat their trend as the trend of the whole data"],"eEn":"BigQuery DataFrames runs processing in BigQuery through a pandas-compatible API without loading all rows into memory. Loading terabytes into pandas is unrealistic, chunked CSV handling is slow and laborious, and judging the whole by the first 1,000 rows is biased."},{"id":"h268","d":"D2","q":"データサイエンスチームは、BigQuery Studio のノートブックで作った週次のデータ集計と可視化のコードを、人手を介さずに毎週月曜の朝に自動実行して結果を残したい。Cloud Composer を新たに構築する規模ではない。最も適切な方法はどれか。","o":["ノートブックのスケジュール実行を設定し、毎週月曜の朝に実行して出力を残す","ノートブックのコードを Cloud Run に移し、Cloud Shell から毎週手動で呼び出して実行する","BigQuery のスケジュールされたクエリに、ノートブックの Python コードをそのまま貼り付けて登録する","ノートブックを共有し、担当者に毎週月曜の朝に手動で全セルを実行して保存してもらう"],"a":0,"e":"BigQuery Studio のノートブックにはスケジュール実行の機能があり、毎週の自動実行と出力の保存を追加の基盤なしに設定できる。Cloud Shell からの手動呼び出しや手動実行は自動化にならず、スケジュールされたクエリは SQL を実行するもので Python のコードは貼り付けても動かない。","qEn":"A data science team wants the weekly aggregation and visualization code written in a BigQuery Studio notebook to run automatically every Monday morning without human involvement and keep the results. The scale does not justify building Cloud Composer. What is the most appropriate method?","oEn":["Configure a notebook schedule to run every Monday morning and keep the outputs","Move the notebook code to Cloud Run and invoke it manually from Cloud Shell every week","Paste the notebook's Python code directly into a BigQuery scheduled query and register it","Share the notebook and ask the person in charge to run all cells manually and save the result every Monday morning"],"eEn":"BigQuery Studio notebooks can run on a schedule, giving weekly automatic runs and saved outputs without extra infrastructure. Manual calls or runs are not automation, and scheduled queries run SQL, so pasted Python code will not work."},{"id":"h269","d":"D2","q":"物流会社の分析担当は、配送リードタイム（時間）の分布の形と外れ値を、営業所間で比較しながら経営会議に示したい。平均値だけでは遅延の多い営業所が見えない。レポートに最も適したグラフはどれか。","o":["営業所ごとの平均リードタイムを円の面積で示した円グラフを、営業所の数だけ並べたもの","営業所ごとの箱ひげ図","営業所ごとの平均リードタイムの月次推移を線で結んで示した、複数系列の折れ線グラフ","全営業所の平均リードタイムを 1 つの大きな数字と前月比で示した、スコアカード"],"a":1,"e":"箱ひげ図は中央値・四分位・外れ値を示せるため、営業所間で分布の形とばらつきを比較できる。平均だけの円グラフやスコアカードは分布と外れ値を隠し、平均の推移を折れ線にしても営業所内のばらつきは見えない。","qEn":"A logistics analyst wants to show the shape and outliers of delivery lead-time (hours) distributions at a management meeting, comparing sales offices. Averages alone hide offices with many delays. Which chart is most suitable for the report?","oEn":["Pie charts showing each office's average lead time as the area of a circle, one for each office","A box plot for each office","A multi-series line chart connecting each office's monthly trend in average lead time","A scorecard showing the average lead time across all offices as one large number with a month-over-month comparison"],"eEn":"A box plot shows median, quartiles, and outliers, so distribution shape and spread can be compared across offices. Average-only pies and scorecards hide distributions and outliers, and a line of average trends still hides within-office spread."},{"id":"h270","d":"D2","q":"マーケティング担当は、広告費と売上の関係に加え、媒体ごとの傾向の違いを 1 枚のグラフで把握したい。キャンペーンは 300 件あり、広告費と売上はいずれも連続値である。最も適切なグラフはどれか。","o":["広告費を横軸、売上を縦軸にした散布図で、媒体を色分けする","媒体ごとに広告費の合計を積み上げた縦棒グラフに、売上の合計を数値ラベルとして重ねて表示する","300 件の売上を媒体別の円グラフで表示し、広告費はそれぞれのツールチップの中に入れる","売上の推移を時系列の折れ線グラフにして、広告費は別のページの表にまとめて載せる"],"a":0,"e":"2 つの連続値の関係を見るには散布図が適し、色分けで媒体ごとの傾向の違いも分かる。合計の積み上げ棒や円グラフは個々のキャンペーンの関係を隠し、時系列の折れ線と別ページの表では 2 変数の関係を 1 枚で比較できない。","qEn":"A marketer wants to grasp, in one chart, the relationship between ad spend and revenue plus differences in trend by medium. There are 300 campaigns, and both spend and revenue are continuous values. Which chart is most appropriate?","oEn":["A scatter plot with ad spend on the x-axis and revenue on the y-axis, colored by medium","A stacked column chart of total ad spend by medium with total revenue overlaid as numeric labels","Show the revenue of the 300 campaigns in pie charts by medium, with ad spend placed in each tooltip","Plot revenue as a time-series line chart and put ad spend in a table on another page"],"eEn":"A scatter plot suits the relationship between two continuous values, and color shows trend differences by medium. Stacked totals and pies hide per-campaign relationships, and a time-series line plus a table on another page cannot compare the two variables in one chart."},{"id":"h271","d":"D2","q":"ある経営ダッシュボードの棒グラフは、売上の縦軸が 9,500 から始まっており、前年比 2% の増加が 3 倍に伸びたように見えるとの指摘を受けた。誤解を与えない表示に直す最も適切な方法はどれか。","o":["棒グラフの縦軸を 0 から始めるか、増減を示したい場合は前年比の差分を直接表示する","縦軸の開始値をさらに 9,900 まで引き上げて、小さな差でも見やすくなるように棒の差を拡大する","棒グラフを 3D 表示に変更し、奥行きを使って棒どうしの差の大きさを立体的に表現する","縦軸の目盛り線と軸ラベルを非表示にして、軸の開始値が閲覧者の目に付かないようにする"],"a":0,"e":"棒グラフは長さで量を比べるため、縦軸を 0 から始めないと差が誇張される。小さな変化を伝えたい場合は前年比の差分を直接表示する。開始値をさらに上げると誇張が増し、3D 化は比較を難しくし、目盛りを消すと軸の切り詰めが隠れて余計に誤解を招く。","qEn":"A bar chart on an executive dashboard starts its sales axis at 9,500, so a 2 percent year-over-year increase looks like a tripling, as someone pointed out. What is the most appropriate way to correct it so it does not mislead?","oEn":["Start the bar chart's axis at 0, or show the year-over-year difference directly when the change is the message","Raise the axis start value further to 9,900 to enlarge the differences between bars so that even small gaps are visible","Change the bar chart to 3D and use depth to express the size of differences between the bars in three dimensions","Hide the axis gridlines and axis labels so that the axis start value is not noticeable to viewers"],"eEn":"Bars compare quantity by length, so a non-zero axis start exaggerates differences; to convey small change, show the year-over-year difference directly. Raising the start exaggerates more, 3D hinders comparison, and hiding ticks conceals the truncation and misleads further."},{"id":"h272","d":"D2","q":"財務担当は、前年度の営業利益から今年度の営業利益に至るまでに、売上増・原価増・販管費増・為替が、それぞれどれだけ寄与したかを、経営会議で 1 枚のグラフで説明したい。最も適したグラフはどれか。","o":["各要因を別々の系列にして、年度の推移を重ねて表示する積み上げ面グラフ","ウォーターフォール チャート","各要因の金額を全体に占める構成比で示した、円グラフまたはドーナツグラフ","各要因の金額を点としてプロットして、要因どうしの相関を調べる散布図"],"a":1,"e":"ウォーターフォール チャートは、始点の値から各要因の増減が累積して終点に至る過程を順に示せるため、利益の増減要因の説明に最適である。積み上げ面グラフは時系列の構成の推移向きで、円グラフは増減ではなく構成比を示し、散布図は 2 変数の関係を見るもので、増減の累積は示せない。","qEn":"A finance officer wants to explain in one chart at a management meeting how much sales growth, higher cost of goods, higher SG&A, and foreign exchange each contributed in going from last year's operating profit to this year's. Which chart is most suitable?","oEn":["A stacked area chart with each factor as a separate series, showing the trend across fiscal years","A waterfall chart","A pie or donut chart showing each factor's amount as its share of the whole","A scatter plot that plots each factor's amount as a point to examine the correlation among factors"],"eEn":"A waterfall chart shows how each factor's increase or decrease accumulates from the start value to the end, ideal for explaining profit changes. Stacked areas show composition over time, pies show share rather than change, and scatter plots show relationships, not cumulative change."},{"id":"h273","d":"D2","q":"営業ダッシュボードでは、目標達成を緑、未達を赤だけで示している。社内の色覚多様性に配慮するガイドラインに沿って、全員が状態を読み取れる表示に改善したい。最も適切な方法はどれか。","o":["赤と緑の彩度をさらに高くして、2 つの色の違いがはっきり目立つように強調する","状態を 3 段階から 8 段階に増やして、色の種類を増やしながら細かく区別できるようにする","色に加えて、矢印・アイコン・テキストなど形や文字でも状態を示す","色の意味を凡例に小さく載せて、閲覧者に凡例をよく確認するよう周知する"],"a":2,"e":"色だけに頼らず、形・アイコン・文字など別の手がかりを併用すると、色の見分けにくい人にも状態が伝わる。赤と緑の彩度を上げても色覚特性では区別できず、色の種類を増やすとむしろ判別が難しくなり、小さな凡例への依存は読み取りの負担を増やす。","qEn":"A sales dashboard shows target achievement in green and misses in red only. To follow the company's color-vision accessibility guidelines, it should be improved so everyone can read the status. What is the most appropriate method?","oEn":["Increase the saturation of red and green further so that the difference between the two colors stands out clearly","Increase statuses from three levels to eight and add more color types so finer distinctions are possible","Show status with shapes and text such as arrows, icons, and labels in addition to color","Put the meaning of colors in a small legend and notify viewers to check the legend carefully"],"eEn":"Pairing color with other cues such as shapes, icons, and text conveys status to people who have difficulty telling colors apart. Higher saturation does not help for color-vision differences, more colors make discrimination harder, and a small legend adds reading burden."},{"id":"h274","d":"D2","q":"経営会議用のダッシュボードを新規に作る。参加者は 5 分で全社の状況を把握し、気になる点だけを深掘りしたい。これまで 40 個のチャートを 1 ページに並べたレポートは、何を見ればよいか分からないと不評だった。最も適切な設計方針はどれか。","o":["最上部に重要な指標を 5 個前後のスコアカードで目標比つきで置き、詳細は別ページへのドリルダウンで見せる","1 ページに収めることを優先し、40 個のチャートをさらに小さくして余白を詰めた配置にする","すべての指標を同じ大きさと色で並べ、どれが重要かの判断は閲覧者に任せることで、見せ方による偏りを避け、中立的に提示する","指標の定義と計算式の説明を各チャートの隣に長い文章で併記し、解釈の誤りを防ぎ、定義の読み飛ばしがないようにする"],"a":0,"e":"経営向けは、結論を先に示すために重要指標を少数のスコアカードに絞り目標比を添え、詳細はドリルダウンで必要な人だけが見る構成が適する。チャートを小さく詰めると読みにくく、同じ見た目で並べると重要度が伝わらず、長い説明文の併記はかえって情報過多を招く。","qEn":"A new dashboard is being built for executive meetings. Participants want to grasp the company's situation in five minutes and drill into only what concerns them. A previous report with 40 charts on one page was unpopular because no one knew what to look at. What is the most appropriate design policy?","oEn":["Place about five key metrics at the top as scorecards with target comparisons and show details through drill-down to other pages","Prioritize fitting everything on one page by shrinking the 40 charts further and tightening the margins","Line up all metrics at the same size and color and leave it to viewers to decide which are important","Write long explanations of metric definitions and formulas next to each chart to prevent misinterpretation so that nobody can skip the definitions"],"eEn":"For executives, a few scorecards with target comparisons present the conclusion first, with details via drill-down for those who need them. Shrinking charts hurts legibility, uniform styling hides importance, and long explanations cause information overload."},{"id":"h275","d":"D2","q":"コールセンターの運用担当は、曜日と時間帯ごとの着信数のパターンを一目で把握し、シフトの配置を決めたい。データは 7 曜日 × 24 時間帯の集計で、強弱の傾向を見たい。最も適したグラフはどれか。","o":["曜日ごとに時間帯別の着信構成を円グラフにして、7 枚を横に並べて表示する","曜日を行、時間帯を列にして、着信数を色の濃淡で示すヒートマップ","時間帯ごとの着信数の平均だけを示したスコアカードを、24 個並べて表示する","着信数の合計を 1 本の折れ線にして、曜日と時間帯を区別せずに時系列で示す"],"a":1,"e":"2 つのカテゴリ軸の組み合わせごとの量の強弱を見るには、色の濃淡で示すヒートマップが適する。曜日別の円グラフは時間帯の変化を比べにくく、時間帯別の平均だけでは曜日差が消え、曜日と時間帯の 2 軸のパターンを同時に把握できない。","qEn":"A call-center operations lead wants to see at a glance the pattern of incoming calls by day of week and hour in order to decide shift allocation. The data is a 7 weekdays x 24 hours aggregation, and the goal is to see intensity trends. Which chart is most suitable?","oEn":["Make a pie chart of the hourly call composition for each weekday and display seven of them side by side","A heat map with weekdays as rows and hours as columns, showing call counts by color intensity","Display 24 scorecards, each showing only the average call count for an hour","Show total calls as a single line in time series without distinguishing weekday and hour"],"eEn":"A heat map showing intensity by color suits quantities across two categorical axes. Per-weekday pies make hourly change hard to compare, hourly averages erase weekday differences, and neither captures the two-axis pattern at once."},{"id":"h276","d":"D2","q":"商品カテゴリが 12 個あり、各カテゴリの売上構成比を役員向けの資料で示したい。小さなカテゴリの比率も正確に比較できるようにしたいが、円グラフでは区別がつかないとの指摘を受けた。最も適切な代替案はどれか。","o":["構成比の降順に並べた横棒グラフにして、各棒に数値ラベルを付ける","12 色の円グラフのままドーナツ型に変更して、中央に売上の合計値を大きく表示する","円グラフを 3D 表示にして、小さなカテゴリの扇形を手前に押し出して目立たせる","全カテゴリを積み上げた 1 本の縦棒グラフにして、カテゴリを色だけで区別する"],"a":0,"e":"カテゴリが多いと円グラフは角度や面積の比較が難しく、並べ替えた棒グラフなら長さで正確に比較できる。ドーナツ型や 3D は読み取りがさらに難しくなり、1 本の積み上げ縦棒も小さな区分の比較が困難である。","qEn":"There are 12 product categories, and the sales share of each must be shown in a document for executives. Small categories' shares should also be comparable accurately, but it was pointed out that a pie chart cannot distinguish them. What is the most appropriate alternative?","oEn":["Use a horizontal bar chart sorted by share in descending order, with value labels on each bar","Keep the 12-color pie but change it to a donut and show the total sales large in the center","Make the pie 3D and push the slices of small categories toward the front to make them stand out","Stack all categories into a single column chart and distinguish categories by color alone"],"eEn":"With many categories, comparing angles and areas in a pie is hard, whereas sorted bars allow precise comparison by length. Donut and 3D are harder to read still, and one stacked column makes small segments hard to compare."},{"id":"h277","d":"D2","q":"LookML の orders ビューには created_at の列があり、現在は created_date、created_week、created_month というディメンションを DATE_TRUNC で 1 つずつ手書きしている。保守が煩雑で、年や四半期も欲しいという要望が出ている。LookML で最も適切な定義方法はどれか。","o":["dimension_group（type: time）を定義し、timeframes に期間の粒度を列挙する","measure を type: date で定義して、期間の粒度ごとに別々の measure を追加していく","dimension を type: string で定義し、SQL に FORMAT_DATE を書いて期間ごとの文字列を作り、並べ替えにも使う","derived_table に期間ごとの列を事前計算した SELECT を書き、PDT として毎晩再構築する"],"a":0,"e":"dimension_group の type: time は 1 つの時刻列から、timeframes に挙げた date・week・month・quarter・year などのディメンションを自動生成でき、保守も簡単になる。measure は集計で時刻の分解に使えず、string 化は日付の並べ替えを損ない、PDT での事前計算は過剰である。","qEn":"The LookML orders view has a created_at column, and the team hand-writes dimensions created_date, created_week, and created_month one by one with DATE_TRUNC. Maintenance is cumbersome, and requests for year and quarter have come in. What is the most appropriate way to define this in LookML?","oEn":["Define a dimension_group of type: time and list the period granularities in timeframes","Define measures of type: date and add a separate measure for each period granularity","Define dimensions of type: string, write FORMAT_DATE in SQL to build strings per period, and use them for sorting as well","Write a SELECT with per-period columns precomputed in a derived_table and rebuild it every night as a PDT"],"eEn":"A dimension_group of type: time generates dimensions such as date, week, month, quarter, and year from a single time column per timeframes, simplifying maintenance. Measures aggregate rather than decompose time, strings spoil date ordering, and PDT precomputation is excessive."},{"id":"h278","d":"D4","q":"データ分析部門には 60 人のアナリストがおり、入退社や異動が毎月のようにある。BigQuery のデータセットへの閲覧権限を個人のユーザーごとにロールとして付与してきたが、退職者の権限の剥奪漏れが監査で指摘された。権限管理を最も確実で運用しやすくする方法はどれか。","o":["ロールの付与時に有効期限の条件をすべてのユーザーに付けて、期限が来たら自動で失効するようにする","アナリストごとに専用のサービス アカウントを作成し、個人ではなくそのサービス アカウントにロールを付与する","Google グループにロールを付与し、メンバーの追加と削除でアクセスを管理する","四半期ごとに IAM ポリシーの JSON をエクスポートし、担当者が目視で棚卸しして不要な行を削除する運用にする"],"a":2,"e":"個人ではなくグループにロールを付与すると、入退社や異動のたびに IAM ポリシーを変更せず、グループのメンバー管理だけでアクセスを付け外しでき、剥奪漏れも減る。一律の有効期限は継続的な業務権限に合わず、人別のサービス アカウントは人の認証の代替にならず、目視の棚卸しは漏れを防げない。","qEn":"The analytics department has 60 analysts with joiners, leavers, and transfers nearly every month. Viewing permissions on BigQuery datasets have been granted as roles to individual users, and an audit found missed revocations for leavers. Which approach makes permission management most reliable and easy to operate?","oEn":["Attach an expiration condition to every user's role grant so that it expires automatically when the date arrives","Create a dedicated service account for each analyst and grant the roles to those service accounts rather than to individuals","Grant the roles to a Google group and manage access by adding and removing members","Export the IAM policy JSON every quarter and have a person inventory it by eye and delete unnecessary entries"],"eEn":"Granting roles to a group lets access be added or removed through group membership without changing IAM policy on every joiner, leaver, or transfer, reducing missed revocations. Uniform expiry does not fit ongoing duties, per-person service accounts do not replace human identity, and eyeball reviews miss things."},{"id":"h279","d":"D4","q":"AWS 上で動く CI/CD パイプラインが、Google Cloud の BigQuery にテスト結果を書き込む必要がある。これまではサービス アカウントのキー（JSON）を発行して AWS のシークレットに保存していたが、漏洩のリスクとローテーションの負担が問題になっている。キーを使わずに安全に認証する最も適切な方法はどれか。","o":["Workload Identity 連携を構成し、AWS の ID から一時的な認証情報を得てサービス アカウントを借用する","サービス アカウントのキーの有効期限を無期限に設定して、ローテーションの作業そのものをなくし、保管場所は AWS のシークレットのまま変えない","AWS 側の固定のパブリック IP アドレスだけを許可する IAM の条件を設定して、認証の手順そのものを省略する","キーを Cloud Storage のバケットに保存しておき、パイプラインの実行のたびに毎回ダウンロードして利用する"],"a":0,"e":"Workload Identity 連携では、AWS などの外部 ID を信頼して短期の認証情報に交換するため、長期のサービス アカウント キーが不要になる。キーを無期限にすると漏洩リスクが増し、IP の条件だけで認証を省くことはできず、キーを別の場所に置いても長期キーの管理負担は残る。","qEn":"A CI/CD pipeline running on AWS must write test results to BigQuery on Google Cloud. It has used a service account key (JSON) stored in AWS secrets, but leakage risk and rotation burden are problems. What is the most appropriate way to authenticate securely without keys?","oEn":["Configure Workload Identity Federation and obtain short-lived credentials from the AWS identity to impersonate the service account","Set the service account key to never expire so that the rotation work itself disappears and operational effort is minimized while the key stays stored in AWS secrets","Set an IAM condition that allows only AWS's fixed public IP addresses and omit the authentication procedure itself","Store the key in a Cloud Storage bucket and download and use it every time the pipeline runs"],"eEn":"Workload Identity Federation trusts an external identity such as AWS's and exchanges it for short-lived credentials, so long-lived service account keys are unnecessary. Non-expiring keys raise leak risk, IP conditions cannot replace authentication, and moving the key elsewhere keeps the burden."},{"id":"h280","d":"D4","q":"セキュリティ監査で、プロジェクトに 30 本以上のダウンロード済みサービス アカウント キーが見つかった。組織としては今後キーの新規作成を禁止し、開発者には代替の認証方法を使わせる方針である。組織全体で新規のキー作成を確実に防ぐ最も適切な方法はどれか。","o":["組織のポリシーで iam.disableServiceAccountKeyCreation 制約を適用する","開発者向けの手順書に、キーを作成しないよう明記して全員に周知し、新規参加者の研修でも説明する","サービス アカウントごとにキーの有効期限を 30 日に設定して、古いキーが自動的に失効するようにし、新しいキーの発行は随時認める","Cloud Audit Logs でキーの作成を検知し、作成されるたびにセキュリティ担当へメールで通知する"],"a":0,"e":"組織のポリシー制約 iam.disableServiceAccountKeyCreation を適用すると、対象の範囲でキーの新規作成が拒否される。手順書での周知は強制力がなく、有効期限を設けても作成自体は止められず、監査ログの通知は作成後に気付くだけで予防にならない。","qEn":"A security audit found more than 30 downloaded service account keys in a project. The organization will prohibit creating new keys and have developers use alternative authentication. What is the most appropriate way to reliably prevent new key creation across the organization?","oEn":["Enforce the iam.disableServiceAccountKeyCreation constraint through Organization Policy","State clearly in the developer guide not to create keys, announce it to everyone, and explain it in training for new joiners","Set a 30-day key expiry on each service account so that old keys expire automatically","Detect key creation in Cloud Audit Logs and notify the security team by email each time one is created"],"eEn":"Enforcing the iam.disableServiceAccountKeyCreation constraint makes new key creation fail within scope. A guide has no enforcement, expiry does not stop creation, and audit-log notifications only reveal creation afterwards instead of preventing it."},{"id":"h281","d":"D4","q":"開発者が、本番のデータパイプラインが使うサービス アカウントの権限で BigQuery のクエリを再現し、権限不足の原因を調べたい。サービス アカウントのキーは発行したくなく、誰がいつ借用したかも監査ログに残したい。最も適切な方法はどれか。","o":["サービス アカウントのキーを一時的に発行して調査に使い、調査が終わったらキーを削除する運用にする","開発者に本番プロジェクトの Owner ロールを付与し、サービス アカウントの設定を直接確認、変更できるようにする","サービス アカウントのパスワードを共有し、Google Cloud コンソールにそのアカウントでログインして調査させる","対象のサービス アカウントに Service Account Token Creator ロールを付与して、借用させる"],"a":3,"e":"Token Creator ロールでサービス アカウントを借用すると、キーを発行せずに短期の認証情報で動作でき、借用の操作が監査ログに残る。一時的でもキーの発行は漏洩の余地を残し、Owner の付与は過剰な権限で、サービス アカウントにはパスワードがなくコンソールにログインできない。","qEn":"A developer wants to reproduce BigQuery queries with the permissions of the service account used by a production data pipeline to investigate missing permissions. No service account key should be issued, and who impersonated it and when must be recorded in audit logs. What is the most appropriate method?","oEn":["Issue a service account key temporarily for the investigation and delete it once the investigation is over","Grant the developer the Owner role on the production project so they can check and change the service account's settings directly","Share the service account's password and have the developer log in to the Google Cloud console as that account to investigate","Grant the Service Account Token Creator role on the target service account and have the developer impersonate it"],"eEn":"Impersonating through Token Creator works with short-lived credentials without issuing a key, and the impersonation is recorded in audit logs. Even temporary keys leave room for leakage, Owner is excessive, and service accounts have no passwords to log in with."},{"id":"h282","d":"D4","q":"データ基盤の立ち上げ期に、時間がなく多くのサービス アカウントへ広めのロールを付与した。半年が経ち、実際に使われている権限は一部だけだと分かっている。実際の利用状況に基づいて余分な権限を特定し、ロールを絞り込む最も適切な方法はどれか。","o":["Security Command Center の検出結果から、公開されているバケットの一覧を取り出して、その権限を見直す","全サービス アカウントのロールをいったんすべて削除し、エラーが出たものから順番に付け直していく","IAM Recommender のロールの推奨事項を確認し、使用状況に基づく、より狭いロールへ置き換える","Cloud Billing のレポートで利用料金の少ないサービス アカウントを選び、そのロールを削除する"],"a":2,"e":"IAM Recommender は過去の権限の使用状況を分析し、使われていない権限を除いた、より狭いロールへの置き換えを提案する。公開バケットの検出結果は権限の使用実績ではなく、全削除は本番を止める恐れがあり、料金の少なさは権限の過剰さを示さない。","qEn":"During the platform's launch period, broad roles were granted to many service accounts for lack of time. Six months later, only some permissions are known to be actually used. What is the most appropriate way to identify excess permissions from actual usage and narrow the roles?","oEn":["Take the list of publicly exposed buckets from Security Command Center findings and review their permissions","Delete the roles of all service accounts once and re-grant them one by one starting with those that produce errors","Review IAM Recommender role recommendations and replace roles with narrower ones based on usage","Pick the service accounts with low charges in Cloud Billing reports and delete their roles"],"eEn":"IAM Recommender analyzes past permission usage and suggests narrower roles without unused permissions. Public-bucket findings are not usage evidence, deleting everything risks outages, and low charges do not indicate excess permissions."},{"id":"h283","d":"D4","q":"新しく参加したアナリストが BigQuery のデータセットにクエリを実行しようとして、アクセス拒否のエラーになる。本人が属するグループには閲覧ロールが付与されているはずだが、どの設定が原因か分からない。原因の特定に最も適したツールはどれか。","o":["Cloud Monitoring のアラート ポリシーを作成して、アクセス拒否の回数がしきい値を超えたら通知するようにする","Policy Troubleshooter で、そのユーザーとリソースと権限の組み合わせの許可または拒否される理由を調べる","Dataplex のデータ品質スキャンを実行して、そのデータセットに対する閲覧の可否を検証させる","本人に一時的に BigQuery 管理者ロールを付与して、拒否されなくなるかどうかを試して確かめる"],"a":1,"e":"Policy Troubleshooter は、指定したプリンシパルとリソースと権限について、どの許可ポリシーや拒否ポリシー、継承が効いているかを示して原因を特定できる。アラート ポリシーは通知だけで原因を示さず、データ品質スキャンは権限と無関係で、管理者の付与は過剰権限を与えるだけである。","qEn":"A newly joined analyst gets an access-denied error when querying a BigQuery dataset. The group they belong to should have a viewer role, but the cause is unclear. Which tool is best suited to identify the cause?","oEn":["Create a Cloud Monitoring alerting policy that notifies when the number of access denials exceeds a threshold","Use Policy Troubleshooter to examine why access is allowed or denied for that user, resource, and permission combination","Run a Dataplex data quality scan and have it verify whether viewing that dataset is allowed for the user and report the result","Temporarily grant the person the BigQuery Admin role and test whether the denial disappears"],"eEn":"Policy Troubleshooter shows which allow policies, deny policies, and inheritance apply to a given principal, resource, and permission, identifying the cause. Alerting only notifies, data quality scans are unrelated to permissions, and granting admin just over-provisions."},{"id":"h284","d":"D4","q":"監査人から、顧客データを含む BigQuery データセットにアクセスできる全員を、グループ経由や上位フォルダからの継承も含めて一覧で出してほしいという依頼があった。IAM ポリシーを 1 つずつ開いて調べるのは現実的でない。最も適切な方法はどれか。","o":["データセットの共有画面に表示されるユーザーの一覧を、画面のスクリーンショットにして監査人に提出する","Cloud Audit Logs の Data Access ログを集計して、過去にクエリを実行したユーザーの一覧を提出する","Policy Analyzer で、対象リソースにアクセスできるプリンシパルを分析する","組織のルート フォルダの IAM ポリシーだけをエクスポートして、そこに載っているメンバーの一覧を提出する"],"a":2,"e":"Policy Analyzer は IAM ポリシーを分析して、グループの展開や継承を含め、対象リソースにアクセスできるプリンシパルを一覧にできる。データセット画面の一覧は継承分を含まず、監査ログは実際の利用者であって権限を持つ人ではなく、ルートのポリシーだけでは下位の付与を見落とす。","qEn":"An auditor asked for a list of everyone who can access a BigQuery dataset containing customer data, including access through groups and inheritance from higher-level folders. Opening IAM policies one by one is impractical. What is the most appropriate method?","oEn":["Submit to the auditor a screenshot of the list of users shown on the dataset's sharing screen","Aggregate the Data Access logs in Cloud Audit Logs and submit a list of users who ran queries in the past","Analyze the principals who can access the target resource with Policy Analyzer","Export only the IAM policy of the organization's root folder and submit the list of members shown there"],"eEn":"Policy Analyzer analyzes IAM policies and lists principals who can access the resource, expanding groups and inheritance. The dataset screen omits inherited access, audit logs show actual users rather than those with permission, and the root policy alone misses lower-level grants."},{"id":"h285","d":"D4","q":"プロジェクトの管理者グループなど、複数のグループに広いロールが付与されている。そのうえで、どのロールが付与されていても、BigQuery のテーブル削除（bigquery.tables.delete）だけは特定の運用管理グループ以外にはできないようにしたい。個々のロールを編集せずに実現する最も適切な方法はどれか。","o":["各グループに付与したロールをすべて外し、削除の権限を含まない別のロールに 1 グループずつ付け替える","テーブルごとに行レベルのアクセスポリシーを追加して、削除の権限を持つ行を運用管理グループだけに限定する","IAM の拒否ポリシーで対象の権限を拒否し、運用管理グループを例外のプリンシパルに指定する","データセットの既定のテーブル有効期限を設定して、人手による削除操作が起きにくい状態にしておく"],"a":2,"e":"拒否ポリシーは許可ポリシーより優先して評価され、例外のプリンシパルを指定できるので、付与済みのロールを編集せずに特定の権限だけを禁止できる。ロールの付け替えは作業量が大きく、行レベルポリシーは行の可視範囲の制御で削除権限と関係がなく、有効期限は削除操作を防がない。","qEn":"Several groups, such as project administrators, have broad roles. Whatever roles are granted, the BigQuery table deletion permission (bigquery.tables.delete) should be usable only by a specific operations group. What is the most appropriate way to achieve this without editing individual roles?","oEn":["Remove all roles granted to the groups and switch them one group at a time to other roles that do not include deletion","Add row-level access policies to each table so that rows with deletion permission are limited to the operations group","Deny the permission with an IAM deny policy and specify the operations group as an exception principal","Set a default table expiration on the dataset so that manual deletion operations are less likely to occur"],"eEn":"Deny policies take precedence over allow policies and accept exception principals, so one permission can be prohibited without editing granted roles. Swapping roles is heavy work, row-level policies control row visibility rather than deletion, and expiration does not prevent deletion."},{"id":"h286","d":"D4","q":"ある企業で、従業員が誤って個人の Gmail アカウントに BigQuery データセットの閲覧権限を付与してしまう事故が起きた。組織のドメイン以外のアカウントには、IAM ポリシーでロールを付与できないようにしたい。最も適切な対策はどれか。","o":["VPC Service Controls の境界を作成して、境界の外部にあるアカウントを自動的に IAM のポリシーから削除させる","BigQuery のデータセットごとに行レベルのアクセスポリシーを設定し、自社ドメインのメールだけを許可する","Cloud Audit Logs を毎週確認し、外部のアカウントへ付与した記録があれば担当者が手動で取り消す","組織のポリシーの iam.allowedPolicyMemberDomains 制約で、許可するドメインを自社に限定する"],"a":3,"e":"iam.allowedPolicyMemberDomains の制約を組織で適用すると、許可したドメイン以外のプリンシパルへの IAM ロールの付与そのものが拒否される。VPC Service Controls は API アクセスの境界で IAM のメンバーを管理せず、行レベルポリシーは行の可視範囲の制御で、週次の確認は事後対応にとどまる。","qEn":"At a company, an employee mistakenly granted view access to a BigQuery dataset to a personal Gmail account. The company wants to prevent roles from being granted in IAM policies to accounts outside the organization's domain. What is the most appropriate measure?","oEn":["Create a VPC Service Controls perimeter that automatically removes accounts outside the perimeter from IAM and denies everyone else","Set row-level access policies on each BigQuery dataset that allow only email addresses in the company's domain","Review Cloud Audit Logs weekly and have a person manually revoke any grant recorded for an external account","Limit the allowed domains to the company's own with the iam.allowedPolicyMemberDomains organization policy constraint"],"eEn":"Enforcing iam.allowedPolicyMemberDomains rejects IAM role grants to principals outside the allowed domains. VPC Service Controls is an API perimeter that does not manage IAM members, row-level policies control row visibility, and weekly reviews remain after-the-fact."},{"id":"h287","d":"D4","q":"Cloud Storage の分析用バケットで、オブジェクトごとに ACL が付けられて権限の全体像が把握できなくなり、一部のオブジェクトが誤って公開されていた。バケットの権限を IAM に一本化し、インターネットへの公開も確実に防ぎたい。最も適切な設定はどれか。","o":["毎晩スクリプトでバケット内の全オブジェクトの ACL を確認し、公開になっているものを手動で非公開に戻す","バケット名を推測されにくいランダムな文字列に変更して、公開されていても見つからないようにする","前段に Cloud CDN を配置してキャッシュのキーに署名を付け、公開オブジェクトへのアクセスを制御する","均一なバケットレベルのアクセスを有効にして ACL を無効にし、公開アクセスの防止を適用する"],"a":3,"e":"均一なバケットレベルのアクセスは ACL を無効にして IAM に一本化し、公開アクセスの防止を適用すると allUsers などへの公開付与自体が拒否される。夜間スクリプトは事後対応で、名前の秘匿は防御にならず、CDN の署名は配信方法の制御でバケット側の誤った公開設定を防がない。","qEn":"In a Cloud Storage analytics bucket, per-object ACLs made the overall permissions impossible to grasp, and some objects were exposed publicly by mistake. The team wants to consolidate bucket permissions in IAM and reliably prevent internet exposure. Which setting is most appropriate?","oEn":["Check the ACLs of all objects in the bucket with a script every night and manually return any public ones to private","Rename the bucket to a random string that is hard to guess so that exposed objects cannot be found","Place Cloud CDN in front, attach signatures to cache keys, and control access to public objects","Enable uniform bucket-level access to disable ACLs and enforce public access prevention"],"eEn":"Uniform bucket-level access disables ACLs and consolidates in IAM, and public access prevention rejects grants to allUsers and the like. A nightly script is reactive, hiding the name is not a defense, and CDN signing controls delivery but not bucket-side exposure."},{"id":"h288","d":"D4","q":"BigQuery の raw データセットにはソース テーブルが数百ある。分析チーム向けに、列を絞った 80 個のビューを別のデータセットに用意しているが、ビューを追加するたびに raw 側でそのビューを承認する手間が発生している。分析チームに raw への直接アクセスを与えないまま、承認の運用を簡素にする最も適切な方法はどれか。","o":["分析チームに raw データセットの BigQuery データ閲覧者ロールを付与して、ビューごとの承認を不要にする","ビューのあるデータセットを、raw データセットの承認済みデータセットとして登録する","80 個のビューを 1 つの大きなビューに統合して、承認する対象を 1 個に減らす","raw データセットの全テーブルを分析チームのデータセットへ複製し、ビューの参照先を複製に切り替える"],"a":1,"e":"承認済みデータセットを使うと、そのデータセット内のビューがまとめて raw のテーブルを参照できるようになり、ビューの追加ごとの承認が不要になる。閲覧者ロールの付与は直接アクセスを許してしまい、ビューの統合は設計を壊し、全テーブルの複製はコストと同期の負担が大きい。","qEn":"A BigQuery raw dataset has hundreds of source tables. 80 column-restricted views for the analytics team sit in another dataset, and each new view must be authorized on the raw side. What is the most appropriate way to simplify authorization without giving the analytics team direct access to raw?","oEn":["Grant the analytics team the BigQuery Data Viewer role on the raw dataset so that per-view authorization is unnecessary","Register the dataset containing the views as an authorized dataset of the raw dataset","Merge the 80 views into one large view to reduce the number of items to authorize to one","Copy all tables of the raw dataset into the analytics team's dataset and switch the views to reference the copies"],"eEn":"With an authorized dataset, all views in it can reference the raw tables together, so each new view needs no separate authorization. Granting a viewer role gives direct access, merging views breaks the design, and copying all tables adds cost and sync burden."},{"id":"h289","d":"D4","q":"データカタログ担当のチームは、全社の BigQuery データセットについて、テーブル名・スキーマ・説明文を閲覧して整備するが、テーブルの中身の行は見てはならない。最小権限の原則に沿った、最も適切なロールはどれか。","o":["BigQuery メタデータ閲覧者（roles/bigquery.metadataViewer）","BigQuery データ閲覧者（roles/bigquery.dataViewer）を、組織のレベルで広く付与する","BigQuery ユーザー（roles/bigquery.user）を、各プロジェクトのレベルでチームに付与する","BigQuery データ編集者（roles/bigquery.dataEditor）を、対象となる各データセットに付与する"],"a":0,"e":"BigQuery メタデータ閲覧者は、テーブルやデータセットのメタデータを参照でき、行データは読めない。データ閲覧者はテーブルの行を読めてしまい、BigQuery ユーザーはジョブの実行などを含み、データ編集者はデータの変更権限まで含むため、いずれも最小権限を超える。","qEn":"The data catalog team will browse and maintain table names, schemas, and descriptions of all BigQuery datasets, but must not see the rows inside tables. Following least privilege, which role is most appropriate?","oEn":["BigQuery Metadata Viewer (roles/bigquery.metadataViewer)","BigQuery Data Viewer (roles/bigquery.dataViewer), granted broadly at the organization level","BigQuery User (roles/bigquery.user), granted to the team at each project level","BigQuery Data Editor (roles/bigquery.dataEditor), granted on each target dataset"],"eEn":"Metadata Viewer can see metadata of tables and datasets but cannot read row data. Data Viewer can read table rows, BigQuery User includes running jobs, and Data Editor includes data modification, so all exceed least privilege."},{"id":"h290","d":"D4","q":"全社のデータは data-lake プロジェクトの BigQuery にあり、マーケティング部は自部門の予算で分析したい。クエリの課金を marketing-analytics プロジェクトに計上しつつ、データ自体は data-lake のものを読み取りだけで利用させたい。最も適切な権限設計はどれか。","o":["グループに data-lake プロジェクトでジョブユーザーとデータ閲覧者の両方を付与し、data-lake 側でクエリを実行させて、権限の付与先を 1 か所にまとめる","marketing-analytics プロジェクトにだけデータ閲覧者を付与すれば、他のプロジェクトのデータも読めるようになる","data-lake のテーブルを marketing-analytics へ毎日コピーして、コピー側のテーブルだけを使わせる","marketing-analytics でジョブユーザーを、data-lake の対象データセットでデータ閲覧者をグループに付与する"],"a":3,"e":"クエリ ジョブの課金は、ジョブを実行したプロジェクトに計上される。実行側にジョブユーザー、データ側のデータセットにデータ閲覧者を付与すれば、課金とデータの所在を分けられる。data-lake で実行すると課金もそこに計上され、実行側だけの付与では他のプロジェクトのデータは読めず、毎日のコピーは重複保管の負担を生む。","qEn":"Company data sits in BigQuery in the data-lake project, and the marketing department wants to analyze on its own budget. Query charges should go to the marketing-analytics project while the data in data-lake is used read-only. What is the most appropriate permission design?","oEn":["Grant the group both Job User and Data Viewer in the data-lake project and have them run queries on the data-lake side","Granting Data Viewer only on the marketing-analytics project will let them read data in other projects as well","Copy the data-lake tables to marketing-analytics every day and let them use only the copied tables","Grant the group BigQuery Job User in marketing-analytics and Data Viewer on the target dataset in data-lake"],"eEn":"Query charges go to the project that runs the job. Granting Job User on the running side and Data Viewer on the data side separates billing from data location. Running in data-lake bills there, running-side grants alone cannot read other projects' data, and daily copies duplicate storage."},{"id":"h291","d":"D4","q":"コールセンターのサポート担当には、顧客の電話番号の下 4 桁だけを見せて本人確認に使わせ、データ分析チームには全桁を参照させたい。電話番号の列は 1 つの BigQuery テーブルにあり、テーブルの複製やビューの増設はせずに、ユーザーごとに見え方を変えたい。最も適切な方法はどれか。","o":["電話番号の列を SHA-256 でハッシュした値に置き換えて、サポート担当にも分析チームにも同じ列を見せる","サポート担当用に下 4 桁だけを持つテーブルを別に作成し、元のテーブルと毎日同期して参照させ、サポート担当には元のテーブルを見せない","電話番号の列を暗号化して保存し、サポート担当には復号用の鍵を渡さずに暗号化された値のまま見せる","列にポリシータグを付けて末尾 4 文字のマスキングを設定し、サポート担当にマスクされたデータの閲覧者を付与する"],"a":3,"e":"ポリシータグとデータマスキング ポリシーを使うと、同じ列をユーザーの権限に応じてその場でマスクして返せる。マスクされたデータの閲覧者には下 4 桁だけが見え、元データの読み取り権限を持つ人は全桁を見られる。ハッシュ置換は全員から元の値を奪い、別テーブルは同期の負担を生み、暗号化では下 4 桁を見せられない。","qEn":"Support agents at a call center should see only the last four digits of a customer's phone number to verify identity, while the analytics team should see all digits. The column is in one BigQuery table, and the visibility must differ per user without duplicating the table or adding views. What is the most appropriate method?","oEn":["Replace the phone number column with a SHA-256 hash and show the same column to both support agents and the analytics team","Create a separate table holding only the last four digits for support agents and keep it synchronized with the original every day","Store the phone number column encrypted and show support agents the encrypted values without giving them the decryption key","Attach a policy tag to the column, set last-four-characters masking, and grant support agents the masked reader role"],"eEn":"Policy tags with data masking policies mask the same column on the fly according to permission: masked readers see the last four digits, and those with raw read access see everything. Hashing removes the original for everyone, a separate table adds sync burden, and encryption cannot reveal the last four."},{"id":"h292","d":"D4","q":"ポリシータグの分類（タクソノミ）に、親タグ『機微情報』の下に『マイナンバー』『口座番号』『生年月日』の子タグを作った。情報セキュリティ部門のグループには、この 3 種類すべての列を読めるようにしたい。作業が最も少なく、将来の子タグの追加にも追随する付与方法はどれか。","o":["3 つの子タグのそれぞれにロールを付与し、子タグを追加するたびに同じ付与を繰り返す運用にする","情報セキュリティ部門のグループに BigQuery データ閲覧者ロールをプロジェクトのレベルで付与する","親タグ『機微情報』に対して、情報セキュリティ部門の各グループにきめ細かい読み取り権限のロールを付与する","タクソノミの子タグをすべて削除し、各列に対して IAM の列レベルの権限を直接設定する"],"a":2,"e":"ポリシータグの階層では親タグへの付与が子タグにも及ぶため、親にきめ細かい読み取り権限のロールを付与すれば、現在と将来の子タグの列を読める。子タグごとの付与は追加のたびに作業が増え、データ閲覧者だけでは保護された列を読めず、列に直接付ける IAM 権限はない。","qEn":"In a policy tag taxonomy, child tags My Number, Account Number, and Date of Birth were created under a parent tag Sensitive. The information security group should be able to read columns of all three kinds. Which grant method needs the least work and also follows future child-tag additions?","oEn":["Grant the role on each of the three child tags and repeat the same grant every time a child tag is added","Grant the information security group the BigQuery Data Viewer role at the project level","Grant the information security group the fine-grained reader role on the parent tag Sensitive","Delete all child tags in the taxonomy and set IAM column-level permissions directly on each column"],"eEn":"In a policy tag hierarchy, a grant on the parent extends to child tags, so granting the fine-grained reader role on the parent covers present and future children. Per-child grants add work, Data Viewer alone cannot read protected columns, and IAM has no direct column-level permissions."},{"id":"h293","d":"D4","q":"売上テーブルに、地域グループごとに自地域の行だけを見せる行アクセスポリシーを作成した。ところが、本社の経営企画グループはどのポリシーの対象にも含まれておらず、クエリしても結果が 0 行になる。経営企画グループには全行を見せたい。最も適切な対応はどれか。","o":["経営企画グループを対象に、FILTER USING (TRUE) の行アクセスポリシーを追加する","テーブルのすべての行アクセスポリシーを削除して、権限の制御をデータセット単位のロールだけに戻す","経営企画グループが実行するクエリに WHERE 1=1 を付けて、ポリシーの条件を回避できるようにする","既存の各ポリシーの対象に allAuthenticatedUsers を追加して、地域の条件も TRUE に書き換える"],"a":0,"e":"行アクセスポリシーは、どのポリシーにも該当しないユーザーに 0 行を返す。全行を見せたいグループには FILTER USING (TRUE) のポリシーを追加すればよい。ポリシーの全削除は地域ごとの制限を失い、WHERE 句ではポリシーを回避できず、全認証ユーザーへの TRUE は他地域の担当にも全行を見せてしまう。","qEn":"Row access policies were created on a sales table so each regional group sees only its own region's rows. The headquarters planning group is not a grantee of any policy, so its queries return zero rows. The planning group should see all rows. What is the most appropriate response?","oEn":["Add a row access policy with FILTER USING (TRUE) for the planning group","Delete all row access policies on the table and return control to dataset-level roles only","Add WHERE 1=1 to queries run by the planning group so that they can bypass the policy conditions","Add allAuthenticatedUsers as a grantee of each existing policy and rewrite the regional condition to TRUE"],"eEn":"Row access policies return zero rows to users covered by no policy. Add a FILTER USING (TRUE) policy for the group that needs all rows. Deleting all policies loses regional restrictions, WHERE cannot bypass policies, and TRUE for all authenticated users exposes everything to other regions."},{"id":"h294","d":"D4","q":"開発チームが新機能のテスト用に、本番の顧客テーブル（氏名・メール・電話番号を含む）に近い性質のデータを開発用データセットに必要としている。開発者には実際の個人情報を一切渡してはならず、開発側から元の値に戻せないことも要件である。最も適切な方法はどれか。","o":["本番テーブルに動的データ マスキングを設定し、開発者にマスクされたデータの閲覧者ロールを付与して本番を直接参照させ、複製を作らずに済ます","Sensitive Data Protection で、元に戻せない変換（伏せ字や置換）を使って匿名化したデータを開発用の環境へ書き出す","本番テーブルを開発用プロジェクトへスナップショットとして複製し、開発者には閲覧のみを許可して書き込みを禁止する","本番データを CMEK で暗号化した開発用データセットへコピーし、鍵へのアクセス権を開発者には与えない"],"a":1,"e":"Sensitive Data Protection の匿名化は、検出した個人情報を伏せ字や置換などで変換した新しいデータを作るため、開発側に実データは渡らない。動的マスキングは本番の実データを残したまま表示だけを変え、スナップショットの複製は実データを含み、CMEK は暗号化であって個人情報の除去ではない。","qEn":"A development team needs data resembling the production customer table (names, emails, phone numbers) in a dev dataset to test a new feature. Developers must receive no real personal information, and the values must not be recoverable from the dev side. What is the most appropriate method?","oEn":["Set dynamic data masking on the production table, grant developers the masked reader role, and let them reference production directly to avoid making copies","Write out data de-identified with Sensitive Data Protection using irreversible transformations (masking or replacement) for development","Copy the production table into the dev project as a snapshot and allow developers read-only access while forbidding writes","Copy production data into a dev dataset encrypted with CMEK and do not give developers access to the key"],"eEn":"Sensitive Data Protection de-identification creates new data with detected personal information masked or replaced, so no real data reaches development. Dynamic masking leaves production data in place, snapshots contain real data, and CMEK encrypts rather than removes personal information."},{"id":"h295","d":"D4","q":"マーケティング分析のため、顧客の識別子であるメールアドレスを含む購買履歴と問い合わせ履歴を結合して分析したい。分析者にメールアドレスの実値は見せたくないが、同じ顧客の行は結合できる必要がある。さらに、承認された担当者だけは必要時に元のメールアドレスへ戻せるようにしたい。最も適切な方法はどれか。","o":["メールアドレスを毎回ランダムな文字列に置き換えて、対応表は保存せずに分析用のテーブルを作り、結合はせず集計だけを行わせる","決定的暗号化によるトークン化で、Cloud KMS のラップされた鍵を使って置換する","メールアドレスの列を伏せ字（アスタリスク）に置換して、全員に同じ形式の値で見せる","メールアドレスの列を削除して、分析者には性別と年代の列だけを見せて結合を行わせる"],"a":1,"e":"決定的暗号化によるトークン化は、同じ入力から常に同じトークンを作るため結合に使え、Cloud KMS の鍵を持つ承認者だけが元の値へ戻せる。毎回ランダムな置換や伏せ字では結合も復元もできず、列の削除は顧客単位の結合を不可能にする。","qEn":"For marketing analysis, purchase history and inquiry history keyed by customer email addresses must be joined. Analysts must not see actual addresses, yet rows of the same customer must still join, and approved staff must be able to restore the original address when needed. What is the most appropriate method?","oEn":["Replace the addresses with a random string each time and build the analysis table without saving a mapping table, letting analysts aggregate without joining","Replace the addresses by deterministic-encryption tokenization using a Cloud KMS wrapped key","Replace the email column with asterisks and show everyone values in the same format","Delete the email column and let analysts perform the join using only gender and age-group columns"],"eEn":"Deterministic-encryption tokenization yields the same token for the same input, so joins work, and only approved holders of the Cloud KMS key can restore the original. Random replacement or asterisks allow neither joining nor restoring, and deleting the column makes per-customer joins impossible."},{"id":"h296","d":"D4","q":"病院の診療データを研究者へ提供する。患者ごとの受診日どうしの間隔（入院から退院までの日数など）は分析に必要だが、実際の受診日は匿名性のため伏せたい。日付をずらす際に、同じ患者の日付は同じ日数だけずらしたい。最も適切な変換はどれか。","o":["すべての日付を年だけに丸めて、月と日の情報を削除してから研究者に提供することで、実際の受診日を伏せる","日付シフトで、患者 ID をコンテキストにして、患者ごとに同じ日数だけずらす","日付の値を行ごとに独立したランダムな日数でずらして、受診日の特定を難しくする","日付の列を削除して、受診回数のような回数の情報だけを残して提供する"],"a":1,"e":"日付シフトにコンテキスト（患者 ID）を指定すると、同じ患者の日付が同じ日数だけずれるため、受診日どうしの間隔が保たれる。年への丸めは間隔を失い、行ごとにランダムにずらすと間隔が壊れ、列の削除は期間の分析そのものを不可能にする。","qEn":"Hospital clinical data will be provided to researchers. Intervals between a patient's visit dates (such as days from admission to discharge) are needed, but actual dates should be hidden for anonymity. When shifting dates, the same patient's dates must move by the same number of days. Which transformation is most appropriate?","oEn":["Round every date to the year only and delete month and day information before providing it to researchers","Use date shifting with the patient ID as context so each patient's dates move by the same number of days","Shift each date by an independent random number of days per row to make visit dates hard to identify","Delete the date column and provide only count-type information such as the number of visits"],"eEn":"Date shifting with a context such as the patient ID moves a patient's dates by the same number of days, preserving intervals between visits. Rounding to years loses intervals, per-row random shifts break them, and deleting the column makes period analysis impossible."},{"id":"h297","d":"D4","q":"社内の従業員番号（例: EMP-204518）が、自由記述の問い合わせ本文に含まれている。Sensitive Data Protection の組み込みの infoType では検出されない。この形式の文字列を検出して匿名化の対象にする、最も適切な方法はどれか。","o":["組み込みの PHONE_NUMBER の infoType を有効にして、数字を含む文字列をまとめて検出させる","正規表現を使うカスタム infoType を定義して、検査テンプレートに追加する","検査の最小可能性（likelihood）を VERY_UNLIKELY に下げて、検出の感度を最大にしてから再検査する","問い合わせ本文を Cloud Storage に移して、バケットのライフサイクルのルールで該当する文字列を削除する"],"a":1,"e":"組み込みにない独自形式の識別子は、正規表現（または辞書）によるカスタム infoType を定義すれば検出できる。電話番号の infoType は別の形式を対象にし、可能性のしきい値を下げても未定義の形式は見つからず、ライフサイクルのルールは文字列の検出や削除に使えない。","qEn":"Internal employee numbers (for example EMP-204518) appear in free-text inquiry bodies, and Sensitive Data Protection's built-in infoTypes do not detect them. What is the most appropriate way to detect strings of this format and make them subject to de-identification?","oEn":["Enable the built-in PHONE_NUMBER infoType so that strings containing digits are detected together","Define a custom infoType that uses a regular expression and add it to the inspection template","Lower the minimum likelihood of the inspection to VERY_UNLIKELY to maximize detection sensitivity and re-inspect","Move the inquiry bodies to Cloud Storage and delete the matching strings with a bucket lifecycle rule"],"eEn":"Identifiers in a custom format can be detected by defining a custom infoType based on a regular expression or dictionary. The phone number infoType targets another format, lowering likelihood cannot find an undefined format, and lifecycle rules cannot detect or delete strings."},{"id":"h298","d":"D4","q":"Sensitive Data Protection の検査で、テスト用に埋め込まれた test@example.com などのダミーのメールアドレスが大量に検出され、本物の検出結果が埋もれている。ダミーの値だけを検出から外し、実在の可能性があるメールアドレスは引き続き検出したい。最も適切な設定はどれか。","o":["EMAIL_ADDRESS の infoType を検査の対象から外して、メールアドレスは一切検査しないことにする","除外ルールを使い、example.com ドメインのメールアドレスを検出の対象から除外する","検査の最小可能性を VERY_LIKELY に引き上げて、確実に該当するものだけが検出されるようにする","検出結果を手作業で CSV にエクスポートし、ダミーの行を削除してから関係者へ共有する運用にする"],"a":1,"e":"除外ルールは、特定の値やパターンに一致する検出を結果から取り除けるため、ダミーのメールアドレスだけを外して本物の検出を残せる。infoType 自体の無効化は本物も見逃し、最小可能性を上げてもダミーはメールとして高い可能性で検出され続け、手作業の削除は継続的な運用に向かない。","qEn":"In a Sensitive Data Protection inspection, many dummy email addresses embedded for testing, such as test@example.com, are detected and bury real findings. The team wants to exclude only the dummy values while still detecting possibly real addresses. Which setting is most appropriate?","oEn":["Remove the EMAIL_ADDRESS infoType from the inspection so that email addresses are not inspected at all","Use an exclusion rule to exclude email addresses in the example.com domain from detection","Raise the minimum likelihood of the inspection to VERY_LIKELY so that only certain matches are detected","Export the findings to CSV by hand, delete the dummy rows, and then share them with stakeholders"],"eEn":"Exclusion rules remove findings matching specific values or patterns, dropping dummy addresses while keeping real findings. Disabling the infoType misses real ones too, raising likelihood still detects dummies with high likelihood, and manual deletion does not suit continuous operation."},{"id":"h299","d":"D4","q":"自治体が、住民の年齢・郵便番号・職業を含むデータを匿名化して研究機関に公開する。氏名などの直接識別子は削除済みだが、年齢・郵便番号・職業の組み合わせから個人が特定される恐れがある。公開前にこの再識別のリスクを定量的に評価する最も適切な方法はどれか。","o":["Sensitive Data Protection の検査ジョブを実行して、氏名やメールアドレスが残っていないかだけを確認する","Cloud KMS の鍵でデータ全体を暗号化し、鍵の自動ローテーションが有効であることを確認してから公開する","Sensitive Data Protection のリスク分析で、準識別子の列を指定して k-匿名性を計算する","データセットに行レベルのアクセスポリシーを設定して、研究機関のメンバーだけが読めるように制限する"],"a":2,"e":"リスク分析の k-匿名性は、準識別子の組み合わせで同じ値を持つ行が最低 k 件あるかを測り、再識別のしやすさを定量化できる。検査ジョブは直接識別子の有無を調べるだけで、暗号化は組み合わせによる特定を防がず、行レベルのポリシーは再識別のリスクを評価しない。","qEn":"A municipality will publish anonymized resident data containing age, postal code, and occupation to research institutions. Direct identifiers such as names are removed, but individuals could be identified from the combination of age, postal code, and occupation. What is the most appropriate way to quantitatively assess this re-identification risk before publication?","oEn":["Run a Sensitive Data Protection inspection job and check only that no names or email addresses remain","Encrypt the entire dataset with a Cloud KMS key and publish after confirming automatic key rotation is enabled","Run Sensitive Data Protection risk analysis, specifying the quasi-identifier columns, to compute k-anonymity","Set row-level access policies on the dataset so that only members of the research institutions can read it"],"eEn":"k-anonymity in risk analysis measures whether each combination of quasi-identifiers appears in at least k rows, quantifying re-identification risk. Inspection jobs only look for direct identifiers, encryption does not prevent identification by combination, and row-level policies do not assess the risk."},{"id":"h300","d":"D4","q":"組織には数百のプロジェクトがあり、BigQuery・Cloud SQL・Cloud Storage のどこに機微なデータがあるのか把握できていない。新しいテーブルやバケットも日々増える。個別に検査ジョブを作らず、継続的に機微データの所在を把握して、高リスクの資産をセキュリティ チームに通知したい。最も適切な方法はどれか。","o":["プロジェクトごとに検査ジョブを手作業で作成し、四半期に 1 回すべての資産を一括でスキャンする運用にする","Cloud Asset Inventory でリソースの一覧を取得し、リソース名に pii を含むものを機微データとみなして扱う","Dataplex のデータ品質スキャンを全テーブルに設定し、NULL 率の高い列を機微データの候補として扱う","検出サービスを組織単位で構成し、データ プロファイルを Security Command Center に公開する"],"a":3,"e":"Sensitive Data Protection の検出サービスは、組織やフォルダ単位で BigQuery・Cloud SQL・Cloud Storage を継続的にプロファイリングし、結果を Security Command Center などへ公開できる。手作業の四半期スキャンは新規資産に追随せず、名前による推定は不正確で、NULL 率は機微性を示さない。","qEn":"An organization has hundreds of projects and cannot tell where sensitive data lives across BigQuery, Cloud SQL, and Cloud Storage, with new tables and buckets added daily. Without creating individual inspection jobs, it wants continuous visibility into where sensitive data is and to notify the security team of high-risk assets. What is the most appropriate method?","oEn":["Create inspection jobs by hand for each project and scan all assets at once once per quarter","Get a list of resources from Cloud Asset Inventory and treat those whose names contain pii as sensitive data","Set Dataplex data quality scans on all tables and treat columns with high null rates as candidates for sensitive data","Configure the discovery service at the organization level and publish data profiles to Security Command Center"],"eEn":"The discovery service continuously profiles BigQuery, Cloud SQL, and Cloud Storage at organization or folder level and can publish results to Security Command Center. Manual quarterly scans miss new assets, name-based guessing is inaccurate, and null rate does not indicate sensitivity."},{"id":"h301","d":"D4","q":"東京リージョン（asia-northeast1）に BigQuery のデータセットを作成し、CMEK で暗号化する。Cloud KMS のキーリングを新しく作成するにあたり、このデータセットの暗号化に使えるようにするには、キーリングの場所をどこにするのが最も適切か。","o":["災害対策のために、データセットとは別の大阪リージョン（asia-northeast2）にキーリングを作成して鍵を離しておく","データセットと同じ asia-northeast1 にキーリングを作成する","鍵の管理を集約するため、米国の us-central1 にキーリングを作成し、世界中のデータセットで共通に使う","マルチリージョンの EU にキーリングを作成して、どのリージョンのデータセットにも使える汎用の鍵にする"],"a":1,"e":"BigQuery の CMEK では、Cloud KMS のキーリングをデータセットと同じ場所に作成する必要がある。大阪や米国、EU に置いた鍵は場所が一致しないため東京のデータセットに指定できず、鍵を離して置く構成や汎用の鍵にする構成はこの制約を満たさない。","qEn":"A BigQuery dataset is created in the Tokyo region (asia-northeast1) and encrypted with CMEK. When creating a new Cloud KMS key ring that can be used to encrypt this dataset, where should the key ring be located?","oEn":["For disaster recovery, create the key ring in a different Osaka region (asia-northeast2) so the keys are kept apart from the dataset","Create the key ring in asia-northeast1, the same as the dataset","To centralize key management, create the key ring in us-central1 in the US and use it commonly for datasets worldwide","Create the key ring in the EU multi-region to make it a general-purpose key usable for datasets in any region"],"eEn":"For BigQuery CMEK, the Cloud KMS key ring must be in the same location as the dataset. Keys in Osaka, the US, or the EU do not match the Tokyo dataset's location, so keeping keys apart or making a general-purpose key violates this constraint."},{"id":"h302","d":"D4","q":"金融機関が、BigQuery と Cloud Storage のデータの暗号鍵を、Google Cloud の外部にある自社管理の鍵管理システムで保持したい。鍵への Google の関与を最小にしたい。BigQuery を含む両方のサービスで使える方式として、最も適切なものはどれか。","o":["顧客指定の暗号鍵（CSEK）を、BigQuery のテーブルと Cloud Storage のオブジェクトの両方に指定する","Google が管理する暗号鍵を使い続け、鍵のローテーションの間隔だけを自社の運用ルールに合わせて短くする","クライアント側で暗号化してからアップロードし、BigQuery では暗号化済みのバイナリ列を SQL 関数で集計する","Cloud EKM で外部の鍵を参照し、CMEK として BigQuery と Cloud Storage に設定して使う"],"a":3,"e":"Cloud EKM を使うと、鍵の実体を外部の鍵管理システムに置いたまま、Cloud KMS 経由で CMEK として BigQuery や Cloud Storage に利用できる。CSEK は BigQuery では使えず、Google 管理の鍵の運用は利用者が制御できず、クライアント側暗号化では暗号化済みの列を BigQuery が集計できない。","qEn":"A financial institution wants to keep encryption keys for BigQuery and Cloud Storage data in its own key management system outside Google Cloud, minimizing Google's involvement with the keys. Which approach works for both services, including BigQuery?","oEn":["Specify customer-supplied encryption keys (CSEK) for both BigQuery tables and Cloud Storage objects","Keep using Google-managed encryption keys and only shorten the rotation interval to match the company's operating rules","Encrypt on the client side before upload and aggregate the encrypted binary columns in BigQuery with SQL functions","Reference the external key with Cloud EKM and configure it as CMEK for BigQuery and Cloud Storage"],"eEn":"Cloud EKM keeps key material in an external key manager while serving as CMEK for BigQuery and Cloud Storage through Cloud KMS. CSEK cannot be used with BigQuery, Google-managed key operations are not customer-controllable, and client-side encrypted columns cannot be aggregated."},{"id":"h303","d":"D4","q":"多数の開発チームが BigQuery データセットや Cloud Storage バケットを頻繁に作る。セキュリティ部門は CMEK を必須にしたいが、鍵とキーリングの作成を部門に依頼する運用はボトルネックで、命名や権限の設定ミスも起きている。統制を保ちつつ鍵の作成を自動化する最も適切な方法はどれか。","o":["全チームにプロジェクトでキーリングの作成権限と鍵の管理者ロールを付与して、各チームに鍵を作らせる運用に切り替える","鍵を 1 つだけ作成して、全チームのデータセットとバケットで共通に共有して使うようにする","Cloud KMS Autokey を有効にし、リソースの作成時に鍵が自動的に作成および割り当てされるようにする","CMEK を必須にする方針をやめて、Google 管理の鍵だけを使う方針に切り替える"],"a":2,"e":"Autokey は、リソースの作成に合わせて、命名規則と権限が整った鍵を必要な場所に自動で作成して割り当てるので、統制を保ったまま依頼待ちを減らせる。各チームに鍵の管理権限を渡すと設定ミスが増え、1 つの鍵の共有は影響範囲が大きく、CMEK をやめると要件を満たさない。","qEn":"Many development teams frequently create BigQuery datasets and Cloud Storage buckets. Security wants CMEK mandatory, but asking it to create keys and key rings is a bottleneck and naming and permission mistakes occur. What is the most appropriate way to automate key creation while keeping control?","oEn":["Grant every team key ring creation permissions and the key administrator role in its project and let each team create keys","Create just one key and have all teams share it for their datasets and buckets","Enable Cloud KMS Autokey so that keys following the convention are created and assigned when resources are created","Drop the policy of mandatory CMEK and switch to using only Google-managed keys"],"eEn":"Autokey automatically creates and assigns keys with proper naming and permissions where needed as resources are created, cutting request waits while keeping control. Giving teams key admin rights raises misconfiguration, a shared key has a large blast radius, and dropping CMEK fails the requirement."},{"id":"h304","d":"D4","q":"SaaS 事業者が、顧客企業ごとに BigQuery のデータセットを分けて保管している。契約には、顧客が契約を終了したとき、タイムトラベルやスナップショットを含むすべての複製も含めて、その顧客のデータを確実に読み出せない状態にするという条項がある。テーブルの削除では保持期間中の複製が残ることが懸念される。事前に準備しておく最も適切な設計はどれか。","o":["契約終了時にテーブルを DROP し、タイムトラベルの期間が過ぎるのを待ってから完了の報告をする","顧客ごとに別々の CMEK を使うデータセットにしておき、契約終了時にその鍵のバージョンを破棄する","全顧客のデータを共通の 1 つの CMEK で暗号化しておき、契約終了時に該当する顧客の行を DELETE 文で削除する","契約終了時に、顧客のデータセットへのアクセス権を IAM からすべて削除し、データそのものは残しておく"],"a":1,"e":"顧客ごとに別の CMEK を使っておけば、鍵のバージョンを破棄することで、タイムトラベルやスナップショットを含む暗号文をまとめて読み出せなくできる。DROP や DELETE は保持期間中の複製が残り、共通鍵は他の顧客のデータまで読めなくなるため破棄できず、アクセス権の削除ではデータが残ったままである。","qEn":"A SaaS provider stores each customer company's data in a separate BigQuery dataset. The contract requires that, when a customer terminates, its data be rendered unreadable including all copies such as time travel and snapshots. Table deletion leaves copies during retention. Which design prepared in advance is most appropriate?","oEn":["Drop the tables when the contract ends, wait until the time travel period has passed, and then report completion","Give each customer a dataset using its own CMEK and destroy that key version when the contract ends","Encrypt all customers' data with one common CMEK and delete the terminating customer's rows with a DELETE statement when the contract ends","Remove all access to the customer's dataset from IAM when the contract ends while leaving the data itself in place"],"eEn":"With a CMEK per customer, destroying the key version makes all ciphertext, including time travel and snapshots, unreadable at once. DROP and DELETE leave copies during retention, a shared key cannot be destroyed without affecting other customers, and removing access leaves the data."},{"id":"h305","d":"D4","q":"セキュリティ要件で、ある BigQuery データセット内のテーブルはすべて CMEK で暗号化する必要がある。開発者はテーブルを日常的に作成しており、テーブルごとに暗号化の設定を付け忘れることが懸念される。設定漏れを防ぐ最も適切な方法はどれか。","o":["テーブルの作成手順書に、暗号化の設定を必ず付けるよう明記し、コードレビューでその記載を確認する","データセットにデフォルトの CMEK を設定し、新しいテーブルが自動でその鍵を使うようにする","テーブルの作成後に毎晩ジョブを実行して、暗号化の設定がされていないテーブルを見つけ次第削除する","プロジェクトで BigQuery のテーブルを作成できるユーザーの数を減らして、作成の機会そのものを限定する"],"a":1,"e":"データセットにデフォルトの Cloud KMS キーを設定すると、そのデータセットに作られる新しいテーブルは個別の指定がなくても CMEK で暗号化される。手順書とレビューは設定漏れを防ぐ強制力がなく、夜間の削除ジョブは作業の損失を招き、ユーザーを減らしても暗号化の設定は担保されない。","qEn":"Security requirements say all tables in a certain BigQuery dataset must be encrypted with CMEK. Developers create tables daily, and there is concern that they will forget to set encryption per table. What is the most appropriate way to prevent omissions?","oEn":["State in the table creation guide that encryption settings must always be added and check that statement in code review","Set a default CMEK on the dataset so that new tables automatically use that key","Run a job every night after table creation and delete any table found without encryption settings","Reduce the number of users who can create tables in the project to limit the opportunities for creation itself"],"eEn":"Setting a default Cloud KMS key on the dataset encrypts new tables with CMEK even without per-table specification. Guides and reviews cannot enforce it, a nightly deletion job destroys work, and fewer users does not ensure encryption."},{"id":"h306","d":"D4","q":"組織全体のポリシーとして、BigQuery と Cloud Storage では CMEK を使わないリソースを作成できないようにしたい。個々のプロジェクト管理者の設定に頼らず、組織として強制する最も適切な方法はどれか。","o":["gcp.restrictNonCmekServices 制約を組織のポリシーで適用し、対象に両サービスを指定する","各プロジェクトの管理者に CMEK を使うよう依頼するメールを送り、月次で実施状況を報告してもらう","VPC Service Controls の境界に BigQuery と Cloud Storage を加えて、暗号化されていない通信を遮断する","暗号化の設定を Cloud Audit Logs から集計する Looker のダッシュボードを作り、毎週レビューする"],"a":0,"e":"gcp.restrictNonCmekServices 制約を組織で適用すると、対象サービスで CMEK を指定しないリソースの作成が拒否される。依頼メールとダッシュボードは強制力がなく事後の確認にとどまり、VPC Service Controls は API アクセスの境界で、保存時の暗号鍵の指定とは別の制御である。","qEn":"As an organization-wide policy, resources in BigQuery and Cloud Storage must not be creatable without CMEK. What is the most appropriate way to enforce this at the organization level without relying on individual project administrators' settings?","oEn":["Apply the gcp.restrictNonCmekServices constraint and name BigQuery and Cloud Storage as targets","Email each project administrator to ask them to use CMEK and have them report the status of implementation monthly","Add BigQuery and Cloud Storage to a VPC Service Controls perimeter to block unencrypted communication","Build a Looker dashboard that aggregates encryption settings from Cloud Audit Logs and review it every week"],"eEn":"Enforcing gcp.restrictNonCmekServices at the organization rejects creation of resources without CMEK in the target services. Emails and dashboards lack enforcement, and VPC Service Controls is an API access perimeter, separate from specifying at-rest keys."},{"id":"h307","d":"D4","q":"個人情報の消去請求に備え、BigQuery の顧客テーブルの氏名と住所の列を、顧客ごとに異なる鍵で SQL の中から暗号化して保存したい。消去請求があった顧客については、バックアップやタイムトラベル上の複製も含めて、鍵の削除だけで読めなくしたい。最も適切な方法はどれか。","o":["列を TO_BASE64 関数で変換して保存し、消去請求があったときに該当する顧客の列を NULL に更新する","AEAD 暗号化関数で顧客ごとのキーセットを使い、キーセットを Cloud KMS の鍵でラップして管理する","全顧客に共通の 1 つのキーセットで AEAD 暗号化しておき、消去請求があったときに該当する顧客の行を削除する","動的データ マスキングを設定し、消去請求のあった顧客の列を全ユーザーにマスクされた値で見せる"],"a":1,"e":"顧客ごとのキーセットで AEAD 暗号化し、ラップした鍵を別に管理すれば、消去請求時に該当の鍵を削除するだけで、過去の複製を含む暗号文を復号できなくできる。Base64 は暗号化ではなく、共通キーセットでは顧客単位で鍵を消せず、動的マスキングは表示を変えるだけで元データは残る。","qEn":"To prepare for erasure requests, the name and address columns of a BigQuery customer table should be encrypted from within SQL with a different key per customer. For a customer who requests erasure, deleting the key alone should make everything unreadable, including backups and time travel copies. What is the most appropriate method?","oEn":["Convert the columns with TO_BASE64 before storing them and update the customer's columns to NULL when an erasure request arrives","Encrypt the columns with AEAD using a keyset per customer, wrapped by a Cloud KMS key and managed separately","Encrypt with AEAD using one keyset common to all customers and delete the customer's rows when an erasure request arrives","Set up dynamic data masking and show the erasure-requesting customer's columns to all users as masked values"],"eEn":"With per-customer AEAD keysets and separately managed wrapped keys, deleting that key on erasure makes the ciphertext, including past copies, undecryptable. Base64 is not encryption, a common keyset cannot be deleted per customer, and masking only changes display."},{"id":"h308","d":"D4","q":"規制の厳しい業界の企業が、Google のサポート担当者が障害調査のためであっても、顧客のデータにアクセスする前に自社の承認を必須にしたい。通常の IAM の設定だけでは Google 側の運用担当を制御できない。最も適切なサービスはどれか。","o":["Access Approval で、Google の担当者によるデータへのアクセスを承認制にする","Cloud Audit Logs の Data Access ログを有効にして、Google の担当者によるアクセスを事後にすべて確認する","VPC Service Controls の境界を設定して、Google の担当者のネットワークからのアクセスを遮断する","CMEK を無効にして Google が管理する鍵に切り替え、Google の担当者のアクセスを鍵の側で制限する"],"a":0,"e":"Access Approval は、Google の担当者が顧客のコンテンツにアクセスする前に、顧客の承認を必要とする仕組みである。ログの確認は事後であって承認制にならず、VPC Service Controls は顧客の API アクセスの境界でサポート担当の運用を止められず、Google 管理の鍵への切り替えは制御をむしろ弱める。","qEn":"A company in a heavily regulated industry wants Google support staff to need its approval before accessing customer data, even for incident investigation. Regular IAM settings alone cannot control Google's operations staff. Which service is most appropriate?","oEn":["Use Access Approval to make access to data by Google personnel subject to approval","Enable Data Access logs in Cloud Audit Logs and review all access by Google personnel after the fact","Configure a VPC Service Controls perimeter to block access from the network of Google personnel","Disable CMEK and switch to Google-managed keys to restrict Google personnel access on the key side"],"eEn":"Access Approval requires the customer's approval before Google personnel access customer content. Log review is after the fact, VPC Service Controls is a customer API perimeter that cannot stop support operations, and switching to Google-managed keys weakens control."},{"id":"h309","d":"D4","q":"監査担当が、機微な顧客ファイルを置く Cloud Storage のバケットで、いつ誰がどのオブジェクトを読み取ったかを調べたい。ところが Cloud Logging にオブジェクトの読み取りの記録が見当たらない。Cloud Storage の既定の状態を踏まえた、最も適切な対応はどれか。","o":["管理アクティビティの監査ログを無効にして、オブジェクトの読み取りの記録だけを残すようにする","バケットのオブジェクトのバージョニングを有効にして、読み取りのたびに新しい世代が記録されるようにし、誰がいつ読んだかも追跡できるようにする","Cloud Storage の Data Access 監査ログのうち、読み取り（DATA_READ）を有効にする","Cloud Monitoring のダッシュボードで、バケットのネットワーク送信量のグラフを日次で確認する"],"a":2,"e":"Cloud Storage のオブジェクト読み取りを記録する Data Access 監査ログは、既定では無効なので、DATA_READ を有効にする必要がある。管理アクティビティのログは無効にできず設定の変更を記録するもので、バージョニングは世代の管理で読み取りを記録せず、送信量のグラフは誰が読んだかを示さない。","qEn":"An auditor wants to know who read which object and when in a Cloud Storage bucket holding sensitive customer files, but Cloud Logging shows no record of object reads. Considering Cloud Storage's default state, what is the most appropriate response?","oEn":["Disable Admin Activity audit logs so that only records of object reads remain","Enable object versioning on the bucket so that a new generation is recorded each time an object is read","Enable the read (DATA_READ) category of Data Access audit logs for Cloud Storage","Check a graph of the bucket's network egress in a Cloud Monitoring dashboard every day"],"eEn":"Data Access audit logs that record Cloud Storage object reads are off by default, so DATA_READ must be enabled. Admin Activity logs cannot be disabled and record configuration changes, versioning manages generations, and egress graphs do not show who read."},{"id":"h310","d":"D4","q":"金融規制のため、プロジェクトの監査ログを 7 年間保管し、調査のときに SQL で検索できるようにしたい。Cloud Logging の既定のバケットの保持期間では足りない。長期保管と検索性を両立する、最も適切な構成はどれか。","o":["ログを毎月手作業で CSV にダウンロードし、担当者のローカル PC のフォルダに 7 年間保管する","ログ シンクの宛先を Pub/Sub のトピックにして、トピックのメッセージ保持期間を 7 年に設定する","ログを Cloud Monitoring のメトリクスに変換して、メトリクスを 7 年間保持して検索に使う","ログ シンクで監査ログを BigQuery のデータセットにエクスポートし、保持の期間を管理する"],"a":3,"e":"ログ シンクで BigQuery にエクスポートすれば、既定の保持期間に縛られず長期に保管でき、SQL でも検索できる。手作業の CSV 保管は漏れと改ざんの管理が難しく、Pub/Sub のメッセージ保持期間は長期保管に向かず、ログベースのメトリクスは個々のログの内容を残さない。","qEn":"Under financial regulations, a project's audit logs must be kept for seven years and be searchable with SQL during investigations. The default Cloud Logging bucket retention is insufficient. Which configuration best combines long-term retention and searchability?","oEn":["Download logs to CSV by hand every month and keep them in a folder on the staff member's local PC for seven years","Make a Pub/Sub topic the log sink destination and set the topic's message retention to seven years","Convert logs into Cloud Monitoring metrics and retain the metrics for seven years to use for searching","Export audit logs to a BigQuery dataset with a log sink and manage the retention period"],"eEn":"Exporting to BigQuery with a log sink stores logs long term regardless of default retention and allows SQL search. Manual CSVs are hard to protect, Pub/Sub message retention is unsuited to long-term storage, and log-based metrics do not keep individual log contents."},{"id":"h311","d":"D4","q":"障害対応のため、オンコールのエンジニアが本番の BigQuery データセットに対して管理者権限を数時間だけ必要とすることがある。普段は権限を持たせず、申請と承認を経て一定時間だけ付与し、誰がどんな理由で使ったかを記録したい。最も適切な方法はどれか。","o":["オンコールのエンジニア全員に BigQuery 管理者ロールを常時付与しておき、操作の内容は監査ログで後から確認することで、対応の速度を優先する","チャットで依頼を受けた管理者がロールを手動で付与し、数時間後に手動で外す運用にして、やりとりを記録として残す","共有の管理者用アカウントを 1 つ作り、パスワードを金庫に保管して、必要なときに申請して借りる運用にする","Privileged Access Manager でエンタイトルメントを作成し、承認を経て時間を限定した付与を行う"],"a":3,"e":"Privileged Access Manager は、エンタイトルメントごとに申請・承認・期間限定の付与を行い、理由と操作の記録を残せる。常時の付与は最小権限に反し、チャットでの手動付与は外し忘れや記録の不備を招き、共有アカウントは操作した個人を特定できない。","qEn":"During incidents, on-call engineers sometimes need administrator permissions on a production BigQuery dataset for a few hours. They should hold no such permission normally, receive it for a limited time after request and approval, and the use and reason should be recorded. What is the most appropriate method?","oEn":["Grant the BigQuery Admin role permanently to all on-call engineers and check their operations later in audit logs","Have an administrator who receives a request in chat grant the role by hand and remove it by hand hours later, keeping the exchange as a record","Create one shared administrator account, keep its password in a vault, and operate so that people apply to borrow it when needed","Create an entitlement in Privileged Access Manager and grant access for a limited time after approval"],"eEn":"Privileged Access Manager provides request, approval, and time-limited grants per entitlement and records reasons and actions. Permanent grants violate least privilege, manual chat-based grants risk forgotten removals and poor records, and shared accounts cannot identify individuals."},{"id":"h312","d":"D4","q":"1 つの Cloud Storage バケットの中で、プレフィックス team-a/ はチーム A だけ、team-b/ はチーム B だけが読み書きできるようにしたい。バケットを分けると他のシステムの参照先を変更する必要があるため避けたい。バケットでは均一なバケットレベルのアクセスが有効である。最も適切な方法はどれか。","o":["プレフィックスごとにマネージド フォルダを作成し、各フォルダにチームの IAM ロールを付与する","各オブジェクトに ACL を設定して、チームごとに読み取りと書き込みを許可する","チーム A とチーム B の両方にバケット全体のオブジェクト管理者ロールを付与し、プレフィックスを守る運用ルールを決める","プレフィックスの名前をランダムな文字列に変更して、他のチームから推測されないようにする"],"a":0,"e":"マネージド フォルダは、バケット内のプレフィックスに対して個別に IAM ポリシーを設定できるため、バケットを分けずにチームごとの権限を分けられる。均一なバケットレベルのアクセスでは ACL を使えず、バケット全体の付与はルールに頼るだけで強制できず、名前の秘匿はアクセス制御にならない。","qEn":"Within one Cloud Storage bucket, only team A should read and write the team-a/ prefix and only team B the team-b/ prefix. Splitting buckets would force other systems to change references, so it should be avoided. Uniform bucket-level access is enabled on the bucket. What is the most appropriate method?","oEn":["Create a managed folder for each prefix and grant each team's IAM role on its folder","Set ACLs on each object to allow reading and writing per team","Grant both teams the object admin role on the whole bucket and set an operating rule to respect the prefixes","Rename the prefixes to random strings so that other teams cannot guess them"],"eEn":"Managed folders allow separate IAM policies on prefixes within a bucket, separating team permissions without splitting buckets. ACLs are unavailable under uniform bucket-level access, bucket-wide grants rely on rules, and hiding names is not access control."},{"id":"h313","d":"D4","q":"データ ガバナンス担当は、他部署から引き継いだ BigQuery の customers テーブル（5,000 万行）について、どの列に NULL が多いか、値の分布や最小・最大がどうなっているかを、ルールを書く前にまず把握したい。最も適切な機能はどれか。","o":["Dataplex Universal Catalog のデータ プロファイル スキャンを実行する","Dataplex のデータ品質スキャンで、全列に NOT NULL のルールを作成して実行し、失敗した列を確認する","BigQuery のテーブル スナップショットを作成して、スナップショットのスキーマ情報から各列の特徴を確認する","Cloud Logging で過去のクエリを検索して、列ごとに参照された回数を集計し、利用の多い列を調べる"],"a":0,"e":"データ プロファイル スキャンは、列ごとの NULL の割合、一意の値の割合、最小・最大、よく出る値などの統計を自動で取得するため、ルールを書く前の現状把握に向く。品質スキャンは期待する条件を先に決めて検証するもので、スナップショットのスキーマは統計を持たず、クエリ履歴は値の分布を示さない。","qEn":"A data governance lead inherited a BigQuery customers table (50 million rows) from another department and wants to understand which columns have many NULLs and what the value distributions and minimum and maximum look like before writing any rules. Which feature is most appropriate?","oEn":["Run a Dataplex Universal Catalog data profile scan","Create a NOT NULL rule on all columns in a Dataplex data quality scan, run it, and check the columns that fail","Create a BigQuery table snapshot and check each column's characteristics from the snapshot's schema information","Search past queries in Cloud Logging, count how often each column was referenced, and look at the most used columns"],"eEn":"A data profile scan automatically gathers per-column statistics such as null share, distinct share, min and max, and frequent values, suiting understanding before writing rules. Quality scans verify predefined expectations, snapshot schemas carry no statistics, and query history shows no distributions."},{"id":"h314","d":"D4","q":"注文テーブルの email 列について、Dataplex のデータ品質スキャンで『NULL でない』ルールを設定した。実運用ではゲスト購入などでごく一部が NULL になるのが正常で、99% 以上が埋まっていれば合格としたい。いまは NULL が 1 件でもあるとスキャンが失敗扱いになって困っている。最も適切な設定はどれか。","o":["ルールの対象の列から email を外して、スキャンが失敗扱いにならないようにする","NonNull ルールのしきい値（合格とする行の割合）を 0.99 に設定する","スキャンの行フィルタに email IS NOT NULL を指定して、NULL の行を最初から検証の対象外にする","スキャンの実行を週次から日次に変えて、NULL の発生件数が日ごとに平均化されるようにする"],"a":1,"e":"データ品質ルールには合格とする行の割合のしきい値を設定でき、0.99 にすれば 1% までの NULL を許容できる。対象列から外すと検証そのものを失い、行フィルタで NULL を除くと欠損を検知できなくなり、実行頻度を変えても 1 回の評価の合格基準は変わらない。","qEn":"A 'not null' rule was set on the email column of an orders table in a Dataplex data quality scan. In operation, a small share being NULL is normal because of guest purchases, and 99 percent or more filled should pass. Currently even one NULL makes the scan fail. What is the most appropriate setting?","oEn":["Remove email from the columns targeted by the rule so that the scan does not fail","Set the NonNull rule's threshold (the share of passing rows) to 0.99","Specify email IS NOT NULL in the scan's row filter so that NULL rows are excluded from validation from the start","Change the scan from weekly to daily so that the number of NULL occurrences is averaged day by day"],"eEn":"Data quality rules accept a threshold for the share of passing rows, and 0.99 tolerates up to 1 percent NULLs. Removing the column loses validation, filtering out NULLs hides missing values, and changing run frequency does not change a single run's pass criterion."},{"id":"h315","d":"D4","q":"日次パーティションの売上テーブル（数十 TB）に対して、データ品質スキャンを毎日実行している。毎回テーブル全体をスキャンしてコストが高いが、実際に検証したいのは当日に追加された分だけである。最も適切な設定はどれか。","o":["サンプリングの割合を 100% に設定して、検証結果の信頼性をできるだけ高くする","増分スキャンを有効にして、日付などの増分列を指定して、新しいデータだけを検証する","スキャンの実行頻度を日次から月次に変更して、スキャンの回数そのものを減らす","品質ルールの数を減らして、1 回のスキャンの実行時間が短くなるようにする"],"a":1,"e":"増分スキャンは、指定した増分列に基づいて新しく追加された分だけを検証するため、巨大なテーブルでも毎日のスキャン量とコストを抑えられる。サンプリング 100% は全件の検証でコストが増え、月次への変更は当日の問題を検知できず、ルールを減らしてもスキャンするデータ量は変わらない。","qEn":"A data quality scan runs daily on a daily-partitioned sales table of tens of terabytes. It scans the whole table each time, which is costly, though only the data added that day needs validation. What is the most appropriate setting?","oEn":["Set the sampling percentage to 100 percent to make the validation results as reliable as possible by reading every row","Enable incremental scanning, specify an incremental column such as the date, and validate only new data","Change the scan frequency from daily to monthly to reduce the number of scans themselves","Reduce the number of quality rules so that each scan finishes in less time"],"eEn":"Incremental scans validate only newly added data based on the specified column, keeping daily scan volume and cost low on huge tables. 100 percent sampling costs more, monthly runs miss daily issues, and fewer rules do not change the data scanned."},{"id":"h316","d":"D4","q":"注文テーブル orders の customer_id が customers テーブルに必ず存在する（参照整合性）ことを、Dataplex のデータ品質スキャンで毎日検証したい。標準の NULL や範囲のルールでは表現できない。最も適切なルールの種類はどれか。","o":["セット メンバーシップ ルールに、customers の全 customer_id を許可する値として列挙し登録する","一意性ルールを orders の customer_id に設定して、同じ値が重複していないことを確認する","正規表現ルールで、customer_id が数字だけの形式になっているかどうかを確認する","SQL アサーション ルールで、customers に存在しない customer_id の行を返すクエリを定義する"],"a":3,"e":"SQL アサーション ルールは、条件に違反する行を返すクエリで任意のテーブル間の検証を表現でき、結果が 0 行なら合格になる。許可値の列挙は顧客の増減に追随できず、一意性ルールは重複を調べるだけで存在確認ではなく、正規表現は形式の確認で参照先の存在を保証しない。","qEn":"A team wants a Dataplex data quality scan to verify daily that every customer_id in the orders table exists in the customers table (referential integrity). Standard NULL or range rules cannot express this. Which rule type is most appropriate?","oEn":["Enumerate and register every customer_id of customers as an allowed value in a set membership rule and update it as customers change","Set a uniqueness rule on orders.customer_id to confirm that the same value is not duplicated","Use a regular expression rule to check whether customer_id has a digits-only format","Use a SQL assertion rule defining a query that returns rows whose customer_id does not exist in customers"],"eEn":"A SQL assertion rule expresses cross-table validation with a query returning violating rows, passing when zero rows come back. Enumerated allowed values cannot follow customer changes, uniqueness checks duplicates not existence, and regex checks format, not the referenced row."},{"id":"h317","d":"D4","q":"データ品質スキャンの結果を、品質スコアの推移として経営層に毎月報告したい。スキャンごとの結果はコンソールでしか見られず、過去分の推移をグラフにできていない。結果を継続的に分析できるようにする最も適切な方法はどれか。","o":["毎月、コンソールの結果画面のスクリーンショットを撮って、スライドに貼り付けて時系列に並べる","スキャンの結果を Cloud Logging のログ バケットに保存し、ログの出力件数をグラフにして推移を示す","結果を BigQuery のテーブルにエクスポートする設定を有効にして、Looker Studio に接続する","スキャンの実行頻度を月次から日次に上げて、直近の実行結果だけがコンソールに表示されるようにする"],"a":2,"e":"データ品質スキャンには、結果を BigQuery のテーブルにエクスポートする機能があり、蓄積した結果から Looker Studio などで推移を可視化できる。スクリーンショットは分析に使えず、ログの件数はスコアの推移を表さず、頻度を上げても履歴は蓄積されない。","qEn":"Data quality scan results should be reported monthly to executives as a trend of quality scores. Results per scan can be seen only in the console, and the past trend cannot be charted. What is the most appropriate way to make the results continuously analyzable?","oEn":["Take screenshots of the console results screen each month and paste them chronologically into slides","Save scan results in a Cloud Logging log bucket and chart the number of log entries to show the trend","Enable exporting results to a BigQuery table and connect it to Looker Studio","Raise the scan frequency from monthly to daily so that only the most recent run result is shown in the console"],"eEn":"Data quality scans can export results to a BigQuery table, and accumulated results can be visualized as a trend in Looker Studio. Screenshots are not analyzable, log counts do not represent score trends, and a higher frequency does not build history."},{"id":"h318","d":"D4","q":"データ基盤チームは、BigQuery の sales_raw テーブルの列名を変更する予定である。この変更でどの下流のテーブルやビューが影響を受けるのかを、依存関係を人手で調べずに把握したい。最も適切な機能はどれか。","o":["INFORMATION_SCHEMA.TABLES を参照して、sales_raw と同じデータセットにあるテーブル名の一覧を確認する","sales_raw のテーブル スナップショットを作成して、スナップショットに対するクエリで影響範囲を試して確認する","Cloud Monitoring でスロット使用率を確認し、sales_raw を参照するクエリが多い時間帯を調べる","Dataplex Universal Catalog のデータ リネージで、sales_raw の下流の依存関係を確認する"],"a":3,"e":"データ リネージは、BigQuery のジョブから取得したテーブル間のデータの流れを可視化するため、sales_raw を元にしている下流のテーブルやビューをたどって影響範囲を把握できる。同じデータセットのテーブル名の一覧には依存関係がなく、スナップショットは時点のコピーで、スロット使用率は参照関係を示さない。","qEn":"A data platform team plans to rename a column of the BigQuery sales_raw table. It wants to know which downstream tables and views would be affected without investigating dependencies by hand. Which feature is most appropriate?","oEn":["Refer to INFORMATION_SCHEMA.TABLES and check the list of table names in the same dataset as sales_raw","Create a table snapshot of sales_raw and test the impact range by running queries against the snapshot","Check slot utilization in Cloud Monitoring and look for time windows with many queries referencing sales_raw","Check sales_raw's downstream dependencies in Dataplex Universal Catalog data lineage"],"eEn":"Data lineage visualizes data flows between tables captured from BigQuery jobs, so downstream tables and views based on sales_raw can be traced. A same-dataset table list has no dependencies, snapshots are point-in-time copies, and slot utilization shows no references."},{"id":"h319","d":"D4","q":"社内にはオンプレミスの Oracle データベースと BI ツールのダッシュボードがあり、これらのメタデータも BigQuery のテーブルと同じカタログで検索できるようにしたい。Google Cloud 上のサービスだけが自動で登録される状態で、他のシステムの資産が検索結果に出てこない。最も適切な方法はどれか。","o":["Oracle のテーブル定義をスプレッドシートにまとめて共有し、カタログ検索の代わりとして使ってもらう","Oracle のデータをすべて BigQuery に複製して、複製したテーブルのメタデータだけをカタログで管理する","BI ツールのダッシュボードを PDF に書き出して Cloud Storage に保存し、ファイル名で検索してもらう","Dataplex Universal Catalog にカスタム エントリを作り、メタデータのインポートで登録する"],"a":3,"e":"Dataplex Universal Catalog では、Google Cloud 外の資産もカスタム エントリとして作成し、メタデータのインポートで登録でき、BigQuery のテーブルと同じ検索で見つけられる。スプレッドシートはカタログと連動せず、全データの複製は目的に対して過大で、PDF のファイル名検索は資産のメタデータを管理しない。","qEn":"The company has an on-premises Oracle database and BI tool dashboards, and wants their metadata to be searchable in the same catalog as BigQuery tables. Only Google Cloud services are registered automatically, so assets of other systems do not appear in search results. What is the most appropriate method?","oEn":["Compile Oracle table definitions in a spreadsheet and share it for people to use instead of catalog search","Replicate all Oracle data to BigQuery and manage only the replicated tables' metadata in the catalog","Export the BI dashboards to PDF, save them in Cloud Storage, and have people search by file name","Create custom entries in Dataplex Universal Catalog and register external assets via metadata import"],"eEn":"Dataplex Universal Catalog lets assets outside Google Cloud be created as custom entries via metadata import and found in the same search as BigQuery tables. Spreadsheets are not linked to the catalog, replicating all data is excessive, and PDF filename search manages no asset metadata."},{"id":"h320","d":"D4","q":"Cloud Storage のバケットに、パートナーから届く CSV と Parquet のファイルが毎日追加される。ファイルごとに外部テーブルを手作業で作成していたが、新しいフォルダが増えるたびに作業が発生する。ファイルを自動で見つけ、BigQuery から参照できるテーブルとして登録したい。最も適切な方法はどれか。","o":["データ プロファイル スキャンをバケットに設定して、ファイルの列ごとの統計を自動で取得させる","Cloud Storage のライフサイクル ルールを設定して、新しいファイルを毎日 BigQuery へ移動させる","BigQuery の INFORMATION_SCHEMA を参照して、バケット内のファイルの一覧を取得し、テーブルを作る","Dataplex の検出スキャンをバケットに設定し、BigLake テーブルを自動で作成・更新させる"],"a":3,"e":"Dataplex の検出スキャンは、Cloud Storage のバケット内の構造化データを自動で見つけ、BigQuery から参照できる BigLake テーブルとして作成・更新できる。プロファイル スキャンは既存のテーブルの統計を出すだけで、ライフサイクル ルールはオブジェクトの削除やクラス変更を行い、INFORMATION_SCHEMA は Cloud Storage のファイルを列挙しない。","qEn":"CSV and Parquet files from a partner are added to a Cloud Storage bucket every day. External tables were created by hand per file, and each new folder creates more work. The team wants files discovered automatically and registered as tables queryable from BigQuery. What is the most appropriate method?","oEn":["Set a data profile scan on the bucket to obtain per-column statistics of the files automatically","Configure a Cloud Storage lifecycle rule to move new files to BigQuery every day","Refer to BigQuery INFORMATION_SCHEMA to get the list of files in the bucket and create tables from it","Set up a Dataplex discovery scan on the bucket to create and update BigLake tables automatically"],"eEn":"A Dataplex discovery scan automatically finds structured data in a bucket and creates and updates BigLake tables queryable from BigQuery. Profile scans only give statistics on existing tables, lifecycle rules delete or change class, and INFORMATION_SCHEMA does not list Cloud Storage files."},{"id":"h321","d":"D4","q":"小売会社と広告会社が、それぞれの顧客データを持ち寄って、共通の顧客の重なりと広告の効果を分析したい。双方とも、相手に自社の生の行データを見せたり、コピーを渡したりすることはできない。BigQuery 上でこの要件を満たす最も適切な方法はどれか。","o":["双方が自社のデータセットに対して、相手の担当者全員に BigQuery データ閲覧者ロールを付与する","どちらかの会社が相手のデータを CSV で受け取り、自社の BigQuery に読み込んで結合して分析する","BigQuery sharing（旧 Analytics Hub）のデータ クリーン ルームで、許可した集計クエリだけを実行させる","双方のデータを匿名化せずに Cloud Storage の共有バケットへ置き、同じ署名付き URL で読めるようにして、分析は各社が手元で自由に行えるようにする"],"a":2,"e":"データ クリーン ルームでは、各社のデータを移動やコピーせずに共有し、許可された集計のクエリだけを実行できるため、生の行を見せずに重なりや効果を分析できる。閲覧者ロールの付与は生の行を見せ、CSV の受け渡しはコピーが渡り、共有バケットと署名付き URL は生データを丸ごと渡すことになる。","qEn":"A retailer and an advertiser want to bring their customer data together to analyze overlapping customers and ad effectiveness. Neither can show raw rows or hand over copies of its data to the other. What is the most appropriate way to meet this requirement on BigQuery?","oEn":["Each side grants the BigQuery Data Viewer role on its own dataset to all of the other side's staff","One company receives the other's data as CSV, loads it into its own BigQuery, and joins it for analysis","Create a data clean room in BigQuery sharing (formerly Analytics Hub) and let only approved aggregate queries run","Place both sides' data without anonymization in a shared Cloud Storage bucket and make it readable via the same signed URL"],"eEn":"A data clean room shares each party's data without moving or copying it and runs only approved aggregate queries, enabling overlap and effectiveness analysis without exposing raw rows. Viewer roles expose rows, CSV handoff passes copies, and a shared bucket with signed URLs hands over raw data."},{"id":"h322","d":"D4","q":"アクセスログを日単位のパーティションで保存している BigQuery テーブルがある。社内規程では、ログは 400 日間だけ保持し、それより古いものは自動で削除することになっている。テーブルを作り直さず、運用の手間なく規程を満たす最も適切な方法はどれか。","o":["テーブルそのものの有効期限を 400 日後に設定し、期限が来たらテーブルを新しく作り直して運用を続け、移行の作業は担当者が行う","テーブルのパーティションの有効期限（partition_expiration_days）を 400 日に設定する","毎月 1 日に担当者が手作業で DELETE 文を実行して、400 日より古い行を削除する運用にする","データセットのタイムトラベル期間を 400 日に設定して、それより古いデータが自動的に消えるようにする"],"a":1,"e":"パーティションの有効期限を設定すると、各パーティションが作成から指定した日数で自動的に削除され、直近のデータはそのまま残る。テーブルの有効期限は新しいデータを含むテーブル全体を消し、手作業の DELETE は運用負荷と漏れを生み、タイムトラベル期間は最大 7 日で保持規程とは別の機能である。","qEn":"A BigQuery table stores access logs in daily partitions. Company policy says logs are kept only 400 days and older ones are deleted automatically. What is the most appropriate way to satisfy the policy without recreating the table and without operational effort?","oEn":["Set an expiration on the table itself 400 days out and recreate the table when it expires to continue operation","Set the table's partition expiration (partition_expiration_days) to 400 days","Have a staff member run a DELETE statement by hand on the first of each month to remove rows older than 400 days","Set the dataset's time travel window to 400 days so that older data disappears automatically"],"eEn":"Partition expiration deletes each partition automatically after the specified days while recent data remains. Table expiration deletes the whole table including new data, manual DELETE adds burden and omissions, and the time travel window is capped at seven days and is a different feature."},{"id":"h323","d":"D4","q":"データ分析用のサンドボックス データセットに、検証用の一時テーブルが際限なく溜まっている。管理者はデータセットの既定のテーブル有効期限を 7 日に設定したが、すでにあるテーブルは今も残り続けている。この動作についての最も正確な説明はどれか。","o":["設定後は 7 日ごとに、データセット内のすべてのテーブルが既存のものも含めて一斉に削除される","既存のテーブルにも適用されるが、実際の削除はタイムトラベルの期間が過ぎてからさらに遅れて実行される","既定のテーブル有効期限は、設定後に新しく作成されるテーブルにだけ適用され、既存のテーブルは対象外である","有効期限の設定は BigQuery のテーブルには効かず、Cloud Storage のオブジェクトにだけ適用される"],"a":2,"e":"データセットの既定のテーブル有効期限は、設定後に作成されるテーブルに適用され、既存のテーブルには遡及しない。既存のテーブルは個別に有効期限を設定する必要がある。一斉削除や削除の遅延は仕様にない説明で、BigQuery のテーブルにも有効期限は設定できる。","qEn":"Temporary validation tables keep piling up in a sandbox dataset for data analysis. The administrator set the dataset's default table expiration to seven days, but existing tables still remain. Which is the most accurate explanation of this behavior?","oEn":["After the setting, every seven days all tables in the dataset, including existing ones, are deleted at once without exception","It applies to existing tables too, but actual deletion runs later still, after the time travel period has passed","The default table expiration applies only to tables created after it is set, and existing tables are not covered","The expiration setting has no effect on BigQuery tables and applies only to Cloud Storage objects"],"eEn":"A dataset's default table expiration applies to tables created after it is set and is not retroactive; existing tables need individual expirations. Mass deletion and delayed deletion are not in the specification, and BigQuery tables do support expiration."},{"id":"h324","d":"D4","q":"データ更新が頻繁な BigQuery のデータセットで、物理ストレージ課金モデルを使っている。タイムトラベル用に保持される変更前のデータが大きく、ストレージ コストを押し上げている。誤操作からの復元は直近 2 日で足りると運用側が判断した。最も適切な対応はどれか。","o":["フェイルセーフ期間を 0 日に設定して、削除後に保持されるデータをなくす","データセットの既定のテーブル有効期限を 2 日に設定して、古いテーブルを自動的に削除する","データセットのタイムトラベル期間を 2 日に短縮する","テーブルを毎日スナップショットに複製し、その代わりに元のテーブルのタイムトラベルを無効にする"],"a":2,"e":"タイムトラベル期間は 2〜7 日で設定でき、物理ストレージ課金では保持される変更前のデータが課金対象なので、2 日に短縮するとコストを抑えられる。フェイルセーフ期間は設定できず、既定の有効期限はテーブルを消してしまい、毎日のスナップショットは別の保管コストを増やし、タイムトラベルは無効化できない。","qEn":"A frequently updated BigQuery dataset uses the physical storage billing model. The pre-change data retained for time travel is large and raises storage cost. Operations decided that recovery from mistakes only needs the last two days. What is the most appropriate response?","oEn":["Set the fail-safe period to zero days so that no data is retained after deletion","Set the dataset's default table expiration to two days to delete old tables automatically","Shorten the dataset's time travel window to two days","Replicate the table to a snapshot every day and disable time travel on the original table in exchange"],"eEn":"The time travel window is configurable from two to seven days, and under physical billing retained pre-change data is billed, so shortening to two days cuts cost. Fail-safe is not configurable, default expiration deletes tables, daily snapshots add cost, and time travel cannot be disabled."},{"id":"h325","d":"D4","q":"運用担当者が 3 日前に BigQuery のテーブルを誤って削除したことに今日気付いた。データセットのタイムトラベル期間は既定のままで、スナップショットの運用はしていない。テーブルを復元する最も適切な方法はどれか。","o":["タイムトラベル期間内なので、削除前の時点を指定して、元のテーブルを新しいテーブルへコピーして復元する","BigQuery は削除時に自動でバケットへエクスポートを作成しているので、そのファイルを読み込み直して復元する","削除から 1 日を過ぎたテーブルは復元できないので、元のデータソースから再度取り込んで作り直す","Google Cloud サポートに依頼しない限り、削除したテーブルはどんな期間であっても復元できない"],"a":0,"e":"既定のタイムトラベル期間は 7 日なので、削除から 3 日であれば、削除前の時点を指定して新しいテーブルへコピーすれば復元できる。削除時に自動でエクスポートが作られることはなく、復元できないのは 1 日後ではなく期間を過ぎてからで、期間内ならサポートへの依頼なしで復元できる。","qEn":"An operator noticed today that a BigQuery table was deleted by mistake three days ago. The dataset's time travel window is at its default, and no snapshots are maintained. What is the most appropriate way to restore the table?","oEn":["Since it is within the time travel window, copy the table as of a point before deletion into a new table to restore it","BigQuery automatically creates an export to a bucket on deletion, so reload that file to restore the table","A table cannot be restored once more than one day has passed since deletion, so re-ingest from the original source and rebuild it","Unless Google Cloud Support is asked, a deleted table cannot be restored in any period"],"eEn":"The default time travel window is seven days, so a table deleted three days ago can be restored by copying it as of a point before deletion into a new table. No export is created automatically, the limit is the window rather than one day, and no support request is needed within it."},{"id":"h326","d":"D4","q":"開発チームが、20 TB の本番テーブルと同じ内容に対して、書き込みを伴うテストを繰り返したい。本番に影響を与えたくなく、テスト環境のストレージ コストもできるだけ抑えたい。最も適切な方法はどれか。","o":["本番テーブルのテーブル スナップショットを作成し、スナップショットに対して直接書き込みを伴うテストを行う","本番テーブルのテーブル クローンを作成し、クローンに対してテストを行う","本番テーブルを CREATE TABLE AS SELECT で全件コピーして、コピーに対してテストを行う","本番テーブルに対する書き込み権限を開発チームに付与し、テスト後に変更を手作業で元に戻す"],"a":1,"e":"テーブル クローンは書き込み可能で、元のテーブルとの差分にだけストレージ課金が生じるため、本番に影響せず低コストでテストできる。スナップショットは読み取り専用で書き込めず、全件コピーは同じ容量分の保管コストがかかり、本番への書き込み権限の付与は本番を壊すリスクを負う。","qEn":"A development team wants to run repeated write-heavy tests against the same content as a 20 TB production table. It must not affect production, and test environment storage cost should be kept as low as possible. What is the most appropriate method?","oEn":["Create a table snapshot of the production table and run write tests directly against the snapshot","Create a table clone of the production table and run the tests against the clone","Copy the whole production table with CREATE TABLE AS SELECT and run the tests against the copy","Grant the development team write permission on the production table and revert changes manually after testing"],"eEn":"A table clone is writable and incurs storage charges only for differences from the base table, so tests are low-cost and isolated from production. Snapshots are read-only, a full copy costs the full capacity, and write access to production risks damaging it."},{"id":"h327","d":"D4","q":"経理部門は、毎月末時点の BigQuery の残高テーブルの状態を、13 か月間にわたって照会できる形で保全したい。タイムトラベルで遡れる期間は最大でも 7 日しかなく、月ごとにテーブルの全件を別テーブルへコピーするのはストレージ コストの点で避けたい。最も適切な方法はどれか。","o":["タイムトラベル期間を 400 日に延長して、13 か月前の時点を FOR SYSTEM_TIME AS OF で参照できるようにする","月次のスケジュールされたクエリでテーブル スナップショットを作成し、有効期限を 13 か月後に設定する","フェイルセーフ期間に頼って、必要になったときに Google へ依頼して過去の状態を取り出してもらう","毎月末にテーブルの全件を新しいテーブルへコピーして、永続的にそのまま保管しておく"],"a":1,"e":"テーブル スナップショットは元テーブルとの差分にだけストレージ課金が生じ、有効期限を付けて月次で作成すれば、タイムトラベルを超える期間の状態を低コストで照会できる。タイムトラベル期間は最大 7 日で延長できず、フェイルセーフは通常の復元手段ではなく、全件コピーはコスト要件に反する。","qEn":"The accounting department wants to preserve the month-end state of a BigQuery balance table in a queryable form for 13 months. Time travel reaches back at most seven days, and copying the whole table to a separate table each month is undesirable for storage cost. What is the most appropriate method?","oEn":["Extend the time travel window to 400 days so that the point 13 months ago can be referenced with FOR SYSTEM_TIME AS OF","Create table snapshots with a monthly scheduled query and set their expiration 13 months out","Rely on the fail-safe period and ask Google to retrieve past states when needed","Copy the whole table to a new table every month end and keep it permanently as is"],"eEn":"Snapshots incur storage charges only for differences, so monthly snapshots with expirations preserve states beyond time travel cheaply and queryably. The time travel window maxes at seven days, fail-safe is not a routine recovery path, and full copies violate the cost requirement."},{"id":"h328","d":"D4","q":"2 時間前に誤った UPDATE 文が実行され、BigQuery の顧客テーブルの一部の行が壊れた。テーブル自体は存在し、他の更新は今も続いている。壊れた行だけを更新前の値に戻すために、最もよく使われる方法はどれか。","o":["テーブルを DROP してから、前日のバックアップ ファイルを Cloud Storage から取り込み直す","FOR SYSTEM_TIME AS OF で 2 時間前を照会し、その値で該当する行を書き戻す","BigQuery の変更履歴の機能を使って、直近 2 時間に実行された UPDATE 文を自動的に取り消す","テーブルの有効期限を 2 時間後に設定して、期限が来た時点で自動的に前の状態へ戻るようにする"],"a":1,"e":"タイムトラベルを使うと、FOR SYSTEM_TIME AS OF で過去の時点の状態を照会でき、その値で壊れた行だけを書き戻せるため、他の更新を失わずに修復できる。DROP は他の更新を失い、UPDATE を自動で取り消す機能はなく、有効期限はテーブルを削除するだけで前の状態に戻らない。","qEn":"Two hours ago an incorrect UPDATE statement corrupted some rows of a BigQuery customer table. The table still exists and other updates continue. Which is the most common way to restore only the corrupted rows to their pre-update values?","oEn":["Drop the table and reload the previous day's backup file from Cloud Storage","Query the state two hours ago with FOR SYSTEM_TIME AS OF and write the affected rows back","Use BigQuery's change-history feature to automatically undo the UPDATE statements executed in the last two hours","Set the table's expiration two hours out so that it returns to its previous state automatically when it expires"],"eEn":"With time travel, FOR SYSTEM_TIME AS OF queries a past state and only the broken rows are written back, so other updates are not lost. DROP loses other updates, there is no feature to automatically undo UPDATEs, and expiration just deletes the table."},{"id":"h329","d":"D4","q":"過去の売上を格納した BigQuery のテーブルが 200 TB あり、数か月以上更新されていないが、時折クエリされる。コスト削減のため、Cloud Storage の Archive クラスへエクスポートしてテーブルを削除することが提案された。クエリの手間とコストの面で、最も適切な考え方はどれか。","o":["長期ストレージの料金を受けるには、テーブルをエクスポートして長期保存用のデータセットへ再び読み込む必要がある","Archive クラスの方が照会のたびの復元の手間やコストを含めても常に安くなるので、エクスポートして削除する","更新のない状態が続いたテーブルは自動的に長期ストレージの料金になるので、そのまま BigQuery に置く","更新のないテーブルは、長期ストレージの料金になる代わりに、クエリの実行が遅くなる"],"a":2,"e":"BigQuery では、一定期間更新されないテーブルやパーティションのストレージは自動的に低い料金になり、性能や可用性は変わらない。照会の機会があるデータはそのまま置くのが簡単で安全である。再読み込みは不要で、Archive への移動は照会のたびに復元の手間がかかり、性能の低下もない。","qEn":"A 200 TB BigQuery table of historical sales has not been updated for several months but is queried occasionally. To cut cost, exporting it to the Cloud Storage Archive class and deleting the table was proposed. Considering query effort and cost, what is the most appropriate view?","oEn":["To receive long-term storage pricing, the table must be exported and reloaded into a dataset for long-term retention","Archive is always cheaper even counting the restoration effort and cost at each query, so export and delete","Tables left unmodified automatically move to long-term storage pricing, so keep it in BigQuery as is","Unmodified tables get long-term storage pricing but queries on them run more slowly in exchange"],"eEn":"In BigQuery, storage for tables or partitions unmodified for a period automatically gets lower pricing with no change in performance or availability, so data that is queried is simplest and safest left in place. No reload is needed, Archive adds restoration effort, and there is no slowdown."},{"id":"h330","d":"D4","q":"重要な設定ファイルを置く Cloud Storage のバケットで、誤上書きに備えてオブジェクトのバージョニングを有効にした。ところが数か月で過去の世代（ノンカレント バージョン）が際限なく溜まり、ストレージ コストが増え続けている。最新の世代を含めて直近 3 世代だけを残し、それより古い世代は自動で削除したい。最も適切な設定はどれか。","o":["バージョニングを無効にして、これまでに溜まった過去の世代をすべて削除し、現行のものだけを残す","ライフサイクル ルールの age 条件で、作成から 1 日が過ぎたすべてのオブジェクトを自動的に削除する","Autoclass を有効にして、古い世代を自動でより安いストレージ クラスへ移動させながら、すべて保持し続ける","ライフサイクル ルールで、新しいバージョンの数が 3 以上のオブジェクトを削除する"],"a":3,"e":"ライフサイクル ルールの numNewerVersions を使うと、新しい世代が一定数以上あるバージョンだけを自動削除でき、誤上書きへの備えとコストを両立できる。バージョニングの無効化は保護を失い、age だけの削除は現行のオブジェクトも消し、Autoclass は世代数を減らさずクラスを移すだけである。","qEn":"Object versioning was enabled on a Cloud Storage bucket holding important configuration files to guard against accidental overwrites. Within months, past generations (noncurrent versions) pile up without limit and storage cost keeps rising. The team wants to keep only the latest three generations including the live one and delete older ones automatically. Which setting is most appropriate?","oEn":["Disable versioning, delete all accumulated past generations, and keep only the current ones","Use a lifecycle rule age condition to automatically delete every object one day after creation","Enable Autoclass so that old generations automatically move to cheaper storage classes while all of them are kept","Use a lifecycle rule that deletes objects with three or more newer versions (numNewerVersions)"],"eEn":"The lifecycle numNewerVersions condition automatically deletes only versions with at least a set number of newer ones, balancing overwrite protection and cost. Disabling versioning loses protection, an age-only rule deletes live objects, and Autoclass moves classes without reducing generations."},{"id":"h331","d":"D4","q":"運用担当者が昨日、本番バケットのフォルダを gsutil rm -r で誤って削除した。バケットでオブジェクトのバージョニングは有効にしておらず、保持ポリシーもない。バケットは最近作成されたもので、設定は既定のままである。削除したオブジェクトを取り戻す最も適切な方法はどれか。","o":["ソフト削除の保持期間内なので、削除されたオブジェクトを復元する","バケットのバージョニングを今から有効にして、昨日削除されたオブジェクトの過去の世代を読み出す","Cloud Storage は削除をすべて即時に確定するので、バックアップから再び取り込む以外に方法はない","Cloud Audit Logs の管理アクティビティ ログから、削除されたオブジェクトの内容を取り出して再作成する"],"a":0,"e":"Cloud Storage には、削除したオブジェクトを保持期間の間は復元できるソフト削除があり、新しいバケットでは既定で有効になっている。バージョニングは今から有効にしても過去の削除は取り戻せず、削除が即時確定するとは限らず、監査ログにはオブジェクトの内容が含まれない。","qEn":"An operator mistakenly deleted a folder in a production bucket yesterday with gsutil rm -r. Object versioning is not enabled and there is no retention policy. The bucket was created recently and its settings are at their defaults. What is the most appropriate way to get the deleted objects back?","oEn":["Restore the deleted objects, since they are within the soft delete retention period","Enable versioning on the bucket now and read the past generations of the objects deleted yesterday","Cloud Storage finalizes every deletion immediately, so the only way is to ingest again from a backup","Extract the contents of the deleted objects from the Admin Activity logs in Cloud Audit Logs and recreate them"],"eEn":"Cloud Storage soft delete lets deleted objects be restored during the retention period and is on by default for new buckets. Enabling versioning now cannot recover past deletions, deletion is not always immediately final, and audit logs do not contain object contents."},{"id":"h332","d":"D4","q":"訴訟に関連する可能性のある契約書が、Cloud Storage のバケットに多数ある。バケットには 3 年のオブジェクト保持ポリシーが設定され、期間が過ぎたものは削除する運用である。調査が終わるまで、特定のオブジェクトだけは保持期間が過ぎても削除させたくない。最も適切な方法はどれか。","o":["対象のオブジェクトに、一時的な保留（temporary hold）を設定する","バケットの保持ポリシーの期間を 10 年に延長して、すべてのオブジェクトをこの先も長く保持する","対象のオブジェクトを別のバケットにコピーしたうえで、元のバケットにあるオブジェクトを削除する","対象のオブジェクトのストレージ クラスを Archive に変更して、削除の対象になりにくい状態にする"],"a":0,"e":"オブジェクトの保留（hold）を設定すると、保持期間が過ぎても保留が解除されるまで削除や上書きができない。バケット全体の保持期間の延長は不要な保持が増え、別のバケットへの移動は元の削除を伴い、ストレージ クラスの変更は削除の可否に影響しない。","qEn":"A Cloud Storage bucket holds many contracts that may relate to litigation. The bucket has a three-year object retention policy, and objects past the period are deleted. Until the investigation ends, certain objects must not be deleted even after the retention period passes. What is the most appropriate method?","oEn":["Place a temporary hold on the target objects","Extend the bucket's retention policy period to ten years so that all objects are kept long into the future","Copy the target objects to another bucket and then delete the objects in the original bucket","Change the storage class of the target objects to Archive so that they are less likely to be deleted"],"eEn":"Placing a hold on an object prevents deletion or overwrite until the hold is released, even after the retention period. Extending the bucket-wide retention keeps unneeded objects, moving to another bucket involves deleting the original, and changing storage class does not affect deletability."},{"id":"h333","d":"D4","q":"データ サイエンスチームのバケットには、プロジェクトごとに異なる頻度でアクセスされるデータが数百 TB ある。どのオブジェクトがいつ使われなくなるかを予測できず、ライフサイクル ルールの年齢条件では、再び使われ始めたデータに取り出し料金や早期削除の料金が発生している。アクセスの実態に合わせてストレージ クラスを自動で調整したい。最も適切な設定はどれか。","o":["ライフサイクル ルールの年齢条件を 7 日に短縮して、すべてのオブジェクトを早めに Coldline へ移す","すべてのオブジェクトを Standard クラスに固定し、ストレージ クラスの変更そのものを禁止する","バケットで Autoclass を有効にする","オブジェクトのアクセス頻度を月次で集計し、担当者が手作業でストレージ クラスを書き換える運用にする"],"a":2,"e":"Autoclass は、オブジェクトごとの実際のアクセスに応じて Standard から Nearline、Coldline、Archive へ自動で移動し、アクセスされたら Standard に戻すため、予測できないパターンでも取り出し料金の問題を避けられる。年齢条件の短縮は再利用に弱く、Standard 固定はコストが高く、手作業の書き換えは運用負荷が大きい。","qEn":"A data science team's bucket holds hundreds of terabytes accessed at different frequencies per project. It cannot predict which objects stop being used and when, and lifecycle age conditions cause retrieval and early-deletion charges on data that starts being used again. The team wants storage classes adjusted automatically to actual access. Which setting is most appropriate?","oEn":["Shorten the lifecycle age condition to seven days and move all objects to Coldline early","Fix all objects to the Standard class and prohibit changing storage class altogether","Enable Autoclass on the bucket","Aggregate object access frequency monthly and have staff rewrite storage classes by hand"],"eEn":"Autoclass automatically moves each object between Standard, Nearline, Coldline, and Archive according to actual access and returns it to Standard when accessed, avoiding retrieval charge issues under unpredictable patterns. Shorter age rules suffer on reuse, Standard-only is costly, and manual rewrites burden operations."},{"id":"h334","d":"D4","q":"ログ分析用の BigQuery データセットには、圧縮率が非常に高い（約 8 倍）テキスト中心のテーブルが数百 TB ある。現在は論理ストレージ課金モデルで、ストレージ料金が大きい。クエリの方法は変えずに、圧縮の効果をストレージ料金に反映させたい。最も適切な方法はどれか。","o":["テーブルを Parquet で Cloud Storage にエクスポートして、BigQuery 側のデータは削除する","データセットの課金モデルを物理ストレージに切り替える","データセットのタイムトラベル期間を 7 日に延長して、圧縮済みの履歴を長く保持する","すべてのテーブルにクラスタリングを設定して、課金対象の論理バイト数を減らす"],"a":1,"e":"物理ストレージ課金では圧縮後のバイト数が課金対象になるため、圧縮率が高いデータでは料金を下げられる。Parquet への書き出しはクエリの方法を変えてしまい、タイムトラベルの延長は物理課金では課金対象を増やし、クラスタリングは論理バイト数を減らさない。","qEn":"A BigQuery dataset for log analysis holds hundreds of terabytes of text-heavy tables with very high compression (about 8x). It currently uses the logical storage billing model and storage charges are large. The team wants compression to be reflected in storage charges without changing how queries are run. What is the most appropriate method?","oEn":["Export the tables to Cloud Storage as Parquet and delete the data on the BigQuery side","Switch the dataset's billing model to physical storage","Extend the dataset's time travel window to seven days to keep compressed history longer","Set clustering on all tables to reduce the logical bytes that are billed"],"eEn":"Physical storage billing charges for compressed bytes, which lowers cost for highly compressible data. Exporting to Parquet changes how queries run, extending time travel adds billable data under physical billing, and clustering does not reduce logical bytes."},{"id":"h335","d":"D4","q":"個人情報保護の社内規程により、日本の顧客データは日本国内のデータセンターにだけ保存する必要がある。新しく作成する BigQuery のデータセットのロケーションとして、最も適切なものはどれか。","o":["US マルチリージョン（可用性が高く、米国内の複数のリージョンに分散して保存される）","EU マルチリージョン（欧州連合内の複数のリージョンにデータが分散して保存される）","東京リージョン（asia-northeast1）","シンガポール リージョン（asia-southeast1。アジアで日本に近く、通信の遅延が小さい）"],"a":2,"e":"日本国内に限定するなら、東京（asia-northeast1）か大阪（asia-northeast2）の単一リージョンを選ぶ。US や EU のマルチリージョンはそれぞれ米国と EU 内に保存され、シンガポールも国外であり、いずれも日本国内に限定する規程を満たさない。","qEn":"Under internal personal-data protection rules, Japanese customer data must be stored only in data centers in Japan. Which location is most appropriate for a newly created BigQuery dataset?","oEn":["US multi-region (highly available, with data spread across multiple regions in the United States)","EU multi-region (with data spread across multiple regions within the European Union)","Tokyo region (asia-northeast1)","Singapore region (asia-southeast1, close to Japan in Asia with low communication latency)"],"eEn":"To stay within Japan, choose a single region such as Tokyo (asia-northeast1) or Osaka (asia-northeast2). The US and EU multi-regions store data in the United States and the EU respectively, and Singapore is outside Japan, so none meets the rule."},{"id":"h336","d":"D4","q":"BigQuery のデータセットを US マルチリージョンに作成して運用してきたが、規程の変更で日本国内への移行が必要になった。データセットの設定画面でロケーションを東京に変更しようとしたが、変更できなかった。最も適切な移行方法はどれか。","o":["データセットのロケーションの設定を US から asia-northeast1 へ上書きして、保存済みのデータを BigQuery に自動で移動させる","組織ポリシーのリソース ロケーションの制約を asia-northeast1 に変更して、既存のデータセットを自動的に移動させる","US のデータセットは残したまま、東京のリージョンを参照するビューを作成して、データが日本にあるものとみなす","東京にデータセットを新規作成し、データセットのコピーでテーブルを移して、切り替え後に元のデータセットを削除する"],"a":3,"e":"BigQuery のデータセットのロケーションは作成後に変更できないため、目的のロケーションに新しいデータセットを作り、データセットのコピーでデータを移して切り替える。組織ポリシーは新規作成の制約で既存データを動かさず、ビューは元のロケーションのデータを参照するだけで、データの所在は変わらない。","qEn":"A BigQuery dataset has been operated in the US multi-region, but a policy change requires moving it to Japan. The attempt to change the location to Tokyo in the dataset settings failed. What is the most appropriate migration method?","oEn":["Overwrite the dataset location setting from US to asia-northeast1 and have BigQuery automatically move the stored data","Change the resource location constraint in Organization Policy to asia-northeast1 so that existing datasets move automatically","Leave the US dataset in place and create a view that references the Tokyo region, treating the data as being in Japan","Create a new dataset in Tokyo, move the tables with dataset copy, and delete the original dataset after cutover"],"eEn":"A BigQuery dataset's location cannot be changed after creation, so create a new dataset in the target location, move data with dataset copy, and cut over. Organization policy constrains new creation without moving data, and a view merely references data in the original location."},{"id":"h337","d":"D4","q":"BigQuery で、US マルチリージョンのデータセットのテーブルと、東京リージョン（asia-northeast1）のデータセットのテーブルを JOIN するクエリを実行したところ、データセットが見つからないというエラーになった。BigQuery のロケーションの仕様を踏まえた、最も適切な対処はどれか。","o":["どちらかのテーブルを、もう一方と同じロケーションのデータセットへコピーしてから JOIN する","クエリの実行ロケーションを US と asia-northeast1 の両方に指定して、実行するようにジョブを構成する","JOIN をやめて、2 つのテーブルを別々に照会した結果を UNION ALL でひとつにまとめる","テーブル名の前にプロジェクト ID を付けて、完全修飾名で両方のテーブルを参照する"],"a":0,"e":"BigQuery のクエリは 1 つのロケーションで実行され、異なるロケーションのデータセットをまたいで結合できないため、データを同じロケーションにコピーしてから結合する。ロケーションを複数指定することはできず、UNION ALL でも同じ制約に当たり、完全修飾名にしてもロケーションの違いは解消しない。","qEn":"A BigQuery query joining a table in a US multi-region dataset with a table in a Tokyo region (asia-northeast1) dataset failed with a dataset-not-found error. Given how BigQuery locations work, what is the most appropriate remedy?","oEn":["Copy one of the tables into a dataset in the same location as the other, then JOIN","Configure the job to run with both US and asia-northeast1 specified as the query location","Drop the JOIN and combine the results of querying the two tables separately with UNION ALL","Prefix the table names with the project ID and reference both tables with fully qualified names"],"eEn":"A BigQuery query runs in one location and cannot combine datasets across locations, so copy data to the same location first. Multiple locations cannot be specified, UNION ALL hits the same constraint, and fully qualified names do not remove location differences."},{"id":"h338","d":"D4","q":"日本の顧客の動画ファイルを Cloud Storage に保存する。データは日本国内から出してはならず、同時に、1 つのリージョン全体が停止してもデータにアクセスし続けられる必要がある。最も適切なバケットのロケーションはどれか。","o":["東京の単一リージョン（asia-northeast1。1 つのリージョンの複数のゾーンに冗長化される）","US マルチリージョン（米国内の複数のリージョンに地理的に冗長化される）","EU マルチリージョン（欧州内の複数のリージョンに地理的に冗長化される）","東京と大阪を組み合わせたデュアルリージョン（asia1）"],"a":3,"e":"東京と大阪のデュアルリージョン（asia1）は、データを日本国内の 2 つのリージョンに冗長に保存するため、国外へ出さずにリージョン障害にも耐える。東京の単一リージョンはリージョン全体の停止に耐えられず、US と EU のマルチリージョンは日本国内に限定する要件に反する。","qEn":"Video files of Japanese customers are to be stored in Cloud Storage. Data must not leave Japan, and it must remain accessible even if an entire region goes down. Which bucket location is most appropriate?","oEn":["Tokyo single region (asia-northeast1, redundant across multiple zones in one region)","US multi-region (geographically redundant across multiple regions in the United States)","EU multi-region (geographically redundant across multiple regions in Europe)","The dual-region combining Tokyo and Osaka (asia1)"],"eEn":"The Tokyo-Osaka dual-region (asia1) stores data redundantly in two regions within Japan, surviving a regional outage without leaving the country. A single Tokyo region cannot survive a region-wide outage, and the US and EU multi-regions violate the Japan-only requirement."},{"id":"h339","d":"D4","q":"グローバル企業の組織で、EU の顧客データを扱うプロジェクトは EU 内にしかリソースを作成できないようにしたい。開発者が誤って米国のリージョンに BigQuery のデータセットや Cloud Storage のバケットを作らないよう、組織として強制したい。最も適切な方法はどれか。","o":["開発者向けの手順書に EU のリージョンだけを使うよう記載し、作成後に毎月のレビューで内容を確認する","VPC Service Controls の境界を作成して、境界の中のリソースが自動的に EU のロケーションへ移動するようにする","米国のリージョンにあるデータセットを検出したら削除するスクリプトを、毎晩定期的に実行する","EU のプロジェクトのフォルダに gcp.resourceLocations 制約を適用し、EU のロケーションだけを許可しておく"],"a":3,"e":"gcp.resourceLocations 制約を適用すると、許可していないロケーションでのリソース作成が拒否されるため、誤った作成を組織として防げる。手順書とレビューは強制力がなく、VPC Service Controls はリソースを移動させず、夜間の削除スクリプトは作成後の事後対応でデータの損失も招く。","qEn":"In a global company, projects handling EU customer data should be able to create resources only inside the EU. The organization wants to enforce that developers cannot mistakenly create BigQuery datasets or Cloud Storage buckets in a US region. What is the most appropriate method?","oEn":["Write in the developer guide to use only EU regions and confirm it in monthly reviews after creation","Create a VPC Service Controls perimeter so that resources inside the perimeter move to EU locations automatically","Run a script every night that deletes any dataset detected in a US region","Apply the gcp.resourceLocations constraint to the folder containing the EU projects and allow only EU locations"],"eEn":"Applying the gcp.resourceLocations constraint rejects resource creation in disallowed locations, preventing mistakes organization-wide. Guides and reviews lack enforcement, VPC Service Controls does not move resources, and nightly deletion scripts are reactive and lose data."}]).map(shuffleChoices);
