function StorageTree({ lang }) {
  const en = lang === "en";
  const steps = {
    start:{ q: en?"Primary workload?":"主な用途は？", opts:[[en?"Analytics (DWH)":"分析(DWH)","bq"],[en?"Transactional (OLTP)":"トランザクション","tx"],[en?"NoSQL":"NoSQL","nosql"],[en?"Files/objects":"ファイル","gcs"]] },
    tx:{ q: en?"Global scale & strong consistency?":"グローバル規模と強整合が要る？", opts:[[en?"Yes":"はい","spanner"],[en?"No":"いいえ","sql"]] },
    nosql:{ q: en?"Pattern?":"パターンは？", opts:[[en?"Wide-column":"ワイドカラム","bt"],[en?"Document sync":"ドキュメント同期","fs"]] },
  };
  const leaves = {
    bq:["BigQuery", en?"Serverless analytical DWH":"サーバーレス分析DWH"],
    spanner:["Spanner", en?"Global, horizontal, strong consistency":"水平スケール・強整合のグローバルRDB"],
    sql:["Cloud SQL", en?"Managed RDB; traditional OLTP":"マネージドRDB・伝統的OLTP"],
    bt:["Bigtable", en?"Low-latency wide-column NoSQL":"低レイテンシのワイドカラムNoSQL"],
    fs:["Firestore", en?"Document NoSQL with real-time sync":"リアルタイム同期のドキュメントNoSQL"],
    gcs:["Cloud Storage", en?"Object storage; pick class by access":"オブジェクトストレージ・頻度でクラス選択"],
  };
  const [path, setPath] = useState([]);
  const cur = path.length === 0 ? "start" : path[path.length - 1];
  const leaf = leaves[cur];
  return (
    <div>
      <div style={{ marginBottom: 10, fontSize: 12, color: "#6b7076" }}>{path.length > 0 && <button onClick={() => setPath(path.slice(0, -1))} style={{ border: "none", background: "none", color: nvInk(C.primary, C.light), cursor: "pointer", fontWeight: 700, padding: 0 }}>{en?"← Back":"← 戻る"}</button>}</div>
      {!leaf && steps[cur] && (
        <div>
          <div style={{ fontSize: 15, fontWeight: 700, color: C.deep, marginBottom: 12 }}>{steps[cur].q}</div>
          {steps[cur].opts.map(([label, to]) => (
            <button key={to} onClick={() => setPath([...path, to])} style={{ display: "block", width: "100%", textAlign: "left", marginBottom: 8, padding: "12px 14px", borderRadius: 9, border: `1.5px solid ${C.mid}`, background: "#fff", color: C.ink, cursor: "pointer", fontSize: 14, fontWeight: 600 }}>{label} →</button>
          ))}
        </div>
      )}
      {leaf && (
        <div style={{ background: "#E6F4EA", border: `2px solid ${C.ok}`, borderRadius: 10, padding: 14 }}>
          <div style={{ fontSize: 11, color: C.ok, fontWeight: 700 }}>{en?"Recommended":"推奨"}</div>
          <div style={{ fontSize: 16, fontWeight: 800, color: C.deep, margin: "4px 0" }}>{leaf[0]}</div>
          <div style={{ fontSize: 13, lineHeight: 1.5 }}>{leaf[1]}</div>
          <button onClick={() => setPath([])} style={{ marginTop: 12, padding: "8px 14px", borderRadius: 8, border: "none", background: C.primary, color: nvInk("#ffffff", C.primary), fontWeight: 700, fontSize: 13, cursor: "pointer" }}>{en?"Restart":"最初から"}</button>
        </div>
      )}
    </div>
  );
}

